INSERT INTO algorithm VALUES(102,'Evaluating de novo sequencing vs database-driven identification',NULL,NULL,NULL,'Briefings in Bioinformatics review evaluating whether de novo sequencing has become an accurate alternative to database-driven peptide identification. Surveys state-of-the-art tools and benchmark performance circa 2017.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(103,'pUniFind',NULL,NULL,'Transformer (AR)','Multimodal pre-trained transformer for mass spectra that unifies peptide-spectrum scoring and zero-shot de novo sequencing in a single model. Trained on >100M open-search-derived spectra; reports +60% PSMs over prior de novo methods with 1,300+ modifications supported, and a DL-based QC step that recovers 38.5% additional peptides.','algorithm',1,'DDA',NULL,NULL);
