INSERT INTO algorithm VALUES(141,'GutenTag',NULL,NULL,'Sequence tag','High-throughput sequence tagging using an empirically derived fragmentation model.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(142,'MS-Profile',NULL,NULL,'Spectral profile','Spectral profile representation for gapped de novo peptide sequencing and identification.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(143,'Proteomics-grade de novo sequencing',NULL,NULL,'Heuristic','Proteomics-grade de novo sequencing approach for large MS/MS data sets.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(144,'NovoDB',NULL,NULL,'Hybrid search','Protein identification method integrating de novo sequencing with database searching.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(145,'Meta-SPS',NULL,NULL,'Spectral assembly','Shotgun protein sequencing with meta-contig assembly for longer de novo protein contigs.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(146,'Plasmopara elicitor de novo workflow',NULL,NULL,NULL,'Downstream application combining de novo peptide sequencing algorithms with RACE-PCR to identify a Plasmopara halstedii elicitor protein.','downstream-application',0,'DDA',NULL,'plant-pathogen');
INSERT INTO algorithm VALUES(147,'Peptide sequence tags',NULL,NULL,'Sequence tag','Error-tolerant peptide identification using short de novo sequence tags and flanking masses.','adjacent',0,'DDA','PST; sequence tag search',NULL);
INSERT INTO algorithm VALUES(148,'Rapid QTOF de novo sequencing',NULL,NULL,'Chemical labeling assisted','Nanoelectrospray, isotopic-labeling, and quadrupole/time-of-flight workflow for rapid de novo peptide sequencing.','algorithm',0,'DDA','QTOF isotopic-labeling de novo sequencing',NULL);
INSERT INTO algorithm VALUES(149,'Peptide and protein de novo sequencing by mass spectrometry',NULL,NULL,NULL,'Current Opinion in Structural Biology review on peptide and protein de novo sequencing by mass spectrometry.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(150,'MS BLAST',NULL,NULL,'Homology search','Homology search of error-tolerant de novo sequences against a protein database, introduced for charting the proteomes of organisms with unsequenced genomes and later used to validate borderline identifications.','adjacent',0,'DDA','MS BLAST',NULL);
INSERT INTO algorithm VALUES(151,'Lys-N MALDI-MS/MS de novo sequencing',NULL,NULL,'Enzymatic ladder assisted','De novo peptide sequencing strategy using Lys-N metalloendopeptidase digestion with MALDI-MS/MS.','adjacent',0,'DDA','Lys-N metalloendopeptidase de novo sequencing',NULL);
INSERT INTO algorithm VALUES(152,'Dimethyl isotope labeling de novo sequencing',NULL,NULL,'Chemical labeling assisted','Dimethyl isotope labeling-assisted workflow for de novo peptide sequencing.','adjacent',0,'DDA','Dimethyl labeling assisted de novo sequencing',NULL);
INSERT INTO algorithm VALUES(153,'18O ion trap de novo sequencing',NULL,NULL,'Chemical labeling assisted','Ion-trap de novo peptide sequencing method using 18O labeling to distinguish fragment ion series.','adjacent',0,'DDA','18O labeling',NULL);
INSERT INTO algorithm VALUES(154,'PSD MALDI high-sensitivity de novo sequencing',NULL,NULL,'Chemical derivatization assisted','High-sensitivity postsource decay MALDI method for de novo peptide sequencing with N-terminal sulfonation.','adjacent',0,'DDA','PSD MALDI de novo sequencing',NULL);
INSERT INTO algorithm VALUES(155,'Lysine derivatization PSD de novo sequencing',NULL,NULL,'Chemical derivatization assisted','Derivatization workflow for lysine-terminated tryptic peptides to facilitate PSD MALDI de novo sequencing.','adjacent',0,'DDA','guanidination; sulfonation',NULL);
INSERT INTO algorithm VALUES(156,'Isotopic N-terminal labeling de novo sequencing',NULL,NULL,'Chemical labeling assisted','Isotopic N-terminal labeling with a fragmentation-directing moiety for protein quantitation and facilitated de novo sequencing.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(157,'MCAT',NULL,NULL,'Chemical labeling assisted','Mass-coded abundance tagging strategy for de novo peptide sequencing and quantitative profiling of complex protein mixtures.','adjacent',0,'DDA','mass-coded abundance tagging',NULL);
INSERT INTO algorithm VALUES(158,'Manual MS/MS de novo interpretation',NULL,NULL,'Manual interpretation','Protocol for manual de novo peptide sequencing from MS/MS spectra.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(159,'PepSUMS',NULL,NULL,'Graph / machine learning','Computational framework integrating mass tags and dissociation chemistry for de novo peptide sequencing from MS/MS experiments.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(160,'DeNovoID',NULL,NULL,'Hybrid search','Web-based tool for identifying peptides from sequence and mass tags deduced from de novo peptide sequencing.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(161,'MILP de novo peptide identification framework',NULL,NULL,'Integer optimization','Mixed-integer optimization framework for de novo peptide identification from tandem mass spectra.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(162,'Peptide de novo sequencing benchmark data sets',NULL,NULL,NULL,'Large and diverse benchmark data sets for evaluating peptide de novo sequencing algorithms.','benchmark',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(163,'DirecTag',NULL,NULL,'Sequence tag','Open-source statistical scoring algorithm for accurate sequence tags from peptide MS/MS spectra.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(164,'CompNovo',NULL,NULL,'Spectra pair','De novo sequencing algorithm combining complementary CID and ETD tandem MS spectra.','algorithm',0,'DDA','CompNovoCID',NULL);
INSERT INTO algorithm VALUES(165,'ADEPTS',NULL,NULL,'Spectra pair','Advanced peptide de novo sequencing framework using a pair of tandem mass spectra.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(166,'Conovo',NULL,NULL,'Constrained search','Constrained de novo sequencing algorithm for peptide families such as conotoxins.','algorithm',0,'DDA','Constrained de novo sequencing',NULL);
INSERT INTO algorithm VALUES(167,'Multienzyme DeepNovo models',NULL,NULL,'CNN + RNN','DeepNovo-based multienzyme models for improving peptide de novo sequencing generalizability.','algorithm',1,'DDA','MEM; multienzyme models',NULL);
INSERT INTO algorithm VALUES(168,'De novo evaluation for monoclonal-antibody assembly',NULL,NULL,NULL,'Benchmark evaluation of de novo peptide sequencing tools for monoclonal antibody assembly.','benchmark',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(169,'Hunt Lab Guide',NULL,NULL,NULL,'Molecular & Cellular Proteomics guide to manual de novo peptide sequence analysis by tandem mass spectrometry.','review',NULL,NULL,'The Hunt Lab Guide to De Novo Peptide Sequence Analysis',NULL);
INSERT INTO algorithm VALUES(170,'QuasiNovo',NULL,NULL,'Graph / DP + neural network','De novo peptide sequencing algorithm using a neural-network ion classifier, dynamic programming candidate generation, and amino acid usage/edge-frequency scoring.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(171,'Orthrus','https://github.com/yc386/orthrus_metaproteomics','https://github.com/yc386/orthrus_metaproteomics','Hybrid de novo + database search','Open-source metaproteomics pipeline combining Casanovo transformer-based de novo sequencing with Sage database search and Mokapot rescoring.','downstream-application',1,'DDA',NULL,'metaproteomics');
INSERT INTO algorithm VALUES(172,'Ozboneprot',NULL,NULL,'Palaeoproteomics workflow','Workflow for de novo sequencing and validation of bone proteins to support shotgun palaeoproteomics on Australian zooarchaeological and palaeontological samples.','downstream-application',0,'DDA',NULL,'palaeoproteomics');
INSERT INTO algorithm VALUES(173,'cryoEM + MS antibody sequencing workflow',NULL,NULL,NULL,'Workflow combining cryoEM-derived sequences (via ModelAngelo) with LC-MS/MS-based assembly (via Stitch) for simultaneous polyclonal antibody sequencing and epitope mapping. Reports 80–90% accuracy on antibody variable domains and improves MS-based assembly against polyclonal backgrounds.','adjacent',NULL,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(174,'DLDN-Bench',NULL,NULL,NULL,'Benchmark framework for deep-learning de novo peptide sequencing in proteomics. Derives evaluation datasets from human muscle biopsy MS data on PRIDE annotated by cross-engine consensus, and reports precision / coverage of recent DL tools (and classical baselines) against that pseudo-ground-truth.','benchmark',NULL,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(175,'Streptolysin O epitope de novo workflow',NULL,NULL,NULL,'Multi-modal MS workflow combining three deep-learning de novo sequencers (PointNovo, Casanovo, InstaNovo) with antibody profiling to identify a conserved protective epitope in Streptococcus pyogenes Streptolysin O.','downstream-application',1,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(176,'MemNovo',NULL,NULL,'Transformer (AR)','Autoregressive transformer de novo sequencer with a memory mechanism that lets the decoder revisit the input spectrum at each step to balance error accumulation.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(177,'DeNovoGUI',NULL,NULL,NULL,'Open-source Java graphical user interface for tandem-MS de novo sequencing. Wraps PepNovo+, DirecTag, Novor, and pNovo behind a single workflow with shared input/output handling and result inspection. From the CompOmics group at Ghent + collaborators in Bergen, Magdeburg, and Salzburg.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(178,'SearchGUI',NULL,NULL,NULL,'Open-source common interface wrapping a wide set of proteomics database search engines (X!Tandem, MS-GF+, Comet, OMSSA, MS Amanda, MyriMatch, Tide, Andromeda, MetaMorpheus, Sage) plus classical de novo engines (PepNovo+, DirecTag, Novor, pNovo). Sister project to DeNovoGUI from the same CompOmics-aligned Bergen / Ghent group.','adjacent',0,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(179,'Homo antecessor enamel proteome',NULL,NULL,NULL,'Palaeoproteomic de novo + tag-search workflow that recovers enamel proteome from a ~800,000-year-old Homo antecessor tooth and uses the resulting sequences to place the lineage on the hominin tree.','downstream-application',1,'DDA',NULL,'palaeoproteomics');
INSERT INTO algorithm VALUES(180,'Stephanorhinus enamel proteome',NULL,NULL,NULL,'Palaeoproteomic enamel-protein workflow on a 1.77-million-year-old Stephanorhinus tooth from Dmanisi, resolving rhinoceros phylogeny beyond the reach of ancient DNA.','downstream-application',1,'DDA',NULL,'palaeoproteomics');
INSERT INTO algorithm VALUES(181,'Gigantopithecus enamel proteome',NULL,NULL,NULL,'Palaeoproteomic de novo workflow that recovered the enamel proteome of a 1.9-million-year-old Gigantopithecus blacki molar from Chuifeng Cave, placing it as an early-diverging pongine.','downstream-application',1,'DDA',NULL,'palaeoproteomics');
INSERT INTO algorithm VALUES(182,'Ancient ostrich eggshell proteome',NULL,NULL,NULL,'Sequencing of ancient peptides bound to ostrich eggshell mineral surfaces, demonstrating protein survival into deep time (~3.8 million years) via de novo MS/MS workflows.','downstream-application',0,'DDA',NULL,'palaeoproteomics');
INSERT INTO algorithm VALUES(183,'Prosit',NULL,NULL,'CNN + RNN','Deep-learning (bidirectional RNN + attention) predictor of peptide fragment-ion intensities and retention times: widely used to validate and rescore de novo sequencing candidates against predicted spectra.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(184,'MS2Rescore',NULL,NULL,NULL,'Data-driven PSM rescoring framework that mixes search-engine scores with DL-predicted features (MS2PIP fragment intensities, DeepLC retention times, ion-mobility, etc.); used to boost de novo + database-search identification rates, including downstream of Casanovo / DeepNovo.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(185,'PeptideShaker',NULL,NULL,NULL,'Open-source Java GUI that aggregates and inspects search-engine and de-novo-engine results: the third sibling alongside DeNovoGUI and SearchGUI from the CompOmics-aligned Bergen / Ghent group.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(186,'Snake venom proteomes review',NULL,NULL,NULL,'Toxins (2017) review and database surveying snake venom proteomes assembled largely via de novo sequencing: entry point into venomics as a downstream application area for de novo methods.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(187,'Human plasma IgG1 repertoire profiling',NULL,NULL,NULL,'De novo MS workflow (LC-MS coupled with Stitch / native MS) for profiling the circulating human plasma IgG1 antibody repertoire, demonstrating individual-specific dynamics: landmark application of de novo to clinical antibodyomics.','downstream-application',1,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(188,'MS2PIP',NULL,NULL,'Random Forest','Original MS2PIP: random-forest predictor of MS/MS fragment-ion peak intensities used to rescore search-engine and de novo sequencing results. Later updates (2019 web server, 2024 DL backbone) live in algorithm.short_description.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(189,'Awesome De Novo Peptide Sequencing catalog',NULL,NULL,NULL,'This catalog itself: a curated, interactive map of the de novo peptide sequencing field. SQLite database of papers, models, authors, affiliations, and venues, surfaced via an Observable JS site. Released under CC BY 4.0 (catalog) + MIT (helper scripts).','meta',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(190,'jingbo02 Awesome-Denovo-Peptide-Sequencing',NULL,NULL,NULL,'Curated GitHub-resident paper collection covering de novo peptide sequencing, maintained by Jingbo Zhou (Westlake / Zhejiang). Kindred meta-resource alongside this catalog: slightly different scope and editorial choices, but covers the same field.','meta',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(191,'Casanovo Foundation',NULL,NULL,'Transformer (AR)','Foundation model for tandem-MS proteomics: pre-trained the Casanovo spectrum encoder on 30M labelled spectra from MassIVE-KB, then reused the encoder off-the-shelf for downstream tasks (de novo sequencing, spectrum quality, chimericity, phosphorylation, glycosylation prediction). Successor in spirit to Casanovo v1/v2/v5.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(192,'π-HelixNovo2',NULL,NULL,'Transformer (AR)','Successor to π-HelixNovo with an emphasis on availability: an online inference service alongside the model architecture refinement. Same Tsinghua / Pengcheng Lab / NCPSB collaboration as the original.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(193,'Prior-vs-physics benchmark for DL de novo sequencing',NULL,NULL,NULL,'Benchmark that disentangles how much of a DL de novo sequencer''s output reflects MS/MS fragmentation evidence vs learned peptide-sequence priors: important for assessing robustness on out-of-distribution proteomes.','benchmark',NULL,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(194,'FDR control for AI-based de novo sequencing',NULL,NULL,NULL,'FDR-control post-processing layer for the output of AI-based de novo peptide sequencers. Surfaces trustworthy identifications and calibrates confidence scores across models. Applicable to any deep-learning de novo pipeline.','post-processor',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(195,'GP-based scoring function for de novo PSM re-ranking',NULL,NULL,'Learning-to-rank','Genetic-programming-derived scoring function for re-ranking peptide-spectrum matches emitted by de novo sequencing tools. Improves top-k accuracy over the default scorer.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(196,'Deep-learning protein identification primer',NULL,NULL,'CNN + RNN','Companion vision paper by the DeepNovo authors laying out how deep learning applies to protein identification end-to-end (from spectrum → amino-acid tokens → peptide → protein). Predates the PNAS DeepNovo paper by a few months.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(197,'Adaptive GA for tandem-MS peptide sequencing',NULL,NULL,'Heuristic','Adaptive genetic algorithm for protein sequencing from tandem MS. Represents peptides as GA individuals, evolves them against the observed spectrum; the adaptive component tunes mutation / crossover rates on the fly.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(198,'Koala milk lactation proteome',NULL,NULL,NULL,'Non-model marsupial milk proteomics workflow using InstaNovo+ de novo sequencing to profile lactation-stage-specific protein shifts in koala milk against the joey''s development.','downstream-application',NULL,'DDA',NULL,'wildlife-proteomics');
INSERT INTO algorithm VALUES(199,'Tasmanian devil pouch proteome',NULL,NULL,NULL,'De novo peptide sequencing workflow (InstaNovo+) applied to the first proteomic characterisation of Tasmanian devil pouch secretions, uncovering antimicrobial and immune-protective proteins shielding immunologically vulnerable joeys.','downstream-application',NULL,'DDA',NULL,'wildlife-proteomics');
INSERT INTO algorithm VALUES(200,'MARLOWE',NULL,NULL,'Probabilistic taxonomy classifier','Computational tool that takes de novo-sequenced peptides from mass spectra of an unknown biological sample and returns a ranked, probabilistic list of source organisms, aimed at forensic biothreat and biodiversity casework.','downstream-application',NULL,'DDA',NULL,'forensics');
INSERT INTO algorithm VALUES(201,'Processed meat species markers',NULL,NULL,NULL,'De novo peptide sequencing workflow combining FBDA peptide derivatization, dual-polarity DIA-MS, and SCX fractionation to discover species-specific markers (myosin, troponin) in highly processed pork, chicken and bovine meat products, enabling detection of adulteration down to 10 % species contamination.','downstream-application',NULL,'DIA',NULL,'food-authentication');
INSERT INTO algorithm VALUES(202,'Protein Acrobat',NULL,NULL,'Graph / DP','De novo peptide sequencing tool from the Cindrić group, coupling MALDI-TOF/TOF fragmentation of chemically activated peptides with de novo sequence elucidation and NCBInr alignment for organism identification (bacteria, viruses, meat-species markers).','algorithm',0,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(203,'Direct UTI pathogen ID (MALDI-TOF)',NULL,NULL,NULL,'Culture-independent MALDI-TOF/TOF de novo peptide sequencing workflow (using Protein Acrobat + NCBInr alignment) that identifies uropathogens directly from native patient urine in under 24 h, side-stepping the standard 24–72 h culture step in clinical microbiology.','downstream-application',NULL,NULL,NULL,'pathogen-identification');
INSERT INTO algorithm VALUES(204,'PNNL forensic metaproteomic characterization',NULL,NULL,NULL,'De novo peptide sequencing plus taxonomic assignment and statistical scoring to characterize protein sources in complex forensic samples: a precursor to the MARLOWE tool from the same PNNL group.','downstream-application',NULL,'DDA',NULL,'forensics');
INSERT INTO algorithm VALUES(205,'Spider venom peptidome (SPITC + de novo)',NULL,NULL,NULL,'SPITC N-terminal derivatization + 18O labeling coupled with de novo peptide sequencing to simultaneously identify and quantify spider-venom peptides from species with unknown genomes.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(206,'Bothriopsis taeniata PLA2 K49',NULL,NULL,NULL,'Automatic de novo sequencing (PEAKS Studio) with CID/HCD/ETD triplex MS/MS to elucidate the full-length sequence of a new PLA2 K49 (Btt-TX) from Bothriopsis taeniata snake venom.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(207,'Hypnale hypnale venomics',NULL,NULL,NULL,'Venomics workflow combining SDS-PAGE + LC-MS/MS with Novor + PEAKS de novo sequencing and MS-BLAST similarity search to characterize the venom proteome of the hump-nosed pit viper (Western Ghats).','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(208,'Bufo gargarizans skin peptidome',NULL,NULL,NULL,'Peptidomics workflow using nano-LC-MS/MS and PEAKS de novo sequencing against a transcriptome-derived database to characterise <10 kDa bioactive peptides from Bufo gargarizans (Venenum Bufonis) skin secretions.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(209,'Ruby ant venom decapeptide',NULL,NULL,NULL,'Combined Edman degradation and de novo peptide sequencing to isolate and characterize U-MYRTX-MRArub1, a novel insecticidal decapeptide from Myrmica rubra ant venom.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(210,'Anatolian meadow viper top-down ISD venomics',NULL,NULL,NULL,'Extended top-down venomics workflow using in-source decay (ISD) with 1,5-diaminonaphthalene reducing matrix to enable disulfide-bond counting and de novo sequencing-based identification of high-molecular-weight venom constituents, applied to the newly described Vipera anatolica senliki.','downstream-application',NULL,NULL,NULL,'venomics');
INSERT INTO algorithm VALUES(211,'Malabar pit viper venomics',NULL,NULL,NULL,'Venomics workflow combining SDS-PAGE and ion-exchange pre-fractionation with LC-MS/MS + Novor and PEAKS de novo sequencing to identify 97 proteins (including 18 exclusive to de novo) from Trimeresurus malabaricus venom, and evaluate antivenom cross-reactivity.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(212,'Naja naja venomics',NULL,NULL,NULL,'Venomics + antivenomics workflow using SDS-PAGE, RP-HPLC and Q-TOF LC-MS/MS with PEAKS + Novor de novo sequencing to identify 115 proteins across 17 venom protein families in Indian cobra venom from the Western Ghats, and benchmark polyvalent-antivenom recognition.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(213,'Scorpion venom short peptides',NULL,NULL,NULL,'LC-HRMS with de novo sequencing of short (2-12 aa) scorpion venom peptides: 156 sequences identified, revealing N- and C-terminal modifications including the previously unreported N-benzoyl modification.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(214,'Daboia siamensis multi-omics venomics',NULL,NULL,NULL,'Multi-omics venomics of Russell''s viper (Daboia siamensis, Thai specimens): 10x-linked-read + short-read genome assembly and venom-gland transcriptomics feed a MAKER-annotated CDS database, which is searched with PEAKS Studio (database) plus SMSNet (deep-learning de novo) to identify 1,662 venom proteins including previously unreported hyaluronidase-1, phospholipase B and waprin.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(215,'Snake venomics quantification review',NULL,NULL,NULL,'Calvete-lab review of mass-spectrometry-based quantification of snake venom proteomes for non-model species: label-free strategies, absolute quantification via ICP-MS, hybrid elemental/molecular MS setups. Discusses manual de novo interpretation as an established workflow for non-model venomics.','review',NULL,NULL,NULL,'venomics');
INSERT INTO algorithm VALUES(216,'Conus regius conopeptidome',NULL,NULL,NULL,'Reversed-phase LC + Q-TOF MS/MS with Peaks Studio v7 de novo sequencing to identify 520 conopeptides from the vermivorous cone snail Conus regius, spanning 13 conotoxin gene superfamilies and eight disulfide-poor peptide classes: the first molluscan entry in the venomics lane.','downstream-application',NULL,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(217,'Insect adipokinetic hormone neuropeptidomics',NULL,NULL,NULL,'High-resolution LC-MS with de novo peptide sequencing to identify and confirm mature adipokinetic-hormone (AKH) neuropeptides, including novel sequences with post-translational hydroxyproline, across one cockroach, two moths and two flies, cross-checked against genome/transcriptome predictions.','downstream-application',NULL,'DDA',NULL,'neuropeptidomics');
INSERT INTO algorithm VALUES(218,'Sea bass muscle bioactive peptidome',NULL,NULL,NULL,'Native-peptide discovery workflow combining suspect-screening for short peptides (2-4 aa, including modified aminoacyl derivatives) with database + de novo sequencing for medium-sized peptides (2,665 identified by de novo alone) from sea bass muscle, generalising to any food-matrix bioactive-peptide search.','downstream-application',NULL,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(219,'SequenceAssembler',NULL,NULL,'Sequence assembly','Post-identification tool that assembles full-length protein sequences by unifying peptide-spectrum matching (PSM) and de novo sequencing outputs from Novor Cloud, PEAKS Studio, and PatternLab for Proteomics; one-click GUI and comparable in performance to Stitch.','post-processor',0,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(220,'De novo sequence-ambiguity benchmark',NULL,NULL,NULL,'Benchmark across 8 leading DL de novo peptide sequencers on three proteomics datasets, showing large overlap of correct calls between models and that post-processing yields only modest gains. The shared error source is limited fragment-ion coverage, a bottleneck that database search shares as well.','benchmark',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(221,'Wastewater microbial + human biomarker metaproteomics',NULL,NULL,NULL,'Delft (Pabst / van Loosdrecht) metaproteomics workflow for raw wastewater: efficient protein extraction plus a de novo-sequencing step that customises large public sequence databases so search coverage stays high in the presence of a heterogeneous, chemically noisy matrix. Applied to two urban WWTPs over ~3 months to profile a core microbiome (gut bacteria, opportunistic pathogens) alongside ~200 human proteins as population-level health indicators (immunoglobulins, uromodulin, cancer-associated proteins).','downstream-application',NULL,'DDA',NULL,'wastewater-metaproteomics');
INSERT INTO algorithm VALUES(222,'HDPS',NULL,NULL,'Hybrid de novo + database search','Heuristic two-round sequence assembly strategy combining multi-enzyme and microwave-assisted acid hydrolysis, pNovo de novo peptide sequencing, and pFind homology database search with k-mer graph assembly and majority-vote error correction; achieved 100% sequence coverage and >98% amino-acid accuracy on full-length Ricin toxin A and B chains without a reference sequence, outperforming ALPS.','downstream-application',0,'DDA','Heuristic De Novo Protein Sequencing','toxin-identification');
INSERT INTO algorithm VALUES(223,'CasanovoGUI',NULL,NULL,NULL,'Cross-platform desktop application that wraps the Casanovo Transformer de novo peptide sequencer with a graphical front-end, lowering the barrier to entry for lab-facing MS users who would otherwise need to run Casanovo from the command line.','adjacent',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(224,'PhysNovo',NULL,NULL,'Diffusion','Discrete-diffusion de novo peptide sequencer that folds in physical mass-constraint terms at inference time, so generated sequences respect the observed precursor mass rather than relying purely on the learned amino-acid prior.','algorithm',1,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(225,'Prime-DiffNovo',NULL,NULL,'Transformer (NAR)','Non-autoregressive Transformer de novo peptide sequencer with a diffusion-based refinement step at inference time: the NAR pass drafts a full sequence in parallel, and the diffusion loop iteratively corrects residue predictions to sharpen accuracy.','algorithm',1,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(226,'Golden age of de novo review',NULL,NULL,NULL,'Muth, Hartkopf, Vaudel & Renard 2018 review essay in Proteomics: state of the current de novo sequencing tool landscape, recent applied use cases, and outlook on where the field is heading.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(227,'Flying under the radar review',NULL,NULL,NULL,'O''Bryon, Jenson & Merkley 2020 Protein Science review arguing that de novo peptide identification is under-appreciated relative to database-search methods, with concrete forensic / non-model / immunopeptidomic cases where it wins.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(228,'Automated mAb de novo (Bandeira SPS)',NULL,NULL,'Spectral assembly','Landmark Nat Biotech 2008 paper by Bandeira, Pham, Pevzner, Arnott & Lill: applies Shotgun Protein Sequencing (SPS), that is MS/MS spectral assembly, end-to-end to a monoclonal antibody, recovering both chains without any prior sequence.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(229,'Living proteomics benchmark',NULL,NULL,NULL,'Community-driven, continuously-updated benchmarking resource for deep-learning de novo peptide sequencing: evaluates tools across a broad span of experimental conditions and proteomic applications rather than one frozen test set. Nature Methods Registered Report co-authored by 53 researchers spanning most of the groups that build the tools being benchmarked.','benchmark',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(230,'PSMtags',NULL,NULL,'Chemical derivatization assisted','Small-molecule peptide conjugates found by systematic screening that sharply increase b-ion fragment coverage, raising sequence-identification confidence and improving de novo sequencing. Also supports 9-plex stable-isotope multiplexing at ~240 samples/day, boosting protein data points roughly 6.5x over the unlabelled baseline in sensitive (low-input) proteomics.','adjacent',0,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(231,'De novo protein sequencing review (Vitorino)',NULL,NULL,NULL,'Expert Review of Proteomics survey of de novo sequencing at the protein level: how MS/MS-derived peptide sequences are assembled into full protein sequences, the algorithmic and instrumental limits involved, and where the approach beats database search for organisms and proteoforms absent from reference databases.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(232,'AI proteomics perspective',NULL,NULL,NULL,'62-author Nature Methods Perspective mapping where AI is reshaping MS-based proteomics: peptide and protein identification and quantification (de novo sequencing among them), protein-protein interactions and complexes, spatial and perturbation proteomics, multi-omics integration, and ultimately AI virtual cells. Closes with a call for an AI-friendly data ecosystem for the field.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(233,'FoxNovo',NULL,NULL,'Transformer (NAR)','Non-autoregressive de novo sequencer specialised for HLA-I immunopeptides. Uses dual-token m/z encoding (integer + decimal vocabularies, ~4k tokens instead of ~3M fine-grained bins) in the spectrum encoder, then dynamic-programming top-K decoding over the NAR probability matrix to enforce exact precursor-mass constraints. Reaches >90% peptide accuracy at ~2,800 spectra/s, over 100x faster than the beam-search baseline, and was used to re-analyse 168M spectra from 4,423 raw files in 18 h on one GPU, recovering 41 of 42 targeted-MS-validated non-canonical peptides.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(234,'Spectrum representation ablation study',NULL,NULL,NULL,'MSc thesis ablation of how MS/MS peaks should be represented for a Transformer de novo sequencer. Holds a Casanovo-style encoder-decoder backbone fixed and varies only the peak embedding: additive m/z-intensity, separated/concatenated m/z and intensity, precursor-normalised (relative) m/z, learnable relative m/z, zero-vector controls, and probability-aware embeddings fed with DpNovo''s signal-vs-noise peak probabilities. Finds that separating peak features beats the additive baseline, relative m/z adds a further gain, and the best result combines external signal probability with intensity and mass features: evidence that input representation, not just architecture, moves the needle on Transformer de novo accuracy.','benchmark',1,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(235,'borgonovo',NULL,NULL,'Sequence assembly','Reference-free protein sequencer: multi-protease digestion tiles a protein with overlapping peptides, and the redundant de novo reads are assembled into a per-residue consensus by substitution-tolerant alignment and per-column voting. Re-decoding each spectrum under a prior from its consensus position raises amino-acid accuracy. Wraps Casanovo by default but is backend-agnostic.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(236,'InstaNexus',NULL,NULL,'Sequence assembly','End-to-end workflow for reference-free sequencing of full-length protein therapeutics. Multi-protease digestion yields overlapping peptides, InstaNovo sequences them de novo and Winnow rescores, then greedy overlap or de Bruijn graph assembly (default k=7, min overlap 3) reconstructs contigs ranked by a composite score over coverage, N50, scaffold count and identity. Validated on nanobodies, monoclonal antibodies and de novo mini-binders.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(237,'DNPS-DR',NULL,NULL,NULL,'Automated daily literature briefing for the field, running as a Hugging Face Space. Queries the PubMed eutils API once a day for a fixed keyword set (de novo peptide sequencing, de novo sequencing with mass spectrometry, immunopeptidomics, and the tool names Casanovo, HelixNovo and DeepNovo), summarises each day''s hits with an LLM, and serves them as a dated report. A monitoring service rather than a curated collection, so it complements the hand-maintained meta-resources.','meta',NULL,NULL,'De Novo Peptide Sequencing Daily Report',NULL);
INSERT INTO algorithm VALUES(238,'InstaNovo-FM',NULL,NULL,'Transformer (encoder-only)','Self-supervised foundation model for bottom-up proteomics: an encoder-only transformer trained to reconstruct masked regions of tandem mass spectra under a physics-aware objective, over a corpus of 1.47 billion MS/MS spectra with 184.6 million high-confidence annotations. The embeddings capture fragmentation method, sequence properties and post-translational modifications without peptide labels, and support de novo sequencing, database-free identification and analytical run classification as downstream tasks.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(239,'Fragment-ion and amino-acid probability models',NULL,NULL,'Transformer (encoder-only)','Two local probability-prediction tasks for tandem mass spectra, aimed at telling sequence-informative fragment evidence from noise and from merely unobserved fragments. Fragment-Ion Probability scores whether a peak-supported mass position is a sequence-informative fragment ion; Amino Acid Probability scores whether two mass-consistent positions are adjacent fragments joined by a candidate residue. Encoder-only Transformers outperform CNN baselines on both, and feeding the probabilities to a separate sequencer raises amino-acid recall, amino-acid precision and peptide recall.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(240,'Leucine/isoleucine discrimination',NULL,NULL,'Neural network','Deep-neural-network discrimination of the isomeric residues leucine and isoleucine, which are practically indistinguishable in de novo sequencing from ordinary tandem MS data. Rather than relying on the characteristic satellite ions that EThCD fragmentation produces, it learns from raw spectra directly, searching a broader range of the signal for other evidence that separates the two.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(241,'Sparse autoencoder interpretability of InstaNovo',NULL,NULL,'Sparse autoencoder','Mechanistic-interpretability probe of a de novo sequencer: sparse autoencoders trained on the internal activations at four depths of InstaNovo''s spectrum encoder, paired with a fragment-ion annotation pipeline that labels every peak with chemical concepts derived from first principles, so learned features can be matched to chemical events. Reconstructs the encoder''s representations at over 92% fidelity per layer while preserving more than 99.5% of sequencing loss, and finds the feature-to-concept associations are organised by depth: physical spectral properties sharpest in early layers, cleavage specificity and modification localisation emerging deeper. Causal ablation tests how far those associations reflect genuine use by the model, and exposes a structural limit in correlation-based feature ranking when chemical concepts co-occur.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(242,'Diffusion spectrum foundation model',NULL,NULL,'Diffusion','Self-supervised diffusion encoder for tandem mass spectra, trained by masked spectrum prediction on unlabelled data to give general-purpose spectrum embeddings transferable to downstream proteomics tasks instead of representations inherited from a model optimised only for de novo sequencing. Reaches an R² of 0.784 for precursor m/z at scale against a 0.923 baseline while learning compact, organised latent representations, a trade-off between compactness and predictive accuracy; precursor-charge and fragmentation-type classification stay near the majority-class baselines. Ablations indicate the masking and multi-loss objective drive the latent structure, and that the centroid loss needs modulation such as AdaLN to avoid penalising the learned embeddings.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(243,'INSearch',NULL,NULL,'Hybrid de novo + database search','Prototype AI-native database search that replaces the combinatorial scan with retrieval. A dual encoder projects experimental spectra and theoretical peptide sequences into one shared latent space under a contrastive objective with variance regularisation to prevent feature collapse, and an alternative alignment-and-uniformity loss; approximate nearest-neighbour search then returns the top-k candidates, cutting retrieval from the O(S × ρP) of a conventional engine to O(S(log P + K)). Because retrieval is approximate, candidates are re-ranked by InstaNovo''s decoder run in teacher-forcing mode as a scoring function, aggregating residue log-probabilities by geometric mean. On the nine-species benchmark the held-out yeast split reaches Recall@1/5/100 of 60.0/78.9/91.9%, with neural re-scoring lifting Recall@1 to 82.9%; the harder S. brodae proteome reaches only 55.5% Recall@100, pointing to a need for larger-scale training.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(244,'CPC spectrum encoder pretraining',NULL,NULL,'Transformer (encoder-only)','Unsupervised pretraining of a transformer spectrum encoder by Contrastive Predictive Coding, aimed at the two things that limit supervised de novo sequencing: scarce training data for post-translational modifications, and noisy or incomplete spectra. Exploits the large volume of unlabelled tandem mass spectra that supervised training cannot use. Evaluated on spectral library search rather than sequencing, where on 9-species-V2 it beats OpenMS by 3.73% average amino-acid precision and 4.15% recall, gains 3.8% peptide-level recall, and scales better on inference speed across dataset sizes.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(245,'InstaNovo glycopeptide fine-tuning',NULL,NULL,'Transformer (AR)','Adaptation of InstaNovo, a transformer de novo peptide sequencer, to glycoproteomics by fine-tuning on glycopeptide spectra. Learning from glyco spectra is measurable but limited, and every fine-tuning setting suffers catastrophic forgetting, losing accuracy on peptides the base model handled well; fine-tuning on unfiltered spectra that partly overlap the original training set gives the strongest learning signal but does not remove the effect. PCA of spectrum embeddings shows a large domain shift that explains the difficulty, and the study argues for treating overlapping glyco spectra as informative examples rather than outliers to discard, alongside multi-task and contrastive objectives and embedding transformations that pull glyco spectra toward the original distribution.','downstream-application',1,'DDA',NULL,'glycoproteomics');
INSERT INTO algorithm VALUES(246,'CORALS peptide biosignature detection',NULL,NULL,NULL,'Laser desorption mass spectrometry workflow for detecting and sequencing short peptides as candidate biosignatures on icy ocean worlds such as Enceladus, demonstrated on the CORALS spaceflight prototype: a pulsed UV laser source feeding an Orbitrap mass analyser at ultrahigh mass resolving power and accuracy. Targets the 3-mer and 4-mer peptides found enriched in the psychrophile Colwellia psychrerythraea, on the premise that life persisting in cryogenic extraterrestrial brines might converge on a similar set. Adding silicon nanoparticles raises ionisation efficiency and improves mass resolving power and accuracy by suppressing metastable decay, which is what makes peptide de novo sequencing feasible; protonated peptides, their dimers and metal adducts are all detected. Sequencing rather than database matching is the only option available here, since no reference proteome exists for an unknown organism.','downstream-application',0,'DDA',NULL,'astrobiology');
INSERT INTO algorithm VALUES(247,'Cricket hydrolysate immunomodulatory peptides',NULL,NULL,NULL,'Sequence-resolved workflow for finding immunomodulatory peptides in cricket protein hydrolysate, an alternative-protein food ingredient. The hydrolysate is analysed without a proteolytic digest (PEAKS run with a non-specific enzyme setting) on a Q Exactive, and sequenced de novo with PEAKS to 25,582 assignments at ALC above 50%. Those are filtered to unmodified peptides scoring above 80 that together account for 95% of total abundance (n = 3231), then prioritised by structure-based screening against the STAT3 SH2 domain and molecular dynamics. Selected synthetic peptides reduced LPS-induced IL-6 and TNF-alpha secretion in BV2 microglia, and the hydrolysate itself reduced STAT3 phosphorylation. The paper labels the MS step ''de novo peptidomics''; its own methods and results call the same operation de novo sequencing, so the phrase denotes de novo sequencing of an undigested peptidome rather than a broader pipeline.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(248,'High plains disease agent characterization',NULL,NULL,NULL,'Downstream application of de novo peptide sequencing to an unidentified plant pathogen. The 32-kDa protein specific to high plains disease was sequenced by time-of-flight MS after the agent was isolated in pure culture by vascular puncture inoculation. De novo sequencing of peptides from proteolytic digests of the SDS-PAGE band corrected the public record: the GenBank nucleotide-derived sequence U60141, deposited as the probable N-protein of high plains virus, turned out to be incomplete, and 18 further residues were found at the N terminus. BLAST then returned no significant homology to any protein in the databases, indicating a hitherto unclassified virus group. A clean early demonstration of why de novo matters: the answer was unreachable by database search because the correct sequence was not in any database.','downstream-application',0,'DDA',NULL,'plant-pathogen');
INSERT INTO algorithm VALUES(249,'Immunoglobulin peptide biomarker profiling',NULL,NULL,NULL,'Immunoglobulin peptides themselves used as biomarkers of an immune response, rather than the antigens they bind. Rats were immunised with one of two purified antigens and immunoglobulins from pre- and post-immune sera were profiled by nano-LC on an LTQ-Orbitrap with top-5 data-dependent fragmentation, giving 684 peptides differentially present between the treatment groups and cluster separation of the two. Sequences were obtained for 44% of spectral features by combining Mascot database search with de novo sequencing in PEAKS Studio 5.1, merged in Progenesis, which keeps the best-scoring sequence per feature. The authors state the de novo half was essential, because immunoglobulins are poorly represented in sequence databases. The shared peptides found across animals indicate that repertoire development is not fully random but under selection pressure favouring the best-binding sequences.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(250,'Melanoma HLA peptidome immunogenicity',NULL,NULL,NULL,'HLA class I peptidomes of four melanoma cell lines, extracted from isolated HLA, separated by two-dimensional HPLC and sequenced by MALDI post-source-decay MS. Spectra were interpreted twice over, by database-dependent Mascot search and by database-independent de novo sequencing in Sequit!, with synthetic peptides used to confirm assignments and to measure immunogenicity. Overlap between the four peptidomes was small, indicating highly individual HLA peptidomes, yet they were broadly immunogenic both in the patients the lines came from and in unrelated patients, and that cross-patient immunogenicity was only exceptionally attributable to individual peptides. Most epitopes came from low to medium abundance proteins in sensitive processes such as cell cycle control, DNA replication and tumour suppression.','downstream-application',0,'DDA',NULL,'immunopeptidomics');
INSERT INTO algorithm VALUES(251,'PepSeq',NULL,NULL,'Heuristic','Interactive de novo peptide sequencing application in BioLynx, the biopolymer analysis component of the MassLynx suite. The manual is explicit that it is user-driven rather than automatic: PepSeq "has been designed as an interactive program that allows the user to make decisions at each step in deducing the sequence of a peptide". It scores and annotates spectra on the a, b, y and z ions, and takes input either from a MassLynx data file or as a plain mass and intensity list. Three modes: typing a candidate sequence to see its theoretical fragments annotated against the spectrum; FindTag, which builds a set of sub-sequences whose series ions best match the spectrum and extends them step or leap-wise until the molecular weight matches the user-supplied precursor; and MassSeq, a separately purchased option that performs the sequencing automatically from the precursor mass, modifications and a mass-accuracy estimate. There is no methods paper: the method is documented only in the vendor manual, which is catalogued here as the accompanying resource. Provenance runs Micromass UK Ltd to Waters Corporation, and the Version 4.0 guide catches the handover in progress, carrying a Waters part number and a Micromass part number side by side over a 1993-2002 Micromass UK Ltd copyright.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(252,'Mitochondrial small subunit ribosome proteomics',NULL,NULL,NULL,'Bovine mitochondrial small subunit ribosomal proteins resolved by two-dimensional PAGE, in-gel tryptic digestion, capillary LC and electrospray MS/MS, with the resulting peptide sequences used as virtual probes to screen the human EST database by tBLASTN and assemble consensus cDNAs in silico. Spectra without an exact match in either the protein or EST databases were sequenced de novo, manually or with PepSeq. Seven proteins are reported in Table I, and the two de novo-derived peptides are the sole identifying evidence for two of them, MRP-S26 and MRP-S14; MRP-S14 is also one of only two proteins in the study with significant prokaryotic homology, to Escherichia coli S14. Five of the seven belong to a new class of ribosomal proteins with no prokaryotic counterpart.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(253,'Rubisco large subunit N-terminal determination',NULL,NULL,NULL,'De novo sequencing used to establish what the N terminus of a recombinant protein actually is, which the biological argument then rests on. Arabidopsis Rubisco large subunit variants expressed in E. coli are processed unpredictably by the host, so the construct sequence does not tell you which residues survive. Purified proteins were run on SDS gels, the RbcL band excised, and the N termini determined by de novo mass spectrometric sequencing in PEAKS Studio X+, alongside a semi-specific tryptic database search and peak-area quantification; the work was done as a service by the Bioprocessing Technology Institute, A*STAR. The result is Table 1 in full: the observed N termini for wild type and each truncation variant with their peak-area ratios, showing for instance that wild type is a mixture of MSPQTETKAS, SPQTETKAS and PQTETKAS at 36, 15 and 49 percent. Those assignments are what let the paper claim that large subunits lacking residues 1 to 4 are functional carboxylases that Rubisco activase cannot activate, and they drive a further inference about cooperativity, since some deltaN2 N termini proved identical to deltaN3 ones. A tryptic database search alone would not have found them, because host processing leaves ragged non-tryptic N termini.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(254,'b-/y-ion staged neural network',NULL,NULL,'Neural network','Staged neural network that models ion fragmentation patterns and estimates the posterior probability of each ion type, used to pick the informative peaks out of an MS/MS spectrum before sequencing. The motivation is search-space control: too many peaks and the candidate peptide space grows exponentially, too few and the ion ladder has gaps that can only be explained by permutations of amino acid combinations, so either way candidate quality drops. Reported to beat other preprocessing techniques and to cut the candidate search space substantially without losing candidate quality. The authors note the step matters to any interpretation of MS/MS spectra, de novo or not. Two papers a year apart: the BIBM 2012 classifier, and the two-stage version in Proteome Science 2013 that states it improves on it.','adjacent',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(255,'Polyclonal IgG neutralizing antibody discovery',NULL,NULL,NULL,'Sequencing the circulating antibody repertoire itself rather than the B cells that make it. Human plasma-derived polyclonal IgG is sequenced by combining mass spectrometry with B-cell sequencing, applied to the IgG response to the Moderna Spikevax COVID-19 vaccine. Twelve recombinant antibodies were generated from the natural polyclonal response; six of them, including four derived by de novo protein sequencing, bound at least as well as the original polyclonal antibody, and all six neutralised the target antigen. The argument for the approach is that sequencing peripheral B cells may not represent the complete receptor repertoire, so the circulating IgG pool has to be examined directly. Notable as antibody discovery carried out end to end by a commercial de novo sequencing service.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(256,'Proteome signature rescoring',NULL,NULL,'Information theory','Rescores de novo peptide candidates using proteome signatures, the amino acid usage patterns compiled across a proteome, so the scoring function can prefer plausible residue combinations.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(257,'Me-Cou N-terminal derivatization de novo sequencing',NULL,NULL,'Chemical derivatization assisted','N-terminal derivatization with N-succinimidyl 7-methoxycoumarin-3-carboxylate (Me-Cou), which boosts low-mass b-ion yield so de novo sequencing can read the N-terminal residues, applied to untargeted peptidomics on LC-TIMS-qTOF/MS.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(258,'Food inspection de novo peptide screening',NULL,NULL,'','Database-free food inspection workflow: de novo sequencing of MS/MS spectra on a ZenoTOF 7600 for species identification and quantitation in food extracts, with database search as a complementary step, aimed at unknown contaminants and food fraud.','downstream-application',0,'DDA',NULL,'food-authentication');
INSERT INTO algorithm VALUES(259,'Supernovo',NULL,'https://www.proteinmetrics.com/products/de-novo-sequencing-workflows','Template-guided assembly','Automated antibody de novo sequencing: finds the closest-matching germline V-J-C sequences by database search, then converges on the true heavy and light chains by iterative wildcard substitution against the MS/MS spectra. Commercial, shipped in Protein Metrics'' Byos platform.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(260,'Deglycosylation-assisted glycoprotein de novo sequencing',NULL,NULL,'','Integrative strategy for glycoprotein primary structure: enzymatic N-/O- deglycosylation to open up sequence coverage, EThcD to yield long peptides, PEAKS AB de novo sequencing to assemble the backbone, then glycosylation site and glycan characterisation on top. Demonstrated on Etanercept and three TNFR:Fc-fusion biologics of unknown sequence.','downstream-application',0,'DDA',NULL,'glycoproteomics');
INSERT INTO algorithm VALUES(261,'PAAS 3',NULL,NULL,'Heuristic','1984 FORTRAN program that determines the probable amino acid sequence of a peptide from the sequence ion peaks of its mass spectrum, without a database. The third of the Osaka group''s lineage, after PAAS (1981) and Improved PAAS (1983), and the most cited of the three.','algorithm',0,'DDA','PAAS-3',NULL);
INSERT INTO algorithm VALUES(262,'Fast peptide sequencing algorithm (Bartels)',NULL,NULL,'Graph / DP','1990 graph-theory algorithm that sequences polypeptides from FAB tandem mass spectra by scoring mass differences, without needing the amino acid composition, and proposes amino acid pairs or triples to bridge missing peaks. Sub-quadratic in the number of residues.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(263,'De novo sequencing for proteogenomics (review)',NULL,NULL,'','Methods in Molecular Biology chapter reviewing de novo peptide sequencing from tandem mass spectra for the case where database search fails because the peptide is absent from sequence repositories, and its application in proteogenomics.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(264,'ALPS',NULL,NULL,'Sequence assembly','Assembles de novo sequenced peptides and their per-residue confidence scores into a de Bruijn graph to reconstruct complete monoclonal antibody heavy and light chains without a template.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(265,'De novo sequencing of proteins and peptides (review)',NULL,NULL,'','Review of de novo sequencing approaches for peptides and whole proteins, their applications and open problems.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(266,'InsPecT',NULL,NULL,'Sequence tag','Uses peptide sequence tags derived from the spectrum as a database filter, discarding the vast majority of candidate peptides before scoring, which makes blind searches for post-translational modifications tractable.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(267,'pNovoM',NULL,NULL,'Spectra pair','De novo sequencing from mirror spectrum pairs: digesting the same sample with Ac-LysargiNase and with trypsin yields two spectra whose b and y ion series complement each other, which pins down the sequence far more confidently than either alone.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(269,'Spectrum Fusion',NULL,NULL,'Grouped spectra','Combines several tandem mass spectra of the same peptide, acquired under different conditions or charge states, into one fused spectrum before de novo sequencing, which raises the success rate over sequencing any single spectrum.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(270,'De novo peptide sequencing (Proteome Informatics chapter)',NULL,NULL,'','Book chapter reviewing the de novo peptide sequencing field: its history, manual interpretation, the algorithmic approaches, scoring functions, the available software and its applications. Written by the author of PEAKS.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(271,'Lys-Sequencer',NULL,NULL,'Spectra pair','Database-independent de novo sequencing from paired Lys-C and Lys-N digests, whose single-residue-transposed peptides yield complementary high-resolution spectra, with residue-level confidence reported per call.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(272,'De novo robustness to noise and missing cleavages',NULL,NULL,'','Evaluation of how de novo sequencing algorithms degrade as spectra lose fragmentation cleavages and gain noise, run over eight published datasets with Novor and DeepNovo.','benchmark',NULL,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(273,'De novo sequencing of mixture spectra (Liu thesis)',NULL,NULL,'Graph / DP','PhD work on identifying peptides from MIXTURE tandem mass spectra, where two or more peptides co-fragment: formulates the de novo problem for a mixture spectrum and solves it by dynamic programming.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(274,'Composition-based sequencing',NULL,NULL,'Constrained search','Two-step database-free strategy enabled by FT-ICR mass accuracy: determine the peptide''s amino acid COMPOSITION first, then score only the permutations that composition allows, which is a far smaller search space than conventional de novo sequencing explores.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(275,'Algorithm development for de novo sequencing (Chinese-language review)',NULL,NULL,'','Review of de novo peptide sequencing algorithm development from tandem mass spectra, published in Chinese in Progress in Biochemistry and Biophysics.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(276,'ProbPS',NULL,NULL,'Peak selection','Peak selection model that quantifies how the presence of a derivative peak depends on its primary ion''s intensity, so noise can be discarded before sequencing. Benchmarked on the de novo and sequence-tag performance it enables rather than on peak counts.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(277,'Tandem mass spectrum sequencing (review)',NULL,NULL,'','Book chapter presenting de novo sequencing as the alternative to database search engines in shotgun proteomics, covering its pitfalls and challenges and reviewing the main available tools.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(278,'De novo peptide sequencing tutorial',NULL,NULL,'','Self-contained tutorial on de novo peptide sequencing from MS/MS: models the problem formally, then reviews the major algorithmic approaches and their post-processing.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(279,'Cumulative MS score (cMS)',NULL,NULL,'Grouped spectra','Scoring framework that accumulates evidence for a residue across repeated injections rather than scoring one spectrum at a time, to make de novo annotation robust enough to read VH/VL and CDR sequences out of a POLYCLONAL antibody mixture.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(280,'DIY de novo antibody sequencing workflow',NULL,NULL,'','Assembled from off-the-shelf parts rather than new software: multi-protease digestion, complementary fragmentation and existing de novo tools, combined into a protocol that reached complete accuracy across antibody variable regions and decoded an unknown anti-HA antibody.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(281,'Accurate-mass constrained de novo interpretation',NULL,NULL,'Constrained search','Uses 10 ppm parent-mass accuracy plus immonium-ion composition to replace the database with the set of sequence permutations the mass allows, then feeds the resulting de novo sequences into a similarity search. An early statement of the hybrid de novo plus homology strategy.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(282,'De novo sequencing methods in proteomics (review)',NULL,NULL,'','Methods in Molecular Biology chapter describing de novo sequencing of peptides by mass spectrometry and the concepts behind the main algorithms.','review',NULL,NULL,NULL,NULL);
INSERT INTO algorithm VALUES(283,'Champs',NULL,NULL,'Homology search','Sequences a complete novel protein by de novo sequencing its peptides and then assembling them against a HOMOLOGOUS database rather than an exact one, reaching near-full coverage and accuracy where neither approach alone would.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(284,'T-Bruijn graph top-down de novo sequencing',NULL,NULL,'Graph / DP','De novo sequencing from TOP-DOWN spectra, where the whole protein is fragmented rather than tryptic peptides: derives sequence tags and assembles them through a T-Bruijn graph, evaluated on carbonic anhydrase 2 and an alemtuzumab Fab.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(285,'Stitch',NULL,NULL,'Sequence assembly','Assembles de novo peptides from Casanovo, PEAKS, pNovo and MaxNovo into full antibody sequences, and corrects the two error classes that assembly alone cannot: mass coincidences, where a different residue combination matches the same mass, and I/L ambiguity.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(286,'157 nm photodissociation de novo sequencing',NULL,NULL,'Heuristic','De novo sequencing algorithm written for 157 nm photodissociation spectra, which yield clean x-ion series rather than the mixed b/y ions of CID. Reports per-residue accuracy and distinguishes leucine from isoleucine, which equal-mass residues normally make impossible.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(287,'351 nm UVPD de novo sequencing',NULL,NULL,'Chemical derivatization assisted','N-terminal chromophore derivatisation makes a peptide absorb at 351 nm, so selective UV photodissociation cleaves it into a simplified y-ion series instead of the mixed ladders CID gives, deliberately to make the spectra amenable to de novo sequencing.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(288,'MultiTag',NULL,NULL,'Sequence tag','Searches several error-tolerant peptide sequence tags at once, so a protein can be identified across species by sequence similarity even when no tag is individually correct. Tolerating errors in the tags is what lets de novo output drive a homology search.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(289,'TVNovo',NULL,NULL,'Constrained search','Turns de novo sequencing into a search problem by generating a VIRTUAL database per spectrum, enumerating the candidate sequences the precursor mass allows, then scoring them as a database search would. Built for high-resolution LTQ-FT data.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(290,'NeuCode y-ion annotation',NULL,NULL,'Chemical labeling assisted','Two lysine isotopologues differing by 36 mDa are embedded metabolically, so every C-terminal fragment appears as a resolvable doublet and N-terminal ones do not. An algorithm reads that signature to label y-type ions at 93.2% accuracy, which among other uses lifts correct de novo identifications with PepNovo+ by 34%.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(291,'Bothrops moojeni venom protease de novo identification',NULL,NULL,'','Reviews the state of identifying wholly unknown proteins by mass spectrometry and demonstrates it on a snake venom serine protease from Bothrops moojeni, where de novo sequence tags such as D[K/Q]D[I/L]VDD[K/Q] made the identification.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(292,'Degraded-protein search strategy benchmark',NULL,NULL,'','Benchmarks search strategies for ancient and degraded proteins on a controlled beta-lactoglobulin series, comparing database engines against de novo sequencing through DeNovoGUI (PepNovo+, DirecTag, Novor) to see which recovers coverage as degradation increases.','benchmark',NULL,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(293,'Symmetric difference scoring model','','','Graph / DP','Scores a candidate sequence by the symmetric difference between the masses it explains and the masses actually measured, penalising an explained mass that was not observed as well as an observed mass left unexplained. Earlier scoring models only maximised the number of explained masses.','algorithm',0,'DDA','','');
INSERT INTO algorithm VALUES(294,'Retention-time-aware de novo sequencing','','','Graph / DP','Extends the symmetric difference scoring model with the chromatographic retention time, asking for a sequence consistent with both the fragment spectrum and the observed elution time. Develops an algorithm for each of three retention-time prediction models.','algorithm',0,'DDA','','');
INSERT INTO algorithm VALUES(295,'SWPepNovo','','','Graph / DP','Parallelises a PepNovo-style scoring search across the Sunway many-core architecture, using a two-level task partition and a load-balancing scheme to keep the compute elements busy. Targets the case where the spectrum dataset, not the algorithm, is the bottleneck. From the same Hunan group as MRUniNovo.','algorithm',0,'DDA','','');
INSERT INTO algorithm VALUES(296,'AI-model database search framework','','',NULL,'Survey and theoretical framework for using neural network models as the core engine of database search rather than of de novo sequencing, defining and comparing the runtime and scaling behaviour of the emerging approaches. Adjacent to this catalog: the subject is database search, and it names no tool of its own.','adjacent',1,NULL,'','');
INSERT INTO algorithm VALUES(297,'MS/MS proteotyping in clinical microbiology (perspective)','','',NULL,'Perspective arguing that MS2-based proteotyping should replace MS1 profiling such as MALDI-TOF Biotyper for clinical pathogen identification, and surveying the bioinformatics that would make it practical. Covers database search, spectral library and de novo approaches together.','review',NULL,NULL,'','');
INSERT INTO algorithm VALUES(298,'Thai RCC personalised immunopeptidomics','','',NULL,'Profiles the personalised immunopeptidomes of 13 Thai renal cell carcinoma patients, whose HLA allotypes are underrepresented in public reference data. Builds a personalised proteome from whole-exome sequencing and searches it alongside de novo peptide sequencing, so de novo produced part of the result.','downstream-application',0,'DDA','','immunopeptidomics');
INSERT INTO algorithm VALUES(299,'Log-transformed mass domain de novo sequencing','','','Fragment ion analysis','Bypasses averagine-based deconvolution by working directly in natural log-transformed m/z space, where charge-state spacing is mass-invariant and therefore supplies an intrinsic internal-calibration reference on both FT-ICR and Orbitrap. Isotopologue pairing in that domain then supports de novo sequencing of intact proteins.','algorithm',0,'DDA','','');
INSERT INTO algorithm VALUES(300,'NovelNSeq','','',NULL,'Dedicated algorithm for novel N-terminal proteoforms arising from alternative splicing, parsing signature N-terminal extension peptides. Positioned as an alternative to both proteogenomics, which cannot see proteins absent from the transcriptome, and de novo sequencing, which the authors argue lacks the accuracy and traceability required here.','adjacent',0,'DDA','','');
INSERT INTO algorithm VALUES(301,'DeepGlycan','','',NULL,'Deep-learning de novo glycopeptide sequencing that learns the relationship between glycopeptide spectra and fragment ions for both N- and O-glycans, rather than being tied to one fragmentation method. Reports over 92% glycan recall and about 95% precision on N-glycopeptide spectra under both sceHCD and EThcD, and sequences O-glycans with no additional training. Identifies an O-glycopeptide in mouse heart tissue confirmed by exoglycosidase treatment and a synthetic standard.','adjacent',1,'DDA','','');
INSERT INTO algorithm VALUES(302,'π-MNovo','','',NULL,'De novo sequencer adapted to microbial spectra, addressing the fact that existing models were trained largely on non-microbial proteomic data. Built on a purpose-made resource of over 10 million annotated spectra from 72 cultured microbial isolates, each digest split into five high-pH reversed-phase fractions for deeper peptide sampling, and paired with evidence-guided candidate selection. Reports 66.30% complete-peptide recall on a seven-species benchmark, 6.9-21.7% relative above four published models, and recovered 1,587 reference-matched peptides from spectra pFind left unidentified.','algorithm',1,'DDA','','');
INSERT INTO algorithm VALUES(303,'GyroNovo','','','Transformer (AR)','Attacks missing b- and y-ion fragments on two fronts. Rather than treating imputation as a fixed reconstruction task, it uses the decoder errors seen during training to steer the imputation objective toward the fragments that actually cause mistakes, and to build easy and hard augmented views of each spectrum so the decoder learns under varying spectral corruption. It also gives self-attention a mass-aware inductive bias, using rotary embeddings to encode pairwise mass differences between peaks. Inference needs no extra inputs or search. Reports about 9 points of peptide-level and 7 points of amino-acid-level precision over the previous best on NovoBench.','algorithm',1,'DDA','','');
INSERT INTO algorithm VALUES(304,'Hemp seed antimicrobial peptides','','',NULL,'Screens HAN-J6 hemp seed (Cannabis sativa L.) protein for antimicrobial peptides, a source not previously characterised this way. Defatting, alkaline extraction and acid precipitation, then trypsin/Lys-C digestion and LC-MS; PEAKS 12 de novo sequencing returned 3,985 peptides, and CAMP R3 and AMP Scanner_V2 screened the ALC>=80% list to 56 and 260 candidates respectively, 27 of which both tools agreed on.','downstream-application',0,'DDA','','bioactive-peptides');
INSERT INTO algorithm VALUES(305,'Red-legged salamander skin AMPs','','',NULL,'Looks for antimicrobial peptides in red-legged salamander skin secretions, where amphibian work has concentrated on frogs and toads and salamander secretions are barely characterised. nanoLC-MS/MS with PEAKS de novo sequencing found 135 unique peptides across four injections, of which CAMP-R3 and AMP Scanner predicted 36 to be antimicrobial.','downstream-application',0,'DDA','','bioactive-peptides');
INSERT INTO algorithm VALUES(306,'Hellbender skin AMPs','','',NULL,'Bioprospects the skin secretions of Cryptobranchus alleganiensis, the hellbender salamander, for antimicrobial peptide candidates. Solid-phase extraction enrichment and Orbitrap Fusion acquisition, PEAKS de novo sequencing of the secretion peptides, then antimicrobial prediction over the de novo sequences. The third GMU host-defence peptide record in the catalog, alongside the red-legged salamander and hemp seed abstracts from the same lab.','downstream-application',0,'DDA','','bioactive-peptides');
INSERT INTO algorithm VALUES(307,'Transformer architectures in LC-MS/MS proteomics (scoping review)','','',NULL,'Scoping review of Transformer and Transformer-hybrid models across de novo peptide sequencing and peptide property prediction. Searched PubMed/MEDLINE, Scopus and Web of Science for January 2017 to June 2026: 439 records, 207 after deduplication, 49 full texts assessed, 27 studies included, of which 13 were primarily de novo sequencing, 12 property prediction and 2 both. Finds encoder-decoder models dominant for spectrum-to-sequence generation and encoder-style or hybrid architectures common for fragment intensity, retention time, collision cross section and ion mobility. Its main argument is that reported gains are hard to compare at all, because benchmarks are heterogeneous, sequence-overlap auditing is incomplete, calibrated uncertainty is scarce and reporting is inconsistent.','review',NULL,NULL,'','');
INSERT INTO algorithm VALUES(308,'Blowfly larval hemolymph AMPs',NULL,NULL,NULL,'Bioprospects the hemolymph of Chrysomya megacephala blowfly larvae, which develop in decaying matter, for antimicrobial peptides: larvae are challenged with MRSA, the hemolymph is fractionated by RP-HPLC, active fractions go to QTOF-LCMS, and the spectra are read by de novo sequencing rather than searched, since no database covers this species. The resulting sequence is screened against the APD3, DBAASP, dbAMP and CAMPR4 repositories.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(309,'Multi-enzyme template-assisted mAb sequencing',NULL,NULL,NULL,'Complete monoclonal-antibody sequencing from multiple enzyme digests read by HCD and EThcD, with the de novo calls made template-assisted in Supernovo. Refined on an antibody of known sequence, then applied to 25 anti-haemagglutinin influenza antibodies of unknown sequence, recovering high-confidence sequence for over 99% of the CDRs; the resulting heavy and light chains were cloned and expressed, and the recombinant antibodies reproduced the original binding curves. Distinguishes Ile from Leu correctly on the known-sequence controls.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(310,'MS3 w-ion Leu/Ile discrimination',NULL,NULL,'Fragment ion analysis','Separates the isomeric residues leucine and isoleucine during de novo sequencing by instrument rather than by inference: multistage ETD isolates the primary odd-electron z-dot ions and HCD then drives radical-site fragmentation into w-ions, whose masses differ between the two isomers and which come out as the most intense peaks in the spectrum. Demonstrated on six natural non-tryptic peptides of 15 to 37 residues from Rana ridibunda frog skin secretion, resolving all 22 Leu/Ile positions.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(311,'Charge derivatization MALDI-PSD de novo sequencing',NULL,NULL,'Chemical derivatization assisted','Charge-derivatizes a proteolytic digest before MALDI post-source decay so the fragment series reads cleanly, evaluated on a phosphoenolpyruvate carboxykinase of known structure and then used to sequence an unknown variant from Anaerobiospirillum succiniciproducens.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(312,'Differential scanning de novo sequencing',NULL,NULL,NULL,'Resolves the ion-type ambiguity that makes a tandem mass spectrum hard to read by acquiring the same peptide under differing conditions and comparing the scans, so a fragment''s series can be assigned rather than inferred. Aimed at organisms whose genomes are not sequenced, where a database is not an option.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(313,'N-sulfonated peptide MALDI TOF/TOF de novo sequencing',NULL,NULL,'Chemical derivatization assisted','N-sulfonation before MALDI TOF/TOF directs fragmentation into a single dominant series, so a peptide mass fingerprint that does not identify a protein on its own can be followed by a readable de novo spectrum.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(314,'Amino acid-coded mass tagging',NULL,NULL,'Chemical labeling assisted','Codes amino acids by mass before MALDI TOF/TOF so that incomplete CID of singly and doubly charged precursors still yields assignable series, recovering spectra that would otherwise go unidentified and making the instrument''s throughput usable for de novo work.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(315,'Multi-pass CID spectrum interpretation',NULL,NULL,'Heuristic','Interprets low-energy CID product ion spectra from an ion trap in several passes, extracting the data rigorously and then building the sequence, rather than scoring candidate paths in one sweep.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(316,'IRMPD of N-terminal sulfonated peptides',NULL,NULL,'Chemical derivatization assisted','Infrared multiphoton dissociation of N-terminal sulfonated peptides in a quadrupole ion trap, which both dissociates them efficiently and carries the y-ion series all the way down to y1, so the C-terminal residue is not lost.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(317,'Charged tag with C-terminal digestion',NULL,NULL,'Chemical derivatization assisted','Couples a fixed-charge N-terminal derivatization with a C-terminal digestion of the derivatized peptide, so MALDI spectra carry one interpretable series and the ladder can be read directly.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(318,'Layered sequence-similarity proteomics',NULL,NULL,'Homology search','Identifies proteins in organisms with unsequenced genomes by layering the search: a stringent database search first, then automated de novo sequencing of what it leaves behind, then sequence-similarity searching of those de novo reads against related species.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(319,'N-terminal fragment isolation de novo sequencing',NULL,NULL,'Chemical derivatization assisted','Isolates protein N-terminal peptides specifically, through reduction, S-alkylation, guanidination and a cleavable biotin coupling, so several proteins can be N-terminally sequenced in parallel at low picomole level.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(320,'Lys Tag',NULL,NULL,'Chemical derivatization assisted','A single robust lysine modification before MALDI TOF/TOF that improves de novo readability without a multi-step workup, aimed at identifying proteins confidently from biological samples.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(321,'TMPP arginine-peptide de novo sequencing',NULL,NULL,'Chemical derivatization assisted','Extends TMPP-Ac-OSu tagging to arginine-containing peptides, whose fragmentation the basic side chain otherwise complicates, simplifying the pattern enough to read a sequence.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(322,'TMPP N-terminal peptide de novo sequencing',NULL,NULL,'Chemical derivatization assisted','Tags peptide N-termini with TMPP-Ac-OSu after metalloendopeptidase digestion and isolates them, giving MALDI spectra of N-terminal peptides clean enough to sequence de novo.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(323,'Unique sequence tags for PTM discovery',NULL,NULL,'Sequence tag','Reads short, uniquely assignable sequence tags de novo and uses them to find post-translational modifications, trading the full-length sequence for the reliability that made early de novo output hard to trust in routine proteomics.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(324,'NRP dereplication and sequencing',NULL,NULL,'Spectral alignment / assembly','Sequences cyclic nonribosomal peptides from multistage mass spectrometry by spectral alignment, and dereplicates them comparatively against known NRPs. The first high-throughput route to a compound class with no genome to search and considerable pharmacological interest.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(325,'Oxazolone C-terminal derivatization',NULL,NULL,'Chemical derivatization assisted','Selective C-terminal derivatization, which is hard because C-terminal and side-chain carboxyls behave alike, improved in efficiency and given a bromine signature so the C-terminal fragment can be picked out and sequenced.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(326,'Br-signature N-terminal derivatization',NULL,NULL,'Chemical derivatization assisted','A MALDI signal-enhancing N-terminal derivatization carrying a bromine isotope signature, so the tagged N-terminal peptide is unmistakable in the spectrum. Used to read N-terminal processing such as methionine or signal-peptide removal, and to annotate uncharacterized proteins.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(327,'193 nm UVPD of imidazolinylated Lys-N peptides',NULL,NULL,'Chemical derivatization assisted','Imidazolinylation of Lys-N peptides followed by 193 nm ultraviolet photodissociation, which yields a SINGLE product ion series instead of the overlapping series that defeat most de novo strategies.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(328,'De novo assisted search for nonspecific phosphopeptides',NULL,NULL,'Hybrid de novo + database search','Makes broad-specificity proteases usable in phosphoproteomics: a conventional database search cannot identify phosphopeptides without enzyme specificity, so de novo sequencing proposes the sequence and the search confirms it.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(329,'CycloBranch',NULL,NULL,NULL,'Open-source de novo identification engine for nonribosomal peptides, reading accurate product ion masses to handle linear, cyclic and branched topologies that ordinary peptide tools cannot express.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(330,'De novo assisted mixture spectrum characterization',NULL,NULL,'Grouped spectra','Attacks the low identification rate caused by MIXTURE spectra, where more than one peptide co-fragments, by using de novo interpretation to characterize what the spectrum actually contains.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(331,'Top-down protein analysis from de novo strings',NULL,NULL,'Sequence assembly','Takes a set of de novo amino acid strings derived from top-down tandem mass spectra and analyses the protein sample from them, rather than matching spectra to a database.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(332,'Top-down tandem spectrum de novo sequencing',NULL,NULL,NULL,'De novo sequencing of top-down tandem mass spectra, aimed at the proteins no database can serve -- organisms with unknown genomes, antibodies, novel splice variants -- and at recovering a complete sequence rather than peptide-length fragments.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(333,'Hydrogen atom attachment phosphopeptide sequencing',NULL,NULL,'Fragment ion analysis','Radical fragmentation by hydrogen atom attachment on a MALDI instrument, which keeps the labile phosphate in place while cleaving the backbone, so tryptic phosphopeptides can be sequenced de novo and their phosphosites located.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(334,'PASEF sequence confirmation and de novo',NULL,NULL,NULL,'Uses PASEF on a timsTOF to accelerate the multi-protease digests (trypsin, elastase, chymotrypsin) that confirm a biopharmaceutical sequence, with data clean enough to drive de novo sequencing as well.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(335,'Tetrazine-cyclized peptide UV ring-opening',NULL,NULL,'Chemical derivatization assisted','Designs cyclic peptides on solid phase around a tetrazine so that UV light opens the ring and releases them, turning a cyclic sequence -- which tandem MS deconvolutes badly, and which most approved peptide drugs are -- into a linear one that sequences de novo.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(336,'Ascaris suum tissue neuropeptides',NULL,NULL,NULL,'De novo sequences novel neuropeptides directly from Ascaris suum tissue by MALDI TOF/TOF, profiling the tissue without the extraction losses and chemical degradation a workup would add.','downstream-application',0,'DDA',NULL,'neuropeptidomics');
INSERT INTO algorithm VALUES(337,'Wolf spider venom AMPs (lycocitins)',NULL,NULL,NULL,'De novo sequences the antimicrobial peptides lycocitin 1, 2 and 3 from the venom glands of the wolf spider Lycosa singoriensis, two of them new, alongside an unassigned 3038.70 Da peptide.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(338,'Mycobacterium PAH response proteome',NULL,NULL,NULL,'Compares protein profiles of Mycobacterium vanbaalenii PYR-1 grown on high-molecular-weight polycyclic aromatic hydrocarbons by two-dimensional gel electrophoresis, identifying induced proteins partly by de novo sequencing.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(339,'Anti-OX40L mAb de novo sequencing',NULL,NULL,NULL,'Full-length de novo sequencing of a monoclonal antibody raised against OX40 ligand, from overlapping proteolytic and chemical digests read by mass spectrometry and cross-checked by Edman degradation.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(340,'Bromotryptophan conotoxin sequencing',NULL,NULL,NULL,'Sequences a T-1-family conotoxin de novo by FTICR and maps its disulfides, a class whose 10 to 17 residues carry unusual modifications including brominated tryptophan that defeat database identification.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(341,'Rhesus macaque proteome annotation',NULL,NULL,NULL,'Applies de novo sequencing at proteomic scale to Macaca mulatta, whose roughly 42,000 protein annotations against a human 330,000 make database search unreliable, so that a primate disease model can be studied proteomically at all.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(342,'Cytochrome c4 bottom-up sequencing',NULL,NULL,NULL,'Determines the primary structure of the 21 kDa cytochrome c4 of Thiocapsa roseopersicina de novo, bottom-up, from three separate digests (trypsin, Lys-C, Glu-C) read by ion-trap and FTICR mass spectrometry.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(343,'Crustacean hyperglycemic hormone sequencing',NULL,NULL,NULL,'Combines bottom-up and top-down mass spectrometry to sequence the 72-residue crustacean hyperglycemic hormone of Cancer borealis de novo, the sequence having been unavailable for this species.','downstream-application',0,'DDA',NULL,'neuropeptidomics');
INSERT INTO algorithm VALUES(344,'Baboon theta-defensin sequencing',NULL,NULL,NULL,'De novo sequencing by MALDI of two new cyclic theta-defensins purified from hamadryas baboon leukocytes, both active in vitro.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(345,'Camelid VHH top-down sequencing',NULL,NULL,NULL,'Determines the primary structure of a 13.6 kDa camelid single heavy chain antibody by MALDI-TOF/TOF top-down analysis, recovering most of the sequence from the intact protein rather than from peptides.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(346,'Brassica aquaporin PTM analysis',NULL,NULL,NULL,'Characterises root plasma membrane aquaporins of Brassica oleracea by LC-MS/MS, using de novo sequencing to resolve post-translational modifications and to tell isoforms apart.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(347,'Parvalbumin allergen isoform sequencing',NULL,NULL,NULL,'Characterises new parvalbumin isoforms, the major fish allergens, by combining bottom-up proteomics, accurate intact mass by FTICR and selected MS/MS ion monitoring, with the sequences read de novo.','downstream-application',0,'DDA',NULL,'food-authentication');
INSERT INTO algorithm VALUES(348,'Template proteogenomic antibody resurrection',NULL,NULL,NULL,'Recovers the sequence of an anti-lymphotoxin-alpha mouse hybridoma antibody whose genetic material was lost after a decade in storage, by template proteogenomic de novo sequencing of the stored ascites, then reverse-engineers the gene.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(349,'Cane toad parotid secretion peptides',NULL,NULL,NULL,'De novo sequencing of peptides in the parotid secretion of the cane toad Bufo marinus, a highly toxic secretion whose peptide content, unlike amphibian skin, had gone unexamined.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(350,'Host blood meal hemoglobin database',NULL,NULL,NULL,'De novo sequences haemoglobin from nine North American species with unsequenced genomes, with automated processing and manual validation, to build a database that identifies the host a blood meal came from.','downstream-application',0,'DDA',NULL,'forensics');
INSERT INTO algorithm VALUES(351,'Bowman-Birk inhibitor sequencing',NULL,NULL,NULL,'Purifies and de novo sequences a novel Bowman-Birk serine protease inhibitor from Lathyrus sativus seeds by electrospray mass spectrometry, a two-headed small protein with distinct reactive loops.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(352,'Asian frog skin AMPs (Odorrana)',NULL,NULL,NULL,'Identifies eight intact antimicrobial peptides from the skin of the frog Odorrana jingdongensis by de novo sequencing of low-energy ESI CID Q-TOF spectra, supported by Edman degradation and similarity analysis.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(353,'CHH-family neuropeptide characterization',NULL,NULL,NULL,'High-definition de novo sequencing of crustacean hyperglycemic hormone family neuropeptides, large signalling peptides above 4 kDa whose functions cannot be read without both the sequence and the modifications.','downstream-application',0,'DDA',NULL,'neuropeptidomics');
INSERT INTO algorithm VALUES(354,'Intestinal epithelial chemokine peptidomics',NULL,NULL,NULL,'A non-targeted differential peptidomic comparison of intestinal epithelial cells with and without LPS stimulation, where high-resolution MS and partial de novo sequencing name the secreted chemokines.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(355,'Influenza nucleocapsid substitution mapping',NULL,NULL,NULL,'Reads amino acid substitutions in the influenza A nucleocapsid protein by mass spectrometry with de novo sequencing, substitutions being the route by which non-synonymous mutations become antigenic shift and changed virulence.','downstream-application',0,'DDA',NULL,'pathogen-identification');
INSERT INTO algorithm VALUES(356,'Dandelion hydroxyproline glycopeptides',NULL,NULL,NULL,'Isolates and de novo sequences ToHyp1 and ToHyp2, two homologous proline-hydroxyproline glycopeptides from Taraxacum officinale flowers that resemble no known protein, and tests their activity.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(357,'Coconut pollen allergen mining',NULL,NULL,NULL,'Mines novel allergens from coconut pollen, a significant respiratory sensitiser in India, by manual de novo sequencing combined with homology-driven proteomics.','downstream-application',0,'DDA',NULL,'food-authentication');
INSERT INTO algorithm VALUES(358,'High-throughput de novo for crop proteomics',NULL,NULL,NULL,'A proteomic workflow built on high-throughput de novo sequencing for non-model crop plants, where the genome information needed for a database search is missing and cultivars have to be compared anyway.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(359,'Rana latastei skin peptidome',NULL,NULL,NULL,'Routine de novo sequencing of non-tryptic frog skin peptides on an LTQ Orbitrap Velos with manual spectrum interpretation, on the argument that natural non-tryptic peptides are harder than the tryptic case automation was built for.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(360,'Astrovirus-neutralizing antibody resurrection',NULL,NULL,NULL,'Sequences a human astrovirus-neutralizing monoclonal antibody de novo and re-expresses it, addressing the common case where a useful antibody exists as protein but its sequence and cell line do not.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(361,'Anti-CD34 mAb sequencing and humanization',NULL,NULL,NULL,'De novo protein sequencing of QBEND/10, a mouse monoclonal against the haematopoietic progenitor antigen CD34, followed by humanization and in vitro testing of the resulting antibody on endothelial tube formation.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(362,'Scorpion venom AMP sequencing',NULL,NULL,NULL,'Completes the sequences of antimicrobial peptides in Isometrus maculatus scorpion venom by mass spectrometry, where venom-gland transcriptomics had multiplied candidate AMPs without confirming the mature peptides.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(363,'Conus amadis conotoxin discovery',NULL,NULL,NULL,'Proteome-based de novo sequencing of novel conotoxins from the molluscivorous cone snail Conus amadis, with the neurological activity of the natural venom assayed in zebrafish.','downstream-application',0,'DDA',NULL,'venomics');
INSERT INTO algorithm VALUES(364,'Sea cucumber antioxidative peptides',NULL,NULL,NULL,'Compares alcalase against trypsin for releasing antioxidative peptides from Atlantic sea cucumber, sequencing the active peptides de novo by LC-MS/MS and docking them to predict in vivo function.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(365,'Capillary-electrophoresis mAb sequencing',NULL,NULL,NULL,'Reaches complete monoclonal antibody sequence coverage by pairing the usual LC-MS/MS with capillary electrophoresis, on the argument that one separation chemistry alone leaves gaps no amount of searching can fill.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(366,'Neutral-loss screening for di- and tripeptides',NULL,NULL,NULL,'A five-minute LC-MS/MS screen keyed on the 46 Da neutral loss of formic acid to find di- and tripeptides in whey and porcine liver hydrolysates, with de novo sequencing to name them.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(367,'Cuban treefrog host defence peptides',NULL,NULL,NULL,'Establishes the skin peptidome of the Cuban treefrog Osteopilus septentrionalis by manual de novo sequencing, the host defence peptides in amphibian skin glands being their primary immune armament.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(368,'Conformation-specific cytochrome c antibody',NULL,NULL,NULL,'Sequences de novo an antibody that recognises an alternative conformer of cytochrome c, so that conformational states can be detected in cells and tissue, and rebuilds it from that sequence.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(369,'Agile frog skin defence peptides',NULL,NULL,NULL,'Tandem MS de novo sequencing of the skin defence peptides of the central Slovenian agile frog population, on the observation that every species and even population carries a peptidome suited to its habitat.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(370,'Ovalbumin immunomodulatory peptides',NULL,NULL,NULL,'Finds two-way immunomodulatory peptides in ovalbumin hydrolysates prepared with alkaline protease and papain, combining cell assays, de novo sequencing and molecular docking.','downstream-application',0,'DDA',NULL,'bioactive-peptides');
INSERT INTO algorithm VALUES(371,'Anti-MUC1 139H2 reverse engineering',NULL,NULL,NULL,'Reverse-engineers the anti-MUC1 antibody 139H2 by mass spectrometry-based de novo sequencing, MUC1 being a mucin whose aberrant expression and glycosylation matter in adenocarcinoma.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(372,'HCC non-canonical neoantigen discovery',NULL,NULL,NULL,'Finds non-canonical neoantigens in hepatocellular carcinoma by mass spectrometry-based de novo sequencing and then tests them, addressing the gap that de novo proposes cryptic antigens whose immunogenicity goes unverified.','downstream-application',0,'DDA',NULL,'immunopeptidomics');
INSERT INTO algorithm VALUES(373,'Endogenous antibody de novo sequencing (perspective)',NULL,NULL,NULL,'Perspective on reading antibody sequences at the protein level rather than from B-cell receptor repertoires at the nucleotide level, surveying what mass spectrometry can already do for therapeutic antibodies and what endogenous, polyclonal ones still demand.','review',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(374,'Bottom-up tag convolution',NULL,NULL,'Sequence tag','Tells a correct spectrum interpretation from its plausible alternatives by convolving the set of length-k sequence tags a candidate implies, attacking the step de novo sequencing is weakest at: not producing a sequence but choosing between the ones it produced.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(375,'QUORUM',NULL,NULL,'Gradient boosting','Consensus de novo caller with FDR control: runs Casanovo, InstaNovo and PrimeNovo on the same spectrum, scores every aligned residue with a gradient-boosted model from inter-model agreement, ion evidence class and retention-time error, assembles a fourth candidate and picks among the four with a logistic-regression selector.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(376,'AL amyloid light-chain proteoform sequencing',NULL,NULL,NULL,'Pipeline for systemic AL amyloidosis that combines intact-mass Q-TOF measurement before and after deglycosylation with multi-protease digestion and de novo peptide sequencing, linking urinary N-glycosylated light-chain proteoforms to in situ renal amyloid deposits.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(377,'Goat ApoA-I antibody de novo sequencing',NULL,NULL,NULL,'Replaces a polyclonal reagent with defined monoclonals by de novo sequencing goat antibodies: 15 candidate sequences were recovered, four mixtures formulated, and the four-antibody mixture benchmarked against the polyclonal in an ApoA-I immunoturbidimetric assay over 105 human sera.','downstream-application',0,'DDA',NULL,'antibodyomics');
INSERT INTO algorithm VALUES(378,'HTA-protease de novo antibody sequencing',NULL,NULL,'Protease strategy','Uses two hyperthermoacidic archaeal proteases in place of trypsin or chymotrypsin for de novo antibody sequencing, each yielding about five times more unique peptide reads and, with EAciD fragmentation on a ZenoTOF, complete unambiguous sequence coverage of all complementarity-determining regions.','adjacent',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(379,'Alzheimer amino acid substitution pipeline',NULL,NULL,NULL,'Bioinformatic pipeline that searches proteomic data for amino acid substitutions using a de novo sequencing assisted strategy, and identifies the substitutions specific to Alzheimer''s disease as candidate biomarkers or therapeutic targets.','downstream-application',0,'DDA',NULL,'general-proteomics');
INSERT INTO algorithm VALUES(380,'LIPNovo+',NULL,NULL,'Latent imputation','Self-reflective extension of LIPNovo that finds the fragmentation sites where latent imputation is unreliable and refocuses training on them through a reflection-guided curriculum, so the model is not limited to the missingness patterns seen during training.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(381,'RT-GCTnovo',NULL,NULL,'Transformer (NAR)','Combines Transformer encoders with convolutional layers to capture global and local spectral features, fuses them through a sigmoid gate, adds retention time as a constraint, and decodes semi-autoregressively with dynamic mass masks.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(382,'PLMNovo',NULL,NULL,'Transformer (AR)','Casts peptide-spectrum matching as a constrained optimisation that aligns the spectrum encoder''s embeddings with those of a pre-trained protein language model, and trains encoder and decoder with a Lagrangian primal-dual algorithm, optionally fine-tuning the language model.','algorithm',1,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(383,'De novo FDR control procedure',NULL,NULL,NULL,'False discovery rate control for the de novo setting, where target-decoy competition does not apply: reported to be at least as powerful as database search, with empirical evidence of statistical validity on a set of common de novo applications.','post-processor',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(384,'PAAS',NULL,NULL,'Heuristic','The 1981 original, and the earliest de novo peptide sequencing program in this catalog: a computer program that estimates the possible amino acid sequences of a peptide from its mass spectrum, with no database to search. It could also read a sequence from the PTH amino acids released by Edman degradation, which is what sequencing looked like before tandem MS.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO algorithm VALUES(385,'Improved PAAS',NULL,NULL,'Heuristic','The 1983 revision of PAAS, by the same Osaka group with Wollnik added. Sits between the 1981 original and PAAS 3, so the lineage spans three papers in four years.','algorithm',0,'DDA',NULL,NULL);
INSERT INTO publication VALUES(1,'De novo peptide sequencing with InstaNovo: Accurate, database-free peptide identification for large scale proteomics experiments','2023-08-30','10.1101/2023.08.30.555055','Cold Spring Harbor Laboratory','Bottom-up mass spectrometry-based proteomics is challenged by the task of identifying the peptide that generates a tandem mass spectrum. Traditional methods that rely on known peptide sequence databases are limited and may not be applicable in certain contexts. De novo peptide sequencing, which assigns peptide sequences to the spectra without prior information, is valuable for various biological applications; yet, due to a lack of accuracy, it remains challenging to apply this approach in many situations. Here, we introduce InstaNovo, a transformer neural network with the ability to translate fragment ion peaks into the sequence of amino acids that make up the studied peptide(s). The model was trained on 28 million labelled spectra matched to 742k human peptides from the ProteomeTools project. We demonstrate that InstaNovo outperforms current state-of-the-art methods on benchmark datasets and showcase its utility in several applications. Building upon human intuition, we also introduce InstaNovo+, a multinomial diffusion model that further improves performance by iterative refinement of predicted sequences. Using these models, we could de novo sequence antibody-based therapeutics with unprecedented coverage, discover novel peptides, and detect unreported organisms in different datasets, thereby expanding the scope and detection rate of proteomics searches. Finally, we could experimentally validate tryptic and non-tryptic peptides with targeted proteomics, demonstrating the fidelity of our predictions. Our models unlock a plethora of opportunities across different scientific domains, such as direct protein sequencing, immunopeptidomics, and exploration of the dark proteome.','https://www.biorxiv.org/content/10.1101/2023.08.30.555055v3','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(2,'InstaNovo enables diffusion-powered de novo peptide sequencing in large-scale proteomics experiments','2025-04-01','10.1038/s42256-025-01019-5','Springer Science and Business Media LLC','Mass spectrometry-based proteomics focuses on identifying the peptide that generates a tandem mass spectrum. Traditional methods rely on protein databases but are often limited or inapplicable in certain contexts. De novo peptide sequencing, which assigns peptide sequences to spectra without prior information, is valuable for diverse biological applications; however, owing to a lack of accuracy, it remains challenging to apply. Here we introduce InstaNovo, a transformer model that translates fragment ion peaks into peptide sequences. We demonstrate that InstaNovo outperforms state-of-the-art methods and showcase its utility in several applications. We also introduce InstaNovo+, a diffusion model that improves performance through iterative refinement of predicted sequences. Using these models, we achieve improved therapeutic sequencing coverage, discover novel peptides and detect unreported organisms in diverse datasets, thereby expanding the scope and detection rate of proteomics searches. Our models unlock opportunities across domains such as direct protein sequencing, immunopeptidomics and exploration of the dark proteome.','https://doi.org/10.1038/s42256-025-01019-5','Nature Machine Intelligence','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(3,'InstaNovo-P: A de novo peptide sequencing model for phosphoproteomics','2025-05-14','10.1101/2025.05.14.654049','Cold Spring Harbor Laboratory','Phosphorylation, a crucial post-translational modification (PTM), plays a central role in cellular signaling and disease mechanisms. Mass spectrometry-based phosphoproteomics is widely used for system-wide characterization of phosphorylation events. However, traditional methods struggle with accurate phosphorylated site localization, complex search spaces, and detecting sequences outside the reference database. Advances in de novo peptide sequencing offer opportunities to address these limitations, but have yet to become integrated and adapted for phosphoproteomics datasets. Here, we present InstaNovo-P, a phosphorylation specific version of our transformer-based InstaNovo model, fine-tuned on extensive phosphoproteomics datasets. InstaNovo-P significantly surpasses existing methods in phosphorylated peptide detection and phosphorylated site localization accuracy across multiple datasets, including complex experimental scenarios. Our model robustly identifies peptides with single and multiple phosphorylated sites, effectively localizing phosphorylation events on serine, threonine, and tyrosine residues. We experimentally validate our model predictions by studying FGFR2 signaling, further demonstrating that InstaNovo-P uncovers phosphorylated sites previously missed by traditional database searches. These predictions align with critical biological processes, confirming the model''s capacity to yield valuable biological insights. InstaNovo-P adds value to phosphoproteomics experiments by effectively identifying biologically relevant phosphorylation events without prior information, providing a powerful analytical tool for the dissection of signaling pathways.','https://www.biorxiv.org/content/10.1101/2025.05.14.654049v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(4,'Pairwise Attention: Leveraging Mass Differences to Enhance De Novo Sequencing of Mass Spectra','2025-03-28','10.1101/2025.03.28.645943','Cold Spring Harbor Laboratory','A fundamental challenge in mass spectrometry-based proteomics is determining which peptide generated a given MS2 spectrum. Peptide sequencing typically relies on matching spectra against a known sequence database, which in some applications is not available. Deep learning-based de novo sequencing can address this limitation by directly predicting peptide sequences from MS2 data. We have seen the application of the transformer architecture to de novo sequencing produce state-of-the-art results on the so-called nine-species benchmark. In this study, we propose an improved transformer encoder inspired by the heuristics used in the manual interpretation of spectra. We modify the attention mechanism with a learned bias based on pairwise mass differences, termed Pairwise Attention (PA). Adding PA improves average peptide precision at 100\% coverage by 12.7\% (5.9 percentage points) over our base transformer on the original nine-species benchmark. We have also achieved a 7.4\% increase over the previously published model Casanovo. Our MS2 encoding strategy is largely orthogonal to other transformer-based models encoding MS2 spectra, enabling straightforward integration into existing deep-learning approaches. Our results show that integrating domain-specific knowledge into transformers boosts de novo sequencing performance.Competing Interest StatementThe authors have declared no competing interest.','https://www.biorxiv.org/content/10.1101/2025.03.28.645943v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(5,'DiNovo: high-coverage, high-confidence de novo peptide sequencing using mirror proteases and deep learning','2025-03-20','10.1101/2025.03.20.643920','Cold Spring Harbor Laboratory','Despite the recent advancements driven by deep learning, de novo peptide sequencing is still constrained by incomplete peptide fragmentation and insufficient protein digestion in current single protease-based proteomic experiments. Here, we present a software system, named DiNovo, for high-coverage and confidence de novo peptide sequencing by leveraging the complementarity of mirror proteases. DiNovo is empowered by several innovative algorithms, including a mirror-spectra recognition algorithm independent of pre-sequencing, two sequencing algorithms based on deep learning and graph theory, respectively, and target-decoy mapping, a method for sequencing result evaluation free of prior peptide identification. Compared with the trypsin protease used alone, DiNovo using two pairs of mirror proteases led to two to three times high-confidence amino acids sequenced. Compared with previous single-protease de novo sequencing algorithms, DiNovo achieved much higher sequence coverages. DiNovo also showed great potential as a powerful complement or alternative to database search for peptide identification with quality control.Competing Interest StatementThe authors have declared no competing interest.','https://www.biorxiv.org/content/10.1101/2025.03.20.643920v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(6,'PepGo: a deep learning and tree search-based model for de novo peptide sequencing','2025-02-24','10.1101/2025.02.24.640018','Cold Spring Harbor Laboratory','Identifying peptide sequences from tandem mass spectra is a fundamental problem in proteomics. Unlike search-based methods that rely on matching spectra to databases, de novo peptide sequencing determines peptides directly from mass spectra without any prior information. However, the design of models and algorithms for de novo peptide sequencing remains a challenge. Many de novo approaches leverage deep learning but primarily focus on the architecture of neural networks, paying less attention to search algorithms. We introduce PepGo, a de novo peptide sequencing model that integrates Transformer neural networks with Monte Carlo Tree Search (MCTS). PepGo predicts peptide sequences directly from mass spectra without databases, even without prior training. We show that PepGo surpasses existing methods, achieving state-of-the-art performance. To our knowledge, this is the first approach to combine deep learning with MCTS for de novo peptide sequencing, offering a powerful and adaptable solution for peptide identification in proteomics research. Competing Interest Statement The authors have declared no competing interest.','https://www.biorxiv.org/content/10.1101/2025.02.24.640018v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(7,'Regressor-guided Diffusion Model for De Novo Peptide Sequencing with Explicit Mass Control','2026-03-14','10.1609/aaai.v40i1.36968','AAAI Press','The discovery of novel proteins relies on sensitive protein identification, for which de novo peptide sequencing (DNPS) from mass spectra is a crucial approach. While deep learning has advanced DNPS, existing models inadequately enforce the fundamental mass consistency constraint—that a predicted peptide''s mass must match the experimental measured precursor mass. Previous DNPS methods often treat this critical information as a simple input feature or use it in post-processing, leading to numerous implausible predictions that do not adhere to this fundamental physical property. To address this limitation, we introduce DiffuNovo, a novel regressor-guided diffusion model for de novo peptide sequencing that provides explicit peptide-level mass control. Our approach integrates the mass constraint at two critical stages: during training, a novel peptide-level mass loss guides model optimization, while at inference, regressor-based guidance from gradient-based updates in the latent space steers the generation to compel the predicted peptide adheres to the mass constraint. Comprehensive evaluations on established benchmarks demonstrate that DiffuNovo surpasses state-of-the-art methods in DNPS accuracy. Additionally, as the first DNPS model to employ a diffusion model as its core backbone, DiffuNovo leverages the powerful controllability of diffusion architecture and achieves a significant reduction in mass error, thereby producing much more physically plausible peptides. These innovations represent a substantial advancement toward robust and broadly applicable DNPS. The source code is available in the supplementary material.','https://ojs.aaai.org/index.php/AAAI/article/view/36968','AAAI 2026','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(8,'Accurate de novo sequencing of the modified proteome with OmniNovo','2025-12-13','10.48550/arXiv.2512.12272','arXiv','Post-translational modifications (PTMs) serve as a dynamic chemical language regulating protein function, yet current proteomic methods remain blind to a vast portion of the modified proteome. Standard database search algorithms suffer from a combinatorial explosion of search spaces, limiting the identification of uncharacterized or complex modifications. Here we introduce OmniNovo, a unified deep learning framework for reference-free sequencing of unmodified and modified peptides directly from tandem mass spectra. Unlike existing tools restricted to specific modification types, OmniNovo learns universal fragmentation rules to decipher diverse PTMs within a single coherent model. By integrating a mass-constrained decoding algorithm with rigorous false discovery rate estimation, OmniNovo achieves state-of-the-art accuracy, identifying 51\% more peptides than standard approaches at a 1\% false discovery rate. Crucially, the model generalizes to biological sites unseen during training, illuminating the dark matter of the proteome and enabling unbiased comprehensive analysis of cellular regulation.','https://arxiv.org/abs/2512.12272','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(9,'Bidirectional Representations Augmented Autoregressive Biological Sequence Generation','2025-10-09','10.48550/arXiv.2510.08169','arXiv','Autoregressive (AR) models, common in sequence generation, are limited in many biological tasks such as de novo peptide sequencing and protein modeling by their unidirectional nature, failing to capture crucial global bidirectional token dependencies. Non-Autoregressive (NAR) models offer holistic, bidirectional representations but face challenges with generative coherence and scalability. To transcend this, we propose a hybrid framework enhancing AR generation by dynamically integrating rich contextual information from non-autoregressive mechanisms. Our approach couples a shared input encoder with two decoders: a non-autoregressive one learning latent bidirectional biological features, and an AR decoder synthesizing the biological sequence by leveraging these bidirectional features. A novel cross-decoder attention module enables the AR decoder to iteratively query and integrate these bidirectional features, enriching its predictions. This synergy is cultivated via a tailored training strategy with importance annealing for balanced objectives and cross-decoder gradient blocking for stable, focused learning. Evaluations on a demanding nine-species benchmark of de novo peptide sequencing show that our model substantially surpasses AR and NAR baselines. It uniquely harmonizes AR stability with NAR contextual awareness, delivering robust, superior performance on diverse downstream data. This research advances biological sequence modeling techniques and contributes a novel architectural paradigm for augmenting AR models with enhanced bidirectional understanding for complex sequence generation. Code is available at https://github.com/BEAM-Labs/denovo.','https://arxiv.org/abs/2510.08169','NeurIPS 2025','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(10,'Modanovo: A Unified Model for Post-Translational Modification-Aware de Novo Sequencing Using Experimental Spectra from In Vivo and Synthetic Peptides','2025-09-12','10.1101/2025.09.12.675784','Cold Spring Harbor Laboratory','Post-translational modifications (PTMs) play a central role in cellular regulation and are implicated in numerous diseases. Database searching remains the standard for identifying modified peptides from tandem mass spectra, but is hindered by the combinatorial expansion of modification types and sites. De novo peptide sequencing offers an attractive alternative, yet existing methods remain limited to unmodified peptides or a narrow set of PTMs. Here, we curated a large dataset of spectra from endogenous and synthetic peptides from ProteomeTools spanning 19 biologically relevant amino acid-PTM combinations, covering phosphorylation, acetylation, and ubiquitination. We used this dataset to develop Modanovo, an extension of the Casanovo transformer architecture for de novo peptide sequencing. Modanovo achieved robust performance across these amino acid-PTM combinations (median area under the precision-coverage curve 0.92), while maintaining performance on unmodified peptides (0.93), nearly identical to Casanovo (0.94). The model outperformed {pi}-PrimeNovo-PTM and showed increased precision and complementarity to the database search tool MSFragger. Robustness was confirmed across independent datasets, particularly at peptide lengths frequently represented in the curated dataset. Applied to a phosphoproteomics dataset from monkeypox virus-infected cells, Modanovo recovered numerous confident peptides not reported by database search, including new viral phosphosites supported by spectral evidence, thereby demonstrating its complementarity to database-driven identification approaches. These results establish Modanovo as a broadly applicable model for comprehensive de novo sequencing of both modified and unmodified peptides.','https://www.biorxiv.org/content/10.1101/2025.09.12.675784v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(11,'Advancing Proteomic Analyses with Graph-Based Deep Learning: Protein Inference and DIA De Novo Peptide Sequencing','2025-08-15',NULL,'PhD thesis',NULL,'https://dspacemainprd01.lib.uwaterloo.ca/server/api/core/bitstreams/2cd3373a-a4cd-4536-8cec-464a86330205/content',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(12,'Improvements to CasaNovo, a deep learning de novo peptide sequencer','2025-07-25','10.1101/2025.07.25.666826','Cold Spring Harbor Laboratory','Casanovo is a state-of-the-art deep learning model for de novo peptide sequencing from mass spectrometry proteomics data. Here we report on a series of enhancements to Casanovo, aimed at improving the interpretability of the scores assigned to predicted peptides, generalizing the software for use in database search, speeding up training and prediction runtimes, and providing workflows and visualization tools to facilitate adoption of Casanovo and interpretation of its results. Our goal is to make Casanovo accurate and easy to use for applications such as metaproteomics, antibody sequencing, immunopeptidomics, and discovery of novel peptide sequences in standard proteomics analyses. Casanovo is available as open source at https://github.com/Noble-Lab/casanovo.','https://www.biorxiv.org/content/10.1101/2025.07.25.666826v1','bioRxiv','preprint','v5','biorxiv');
INSERT INTO publication VALUES(13,'DiffNovo: A Transformer-Diffusion Model for De Novo Peptide Sequencing','2025-07-24','10.1007/978-3-031-94039-2_8','Bioinformatics and Computational Biology: 17th International Conference','Accurate identification of peptides from Data-Independent Acquisition (DIA) mass spectrometry data is crucial for discovering novel peptides and proteins. In this study, we introduce DiffNovo, which integrates transformer-based architectures with a diffusion model to enhance de novo peptide sequencing for DIA data. The experimental results demonstrate that DiffNovo outperforms existing state-of-the-art models in recall and precision for de novo peptide identification. DiffNovo achieves an average improvement of 20.7% in amino acid precision and an increase of 57.2% in peptide precision across various datasets. These substantial gains highlight the efficacy of DiffNovo in delivering accurate peptide sequencing from DIA mass spectrometry data.','https://link.springer.com/chapter/10.1007/978-3-031-94039-2_8','Bioinformatics and Computational Biology (BICOB 2025)','peer-reviewed',NULL,'pdf');
INSERT INTO publication VALUES(14,'Zero-Shot De Novo Peptide Sequencing with Open Post-Translational Modification Discovery','2025-06-27','10.21203/rs.3.rs-6950964/v1','Research Square','Proteins play essential roles in biology, yet identifying their precise sequences and modifications remains challenging. De novo peptide sequencing offers a powerful solution by directly inferring sequences from mass spectrometry data without relying on protein databases. Recent deep learning models have significantly advanced this task but remain trapped in a major dilemma: they require labeled training data to recognize post-translational modifications (PTMs), which is unavailable for most biologically relevant but rare or unknown modifications. We solve this long-standing problem by introducing RNovA, a transformer-based de novo sequencing algorithm enhanced with relative positional embeddings and reinforcement learning. RNovA enables open PTM discovery in a zero-shot setting—without retraining or a predefined list of candidate residues—while maintaining state-of-the-art performance on standard benchmarks. Demonstrating this capability, we successfully identified peptides modified by kynurenine—an uncommon and biologically relevant PTM—in clinical samples from rheumatoid arthritis patients. RNovA overcomes key limitations of existing methods and enables the exploration of the “dark proteome,” including novel proteins and unexpected modifications. This capability is widely needed in immunology, biomarker discovery, and biomedical research.','https://www.researchsquare.com/article/rs-6950964/v1','Research Square','preprint',NULL,'crossref');
INSERT INTO publication VALUES(15,'MassNet: billion-scale AI-friendly mass spectral corpus enables robust de novo peptide sequencing','2025-06-20','10.1101/2025.06.20.660691','Cold Spring Harbor Laboratory','Breakthroughs in artificial intelligence (AI) for natural language processing and computer vision have been largely driven by high-quality, large-scale datasets such as OpenWebText and ImageNet. Inspired by this, we present MassNet, a foundational resource for proteomics designed to accelerate deep learning applications. MassNet is the largest known corpus of data-dependent acquisition (DDA) mass spectrometry (MS) data, derived from ~30 TB of raw files and comprising 1.54 billion MS/MS spectra, resulting in 558 million peptide-spectrum matches (PSMs) across 35 species, including animals, plants, and microbes. Within the human subset, MassNet includes more than 1.7 million precursors and 19,966 proteins, covering 98% of annotated human proteins. To enable efficient AI training, we developed the Mass Spectrometry Data Tensor (MSDT), a structured format based on Parquet that enables standardized, high-performance batch access and seamless integration with GPU and TPU platforms for distributed training. We further extended MassNet to support de novo peptide sequencing, which infers peptide sequences directly from MS/MS spectra without reference databases, and is critical for discovering novel proteins, characterizing non-model organisms, and identifying post-translational modifications (PTMs). We introduce XuanjiNovo, a non-autoregressive Transformer model that leverages a curriculum learning strategy to enhance training stability. By dynamically adjusting learning difficulty based on model performance, XuanjiNovo achieves smooth convergence on complex, multi-distributional data without manual hyperparameter tuning. Trained on 100 million PSMs from the MassNet, it consistently outperforms state-of-the-art methods across diverse benchmarking tasks. Peptide recall exceeds 0.8 on the Bacteroides thetaiotaomicron and Zea mays datasets. On human data acquired using the Orbitrap Astral platform, XuanjiNovo achieves achieves 38.8% to 144.3% improvement over existing models. MassNet represents the first large-scale, standardized foundational dataset in proteomics, marking a critical milestone in the integration of artificial intelligence into proteomics research.','https://www.biorxiv.org/content/10.1101/2025.06.20.660691v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(16,'Curriculum Learning for Biological Sequence Prediction: The Case of De Novo Peptide Sequencing','2025-06-16','10.48550/arXiv.2506.13485','arXiv','Peptide sequencing-the process of identifying amino acid sequences from mass spectrometry data-is a fundamental task in proteomics. Non-Autoregressive Transformers (NATs) have proven highly effective for this task, outperforming traditional methods. Unlike autoregressive models, which generate tokens sequentially, NATs predict all positions simultaneously, leveraging bidirectional context through unmasked self-attention. However, existing NAT approaches often rely on Connectionist Temporal Classification (CTC) loss, which presents significant optimization challenges due to CTC''s complexity and increases the risk of training failures. To address these issues, we propose an improved non-autoregressive peptide sequencing model that incorporates a structured protein sequence curriculum learning strategy. This approach adjusts protein''s learning difficulty based on the model''s estimated protein generational capabilities through a sampling process, progressively learning peptide generation from simple to complex sequences. Additionally, we introduce a self-refining inference-time module that iteratively enhances predictions using learned NAT token embeddings, improving sequence accuracy at a fine-grained level. Our curriculum learning strategy reduces NAT training failures frequency by more than 90% based on sampled training over various data distributions. Evaluations on nine benchmark species demonstrate that our approach outperforms all previous methods across multiple metrics and species.','https://arxiv.org/abs/2506.13485','ICML 2025','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(17,'Latent Imputation before Prediction: A New Computational Paradigm for De Novo Peptide Sequencing','2025-05-23','10.48550/arXiv.2505.17524','arXiv','De novo peptide sequencing is a fundamental computational technique for ascertaining amino acid sequences of peptides directly from tandem mass spectrometry data, eliminating the need for reference databases. Cutting-edge models usually encode the observed mass spectra into latent representations from which peptides are predicted autoregressively. However, the issue of missing fragmentation, attributable to factors such as suboptimal fragmentation efficiency and instrumental constraints, presents a formidable challenge in practical applications. To tackle this obstacle, we propose a novel computational paradigm called \underline{\textbf{L}}atent \underline{\textbf{I}}mputation before \underline{\textbf{P}}rediction (LIPNovo). LIPNovo is devised to compensate for missing fragmentation information within observed spectra before executing the final peptide prediction. Rather than generating raw missing data, LIPNovo performs imputation in the latent space, guided by the theoretical peak profile of the target peptide sequence. The imputation process is conceptualized as a set-prediction problem, utilizing a set of learnable peak queries to reason about the relationships among observed peaks and directly generate the latent representations of theoretical peaks through optimal bipartite matching. In this way, LIPNovo manages to supplement missing information during inference and thus boosts performance. Despite its simplicity, experiments on three benchmark datasets demonstrate that LIPNovo outperforms state-of-the-art methods by large margins. Code is available at \href{https://github.com/usr922/LIPNovo}{https://github.com/usr922/LIPNovo}.','https://arxiv.org/abs/2505.17524','ICML 2025','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(18,'A transformer-based semi-autoregressive framework for high-speed and accurate de novo peptide sequencing','2025-02-14','10.1038/s42003-025-07584-0','Springer Science and Business Media LLC','De novo peptide sequencing directly identifies peptides from mass spectrometry data, playing a critical role in discovering novel proteins and analyzing complex biological samples without reliance on existing databases. To address challenges in both speed and accuracy, a transformer-based model, TSARseqNovo, incorporates two key innovations: a Semi-Autoregressive decoder for parallel prediction of multiple amino acids and a Masking Refinement decoder for refining low-confidence predictions. These features significantly enhance sequencing efficiency and accuracy. Evaluations on the Nine-Species, Aggregated, and Glycoproteomic datasets, demonstrate that TSARseqNovo outperforms state-of-the-art models, including CasaNovo, NovoB, InstaNovo + , and π-HelixNovo. Specifically, TSARseqNovo achieves up to a 2-fold speed increase over CasaNovo and π-HelixNovo, and approximately 10-fold over NovoB and InstaNovo + , while also showing substantial improvements in peptide prediction precision, especially for long peptides. These advancements position TSARseqNovo as a powerful tool for accelerating high-throughput proteomics research and addressing increasingly complex biological questions. A novel model for analyzing complex biological samples without reliance on databases has been proposed, demonstrating a 2- to 10-fold increase in speed and improved peptide identification precision compared to the current state-of-the-art model.','https://doi.org/10.1038/s42003-025-07584-0','Communications Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(19,'XA-Novo: an accurate and high-throughput mass spectrometry-based de novo sequencing technology for monoclonal antibodies and antibody mixtures','2026-02-15','10.1038/s41467-026-70496-y','Springer Science and Business Media LLC','Elucidating antibody sequences by mass spectrometry-based de novo sequencing is essential but remains technically challenging. Here we present XA-Novo, an accurate and high-throughput de novo sequencing solution that integrates a single-pot multi-enzymatic gradient digestion method with a beam search-based assembler (Fusion) to reconstruct full-length antibody sequences directly from bottom-up mass spectrometry data. Benchmarking across well-characterized antibodies from multiple species demonstrates that XA-Novo outperforms commercial solutions in identification sensitivity, sequence completeness, and reconstruction accuracy. Furthermore, XA-Novo successfully reconstructs six immunotherapeutic antibodies with unknown sequences, and in vitro/vivo assays validate that these generated antibodies exhibit functionality equivalent to their commercial counterparts. Moreover, XA-Novo achieves over 99.54% accurate sequence coverage in distinguishing mixed COVID-19 neutralizing antibodies, exceeding the performance of current assemblers reported for single-antibody sequencing. Overall, XA-Novo establishes a reliable, scalable, and broadly applicable workflow for routine antibody sequencing, thereby accelerating both fundamental antibody research and therapeutic antibody development.','https://www.nature.com/articles/s41467-026-70496-y','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(20,'Distilling Non-Autoregressive Model Knowledge for Autoregressive De Novo Peptide Sequencing','2025-02-05',NULL,'OpenReview',NULL,'https://openreview.net/forum?id=I2ZYngkRW6','ICLR 2025','preprint',NULL,NULL);
INSERT INTO publication VALUES(21,'π-PrimeNovo: an accurate and efficient non-autoregressive deep learning model for de novo peptide sequencing','2025-01-02','10.1038/s41467-024-55021-3','Springer Science and Business Media LLC','Peptide sequencing via tandem mass spectrometry (MS/MS) is essential in proteomics. Unlike traditional database searches, deep learning excels at de novo peptide sequencing, even for peptides missing from existing databases. Current deep learning models often rely on autoregressive generation, which suffers from error accumulation and slow inference speeds. In this work, we introduce π-PrimeNovo, a non-autoregressive Transformer-based model for peptide sequencing. With our architecture design and a CUDA-enhanced decoding module for precise mass control, π-PrimeNovo achieves significantly higher accuracy and up to 89x faster inference than state-of-the-art methods, making it ideal for large-scale applications like metaproteomics. Additionally, it excels in phosphopeptide mining and detecting low-abundance post-translational modifications (PTMs), marking a substantial advance in peptide sequencing with broad potential in biological research.','https://doi.org/10.1038/s41467-024-55021-3','Nature Communications','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(22,'ReNovo: Retrieval-Based De Novo Mass Spectrometry Peptide Sequencing','2024-11-27',NULL,'OpenReview','Proteomics is the large-scale study of proteins. Tandem mass spectrometry, as the only high-throughput technique for protein sequence identification, plays a pivotal role in proteomics research. One of the long-standing challenges in this field is peptide identification, which entails determining the specific peptide (sequence of amino acids) that corresponds to each observed mass spectrum. The conventional approach involves database searching, wherein the observed mass spectrum is scored against a pre-constructed peptide database. However, the reliance on pre-existing databases limits applicability in scenarios where the peptide is absent from existing databases. Such circumstances necessitate de novo peptide sequencing, which derives peptide sequence solely from input mass spectrum, independent of any peptide database. Despite ongoing advancements in de novo peptide sequencing, its performance still has considerable room for improvement, which limits its application in large-scale experiments. In this study, we introduce a novel Retrieval-based De Novo peptide sequencing methodology, termed ReNovo, which draws inspiration from database search methods. Specifically, by constructing a datastore from training data, ReNovo can retrieve information from the datastore during the inference stage to conduct retrieval-based inference, thereby achieving improved performance. This innovative approach enables ReN- ovo to effectively combine the strengths of both methods: utilizing the assistance of the datastore while also being capable of predicting novel peptides that are not present in pre-existing databases. A series of experiments have confirmed that ReNovo outperforms state-of-the-art models across multiple widely-used datasets, incurring only minor storage and time consumption, representing a significant advancement in proteomics. Supplementary materials include the code.','https://openreview.net/forum?id=uQnvYP7yX9','ICLR 2025','ML conference',NULL,'pdf');
INSERT INTO publication VALUES(23,'Disentangling the Complex Multiplexed DIA Spectra in De Novo Peptide Sequencing','2024-11-24','10.48550/arXiv.2411.15684','arXiv','Data-Independent Acquisition (DIA) was introduced to improve sensitivity to cover all peptides in a range rather than only sampling high-intensity peaks as in Data-Dependent Acquisition (DDA) mass spectrometry. However, it is not very clear how useful DIA data is for de novo peptide sequencing as the DIA data are marred with coeluted peptides, high noises, and varying data quality. We present a new deep learning method DIANovo, and address each of these difficulties, and improves the previous established systems by a large margin, via equipping the model with a deeper understanding of coeluted DIA spectra. This paper also provides criteria about when DIA data could be used for de novo peptide sequencing and when not to by providing a comparison between DDA and DIA, in both de novo and database search mode. We find that while DIA excels with narrow isolation windows on older-generation instruments, it loses its advantage with wider windows. However, with Orbitrap Astral, DIA consistently outperforms DDA due to narrow window mode enabled. We also provide a theoretical explanation of this phenomenon, emphasizing the critical role of the signal-to-noise profile in the successful application of de novo sequencing.','https://arxiv.org/abs/2411.15684','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(24,'RankNovo: A Universal Reranking Approach for Robust De Novo Peptide Sequencing','2024-11-20',NULL,'OpenReview',NULL,'https://openreview.net/forum?id=87B3zDRMjv','ICLR 2025','ML conference',NULL,NULL);
INSERT INTO publication VALUES(25,'Transforming de novo peptide sequencing by explainable AI','2024-08-05','10.21203/rs.3.rs-4716013/v1','Research Square','De novo peptide sequencing is crucial for identifying novel proteins, yet its broader application is constrained by the lack of a robust quality control system. In response, we developed a transformer-based model, π-xNovo, that accurately predicts peptides. By analyzing the model''s attention matrix, we elucidated the contribution of spectral peaks to amino acid predictions, thus making de novo sequencing results explainable. Leveraging these insights, we designed a quality control system, π-xNovo-QC, which distinguishes peptide predictions with an accuracy exceeding 80% and a sensitivity above 90%. Applying this system to a large-scale deep human proteome dataset resulted in the identification of 1,931,761 additional peptides, marking a 137% increase over traditional database search results. These newly identified peptides with high confidence facilitated a 17.9% increase in protein identification, a 23.59% increase in the detection of single amino acid polymorphism events, and a 20.02% increase in exon-skipping splicing events. The deployment of this explainable AI system holds significant potential for expanding the application of de novo peptide sequencing, particularly in exploring the darker matter of the entire proteome universe.','https://www.researchsquare.com/article/rs-4716013/v1','Research Square','preprint',NULL,NULL);
INSERT INTO publication VALUES(26,'Sequence-to-sequence translation from mass spectra to peptides with a transformer model','2024-07-30','10.1038/s41467-024-49731-x','Springer Science and Business Media LLC','A fundamental challenge in mass spectrometry-based proteomics is the identification of the peptide that generated each acquired tandem mass spectrum. Approaches that leverage known peptide sequence databases cannot detect unexpected peptides and can be impractical or impossible to apply in some settings. Thus, the ability to assign peptide sequences to tandem mass spectra without prior information-de novo peptide sequencing-is valuable for tasks including antibody sequencing, immunopeptidomics, and metaproteomics. Although many methods have been developed to address this problem, it remains an outstanding challenge in part due to the difficulty of modeling the irregular data structure of tandem mass spectra. Here, we describe Casanovo, a machine learning model that uses a transformer neural network architecture to translate the sequence of peaks in a tandem mass spectrum into the sequence of amino acids that comprise the generating peptide. We train a Casanovo model from 30 million labeled spectra and demonstrate that the model outperforms several state-of-the-art methods on a cross-species benchmark dataset. We also develop a version of Casanovo that is fine-tuned for non-enzymatic peptides. Finally, we demonstrate that Casanovo''s superior performance improves the analysis of immunopeptidomics and metaproteomics experiments and allows us to delve deeper into the dark proteome.','https://doi.org/10.1038/s41467-024-49731-x','Nature Communications','peer-reviewed','v2','openalex');
INSERT INTO publication VALUES(27,'TransNovo','2024-07-15',NULL,NULL,NULL,'https://github.com/ThatMatin/TransNovo',NULL,'preprint',NULL,NULL);
INSERT INTO publication VALUES(28,'PowerNovo: de novo peptide sequencing via tandem mass spectrometry using an ensemble of transformer and BERT models','2024-07-01','10.1038/s41598-024-65861-0','Springer Science and Business Media LLC','The primary objective of analyzing the data obtained in a mass spectrometry-based proteomic experiment is peptide and protein identification, or correct assignment of the tandem mass spectrum to one amino acid sequence. Comparison of empirical fragment spectra with the theoretical predicted one or matching with the collected spectra library are commonly accepted strategies of proteins identification and defining of their amino acid sequences. Although these approaches are widely used and are appreciably efficient for the well-characterized model organisms or measured proteins, they cannot detect novel peptide sequences that have not been previously annotated or are rare. This study presents PowerNovo tool for de novo sequencing of proteins using tandem mass spectra acquired in a variety of types of mass analyzers and different fragmentation techniques. PowerNovo involves an ensemble of models for peptide sequencing: model for detecting regularities in tandem mass spectra, precursors, and fragment ions and a natural language processing model, which has a function of peptide sequence quality assessment and helps with reconstruction of noisy sequences. The results of testing showed that the performance of PowerNovo is comparable and even better than widely utilized PointNovo, DeepNovo, Casanovo, and Novor packages. Also, PowerNovo provides complete cycle of processing (pipeline) of mass spectrometry data and, along with predicting the peptide sequence, involves the peptide assembly and protein inference blocks.','https://doi.org/10.1038/s41598-024-65861-0','Scientific Reports','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(29,'A transformer model for de novo sequencing of data independent acquisition mass spectrometry data','2025-07-01','10.1038/s41592-025-02718-y','Springer Science and Business Media LLC','A core computational challenge in the analysis of mass spectrometry data is the de novo sequencing problem, in which the generating amino acid sequence is inferred directly from an observed fragmentation spectrum without the use of a sequence database. Recently, deep learning models have made substantial advances in de novo sequencing by learning from massive datasets of high-confidence labeled mass spectra. However, these methods are designed primarily for data-dependent acquisition experiments. Over the past decade, the field of mass spectrometry has been moving toward using data-independent acquisition (DIA) protocols for the analysis of complex proteomic samples owing to their superior specificity and reproducibility. Hence, we present a de novo sequencing model called Cascadia, which uses a transformer architecture to handle the more complex data generated by DIA protocols. In comparisons with existing approaches for de novo sequencing of DIA data, Cascadia achieves substantially improved performance across a range of instruments and experimental protocols.','https://www.nature.com/articles/s41592-025-02718-y','Nature Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(30,'Transformer-Based De Novo Peptide Sequencing for Data-Independent Acquisition Mass Spectrometry','2024-02-17','10.48550/arXiv.2402.11363','arXiv','Tandem mass spectrometry (MS/MS) stands as the predominant high-throughput technique for comprehensively analyzing protein content within biological samples. This methodology is a cornerstone driving the advancement of proteomics. In recent years, substantial strides have been made in Data-Independent Acquisition (DIA) strategies, facilitating impartial and non-targeted fragmentation of precursor ions. The DIA-generated MS/MS spectra present a formidable obstacle due to their inherent high multiplexing nature. Each spectrum encapsulates fragmented product ions originating from multiple precursor peptides. This intricacy poses a particularly acute challenge in de novo peptide/protein sequencing, where current methods are ill-equipped to address the multiplexing conundrum. In this paper, we introduce DiaTrans, a deep-learning model based on transformer architecture. It deciphers peptide sequences from DIA mass spectrometry data. Our results show significant improvements over existing STOA methods, including DeepNovo-DIA and PepNet. Casanovo-DIA enhances precision by 15.14% to 34.8%, recall by 11.62% to 31.94% at the amino acid level, and boosts precision by 59% to 81.36% at the peptide level. Integrating DIA data and our DiaTrans model holds considerable promise to uncover novel peptides and more comprehensive profiling of biological samples. Casanovo-DIA is freely available under the GNU GPL license at https://github.com/Biocomputing-Research-Group/DiaTrans.','https://arxiv.org/abs/2402.11363','arXiv','postprint',NULL,'arxiv');
INSERT INTO publication VALUES(31,'pXg: Comprehensive Identification of Noncanonical MHC-I-Associated Peptides From De Novo Peptide Sequencing Using RNA-Seq Reads','2024-04-01','10.1016/j.mcpro.2024.100743','Molecular and Cellular Proteomics','Discovering noncanonical peptides has been a common application of proteogenomics. Recent studies suggest that certain noncanonical peptides, known as noncanonical major histocompatibility complex-I (MHC-I)-associated peptides (ncMAPs), that bind to MHC-I may make good immunotherapeutic targets. De novo peptide sequencing is a great way to find ncMAPs since it can detect peptide sequences from their tandem mass spectra without using any sequence databases. However, this strategy has not been widely applied for ncMAP identification because there is not a good way to estimate its false-positive rates. In order to completely and accurately identify immunopeptides using de novo peptide sequencing, we describe a unique pipeline called proteomics X genomics. In contrast to current pipelines, it makes use of genomic data, RNA-Seq abundance and sequencing quality, in addition to proteomic features to increase the sensitivity and specificity of peptide identification. We show that the peptide-spectrum match quality and genetic traits have a clear relationship, showing that they can be utilized to evaluate peptide-spectrum matches. From 10 samples, we found 24,449 canonical MHC-I-associated peptides and 956 ncMAPs by using a target-decoy competition. Three hundred eighty-seven ncMAPs and 1611 canonical MHC-I-associated peptides were new identifications that had not yet been published. We discovered 11 ncMAPs produced from a squirrel monkey retrovirus in human cell lines in addition to the two ncMAPs originating from a complementarity determining region 3 in an antibody thanks to the unrestricted search space assumed by de novo sequencing. These entirely new identifications show that proteomics X genomics can make the most of de novo peptide sequencing''s advantages and its potential use in the search for new immunotherapeutic targets.','https://doi.org/10.1016/j.mcpro.2024.100743','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(32,'AdaNovo: Adaptive De Novo Peptide Sequencing with Conditional Mutual Information','2024-03-09','10.48550/arXiv.2403.07013','arXiv','Tandem mass spectrometry has played a pivotal role in advancing proteomics, enabling the analysis of protein composition in biological samples. Despite the development of various deep learning methods for identifying amino acid sequences (peptides) responsible for observed spectra, challenges persist in \emph{de novo} peptide sequencing. Firstly, prior methods struggle to identify amino acids with post-translational modifications (PTMs) due to their lower frequency in training data compared to canonical amino acids, further resulting in decreased peptide-level identification precision. Secondly, diverse types of noise and missing peaks in mass spectra reduce the reliability of training data (peptide-spectrum matches, PSMs). To address these challenges, we propose AdaNovo, a novel framework that calculates conditional mutual information (CMI) between the spectrum and each amino acid/peptide, using CMI for adaptive model training. Extensive experiments demonstrate AdaNovo''s state-of-the-art performance on a 9-species benchmark, where the peptides in the training set are almost completely disjoint from the peptides of the test sets. Moreover, AdaNovo excels in identifying amino acids with PTMs and exhibits robustness against data noise. The supplementary materials contain the official code.','https://arxiv.org/abs/2403.07013','ICML 2024','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(33,'Bidirectional de novo peptide sequencing using a transformer model','2024-02-28','10.1371/journal.pcbi.1011892','PLoS Computational Biology','In proteomics, a crucial aspect is to identify peptide sequences. De novo sequencing methods have been widely employed to identify peptide sequences, and numerous tools have been proposed over the past two decades. Recently, deep learning approaches have been introduced for de novo sequencing. Previous methods focused on encoding tandem mass spectra and predicting peptide sequences from the first amino acid onwards. However, when predicting peptides using tandem mass spectra, the peptide sequence can be predicted not only from the first amino acid but also from the last amino acid due to the coexistence of b-ion (or a- or c-ion) and y-ion (or x- or z-ion) fragments in the tandem mass spectra. Therefore, it is essential to predict peptide sequences bidirectionally. Our approach, called NovoB, utilizes a Transformer model to predict peptide sequences bidirectionally, starting with both the first and last amino acids. In comparison to Casanovo, our method achieved an improvement of the average peptide-level accuracy rate of approximately 9.8% across all species.','https://doi.org/10.1371/journal.pcbi.1011892','PLOS Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(34,'Introducing π-HelixNovo for practical large-scale de novo peptide sequencing','2024-02-10','10.1093/bib/bbae021','Oxford University Press (OUP)','De novo peptide sequencing is a promising approach for novel peptide discovery, highlighting the performance improvements for the state-of-the-art models. The quality of mass spectra often varies due to unexpected missing of certain ions, presenting a significant challenge in de novo peptide sequencing. Here, we use a novel concept of complementary spectra to enhance ion information of the experimental spectrum and demonstrate it through conceptual and practical analyses. Afterward, we design suitable encoders to encode the experimental spectrum and the corresponding complementary spectrum and propose a de novo sequencing model $\pi$-HelixNovo based on the Transformer architecture. We first demonstrated that $\pi$-HelixNovo outperforms other state-of-the-art models using a series of comparative experiments. Then, we utilized $\pi$-HelixNovo to de novo gut metaproteome peptides for the first time. The results show $\pi$-HelixNovo increases the identification coverage and accuracy of gut metaproteome and enhances the taxonomic resolution of gut metaproteome. We finally trained a powerful $\pi$-HelixNovo utilizing a larger training dataset, and as expected, $\pi$-HelixNovo achieves unprecedented performance, even for peptide-spectrum matches with never-before-seen peptide sequences. We also use the powerful $\pi$-HelixNovo to identify antibody peptides and multi-enzyme cleavage peptides, and $\pi$-HelixNovo is highly robust in these applications. Our results demonstrate the effectivity of the complementary spectrum and take a significant step forward in de novo peptide sequencing.','https://academic.oup.com/bib/article/25/2/bbae021/7604886','Briefings in Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(35,'A learned score function improves the power of mass spectrometry database search','2024-01-26','10.1101/2024.01.26.577425','Cold Spring Harbor Laboratory','One of the core problems in the analysis of protein tandem mass spectrometry data is the peptide assignment problem: determining, for each observed spectrum, the peptide sequence that was responsible for generating the spectrum. Two primary classes of methods are used to solve this problem: database search and de novo peptide sequencing. State-of-the-art methods for de novo sequencing employ machine learning methods, whereas most database search engines use hand-designed score functions to evaluate the quality of a match between an observed spectrum and a candidate peptide from the database. We hypothesize that machine learning models for de novo sequencing implicitly learn a score function that captures the relationship between peptides and spectra, and thus may be re-purposed as a score function for database search. Because this score function is trained from massive amounts of mass spectrometry data, it could potentially outperform existing, hand-designed database search tools. To test this hypothesis, we re-engineered Casanovo, which has been shown to provide state-of-the-art de novo sequencing capabilities, to assign scores to given peptide-spectrum pairs. We then evaluated the statistical power of this Casanovo score function, Casanovo-DB, to detect peptides on a benchmark of three mass spectrometry runs from three different species. Our results show that, at a 1% peptide-level false discovery rate threshold, Casanovo-DB outperforms existing hand-designed score functions by 35% to 88%. In addition, we show that re-scoring with the Percolator post-processor benefits Casanovo-DB more than other score functions, further increasing the number of detected peptides.','https://www.biorxiv.org/content/10.1101/2024.01.26.577425v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(36,'MARS an improved de novo peptide candidate selection method for non-canonical antigen target discovery in cancer','2024-01-22','10.1038/s41467-023-44460-z','Springer Science and Business Media LLC','Understanding the nature and extent of non-canonical human leukocyte antigen (HLA) presentation in tumour cells is a priority for target antigen discovery for the development of next generation immunotherapies in cancer. We here employ a de novo mass spectrometric sequencing approach with a refined, MHC-centric analysis strategy to detect non-canonical MHC-associated peptides specific to cancer without any prior knowledge of the target sequence from genomic or RNA sequencing data. Our strategy integrates MHC binding rank, Average local confidence scores, and peptide Retention time prediction for improved de novo candidate Selection; culminating in the machine learning model MARS. We benchmark our model on a large synthetic peptide library dataset and reanalysis of a published dataset of high-quality non-canonical MHC-associated peptide identifications in human cancer. We achieve almost 2-fold improvement for high quality spectral assignments in comparison to de novo sequencing alone with an estimated accuracy of above 85.7% when integrated with a stepwise peptide sequence mapping strategy. Finally, we utilize MARS to detect and validate lncRNA-derived peptides in human cervical tumour resections, demonstrating its suitability to discover novel, immunogenic, non-canonical peptide sequences in primary tumour tissue.','https://doi.org/10.1038/s41467-023-44460-z','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(37,'Deep learning-driven fragment ion series classification enables highly precise and sensitive de novo peptide sequencing','2024-01-02','10.1038/s41467-023-44323-7','Springer Science and Business Media LLC','Unlike for DNA and RNA, accurate and high-throughput sequencing methods for proteins are lacking, hindering the utility of proteomics in applications where the sequences are unknown including variant calling, neoepitope identification, and metaproteomics. We introduce Spectralis, a de novo peptide sequencing method for tandem mass spectrometry. Spectralis leverages several innovations including a convolutional neural network layer connecting peaks in spectra spaced by amino acid masses, proposing fragment ion series classification as a pivotal task for de novo peptide sequencing, and a peptide-spectrum confidence score. On spectra for which database search provided a ground truth, Spectralis surpassed 40% sensitivity at 90% precision, nearly doubling state-of-the-art sensitivity. Application to unidentified spectra confirmed its superiority and showcased its applicability to variant calling. Altogether, these algorithmic innovations and the substantial sensitivity increase in the high-precision range constitute an important step toward broadly applicable peptide sequencing.','https://doi.org/10.1038/s41467-023-44323-7','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(38,'ContraNovo: A Contrastive Learning Approach to Enhance De Novo Peptide Sequencing','2024-03-24','10.1609/aaai.v38i1.27765','AAAI Press','De novo peptide sequencing from mass spectrometry (MS) data is a critical task in proteomics research. Traditional de novo algorithms have encountered a bottleneck in accuracy due to the inherent complexity of proteomics data. While deep learning-based methods have shown progress, they reduce the problem to a translation task, potentially overlooking critical nuances between spectra and peptides. In our research, we present ContraNovo, a pioneering algorithm that leverages contrastive learning to extract the relationship between spectra and peptides and incorporates the mass information into peptide decoding, aiming to address these intricacies more efficiently. Through rigorous evaluations on two benchmark datasets, ContraNovo consistently outshines contemporary state-of-the-art solutions, underscoring its promising potential in enhancing de novo peptide sequencing.','https://ojs.aaai.org/index.php/AAAI/article/view/27765','AAAI 2024','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(39,'Accurate de novo peptide sequencing using fully convolutional neural networks','2023-12-02','10.1038/s41467-023-43010-x','Springer Science and Business Media LLC','De novo peptide sequencing, which does not rely on a comprehensive target sequence database, provides us with a way to identify novel peptides from tandem mass spectra. However, current de novo sequencing algorithms suffer from low accuracy and coverage, which hinders their application in proteomics. In this paper, we present PepNet, a fully convolutional neural network for high accuracy de novo peptide sequencing. PepNet takes an MS/MS spectrum (represented as a high-dimensional vector) as input, and outputs the optimal peptide sequence along with its confidence score. The PepNet model is trained using a total of 3 million high-energy collisional dissociation MS/MS spectra from multiple human peptide spectral libraries. Evaluation results show that PepNet significantly outperforms current best-performing de novo sequencing algorithms (e.g. PointNovo and DeepNovo) in both peptide-level accuracy and positional-level accuracy. PepNet can sequence a large fraction of spectra that were not identified by database search engines, and thus could be used as a complementary tool to database search engines for peptide identification in proteomics. In addition, PepNet runs around 3x and 7x faster than PointNovo and DeepNovo on GPUs, respectively, thus being more suitable for the analysis of large-scale proteomics data.','https://doi.org/10.1038/s41467-023-43010-x','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(40,'A complete mass spectrometry-based immunopeptidomics pipeline for neoantigen identification and validation','2023-11-09','10.21203/rs.3.rs-3520814/v1','Research Square','Here we proposed DeepImmu, a complete pipeline for neoantigen identification and validation that was based solely on mass spectrometry (MS) immunopeptidomics. In particular, a new enrichment kit was developed for HLA peptide purification from a small amount of biopsied tissue as low as 18mg. To identify candidate neoantigens from such a small amount of sample, we built DeepNovo Peptidome, a highly sensitive de novo sequencing-based workflow for HLA peptide identification. Furthermore, we developed DeepSelf, a personalized model for immunogenicity prediction based on the central tolerance of T cells, which could be used to prioritize candidate neoantigens from de novo HLA peptides for in vitro validation. Finally, we presented a new MS-based immunopeptidomics study of native tumor tissues from five patients with cervical cancer. We applied DeepImmu pipeline to identify and prioritize candidate neoantigens from low amounts of tumor tissues, and then performed in vitro validation of autologous neoantigen-specific T cell responses to confirm our results. Our MS-based de novo sequencing approach provides an unbiased solution for neoantigen discovery, because it does not depend on prior knowledge of protein databases, RNA sequencing data, or the source of neoantigens. By reducing the amount of sample to biopsy size, our DeepImmu pipeline can be easily performed in routine clinical applications.','https://www.researchsquare.com/article/rs-3520814/v1','Research Square','preprint',NULL,'crossref');
INSERT INTO publication VALUES(41,'Mitigating the missing-fragmentation problem in de novo peptide sequencing with a two-stage graph-based deep learning model','2023-10-19','10.1038/s42256-023-00738-x','Springer Science and Business Media LLC',NULL,'https://doi.org/10.1038/s42256-023-00738-x','Nature Machine Intelligence','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(42,'SeqNovo: De Novo Peptide Sequencing Prediction in IoMT via Seq2Seq','2023-10-04','10.1109/JBHI.2023.3321780','Institute of Electrical and Electronics Engineers (IEEE)','In the Internet of Medical Things (IoMT), de novo peptide sequencing prediction is one of the most important techniques for the fields of disease prediction, diagnosis, and treatment. Recently, deep-learning-based peptide sequencing prediction has been a new trend. However, most popular deep learning models for peptide sequencing prediction suffer from poor interpretability and poor ability to capture long-range dependencies. To solve these issues, we propose a model named SeqNovo, which has the encoding-decoding structure of sequence to sequence (Seq2Seq), the highly nonlinear properties of multilayer perceptron (MLP), and the ability of the attention mechanism to capture long-range dependencies. SeqNovo use MLP to improve the feature extraction and utilize the attention mechanism to discover key information. A series of experiments have been conducted to show that the SeqNovo is superior to the Seq2Seq benchmark model, DeepNovo. SeqNovo improves both the accuracy and interpretability of the predictions, which will be expected to support more related research.','https://ieeexplore.ieee.org/document/10271529','IEEE Journal of Biomedical and Health Informatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(43,'Glycopeptide database search and de novo sequencing with PEAKS GlycanFinder enable highly sensitive glycoproteomics','2023-07-08','10.1038/s41467-023-39699-5','Springer Science and Business Media LLC','Here we present GlycanFinder, a database search and de novo sequencing tool for the analysis of intact glycopeptides from mass spectrometry data. GlycanFinder integrates peptide-based and glycan-based search strategies to address the challenge of complex fragmentation of glycopeptides. A deep learning model is designed to capture glycan tree structures and their fragment ions for de novo sequencing of glycans that do not exist in the database. We performed extensive analyses to validate the false discovery rates (FDRs) at both peptide and glycan levels and to evaluate GlycanFinder based on comprehensive benchmarks from previous community-based studies. Our results show that GlycanFinder achieved comparable performance to other leading glycoproteomics softwares in terms of both FDR control and the number of identifications. Moreover, GlycanFinder was also able to identify glycopeptides not found in existing databases. Finally, we conducted a mass spectrometry experiment for antibody N-linked glycosylation profiling that could distinguish isomeric peptides and glycans in four immunoglobulin G subclasses, which had been a challenging problem to previous studies.','https://doi.org/10.1038/s41467-023-39699-5','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(44,'DpNovo: A DEEP LEARNING MODEL COMBINED WITH DYNAMIC PROGRAMMING FOR DE NOVO PEPTIDE SEQUENCING','2023-07-07',NULL,'MSc thesis','De novo peptide sequencing is an efficient approach to identifying peptides from tandem mass spectrometry (MS/MS). Compared with the database search methods, De novo peptide sequencing is particularly effective in identifying novo peptide sequences. This thesis presents a new De novo sequencing model comprising two deep learning models and a dynamic programming algorithm, namely DpNovo. The deep learning model learns features of a spectrum and gives scores to each peak, and the dynamic programming is capable of determining the optimal amino acid sequence path with the highest accumulated score. Finally, the predicted sequence with mass values representing uncertain mass intervals will be provided. DpNovo is capable of reconstructing charge-two peaks in their charge-one positions, which significantly improves the accuracy of predicting high-charged spectra. Besides, the dynamic programming algorithm ensures that accurate predictions can be made even in cases where some signal peaks are missing. In terms of performance, DpNovo has been tested on both the NIST and ProteomeXchange databases. The deep learning model has demonstrated an excellent ability to identify both signal and noise peaks. Additionally, the accuracy of peptide sequence prediction obtained through the dynamic programming algorithm is comparable to those of other proposed De novo sequencing models.','https://uwo.scholaris.ca/items/84378bf5-f2d9-45d6-8264-10823888cb9a',NULL,'thesis',NULL,'pdf');
INSERT INTO publication VALUES(45,'BiATNovo: An Attention-based Bidirectional De Novo Sequencing Framework for Data-Independent-Acquisition Mass Spectrometry','2024-10-28',NULL,'Cold Spring Harbor Laboratory','De novo sequencing from tandem mass spectra (MS/MS) data is a key technique for identifying novel peptides. In theory, the Data-Independent Acquisition (DIA) method can fragment all precursor ions in an unbiased and non-targeted fashion. However, each spectrum contains fragments from multiple precursor ions, and the unclear relationship between these ions and their fragments poses a significant challenge to the accuracy of de novo sequencing algorithms. Here we present BiATNovo, an attention-based bidirectional de novo peptide sequencing framework. BiATNovo comprises a bidirectional attention-based model and a bidirectional fusion-reranking post-processing module, which enables efficient capture of relationships between tandem mass spectra, fragment ions, and peptide patterns, while also expanding the candidate set to select the optimal sequence. This framework improves peptide prediction accuracy, particularly for long peptide sequences, and mitigates the imbalance where the initial amino acids are predicted more accurately than the last ones. Evaluation results demonstrate that BiATNovo outperforms existing algorithms, including DeepNovo-DIA and PepNet, in both peptid-level and amino acid-level. Furthermore, when extended to DDA datasets, BiATNovo achieves comparable performance to state-of-the-art models.','https://www.biorxiv.org/content/10.1101/2023.05.11.540352v2','bioRxiv','preprint','v2','biorxiv');
INSERT INTO publication VALUES(46,'PGPointNovo: an efficient neural network-based tool for parallel de novo peptide sequencing','2023-04-25','10.1093/bioadv/vbad057','Oxford University Press (OUP)','Summary De novo peptide sequencing for tandem mass spectrometry data is not only a key technology for novel peptide identification, but also a precedent task for many downstream tasks, such as vaccine and antibody studies. In recent years, neural network models for de novo peptide sequencing have manifested a remarkable ability to accommodate various data sources and outperformed conventional peptide identification tools. However, the excellent model is computationally expensive, taking up to 1 week to process about 400 000 spectrums. This article presents PGPointNovo, a novel neural network-based tool for parallel de novo peptide sequencing. PGPointNovo uses data parallelization technology to accelerate training and inference and optimizes the training obstacles caused by large batch sizes. The results of extensive experiments conducted on multiple datasets of different sizes demonstrate that compared with PointNovo the excellent neural network-based de novo peptide sequencing tool, PGPointNovo, accelerates de novo peptide sequencing by up to 7.35× without precision or recall compromises. Availability and implementation The source code and the parameter settings are available at https://github.com/shallFun4Learning/PGPointNovo. Supplementary information Supplementary data are available at Bioinformatics Advances online.','https://doi.org/10.1093/bioadv/vbad057','Bioinformatics Advances','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(47,'PaSER Novor: Real-time de novo sequencing for 4D-Proteomics applications','2023-04-20',NULL,NULL,NULL,'https://www.bruker.com/en/news-and-events/news/2023/bruker-launches-de-novo-sequencing-for-immunopeptidomics.html',NULL,'preprint',NULL,NULL);
INSERT INTO publication VALUES(48,'Denovo-GCN: De Novo Peptide Sequencing by Graph Convolutional Neural Networks','2023-04-05','10.3390/app13074604','MDPI AG','The de novo peptide-sequencing method can be used to directly infer the peptide sequence from a tandem mass spectrum. It has the advantage of not relying on protein databases and plays a key role in the determination of the protein sequences of unknown species, monoclonal antibodies, and cancer neoantigens. In this paper, we propose a method based on graph convolutional neural networks and convolutional neural networks, Denovo-GCN, for de novo peptide sequencing. We constructed an undirected graph based on the mass difference between the spectral peaks in a tandem mass spectrum. The features of the nodes on the spectrum graph, which represent the spectral peaks, were the matching information of the peptide sequence and the mass spectrum. Next, the Denovo-GCN used CNN to extract the features of the nodes. The correlation between the nodes was represented by an adjacency matrix, which aggregated the features of neighboring nodes. Denovo-GCN provides a complete end-to-end training and prediction framework to sequence patterns of peptides. Our experiments on various data sets from different species show that Denovo-GCN outperforms DeepNovo with a relative improvement of 13.7–25.5% in terms of the peptide-level recall.','https://doi.org/10.3390/app13074604','Applied Sciences (MDPI)','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(49,'De novo mass spectrometry peptide sequencing with a transformer model','2022-02-07','10.1101/2022.02.07.479481','Cold Spring Harbor Laboratory','Tandem mass spectrometry is the only high-throughput method for analyzing the protein content of complex biological samples and is thus the primary technology driving the growth of the field of proteomics. A key outstanding challenge in this field involves identifying the sequence of amino acids--the peptide--responsible for generating each observed spectrum, without making use of prior knowledge in the form of a peptide sequence database. Although various machine learning methods have been developed to address this de novo sequencing problem, challenges that arise when modeling tandem mass spectra have led to complex models that combine multiple neural networks and post-processing steps. We propose a simple yet powerful method for de novo peptide sequencing, Casanovo, that uses a transformer framework to map directly from a sequence of observed peaks (a mass spectrum) to a sequence of amino acids (a peptide). Our experiments show that Casanovo achieves state-of-the-art performance on a benchmark dataset using a standard cross-species evaluation framework which involves testing with spectra with never-before-seen peptide labels. Casanovo not only achieves superior performance but does so at a fraction of the model complexity and inference time required by other methods.','https://www.biorxiv.org/content/10.1101/2022.02.07.479481v1','bioRxiv','preprint','v1','biorxiv');
INSERT INTO publication VALUES(50,'NovoRank: Refinement for De Novo Peptide Sequencing Based on Spectral Clustering and Deep Learning','2025-02-07','10.1021/acs.jproteome.4c00300','American Chemical Society (ACS)','De novo peptide sequencing is a valuable technique in mass-spectrometry-based proteomics, as it deduces peptide sequences directly from tandem mass spectra without relying on sequence databases. This database-independent method, however, relies solely on imperfect scoring functions that often lead to erroneous peptide identifications. To boost correct identification, we present NovoRank, a postprocessing tool that employs spectral clustering and machine learning to assign more plausible peptide sequences to spectra. Prior to de novo peptide sequencing, spectral clustering is applied to group similar spectra under the assumption that they originated from the same peptide species. NovoRank then employs a deep learning model, incorporating both cluster-derived proteomic features and individual spectrum characteristics, to rerank the candidate peptides produced by de novo peptide sequencing. Our results show that NovoRank significantly enhances the performance of various de novo peptide sequencing tools, increasing both recall and precision by 0.020 to 0.080 at the peptide-spectrum match (PSM) level. Notably, NovoRank achieves a recall as high as 0.830 for Casanovo at the PSM level. The source code of NovoRank is freely available at https://github.com/HanyangBISLab/NovoRank and is licensed under Creative Commons Attribution-NonCommercial-ShareAlike 4.0 International.','https://pubs.acs.org/doi/10.1021/acs.jproteome.4c00300','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(51,'Uncovering Hidden Members and Functions of the Soil Microbiome Using De Novo Metaproteomics','2022-07-06','10.1021/acs.jproteome.2c00334','American Chemical Society (ACS)','High Resolution Image Download MS PowerPoint Slide Metaproteomics has been increasingly utilized for high-throughput characterization of proteins in complex environments and has been demonstrated to provide insights into microbial composition and functional roles. However, significant challenges remain in metaproteomic data analysis, including creation of a sample-specific protein sequence database. A well-matched database is a requirement for successful metaproteomics analysis, and the accuracy and sensitivity of PSM identification algorithms suffer when the database is incomplete or contains extraneous sequences. When matched DNA sequencing data of the sample is unavailable or incomplete, creating the proteome database that accurately represents the organisms in the sample is a challenge. Here, we leverage a de novo peptide sequencing approach to identify the sample composition directly from metaproteomic data. First, we created a deep learning model, Kaiko, to predict the peptide sequences from mass spectrometry data and trained it on 5 million peptide–spectrum matches from 55 phylogenetically diverse bacteria. After training, Kaiko successfully identified organisms from soil isolates and synthetic communities directly from proteomics data. Finally, we created a pipeline for metaproteome database generation using Kaiko. We tested the pipeline on native soils collected in Kansas, showing that the de novo sequencing model can be employed as an alternative and complementary method to construct the sample-specific protein database instead of relying on (un)matched metagenomes. Our pipeline identified all highly abundant taxa from 16S rRNA sequencing of the soil samples and uncovered several additional species which were strongly represented only in proteomic data.','https://doi.org/10.1021/acs.jproteome.2c00334','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(52,'DePS: An improved deep learning model for de novo peptide sequencing','2022-03-16','10.48550/arXiv.2203.08820','arXiv','De novo peptide sequencing from mass spectrometry data is an important method for protein identification. Recently, various deep learning approaches were applied for de novo peptide sequencing and DeepNovoV2 is one of the represetative models. In this study, we proposed an enhanced model, DePS, which can improve the accuracy of de novo peptide sequencing even with missing signal peaks or large number of noisy peaks in tandem mass spectrometry data. It is showed that, for the same test set of DeepNovoV2, the DePS model achieved excellent results of 74.22%, 74.21% and 41.68% for amino acid recall, amino acid precision and peptide recall respectively. Furthermore, the results suggested that DePS outperforms DeepNovoV2 on the cross species dataset.','https://arxiv.org/abs/2203.08820','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(53,'Deep Novo A+: Improving the Deep Learning Model for De Novo Peptide Sequencing with Additional Ion Types and Validation Set','2022-02-01','10.2174/1574893615666200204112347','Bentham Science Publishers Ltd.','Background: De novo peptide sequencing is one of the key technologies in proteomics, which can extract peptide sequences directly from tandem mass spectrometry (MS/MS) spectra without any protein databases. Since the accuracy and efficiency of de novo peptide sequencing can be affected by the quality of the MS/MS data, the DeepNovo method using deep learning for de novo peptide sequencing is introduced, which outperforms the other state-of-the-art de novo sequencing methods. Objective: For superior performance and better generalization ability, additional ion types of spectra should be considered and the model of DeepNovo should be adaptive. Methods: Two improvements are introduced in the DeepNovo A+ method: a_ions are added in the spectral analysis, and the validation set is used to automatically determine the number of training epochs. Results: Experiments show that compared to the DeepNovo method, the DeepNovo A+ method can consistently improve the accuracy of de novo sequencing under different conditions. Conclusion: By adding a_ions and using the validation set, the performance of de novo sequencing can be improved effectively.','https://www.eurekaselect.com/article/104202','Current Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(54,'Computationally instrument-resolution-independent de novo peptide sequencing for high-resolution devices','2021-03-18','10.1038/s42256-021-00304-3','Springer Science and Business Media LLC',NULL,'https://doi.org/10.1038/s42256-021-00304-3','Nature Machine Intelligence','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(55,'Personalized deep learning of individual immunopeptidomes to identify neoantigens for cancer vaccines','2020-11-16','10.1038/s42256-020-00260-4','Springer Science and Business Media LLC',NULL,'https://doi.org/10.1038/s42256-020-00260-4','Nature Machine Intelligence','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(56,'De Novo Peptide Sequencing Reveals Many Cyclopeptides in the Human Gut and Other Environments','2020-01-22','10.1016/j.cels.2019.11.007','Elsevier BV','Cyclic and branch cyclic peptides (cyclopeptides) represent a class of bioactive natural products that include many antibiotics and anti-tumor compounds. Despite the recent advances in metabolomics analysis, still little is known about the cyclopeptides in the human gut and their possible interactions due to a lack of computational analysis pipelines that are applicable to such compounds. Here, we introduce CycloNovo, an algorithm for automated de novo cyclopeptide analysis and sequencing that employs de Bruijn graphs, the workhorse of DNA sequencing algorithms, to identify cyclopeptides in spectral datasets. CycloNovo reconstructed 32 previously unreported cyclopeptides (to the best of our knowledge) in the human gut and reported over a hundred cyclopeptides in other environments represented by various spectra on Global Natural Products Social Molecular Network (GNPS). https://github.com/bbehsaz/cyclonovo.','https://doi.org/10.1016/j.cels.2019.11.007','Cell Systems','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(57,'Peptide Sequencing with Deep Learning','2020-09-30',NULL,'PhD thesis',NULL,'https://uwspace.uwaterloo.ca/items/58cef361-a66f-4fe2-a4aa-018da0c4762d',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(58,'pNovo 3: precise de novo peptide sequencing using a learning-to-rank framework','2019-07-24','10.1093/bioinformatics/btz366','Oxford University Press (OUP)','MOTIVATION: De novo peptide sequencing based on tandem mass spectrometry data is the key technology of shotgun proteomics for identifying peptides without any database and assembling unknown proteins. However, owing to the low ion coverage in tandem mass spectra, the order of certain consecutive amino acids cannot be determined if all of their supporting fragment ions are missing, which results in the low precision of de novo sequencing. RESULTS: In order to solve this problem, we developed pNovo 3, which used a learning-to-rank framework to distinguish similar peptide candidates for each spectrum. Three metrics for measuring the similarity between each experimental spectrum and its corresponding theoretical spectrum were used as important features, in which the theoretical spectra can be precisely predicted by the pDeep algorithm using deep learning. On seven benchmark datasets from six diverse species, pNovo 3 recalled 29-102% more correct spectra, and the precision was 11-89% higher than three other state-of-the-art de novo sequencing algorithms. Furthermore, compared with the newly developed DeepNovo, which also used the deep learning approach, pNovo 3 still identified 21-50% more spectra on the nine datasets used in the study of DeepNovo. In summary, the deep learning and learning-to-rank techniques implemented in pNovo 3 significantly improve the precision of de novo sequencing, and such machine learning framework is worth extending to other related research fields to distinguish the similar sequences. AVAILABILITY AND IMPLEMENTATION: pNovo 3 can be freely downloaded from http://pfind.ict.ac.cn/software/pNovo/index.html. SUPPLEMENTARY INFORMATION: Supplementary data are available at Bioinformatics online.','https://doi.org/10.1093/bioinformatics/btz366','Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(59,'DeepNovoV2: Better de novo peptide sequencing with deep learning','2019-04-17','10.48550/arXiv.1904.08514','arXiv','Personalized cancer vaccines are envisioned as the next generation rational cancer immunotherapy. The key step in developing personalized therapeutic cancer vaccines is to identify tumor-specific neoantigens that are on the surface of tumor cells. A promising method for this is through de novo peptide sequencing from mass spectrometry data. In this paper we introduce DeepNovoV2, the state-of-the-art model for peptide sequencing. In DeepNovoV2, a spectrum is directly represented as a set of (m/z, intensity) pairs, therefore it does not suffer from the accuracy-speed/memory trade-off problem. The model combines an order invariant network structure (T-Net) and recurrent neural networks and provides a complete end-to-end training and prediction framework to sequence patterns of peptides. Our experiments on a wide variety of data from different species show that DeepNovoV2 outperforms previous state-of-the-art methods, achieving 13.01-23.95\% higher accuracy at the peptide level.','https://arxiv.org/abs/1904.08514','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(60,'Deep learning enables de novo peptide sequencing from data-independent-acquisition mass spectrometry','2018-12-20','10.1038/s41592-018-0260-3','Springer Science and Business Media LLC','We present DeepNovo-DIA, a de novo peptide-sequencing method for data-independent acquisition (DIA) mass spectrometry data. We use neural networks to capture precursor and fragment ions across m/z, retention-time, and intensity dimensions. They are then further integrated with peptide sequence patterns to address the problem of highly multiplexed spectra. DIA coupled with de novo sequencing allowed us to identify novel peptides in human antibodies and antigens.','https://doi.org/10.1038/s41592-018-0260-3','Nature Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(61,'Postnovo: Postprocessing Enables Accurate and FDR-Controlled de Novo Peptide Sequencing','2018-10-02','10.1021/acs.jproteome.8b00278','American Chemical Society (ACS)','De novo sequencing offers an alternative to database search methods for peptide identification from mass spectra. Since it does not rely on a predetermined database of expected or potential sequences in the sample, de novo sequencing is particularly appropriate for samples lacking a well-defined or comprehensive reference database. However, the low accuracy of many de novo sequence predictions has prevented the widespread use of the variety of sequencing tools currently available. Here, we present a new open-source tool, Postnovo, that postprocesses de novo sequence predictions to find high-accuracy results. Postnovo uses a predictive model to rescore and rerank candidate sequences in a manner akin to database search postprocessing tools such as Percolator. Postnovo leverages the output from multiple de novo sequencing tools in its own analyses, producing many times the length of amino acid sequence information (including both full- and partial-length peptide sequences) at an equivalent false discovery rate (FDR) compared to any individual tool. We present a methodology to reliably screen the sequence predictions to a desired FDR given the Postnovo sequence score. We validate Postnovo with multiple data sets and demonstrate its ability to identify proteins that are missed by database search even in samples with paired reference databases.','https://doi.org/10.1021/acs.jproteome.8b00278','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(62,'De novo peptide sequencing by deep learning','2017-07-18','10.1073/pnas.1705691114','National Academy of Sciences','De novo peptide sequencing from tandem MS data is the key technology in proteomics for the characterization of proteins, especially for new sequences, such as mAbs. In this study, we propose a deep neural network model, DeepNovo, for de novo peptide sequencing. DeepNovo architecture combines recent advances in convolutional neural networks and recurrent neural networks to learn features of tandem mass spectra, fragment ions, and sequence patterns of peptides. The networks are further integrated with local dynamic programming to solve the complex optimization task of de novo sequencing. We evaluated the method on a wide variety of species and found that DeepNovo considerably outperformed state of the art methods, achieving 7.7-22.9% higher accuracy at the amino acid level and 38.1-64.0% higher accuracy at the peptide level. We further used DeepNovo to automatically reconstruct the complete sequences of antibody light and heavy chains of mouse, achieving 97.5-100% coverage and 97.2-99.5% accuracy, without assisting databases. Moreover, DeepNovo is retrainable to adapt to any sources of data and provides a complete end-to-end training and prediction solution to the de novo sequencing problem. Not only does our study extend the deep learning revolution to a new field, but it also shows an innovative approach in solving optimization problems by using deep learning and dynamic programming.','https://doi.org/10.1073/pnas.1705691114','PNAS','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(64,'CausalNovo: Advancing De Novo Peptide Sequencing via a Causality-Informed Framework','2026-02-14',NULL,'OpenReview',NULL,'https://openreview.net/forum?id=55GsILa8c9','ICLR 2026','preprint',NULL,NULL);
INSERT INTO publication VALUES(65,'Sequence database searches via de novo peptide sequencing by tandem mass spectrometry','1997-06-15','10.1002/(SICI)1097-0231(19970615)11:9<1067::AID-RCM953>3.0.CO;2-L','Wiley','A method is described for searching protein sequence databases using tandem mass spectra of tryptic peptides. The approach uses a de novo sequencing algorithm to derive a short list of possible sequence candidates which serve as query sequences in a subsequent homology-based database search routine. The sequencing algorithm employs a graph theory approach similar to previously described sequencing programs. In addition, amino acid composition, peptide sequence tags and incomplete or ambiguous Edman sequence data can be used to aid in the sequence determinations. Although sequencing of peptides from tandem mass spectra is possible, one of the frequently encountered difficulties is that several alternative sequences can be deduced from one spectrum. Most of the alternative sequences, however, are sufficiently similar for a homology-based sequence database search to be possible. Unfortunately, the available protein sequence database search algorithms (e.g. Blast or FASTA) require a single unambiguous sequence as input. Here we describe how the publicly available FASTA computer program was modified in order to search protein databases more effectively in spite of the ambiguities intrinsic in de novo peptide sequencing algorithms.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/abs/10.1002/%28SICI%291097-0231%2819970615%2911%3A9%3C1067%3A%3AAID-RCM953%3E3.0.CO%3B2-L','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(66,'De novo peptide sequencing via tandem mass spectrometry','1999-10-01','10.1089/106652799318300','Mary Ann Liebert','Peptide sequencing via tandem mass spectrometry (MS/MS) is one of the most powerful tools in proteomics for identifying proteins. Because complete genome sequences are accumulating rapidly, the recent trend in interpretation of MS/MS spectra has been database search. However, de novo MS/MS spectral interpretation remains an open problem typically involving manual interpretation by expert mass spectrometrists. We have developed a new algorithm, SHERENGA, for de novo interpretation that automatically learns fragment ion types and intensity thresholds from a collection of test spectra generated from any type of mass spectrometer. The test data are used to construct optimal path scoring in the graph representations of MS/MS spectra. A ranked list of high scoring paths corresponds to potential peptide sequences. SHERENGA is most useful for interpreting sequences of peptides resulting from unknown proteins and for validating the results of database search algorithms in fully automated, high-throughput peptide sequencing.','https://www.liebertpub.com/doi/abs/10.1089/106652799318300','Journal of Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(67,'PEAKS: powerful software for peptide de novo sequencing by tandem mass spectrometry','2003-10-15','10.1002/rcm.1196','Wiley','A number of different approaches have been described to identify proteins from tandem mass spectrometry (MS/MS) data. The most common approaches rely on the available databases to match experimental MS/MS data. These methods suffer from several drawbacks and cannot be used for the identification of proteins from unknown genomes. In this communication, we describe a new de novo sequencing software package, PEAKS, to extract amino acid sequence information without the use of databases. PEAKS uses a new model and a new algorithm to efficiently compute the best peptide sequences whose fragment ions can best interpret the peaks in the MS/MS spectrum. The output of the software gives amino acid sequences with confidence scores for the entire sequences, as well as an additional novel positional scoring scheme for portions of the sequences. The performance of PEAKS is compared with Lutefisk, a well-known de novo sequencing software, using quadrupole-time-of-flight (Q-TOF) data obtained for several tryptic peptides from standard proteins.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/abs/10.1002/rcm.1196','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(68,'PepNovo: de novo peptide sequencing via probabilistic network modeling','2005-02-15','10.1021/ac048788h','American Chemical Society (ACS)','We present a novel scoring method for de novo interpretation of peptides from tandem mass spectrometry data. Our scoring method uses a probabilistic network whose structure reflects the chemical and physical rules that govern the peptide fragmentation. We use a likelihood ratio hypothesis test to determine whether the peaks observed in the mass spectrum are more likely to have been produced under our fragmentation model than under a model that treats peaks as random events. We tested our de novo algorithm PepNovo on ion trap data and achieved results that are superior to popular de novo peptide sequencing algorithms. PepNovo can be accessed via the URL http://www-cse.ucsd.edu/groups/bioinformatics/software.html.','https://pubs.acs.org/doi/abs/10.1021/ac048788h','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(69,'NovoHMM: A Hidden Markov Model for de Novo Peptide Sequencing','2005-11-15','10.1021/ac0508853','American Chemical Society (ACS)','De novo sequencing of peptides poses one of the most challenging tasks in data analysis for proteome research. In this paper, a generative hidden Markov model (HMM) of mass spectra for de novo peptide sequencing which constitutes a novel view on how to solve this problem in a Bayesian framework is proposed. Further extensions of the model structure to a graphical model and a factorial HMM to substantially improve the peptide identification results are demonstrated. Inference with the graphical model for de novo peptide sequencing estimates posterior probabilities for amino acids rather than scores for single symbols in the sequence. Our model outperforms state-of-the-art methods for de novo peptide sequencing on a large test set of spectra.','https://pubs.acs.org/doi/10.1021/ac0508853','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(70,'MSNovo: A Dynamic Programming Algorithm for de Novo Peptide Sequencing via Tandem Mass Spectrometry','2007-06-15','10.1021/ac070039n','American Chemical Society (ACS)','Tandem mass spectrometry (MS/MS) has become the experimental method of choice for high-throughput proteomics-based biological discovery. The two primary ways of analyzing MS/MS data are database search and de novo sequencing. In this paper, we present a new approach to peptide de novo sequencing, called MSNovo, which has the following advanced features. (1) It works on data generated from both LCQ and LTQ mass spectrometers and interprets singly, doubly, and triply charged ions. (2) It integrates a new probabilistic scoring function with a mass array-based dynamic programming algorithm. The simplicity of the scoring function, with only 6-10 parameters to be trained, avoids the problem of overfitting and allows MSNovo to be adopted for other machines and data sets easily. The mass array data structure explicitly encodes all possible peptides and allows the dynamic programming algorithm to find the best peptide. (3) Compared to existing programs, MSNovo predicts peptides as well as sequence tags with a higher accuracy, which is important for those applications that search protein databases using the de novo sequencing results. More specifically, we show that MSNovo outperforms other programs on various ESI ion trap data. We also show that for high-resolution data the performance of MSNovo improves significantly. Supporting Information, executable files and data sets can be found at http://msms.usc.edu/supplementary/msnovo.','https://pubs.acs.org/doi/10.1021/ac070039n','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(71,'pNovo: De novo Peptide Sequencing and Identification Using HCD Spectra','2010-05-07','10.1021/pr100182k','American Chemical Society (ACS)','De novo peptide sequencing has improved remarkably in the past decade as a result of better instruments and computational algorithms. However, de novo sequencing can correctly interpret only approximately 30% of high- and medium-quality spectra generated by collision-induced dissociation (CID), which is much less than database search. This is mainly due to incomplete fragmentation and overlap of different ion series in CID spectra. In this study, we show that higher-energy collisional dissociation (HCD) is of great help to de novo sequencing because it produces high mass accuracy tandem mass spectrometry (MS/MS) spectra without the low-mass cutoff associated with CID in ion trap instruments. Besides, abundant internal and immonium ions in the HCD spectra can help differentiate similar peptide sequences. Taking advantage of these characteristics, we developed an algorithm called pNovo for efficient de novo sequencing of peptides from HCD spectra. pNovo gave correct identifications to 80% or more of the HCD spectra identified by database search. The number of correct full-length peptides sequenced by pNovo is comparable with that obtained by database search. A distinct advantage of de novo sequencing is that deamidated peptides and peptides with amino acid mutations can be identified efficiently without extra cost in computation. In summary, implementation of the HCD characteristics makes pNovo an excellent tool for de novo peptide sequencing from HCD spectra.','https://pubs.acs.org/doi/10.1021/pr100182k','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(72,'pNovo+: De Novo Peptide Sequencing Using Complementary HCD and ETD Tandem Mass Spectra','2013-02-01','10.1021/pr3006843','American Chemical Society (ACS)','De novo peptide sequencing is the only tool for extracting peptide sequences directly from tandem mass spectrometry (MS) data without any protein database. However, neither the accuracy nor the efficiency of de novo sequencing has been satisfactory, mainly due to incomplete fragmentation information in experimental spectra. Recent advancement in MS technology has enabled acquisition of higher energy collisional dissociation (HCD) and electron transfer dissociation (ETD) spectra of the same precursor. These spectra contain complementary fragmentation information and can be collected with high resolution and high mass accuracy. Taking these advantages, we have developed a new algorithm called pNovo+, which greatly improves the accuracy and speed of de novo sequencing. On tryptic peptides, 86% of the topmost candidate sequences deduced by pNovo+ from HCD + ETD spectral pairs matched the database search results, and the success rate reached 95% if the top three candidates were included, which was much higher than using only HCD (87%) or only ETD spectra (57%). On Asp-N, Glu-C, or Elastase digested peptides, 69-87% of the HCD + ETD spectral pairs were correctly identified by pNovo+ among the topmost candidates, or 84-95% among the top three. On average, it takes pNovo+ only 0.018 s to extract the sequence from a spectrum or spectral pair on a common personal computer. This is more than three times as fast as other de novo sequencing programs. The increase of speed is mainly due to pDAG, a component algorithm of pNovo+. pDAG finds the k longest paths in a directed acyclic graph without the antisymmetry restriction. We have verified that the antisymmetry restriction is unnecessary for high resolution, high mass accuracy data. The extensive use of HCD and ETD spectral information and the pDAG algorithm make pNovo+ an excellent de novo sequencing tool.','https://pubs.acs.org/doi/10.1021/pr3006843','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(73,'Novor: Real-Time Peptide de Novo Sequencing Software','2015-06-30','10.1007/s13361-015-1204-0','American Chemical Society (ACS)','De novo sequencing software has been widely used in proteomics to sequence new peptides from tandem mass spectrometry data. This study presents a new software tool, Novor, to greatly improve both the speed and accuracy of today''s peptide de novo sequencing analyses. To improve the accuracy, Novor''s scoring functions are based on two large decision trees built from a peptide spectral library with more than 300,000 spectra with machine learning. Important knowledge about peptide fragmentation is extracted automatically from the library and incorporated into the scoring functions. The decision tree model also enables efficient score calculation and contributes to the speed improvement. To further improve the speed, a two-stage algorithmic approach, namely dynamic programming and refinement, is used. The software program was also carefully optimized. On the testing datasets, Novor sequenced 7%-37% more correct residues than the state-of-the-art de novo sequencing tool, PEAKS, while being an order of magnitude faster. Novor can de novo sequence more than 300 MS/MS spectra per second on a laptop computer. The speed surpasses the acquisition speed of today''s mass spectrometer and, therefore, opens a new possibility to de novo sequence in real time while the spectrometer is acquiring the spectral data. Graphical Abstract ᅟ.','https://link.springer.com/article/10.1007/s13361-015-1204-0','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(74,'De novo peptide sequencing rescoring and FDR estimation with Winnow','2025-09-29','10.48550/arXiv.2509.24952','arXiv','Machine learning has markedly advanced de novo peptide sequencing (DNS) for mass spectrometry-based proteomics. DNS tools offer a reliable way to identify peptides without relying on reference databases, extending proteomic analysis and unlocking applications into less-charted regions of the proteome. However, they still face a key limitation. DNS tools lack principled methods for estimating false discovery rates (FDR) and instead rely on model-specific confidence scores that are often miscalibrated. This limits trust in results, hinders cross-model comparisons and reduces validation success. Here we present Winnow, a model-agnostic framework for estimating FDR from calibrated DNS outputs. Winnow maps raw model scores to calibrated confidences using a neural network trained on peptide-spectrum match (PSM)-derived features. From these calibrated scores, Winnow computes PSM-specific error metrics and an experiment-wide FDR estimate using a novel decoy-free FDR estimator. It supports both zero-shot and dataset-specific calibration, enabling flexible application via direct inference, fine-tuning, or training a custom model. We demonstrate that, when applied to InstaNovo predictions, Winnow''s calibrator improves recall at fixed FDR thresholds, and its FDR estimator tracks true error rates when benchmarked against reference proteomes and database search. Winnow ensures accurate FDR control across datasets, helping unlock the full potential of DNS.','https://arxiv.org/abs/2509.24952','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(75,'A Comprehensive and Systematic Review for Deep Learning-Based De Novo Peptide Sequencing','2025-08-01','10.24963/ijcai.2025/1191','IJCAI','Tandem mass spectrometry (MS/MS) has revolutionized the field of proteomics, enabling the high-throughput identification of proteins. However, one of the central challenges in mass spectrometry-based proteomics remains peptide identification, especially in the absence of a comprehensive peptide database. While traditional database search methods compare observed mass spectra to pre-existing protein databases, they are limited by the availability and completeness of these databases. \emph{De novo} peptide sequencing, which derives peptide sequences directly from mass spectra, has emerged as a crucial approach in such cases. In recent years, deep learning has made significant strides in this domain. These methods train deep neural networks for translating mass spectra into peptide sequences without relying on any pre-constructed databases. Despite significant progress, this field still lacks a comprehensive and systematic review. In this paper, we provide the first review of deep learning-based \emph{de novo} peptide sequencing techniques from the perspectives of data types, model architectures, decoding strategies, applications and evaluation metrics. We also identify key challenges and highlight promising avenues for future research, providing a valuable resource for the AI and scientific communities.','https://www.ijcai.org/proceedings/2025/1191','IJCAI 2025','ML conference',NULL,'openalex');
INSERT INTO publication VALUES(76,'Deep Learning Methods for De Novo Peptide Sequencing','2024-11-29','10.1002/mas.21919','Wiley','Protein tandem mass spectrometry data are most often interpreted by matching observed mass spectra to a protein database derived from the reference genome of the sample being analyzed. In many application domains, however, a relevant protein database is unavailable or incomplete, and in such settings de novo sequencing is required. Since the introduction of the DeepNovo algorithm in 2017, the field of de novo sequencing has been dominated by deep learning methods, which use large amounts of labeled mass spectrometry data to train multi-layer neural networks to translate from observed mass spectra to corresponding peptide sequences. Here, we describe these deep learning methods, outline procedures for evaluating their performance, and discuss the challenges in the field, both in terms of methods development and evaluation protocols.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/10.1002/mas.21919','Mass Spectrometry Reviews','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(77,'Uncovering Thousands of New Peptides with Sequence-Mask-Search Hybrid De Novo Peptide Sequencing Framework','2019-12-01','10.1074/mcp.TIR119.001656','ASBMB','Typical analyses of mass spectrometry data only identify amino acid sequences that exist in reference databases. This restricts the possibility of discovering new peptides such as those that contain uncharacterized mutations or originate from unexpected processing of RNAs and proteins. De novo peptide sequencing approaches address this limitation but often suffer from low accuracy and require extensive validation by experts. Here, we develop SMSNet, a deep learning-based de novo peptide sequencing framework that achieves >95% amino acid accuracy while retaining good identification coverage. Applications of SMSNet on landmark proteomics and peptidomics studies reveal over 10,000 previously uncharacterized HLA antigens and phosphopeptides, and in conjunction with database-search methods, expand the coverage of peptide identification by almost 30%. The power to accurately identify new peptides of SMSNet would make it an invaluable tool for any future proteomics and peptidomics studies, including tumor neoantigen discovery, antibody sequencing, and proteome characterization of non-model organisms.','https://www.mcponline.org/article/S1535-9476(20)31650-9/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(78,'NovoBench: Benchmarking Deep Learning-based De Novo Peptide Sequencing Methods in Proteomics','2024-06-16','10.48550/arXiv.2406.11906','arXiv','Tandem mass spectrometry has played a pivotal role in advancing proteomics, enabling the high-throughput analysis of protein composition in biological tissues. Many deep learning methods have been developed for \emph{de novo} peptide sequencing task, i.e., predicting the peptide sequence for the observed mass spectrum. However, two key challenges seriously hinder the further advancement of this important task. Firstly, since there is no consensus for the evaluation datasets, the empirical results in different research papers are often not comparable, leading to unfair comparison. Secondly, the current methods are usually limited to amino acid-level or peptide-level precision and recall metrics. In this work, we present the first unified benchmark NovoBench for \emph{de novo} peptide sequencing, which comprises diverse mass spectrum data, integrated models, and comprehensive evaluation metrics. Recent impressive methods, including DeepNovo, PointNovo, Casanovo, InstaNovo, AdaNovo and $π$-HelixNovo are integrated into our framework. In addition to amino acid-level and peptide-level precision and recall, we evaluate the models'' performance in terms of identifying post-tranlational modifications (PTMs), efficiency and robustness to peptide length, noise peaks and missing fragment ratio, which are important influencing factors while seldom be considered. Leveraging this benchmark, we conduct a large-scale study of current methods, report many insightful findings that open up new possibilities for future development.','https://arxiv.org/abs/2406.11906','NeurIPS 2024','ML conference',NULL,'arxiv');
INSERT INTO publication VALUES(79,'Bridging the Gap between Database Search and De Novo Peptide Sequencing with SearchNovo','2025-01-22',NULL,'OpenReview','A bstract Accurate protein identification from mass spectrometry (MS) data is fundamental to unraveling the complex roles of proteins in biological systems, with peptide sequencing being a pivotal step in this process. The two main paradigms for peptide sequencing are database search, which matches experimental spectra with peptide sequences from databases, and de novo sequencing, which infers peptide sequences directly from MS without relying on pre-constructed database. Although database search methods are highly accurate, they are limited by their inability to identify novel, modified, or mutated peptides absent from the database. In contrast, de novo sequencing is adept at discovering novel peptides but often struggles with missing peaks issue, further leading to lower precision. We introduce SearchNovo, a novel framework that synergistically integrates the strengths of database search and de novo sequencing to enhance peptide sequencing. SearchNovo employs an efficient search mechanism to retrieve the most similar peptide spectrum match (PSM) from a database for each query spectrum, followed by a fusion module that utilizes the reference peptide sequence to guide the generation of the target sequence. Furthermore, we observed that dissimilar (noisy) reference peptides negatively affect model performance. To mitigate this, we constructed pseudo reference PSMs to minimize their impact. Comprehensive evaluations on multiple datasets reveal that SearchNovo significantly outperforms state-of-the-art models. Also, analysis indicates that many retrieved spectra contain missing peaks absent in the query spectra, and the retrieved reference peptides often share common fragments with the target peptides. These are key elements in the recipe for SearchNovo’s success. The code for reproducing the results are available in the supplementary materials.','https://openreview.net/forum?id=SjMtxqdQ73','ICLR 2025','ML conference',NULL,'openalex');
INSERT INTO publication VALUES(80,'NovoBoard: A Comprehensive Framework for Evaluating the False Discovery Rate and Accuracy of De Novo Peptide Sequencing','2024-11-01','10.1016/j.mcpro.2024.100849','ASBMB','De novo peptide sequencing is one of the most fundamental research areas in mass spectrometry-based proteomics. Many methods have often been evaluated using a couple of simple metrics that do not fully reflect their overall performance. Moreover, there has not been an established method to estimate the false discovery rate (FDR) of de novo peptide-spectrum matches. Here we propose NovoBoard, a comprehensive framework to evaluate the performance of de novo peptide-sequencing methods. The framework consists of diverse benchmark datasets (including tryptic, nontryptic, immunopeptidomics, and different species) and a standard set of accuracy metrics to evaluate the fragment ions, amino acids, and peptides of the de novo results. More importantly, a new approach is designed to evaluate de novo peptide-sequencing methods on target-decoy spectra and to estimate and validate their FDRs. Our FDR estimation provides valuable information to assess the reliability of new peptides identified by de novo sequencing tools, especially when no ground-truth information is available to evaluate their accuracy. The FDR estimation can also be used to evaluate the capability of de novo peptide sequencing tools to distinguish between de novo peptide-spectrum matches and random matches. Our results thoroughly reveal the strengths and weaknesses of different de novo peptide-sequencing methods and how their performances depend on specific applications and the types of data.','https://www.mcponline.org/article/S1535-9476(24)00139-7/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(81,'Deep Learning in Proteomics','2020-07-01','10.1002/pmic.201900335','Wiley','Proteomics, the study of all the proteins in biological systems, is becoming a data-rich science. Protein sequences and structures are comprehensively catalogued in online databases. With recent advancements in tandem mass spectrometry (MS) technology, protein expression and post-translational modifications (PTMs) can be studied in a variety of biological systems at the global scale. Sophisticated computational algorithms are needed to translate the vast amount of data into novel biological insights. Deep learning automatically extracts data representations at high levels of abstraction from data, and it thrives in data-rich scientific research domains. Here, a comprehensive overview of deep learning applications in proteomics, including retention time prediction, MS/MS spectrum prediction, de novo peptide sequencing, PTM prediction, major histocompatibility complex-peptide binding prediction, and protein structure prediction, is provided. Limitations and the future directions of deep learning in proteomics are also discussed. This review will provide readers an overview of deep learning and how it can be used to analyze proteomics data.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/10.1002/pmic.201900335','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(82,'Open-pNovo: De Novo Peptide Sequencing with Thousands of Protein Modifications','2017-01-23','10.1021/acs.jproteome.6b00716','American Chemical Society (ACS)','De novo peptide sequencing has improved remarkably, but sequencing full-length peptides with unexpected modifications is still a challenging problem. Here we present an open de novo sequencing tool, Open-pNovo, for de novo sequencing of peptides with arbitrary types of modifications. Although the search space increases by ∼300 times, Open-pNovo is close to or even ∼10-times faster than the other three proposed algorithms. Furthermore, considering top-1 candidates on three MS/MS data sets, Open-pNovo can recall over 90% of the results obtained by any one traditional algorithm and report 5-87% more peptides, including 14-250% more modified peptides. On a high-quality simulated data set, ∼85% peptides with arbitrary modifications can be recalled by Open-pNovo, while hardly any results can be recalled by others. In summary, Open-pNovo is an excellent tool for open de novo sequencing and has great potential for discovering unexpected modifications in the real biological applications.','https://pubs.acs.org/doi/10.1021/acs.jproteome.6b00716','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(83,'pSite: Amino Acid Confidence Evaluation for Quality Control of De Novo Peptide Sequencing and Modification Site Localization','2017-12-04','10.1021/acs.jproteome.7b00428','American Chemical Society (ACS)','MS-based de novo peptide sequencing has been improved remarkably with significant development of mass-spectrometry and computational approaches but still lacks quality-control methods. Here we proposed a novel algorithm pSite to evaluate the confidence of each amino acid rather than the full-length peptides obtained by de novo peptide sequencing. A semi-supervised learning approach was used to discriminate correct amino acids from random one; then, an expectation-maximization algorithm was used to adaptively control the false amino-acid rate (FAR). On three test data sets, pSite recalled 86% more amino acids on average than PEAKS at the FAR of 5%. pSite also performed superiorly on the modification site localization problem, which is essentially a special case of amino acid confidence evaluation. On three phosphopeptide data sets, at the false localization rate of 1%, the average recall of pSite was 91% while those of Ascore and phosphoRS were 64 and 63%, respectively. pSite covered 98% of Ascore and phosphoRS results and contributed 21% more phosphorylation sites. Further analyses show that the use of distinct fragmentation features in high-resolution MS/MS spectra, such as neutral loss ions, played an important role in improving the precision of pSite. In summary, the effective and universal model together with the extensive use of spectral information makes pSite an excellent quality control tool for both de novo peptide sequencing and modification site localization.','https://pubs.acs.org/doi/10.1021/acs.jproteome.7b00428','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(84,'Combining De Novo Peptide Sequencing Algorithms, A Synergistic Approach to Boost Both Identifications and Confidence in Bottom-up Proteomics','2017-06-14','10.1021/acs.jproteome.7b00198','American Chemical Society (ACS)','Complex mass spectrometry based proteomics data sets are mostly analyzed by protein database searches. While this approach performs considerably well for sequenced organisms, direct inference of peptide sequences from tandem mass spectra, i.e., de novo peptide sequencing, oftentimes is the only way to obtain information when protein databases are absent. However, available algorithms suffer from drawbacks such as lack of validation and often high rates of false positive hits (FP). Here we present a simple method of combining results from commonly available de novo peptide sequencing algorithms, which in conjunction with minor tweaks in data acquisition ensues lower empirical FDR compared to the analysis using single algorithms. Results were validated using state-of-the art database search algorithms as well specifically synthesized reference peptides. Thus, we could increase the number of PSMs meeting a stringent FDR of 5% more than 3-fold compared to the single best de novo sequencing algorithm alone, accounting for an average of 11 120 PSMs (combined) instead of 3476 PSMs (alone) in triplicate 2 h LC-MS runs of tryptic HeLa digestion.','https://pubs.acs.org/doi/10.1021/acs.jproteome.7b00198','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(85,'De novo peptide sequencing using exhaustive enumeration of peptide composition','2006-08-01','10.1016/j.jasms.2006.03.007','American Chemical Society (ACS)','We introduce the use of a peptide composition lookup table indexed by residual mass and number of amino acids for de novo sequencing of polypeptides. Polypeptides of 1600 Daltons (Da) or more can be sequenced effectively through exhaustive compositional analysis of MS/MS spectra obtained by unimolecular decomposition (without CID) in a MALDI TOF/TOF despite a fragment mass accuracy of 50 mDa. Peaks are referenced against the lookup table to obtain a complete profile of amino acid combinations, and combinations are assembled into series of increasing length. Concatenating the differences between successive entries in compositional series yields peptide sequences that can be scored and ranked according to signal intensity. While the current work involves measurements acquired on MALDI TOF-TOF, such general treatment of the data anticipates extension to other types of mass analyzers.','https://pubs.acs.org/doi/10.1016/j.jasms.2006.03.007','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(86,'De Novo Peptide Sequencing and Identification with Precision Mass Spectrometry','2007-01-05','10.1021/pr060271u','American Chemical Society (ACS)','The recent proliferation of novel mass spectrometers such as Fourier transform, QTOF, and OrbiTrap marks a transition into the era of precision mass spectrometry, providing a 2 orders of magnitude boost to the mass resolution, as compared to low-precision ion-trap detectors. We investigate peptide de novo sequencing by precision mass spectrometry and explore some of the differences when compared to analysis of low-precision data. We demonstrate how the dramatically improved performance of de novo sequencing with precision mass spectrometry paves the way for novel approaches to peptide identification that are based on direct sequence lookups, rather than comparisons of spectra to a database. With the direct sequence lookup, it is not only possible to search a database very efficiently, but also to use the database in novel ways, such as searching for products of alternative splicing or products of fusion proteins in cancer. Our de novo sequencing software is available for download at http://peptide.ucsd.edu/.','https://pubs.acs.org/doi/10.1021/pr060271u','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(87,'"De novo" peptide sequencing by MALDI-quadrupole-ion trap mass spectrometry: A preliminary study','2003-12-01','10.1016/S1044-0305(03)00346-5','American Chemical Society (ACS)','Collision-induced dissociation of singly charged peptide ions produced by resonant excitation in a matrix-assisted laser desorption/ionization (MALDI) ion trap mass spectrometer yields relatively low complexity MS/MS spectra that exhibit highly preferential fragmentation, typically occurring adjacent to aspartyl, glutamyl, and prolyl residues. Although these spectra have proven to be of considerable utility for database-driven protein identification, they have generally been considered to contain insufficient information to be useful for extensive de novo sequencing. Here, we report a procedure for de novo sequencing of peptides that uses MS/MS data generated by an in-house assembled MALDI-quadrupole-ion trap mass spectrometer (Krutchinsky, Kalkum, and Chait Anal. Chem. 2001, 73, 5066-5077). Peptide sequences of up 14 amino acid residues in length have been deduced from digests of proteins separated by SDS-PAGE. Key to the success of the current procedure is an ability to obtain MS/MS spectra with high signal-to-noise ratios and to efficiently detect relatively low abundance fragment ions that result from the less favorable fragmentation pathways. The high signal-to-noise ratio yields sufficiently accurate mass differences to allow unambiguous amino acid sequence assignments (with a few exceptions), and the efficient detection of low abundance fragment ions allows continuous reads through moderately long stretches of sequence. Finally, we show how the aforementioned preferential cleavage property of singly charged ions can be used to facilitate the de novo sequencing process.','https://pubs.acs.org/doi/10.1016/S1044-0305%2803%2900346-5','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(88,'De Novo Peptide Sequencing Based on a Divide-and-Conquer Algorithm and Peptide Tandem Spectrum Simulation','2004-09-15','10.1021/ac0491206','American Chemical Society (ACS)','Mass spectrometry-based de novo peptide sequencing is generally more reliable on high-resolution instruments owing to their high resolution and mass accuracy. On a lower resolution instrument such as the more widely used quadrupole ion traps, de novo peptide sequencing is not so reliable or requires more MS(3) experiments. However, the peptide CID spectrum has been demonstrated to be quite reproducible on an ion trap instrument and can be predicted with good accuracy. A new de novo peptide sequencing technique, DACSIM, combining a divide-and-conquer algorithm for deriving sequence candidates and spectrum simulation for sequence refinement, is developed for spectra acquired on an ion trap instrument. When DACSIM was used to sequence peptides 500-1900 u in mass generated from proteolytic digests of hemoglobin and myoglobin, the success rate was 70% with a false positive rate of only 6%, when isoleucine and leucine residues were not distinguished.','https://pubs.acs.org/doi/10.1021/ac0491206','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(89,'High-Confidence de Novo Peptide Sequencing Using Positive Charge Derivatization and Tandem MS Spectra Merging','2013-04-16','10.1021/ac4001699','American Chemical Society (ACS)','De novo peptide sequencing holds great promise in discovering new protein sequences and modifications but has often been hindered by low success rate of mass spectra interpretation, mainly due to the diversity of fragment ion types and insufficient information for each ion series. Here, we describe a novel methodology that combines highly efficient on-tip charge derivatization and tandem MS spectra merging, which greatly boosts the performance of interpretation. TMPP-Ac-OSu (succinimidyloxycarbonylmethyl tris(2,4,6-trimethoxyphenyl)phosphonium bromide) was used to derivatize peptides at N-termini on tips to reduce mass spectra complexity. Then, a novel approach of spectra merging was adopted to combine the benefits of collision-induced dissociation (CID) and electron transfer dissociation (ETD) fragmentation. We applied this methodology to rat C6 glioma cells and the Cyprinus carpio and searched the resulting peptide sequences against the protein database. Then, we achieved thousands of high-confidence peptide sequences, a level that conventional de novo sequencing methods could not reach. Next, we identified dozens of novel peptide sequences by homology searching of sequences that were fully backbone covered but unmatched during the database search. Furthermore, we randomly chose 34 sequences discovered in rat C6 cells and verified them. Finally, we conclude that this novel methodology that combines on-tip positive charge derivatization and tandem MS spectra merging will greatly facilitate the discovery of novel proteins and the proteome analysis of nonmodel organisms.','https://pubs.acs.org/doi/10.1021/ac4001699','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(90,'De Novo Peptide Sequencing by Two-Dimensional Fragment Correlation Mass Spectrometry','2000-06-01','10.1021/ac000226k','American Chemical Society (ACS)','A novel concept of two-dimensional fragment correlation mass spectrometry and its application to peptide sequencing is described. The daughter ion (MS2) spectrum of a peptide contains the sequence information of the peptide. However, deciphering the MS2 spectrum, and thus deriving the peptide sequence is complex because of the difficulty in distinguishing the N-terminal fragments (e.g., b series) from the C-terminal fragments (e.g., y series). By taking a granddaughter ion (MS3) spectrum of a particular daughter ion, all fragment ions of the opposite terminus are eliminated in the MS3 spectrum. However, some internal fragments of the peptide will appear in the MS3 spectrum. Because internal fragments are rarely present in the MS2 spectrum, the intersection (a spectrum containing peaks that are present in both spectra) of the MS2 and MS3 spectra should contain only fragments of the same terminal type. A two-dimensional plot of the MS2 spectrum versus the intersection spectra (2-D fragment correlation mass spectrum) often gives enough information to derive the complete sequence of a peptide. This paper describes this novel technique and its application in sequencing cytochrome c and apomyoglobin. For a tryptic digest of cytochrome c, approximately 78% of the protein sequence was determined. For the Glu-C/tryptic digest of apomyoglobin, approximately 66% of the protein sequence was determined.','https://pubs.acs.org/doi/10.1021/ac000226k','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(91,'Comprehensive de Novo Peptide Sequencing from MS/MS Pairs Generated through Complementary Collision Induced Dissociation and 351 nm Ultraviolet Photodissociation','2017-03-30','10.1021/acs.analchem.7b00130','American Chemical Society (ACS)','We describe a strategy for de novo peptide sequencing based on matched pairs of tandem mass spectra (MS/MS) obtained by collision induced dissociation (CID) and 351 nm ultraviolet photodissociation (UVPD). Each precursor ion is isolated twice with the mass spectrometer switching between CID and UVPD activation modes to obtain a complementary MS/MS pair. To interpret these paired spectra, we modified the UVnovo de novo sequencing software to automatically learn from and interpret fragmentation spectra, provided a representative set of training data. This machine learning procedure, using random forests, synthesizes information from one or multiple complementary spectra, such as the CID/UVPD pairs, into peptide fragmentation site predictions. In doing so, the burden of fragmentation model definition shifts from programmer to machine and opens up the model parameter space for inclusion of nonobvious features and interactions. This spectral synthesis also serves to transform distinct types of spectra into a common representation for subsequent activation-independent processing steps. Then, independent from precursor activation constraints, UVnovo''s de novo sequencing procedure generates and scores sequence candidates for each precursor. We demonstrate the combined experimental and computational approach for de novo sequencing using whole cell E. coli lysate. In benchmarks on the CID/UVPD data, UVnovo assigned correct full-length sequences to 83% of the spectral pairs of doubly charged ions with high-confidence database identifications. Considering only top-ranked de novo predictions, 70% of the pairs were deciphered correctly. This de novo sequencing performance exceeds that of PEAKS and PepNovo on the CID spectra and that of UVnovo on CID or UVPD spectra alone. As presented here, the methods for paired CID/UVPD spectral acquisition and interpretation constitute a powerful workflow for high-throughput and accurate de novo peptide sequencing.','https://pubs.acs.org/doi/10.1021/acs.analchem.7b00130','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(92,'Implementation and Uses of Automated de Novo Peptide Sequencing by Tandem Mass Spectrometry','2001-06-01','10.1021/ac001196o','American Chemical Society (ACS)','There are several computer programs that can match peptide tandem mass spectrometry data to their exactly corresponding database sequences, and in most protein identification projects, these programs are utilized in the early stages of data interpretation. However, situations frequently arise where tandem mass spectral data cannot be correlated with any database sequences. In these cases, the unmatched data could be due to peptides derived from novel proteins, allelic or species-derived variants of known proteins, or posttranslational or chemical modifications. Two additional problems are frequently encountered in high-throughput protein identification. First, it is difficult to quickly sift through large amounts of data to identify those spectra that, due to poor signal or contaminants, can be ignored. Second, it is important to find incorrect database matches (false positives). We have chosen to address these difficulties by performing automatic de novo sequencing using a computer program called Lutefisk. Sequence candidates obtained are used as input in a homology-based database search program called CIDentify to identify variants of known proteins. Comparison of database-derived sequences with de novo sequences allows for electronic validation of database matches even if the latter are not completely correct. Modifications to the original Lutefisk program have been implemented to handle data obtained from triple quadrupole, ion trap, and quadrupole/time-of-flight hybrid (Qtof) mass spectrometers. For example, the linearity of mass errors due to temperature-dependent expansion of the flight tube in a Qtof was exploited such that isobaric amino acids (glutamine/lysine and oxidized methionine/ phenylalanine) can be differentiated without careful attention to mass calibration.','https://pubs.acs.org/doi/10.1021/ac001196o','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(93,'Accounting for Digestion Enzyme Bias in Casanovo','2024-09-04','10.1021/acs.jproteome.4c00422','American Chemical Society (ACS)','A key parameter of any bottom-up proteomics mass spectrometry experiment is the identity of the enzyme that is used to digest proteins in the sample into peptides. The Casanovo de novo sequencing model was trained using data that was generated with trypsin digestion; consequently, the model prefers to predict peptides that end with the amino acids "K" or "R". This bias is desirable when Casanovo is used to analyze data that was also generated using trypsin but can be problematic if the data was generated using some other digestion enzyme. In this work, we modify Casanovo to take as input the identity of the digestion enzyme alongside each observed spectrum. We then train Casanovo with data generated by using several different enzymes, and we demonstrate that the resulting model successfully learns to capture enzyme-specific behavior. However, we find, surprisingly, that this new model does not yield a significant improvement in sequencing accuracy relative to a model trained without enzyme information but using the same training set. This observation may have important implications for future attempts to make use of experimental metadata in de novo sequencing models.','https://pubs.acs.org/doi/10.1021/acs.jproteome.4c00422','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(94,'Highly Robust de Novo Full-Length Protein Sequencing','2021-11-23','10.1021/acs.analchem.1c03718','American Chemical Society (ACS)','High Resolution Image Download MS PowerPoint Slide Accurate full-length sequencing of a purified unknown protein is still challenging nowadays due to the error-prone mass-spectrometry (MS)-based methods. De novo identified peptide sequence largely contain errors, undermining the accuracy of assembly. Bias on the detectability of the peptides also makes low-coverage regions, resulting in gaps. Although recent advances on multi-enzyme hydrolysis and algorithms showed complete assembly of full-length protein sequences in a few examples, the robustness in practical application is still to be improved. Here, inspired by genome assembly strategies, we demonstrate a contig-scaffolding strategy to assemble protein sequences with high robustness and accuracy. This strategy integrates multiple unspecific hydrolysis methods to minimize the bias in the hydrolysis process. After de novo identification of the peptides, our assembly algorithm, named Multiple Contigs & Scaffolding (MuCS), assembles the peptide sequences in a multistep, i.e., contig-scaffold manner, with error correction in each step. MS data from different hydrolysis experiments complement each other for robust contig extension and error correction. We demonstrated that our strategy on three proteins and three replications all reached 100% coverage (except one with 98.85%) and 98.69–100% accuracy. It can also efficiently deal with the membrane protein, although the transmembrane region was missing due to the limitation of the MS. The three replicates reached 88.85–92.57% coverage and 97.57–100% accuracy. In sum, we provided a practical, robust, and accurate solution for full-length protein sequencing. The MuCS software is available at http://chi-biotech.com/mucs/ .','https://pubs.acs.org/doi/10.1021/acs.analchem.1c03718','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(95,'UVnovo: A de Novo Sequencing Algorithm Using Single Series of Fragment Ions via Chromophore Tagging and 351 nm Ultraviolet Photodissociation Mass Spectrometry','2016-04-26','10.1021/acs.analchem.6b00261','American Chemical Society (ACS)','De novo peptide sequencing by mass spectrometry represents an important strategy for characterizing novel peptides and proteins, in which a peptide''s amino acid sequence is inferred directly from the precursor peptide mass and tandem mass spectrum (MS/MS or MS(3)) fragment ions, without comparison to a reference proteome. This method is ideal for organisms or samples lacking a complete or well-annotated reference sequence set. One of the major barriers to de novo spectral interpretation arises from confusion of N- and C-terminal ion series due to the symmetry between b and y ion pairs created by collisional activation methods (or c, z ions for electron-based activation methods). This is known as the "antisymmetric path problem" and leads to inverted amino acid subsequences within a de novo reconstruction. Here, we combine several key strategies for de novo peptide sequencing into a single high-throughput pipeline: high-efficiency carbamylation blocks lysine side chains, and subsequent tryptic digestion and N-terminal peptide derivatization with the ultraviolet chromophore AMCA yield peptides susceptible to 351 nm ultraviolet photodissociation (UVPD). UVPD-MS/MS of the AMCA-modified peptides then predominantly produces y ions in the MS/MS spectra, specifically addressing the antisymmetric path problem. Finally, the program UVnovo applies a random forest algorithm to automatically learn from and then interpret UVPD mass spectra, passing results to a hidden Markov model for de novo sequence prediction and scoring. We show this combined strategy provides high-performance de novo peptide sequencing, enabling the de novo sequencing of thousands of peptides from an Escherichia coli lysate at high confidence.','https://pubs.acs.org/doi/10.1021/acs.analchem.6b00261','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(96,'AbNovoBench: a resource and benchmarking platform for monoclonal antibody de novo sequencing','2026-02-02','10.64898/2026.02.02.703105','Cold Spring Harbor Laboratory','Monoclonal antibodies (mAbs) are critical in disease diagnostics and therapeutics, yet the performance of mass spectrometry (MS)-based de novo sequencing remains incompletely characterized due to limited antibody-specific datasets and the absence of a standardized benchmark framework. Here we present AbNovoBench, a comprehensive framework for evaluating data analysis strategies for mAb de novo sequencing. It features the largest high-quality dataset to date, generated in-house, comprising 1,638,248 peptide-spectrum matches from 131 mAbs across six species and 11 proteases, supplemented by eight mAbs with known full-length sequence for end-to-end reconstruction assessment. Employing a unified training dataset, we systematically benchmarked 13 deep learning-based de novo peptide sequencing algorithms and three assembly strategies across peptide sequencing metrics (accuracy, robustness, efficiency, error types) and assembly metrics (coverage depth, assembly score). AbNovoBench (https://abnovobench.com) provides an online platform enriched with curated antibody MS resources and pre-trained models, enabling customizable antibody sequencing workflows, accelerating antibody-specific algorithms development, and improving reproducibility in proteomics.','https://www.biorxiv.org/content/10.64898/2026.02.02.703105v2','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(97,'Wrangling a de novo sequencing benchmark','2024-11-12',NULL,'Springer Nature Communities',NULL,'https://communities.springernature.com/posts/wrangling-a-de-novo-sequencing-benchmark','Springer Nature Communities (Behind the Paper)','commentary',NULL,NULL);
INSERT INTO publication VALUES(98,'A multi-species benchmark for training and validating mass spectrometry proteomics machine learning models','2024-11-08','10.1038/s41597-024-04068-4','Springer Science and Business Media LLC','Training machine learning models for tasks such as de novo sequencing or spectral clustering requires large collections of confidently identified spectra. Here we describe a dataset of 2.8 million high-confidence peptide-spectrum matches derived from nine different species. The dataset is based on a previously described benchmark but has been re-processed to ensure consistent data quality and enforce separation of training and test peptides.','https://www.nature.com/articles/s41597-024-04068-4','Scientific Data','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(99,'DPST: De Novo Peptide Sequencing with Amino-Acid-Aware Transformers','2022-03-23','10.48550/arXiv.2203.13132','arXiv','De novo peptide sequencing aims to recover amino acid sequences of a peptide from tandem mass spectrometry (MS) data. Existing approaches for de novo analysis enumerate MS evidence for all amino acid classes during inference. It leads to over-trimming on receptive fields of MS data and restricts MS evidence associated with following undecoded amino acids. Our approach, DPST, circumvents these limitations with two key components: (1) A confidence value aggregation encoder to sketch spectrum representations according to amino-acid-based connectivity among MS; (2) A global-local fusion decoder to progressively assimilate contextualized spectrum representations with a predefined preconception of localized MS evidence and amino acid priors. Our components originate from a closed-form solution and selectively attend to informative amino-acid-aware MS representations. Through extensive empirical studies, we demonstrate the superiority of DPST, showing that it outperforms state-of-the-art approaches by a margin of 12% - 19% peptide accuracy.','https://arxiv.org/abs/2203.13132','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(100,'Spectrum graph-based de-novo sequencing algorithm MaxNovo achieves high peptide identification rates in collisional dissociation MS/MS spectra','2021-09-04','10.1101/2021.09.04.458985','Cold Spring Harbor Laboratory','We describe MaxNovo, a novel spectrum graph-based peptide de-novo sequencing algorithm integrated into the MaxQuant software. It identifies complete sequences of peptides as well as sequence tags that are incomplete at one or both of the peptide termini. MaxNovo searches for the highest-scoring path in a directed acyclic graph representing the MS/MS spectrum with peaks as nodes and edges as potential sequence constituents consisting of single amino acids or pairs. The raw score is a sum of node and edge weights, plus several reward scores, for instance, for complementary ions or protease compatibility. For search-engine identified peptides, it correlates well with the Andromeda search engine score. We use a particular score normalization and the score difference between the first and second-best solution to define a combined score that integrates all available information. To evaluate its performance, we use a human cell line dataset and take as ground truth all Andromeda-identified MS/MS spectra with an Andromeda score of at least 100. MaxNovo outperforms other software in particular in the high-sensitivity range of precision-coverage plots. We also identify incomplete sequence tags and study their statistical properties. Next, we apply MaxNovo to ion mobility-coupled time of flight data. Here we achieve excellent performance as well, except for potential swaps of the two amino acids closest to the C-terminus, which are not well resolved due to the low end of the mass range in MS/MS spectra in this dataset. We demonstrate the applicability of MaxNovo to palaeoproteomics samples with a Late Pleistocene hominin proteome dataset that was generated using three proteases. Interestingly, we did not use any machine learning in the construction of MaxNovo, but implemented expert domain knowledge directly in the definition of the score. Yet, it performs as good as or better than the leading deep learning-based algorithm.','https://www.biorxiv.org/content/10.1101/2021.09.04.458985v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(101,'PEAKS DB: De Novo Sequencing Assisted Database Search for Sensitive and Accurate Peptide Identification','2012-04-01','10.1074/mcp.M111.010587','ASBMB','Many software tools have been developed for the automated identification of peptides from tandem mass spectra. The accuracy and sensitivity of the identification software via database search are critical for successful proteomics experiments. A new database search tool, PEAKS DB, has been developed by incorporating the de novo sequencing results into the database search. PEAKS DB achieves significantly improved accuracy and sensitivity over two other commonly used software packages. Additionally, a new result validation method, decoy fusion, has been introduced to solve the issue of overconfidence that exists in the conventional target decoy method for certain types of peptide identification software.','https://www.mcponline.org/article/S1535-9476(20)30468-0/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(102,'De novo mass spectrometry peptide sequencing with a transformer model','2022-07-17',NULL,'PMLR','Tandem mass spectrometry is the only high-throughput method for analyzing the protein content of complex biological samples and is thus the primary technology driving the growth of the field of proteomics. A key outstanding challenge in this field involves identifying the sequence of amino acids—the peptide—responsible for generating each observed spectrum, without making use of prior knowledge in the form of a peptide sequence database. Although various machine learning methods have been developed to address this de novo sequencing problem, challenges that arise when modeling tandem mass spectra have led to complex models that combine multiple neural networks and post-processing steps. We propose a simple yet powerful method for de novo peptide sequencing, Casanovo, that uses a transformer framework to map directly from a sequence of observed peaks (a mass spectrum) to a sequence of amino acids (a peptide). Our experiments show that Casanovo achieves state-of-the-art performance on a benchmark dataset using a standard cross-species evaluation framework which involves testing with spectra with never-before-seen peptide labels. Casanovo not only achieves superior performance but does so at a fraction of the model complexity and inference time required by other methods.','https://proceedings.mlr.press/v162/yilmaz22a.html','ICML 2022','ML conference','v1','openalex');
INSERT INTO publication VALUES(103,'A transformer model for de novo sequencing of data independent acquisition mass spectrometry data','2024-06-03','10.1101/2024.06.03.597251','Cold Spring Harbor Laboratory','A core computational challenge in the analysis of mass spectrometry data is the de novo sequencing problem, in which the generating amino acid sequence is inferred directly from an observed fragmentation spectrum without the use of a sequence database. Recently, deep learning models have made significant advances in de novo sequencing by learning from massive datasets of high-confidence labeled mass spectra. However, these methods are primarily designed for data-dependent acquisition (DDA) experiments. Over the past decade, the field of mass spectrometry has been moving toward using data-independent acquisition (DIA) protocols for the analysis of complex proteomic samples due to their superior specificity and reproducibility. Hence, we present a new de novo sequencing model called Cascadia, which uses a transformer architecture to handle the more complex data generated by DIA protocols. In comparisons with existing approaches for de novo sequencing of DIA data, Cascadia achieves state-of-the-art performance across a range of instruments and experimental protocols. Additionally, we demonstrate Cascadias ability to accurately discover de novo coding variants and peptides from the variable region of antibodies.','https://www.biorxiv.org/content/10.1101/2024.06.03.597251v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(104,'XA-Novo: an accurate and high-throughput mass spectrometry-based de novo sequencing technology for monoclonal antibodies and antibody mixtures','2025-02-07','10.21203/rs.3.rs-5858891/v1','Research Square',NULL,'https://www.researchsquare.com/article/rs-5858891/v1','Research Square','preprint',NULL,NULL);
INSERT INTO publication VALUES(105,'Sequence-to-sequence translation from mass spectra to peptides with a transformer model','2023-01-03','10.1101/2023.01.03.522621','Cold Spring Harbor Laboratory','A fundamental challenge for any mass spectrometry-based proteomics experiment is the identification of the peptide that generated each acquired tandem mass spectrum. Although approaches that leverage known peptide sequence databases are widely used and effective for well-characterized model organisms, such methods cannot detect unexpected peptides and can be impractical or impossible to apply in some settings. Thus, the ability to assign peptide sequences to the acquired tandem mass spectra without prior information--de novo peptide sequencing--is valuable for gaining biological insights for tasks including antibody sequencing, immunopeptidomics, and metaproteomics. Although many methods have been developed to address this de novo sequencing problem, it remains an outstanding challenge, in part due to the difficulty of modeling the irregular data structure of tandem mass spectra. Here, we describe Casanovo, a machine learning model that uses a transformer neural network architecture to translate the sequence of peaks in a tandem mass spectrum into the sequence of amino acids that comprise the generating peptide. We train a Casanovo model from 30 million labeled spectra and demonstrate that the model outperforms several state-of-the-art methods on a cross-species benchmark dataset. We also develop a version of Casanovo that is fine-tuned for non-enzymatic peptides. Finally, we demonstrate that Casanovos superior performance improves the analysis of immunopeptidomics and metaproteomics experiments and allows us to delve deeper into the dark proteome.','https://www.biorxiv.org/content/10.1101/2023.01.03.522621v2','bioRxiv','preprint','v2','biorxiv');
INSERT INTO publication VALUES(106,'Personalized deep learning of individual immunopeptidomes to identify neoantigens for cancer vaccines','2019-04-26','10.1101/620468','Cold Spring Harbor Laboratory','Tumor-specific neoantigens play the main role for developing personal vaccines in cancer immunotherapy. We propose, for the first time, a personalized de novo sequencing workflow to identify HLA-I and HLA-II neoantigens directly and solely from mass spectrometry data. Our workflow trains a personal deep learning model on the immunopeptidome of an individual patient and then uses it to predict mutated neoantigens of that patient. This personalized learning and mass spectrometry-based approach enables comprehensive and accurate identification of neoantigens. We applied the workflow to datasets of five melanoma patients and substantially improved the accuracy and identification rate of de novo HLA peptides by 14.3% and 38.9%, respectively. This subsequently led to the identification of 10,440 HLA-I and 1,585 HLA-II new peptides that were not presented in existing databases. Most importantly, our workflow successfully discovered 17 neoantigens of both HLA-I and HLA-II, including those with validated T cell responses and those novel neoantigens that had not been reported in previous studies.','https://www.biorxiv.org/content/10.1101/620468v3','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(107,'π-PrimeNovo: an accurate and efficient non-autoregressive deep learning model for de novo peptide sequencing','2024-05-17','10.1101/2024.05.17.594647','Cold Spring Harbor Laboratory','Peptide sequencing via tandem mass spectrometry (MS/MS) is fundamental in proteomics data analysis, playing a pivotal role in unraveling the complex world of proteins within biological systems. In contrast to conventional database searching methods, deep learning models excel in de novo sequencing peptides absent from existing databases, thereby facilitating the identification and analysis of novel peptide sequences. Current deep learning models for peptide sequencing predominantly use an autoregressive generation approach, where early errors can cascade, largely affecting overall sequence accuracy. And the usage of sequential decoding algorithms such as beam search suffers from the low inference speed. To address this, we introduce{pi} -PrimeNovo, a non-autoregressive Transformer-based deep learning model designed to perform accurate and efficient de novo peptide sequencing. With the proposed novel architecture,{pi} -PrimeNovo achieves significantly higher accuracy and up to 69x faster sequencing compared to the state-of-the-art methods. This remarkable speed makes it highly suitable for computation-extensive peptide sequencing tasks such as metaproteomic research, where{pi} -PrimeNovo efficiently identifies the microbial species-specific peptides. Moreover,{pi} -PrimeNovo has been demonstrated to have a powerful capability in accurately mining phosphopeptides in a non-enriched phosphoproteomic dataset, showing an alternative solution to detect low-abundance post-translational modifications (PTMs). We suggest that this work not only advances the development of peptide sequencing techniques but also introduces a transformative computational model with wide-range implications for biological research.','https://www.biorxiv.org/content/10.1101/2024.05.17.594647v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(108,'NovoBoard: a comprehensive framework for evaluating the false discovery rate and accuracy of de novo peptide sequencing','2024-04-16','10.1101/2024.04.16.589668','Cold Spring Harbor Laboratory','De novo peptide sequencing is a fundamental research area in mass spectrometry (MS) based proteomics. However, those methods have often been evaluated using a couple of simple metrics that do not fully reflect their overall performance. Moreover, there has not been an established method to estimate the false discovery rate (FDR) and the significance of de novo peptide-spectrum matches (PSMs). Here we propose NovoBoard, a comprehensive framework to evaluate the performance of de novo peptide sequencing methods. The framework consists of diverse benchmark datasets (including tryptic, nontryptic, immunopeptidomics, and different species), and a standard set of accuracy metrics to evaluate the fragment ions, amino acids, and peptides of the de novo results. More importantly, a new approach is designed to evaluate de novo peptide sequencing methods on target-decoy spectra and to estimate their FDRs. Our results thoroughly reveal the strengths and weaknesses of different de novo peptide sequencing methods, and how their performances depend on specific applications and the types of data. Our FDR estimation also shows that some tools may perform better than the others in distinguishing between de novo PSMs and random matches, and can be used to assess the significance of de novo PSMs.','https://www.biorxiv.org/content/10.1101/2024.04.16.589668v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(109,'Bridging the Gap between Database Search and De Novo Peptide Sequencing with SearchNovo','2024-10-19','10.1101/2024.10.19.619186','Cold Spring Harbor Laboratory','AO_SCPLOWBSTRACTC_SCPLOWAccurate protein identification from mass spectrometry (MS) data is fundamental to unraveling the complex roles of proteins in biological systems, with peptide sequencing being a pivotal step in this process. The two main paradigms for peptide sequencing are database search, which matches experimental spectra with peptide sequences from databases, and de novo sequencing, which infers peptide sequences directly from MS without relying on pre-constructed database. Although database search methods are highly accurate, they are limited by their inability to identify novel, modified, or mutated peptides absent from the database. In contrast, de novo sequencing is adept at discovering novel peptides but often struggles with missing peaks issue, further leading to lower precision. We introduce SearchNovo, a novel framework that synergistically integrates the strengths of database search and de novo sequencing to enhance peptide sequencing. SearchNovo employs an efficient search mechanism to retrieve the most similar peptide spectrum match (PSM) from a database for each query spectrum, followed by a fusion module that utilizes the reference peptide sequence to guide the generation of the target sequence. Furthermore, we observed that dissimilar (noisy) reference peptides negatively affect model performance. To mitigate this, we constructed pseudo reference PSMs to minimize their impact. Comprehensive evaluations on multiple datasets reveal that SearchNovo significantly outperforms state-of-the-art models. Also, analysis indicates that many retrieved spectra contain missing peaks absent in the query spectra, and the retrieved reference peptides often share common fragments with the target peptides. These are key elements in the recipe for SearchNovos success. The code for reproducing the results are available in the supplementary materials.','https://www.biorxiv.org/content/10.1101/2024.10.19.619186v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(110,'PepNet: A Fully Convolutional Neural Network for De novo Peptide Sequencing','2022-02-09','10.21203/rs.3.rs-1341615/v1','Research Square','The de novo peptide sequencing, which does not rely on a comprehensive target sequence database, provided us a way to identify novel peptides from tandem mass (MS/MS) spectra. However, current de novo sequencing algorithms suffer from lower accuracy and coverage, which hinders their applications in proteomics. In this paper, we present PepNet, a fully convolutional neural network (CNN) for high accuracy de novo peptide sequencing. It takes an MS/MS spectrum (represented as a high dimensional vector) as input, and outputs the optimal peptide sequence along with its confidence score. Our model was trained using a total of 30 million high-energy collisional dissociation (HCD) MS/MS spectra from multiple human peptide spectral libraries. The evaluation results show that PepNet significantly outperformed currently best-performing de novo sequencing algorithms (e.g. PointNovo and DeepNovo) at both peptide level accuracy and positional level accuracy. In addition, PepNet can sequence a large fraction of spectra that were not identified by database search engines, and thus could be used as a complementary tool of database search engines for peptide identification in proteomics.','https://www.researchsquare.com/article/rs-1341615/v1','Research Square','preprint',NULL,'crossref');
INSERT INTO publication VALUES(111,'Deep learning-driven fragment ion series classification enables highly precise and sensitive de novo peptide sequencing','2023-01-05','10.1101/2023.01.05.522752','Cold Spring Harbor Laboratory','Unlike for DNA and RNA, accurate and high-throughput sequencing methods for proteins are lacking, hindering the utility of proteomics in applications where the sequences are unknown including variant calling, neoepitope identification, and metaproteomics. We introduce Spectralis, a new de novo peptide sequencing method for tandem mass spectrometry. Spectralis leverages several innovations including a new convolutional neural network layer connecting peaks in spectra spaced by amino acid masses, proposing fragment ion series classification as a pivotal task for de novo peptide sequencing, and a new peptide-spectrum confidence score. On spectra for which database search provided a ground truth, Spectralis surpassed 40% sensitivity at 90% precision, nearly doubling state-of-the-art sensitivity. Application to unidentified spectra confirmed its superiority and showcased its applicability to variant calling. Altogether, these algorithmic innovations and the substantial sensitivity increase in the high-precision range constitute an important step toward broadly applicable peptide sequencing.','https://www.biorxiv.org/content/10.1101/2023.01.05.522752v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(112,'MARS: Improved De Novo Peptide Candidate Selection for Non-Canonical Antigen Target Discovery in Cancer','2022-08-04','10.21203/rs.3.rs-1890352/v1','Research Square','Cryptic Human Leukocyte Antigen (HLA)-presented peptide identification from unannotated genome sources is a priority for target antigen discovery for development of next generation immunotherapies in cancer. Current immunopeptidomic approaches utilize the integration of transcriptomics data to inform spectral interpretation, however, recent observations that tumour-associated antigen-encoding RNA levels are often low highlights limitations of such proteogenomic approaches 1 . We here employ a de novo sequencing approach with a refined, MHC-centric analysis strategy to detect non-canonical HLA-associated peptide sequences (HLAp) in cancer without integration of transcript sequence information. Our strategy integrates HLA binding prediction, peptide retention time prediction, and average local confidence scores culminating in the machine learning model MARS (MHC binding prediction, Average Local Confidence Score, and Retention time integration for improved de novo candidate Selection). We demonstrate increased HLA-I peptide identification sensitivity by benchmarking our model against de novo sequencing alone with a large synthetic HLA-I peptide library dataset. We further define the sensitivity of MARS by reanalysis of a published dataset of high-quality non-canonical HLAp identifications in human cancer cell line and tissue datasets and achieve almost 2-fold improvement of the full sequence recall (FSR) for high quality spectral assignments in comparison to de novo sequencing alone 2 . We minimize the false discovery rate (FDR) through a step-wise peptide sequence mapping strategy and are able to expand the reported non-canonical peptide space with an assignment accuracy above 85.7%. Finally, we utilize MARS to detect and validate lncRNA-derived peptides in human cervical tumour resections, demonstrating its suitability to discover novel, non-canonical peptide sequences in primary tumour tissue at reduced FDR, in the absence of transcriptomic sequencing data.','https://www.researchsquare.com/article/rs-1890352/v1','Research Square','preprint',NULL,'crossref');
INSERT INTO publication VALUES(113,'A multi-species benchmark for training and validating mass spectrometry proteomics machine learning models','2024-08-30','10.26434/chemrxiv-2024-z5b8m','ChemRxiv','Training machine learning models for tasks such as de novo sequencing or spectral clustering requires large collections of confidently identified spectra. Here we describe a dataset of 2.8 million high-confidence peptide-spectrum matches derived from nine different species. The dataset is based on a previously described benchmark but has been re-processed to ensure consistent data quality and enforce separation of training and test peptides.','https://chemrxiv.org/engage/chemrxiv/article-details/66d24fef20ac769e5f672ad0','ChemRxiv','preprint',NULL,'openalex');
INSERT INTO publication VALUES(114,'Introducing PandaNovo for practical large-scale de novo peptide sequencing','2023-07-15','10.1101/2023.07.15.549133','Cold Spring Harbor Laboratory','De novo peptide sequencing is a promising approach for novel peptide discovery. We use a novel concept of complementary spectra to enhance ion information and propose a de novo sequencing model{pi} -HelixNovo based on Transformer architecture.{pi} -HelixNovo outperforms other state-of-the-art models and enhances the taxonomic resolution of gut metaproteome, taking a significant step forward in de novo sequencing.','https://www.biorxiv.org/content/10.1101/2023.07.15.549133v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(115,'π-MSNet: A billion-scale, AI-ready living proteomics data portal','2026-04-13','10.64898/2026.04.13.718149','Cold Spring Harbor Laboratory','Artificial intelligence (AI) is reshaping proteomics workflows, delivering remarkable gains in both peptide identification sensitivity and quantitative performance. However, the potential of deep learning models in proteomics has not been fully exploited due to the scarcity of large-scale, high-quality and consistently labeled datasets. Here, we present {pi}-MSNet, a billion-scale, AI-ready living mass spectrometry (MS) data portal. Using a uniform identification and quality control workflow, it comprises over 1.66 billion MS/MS spectra, 501 million peptide-spectrum matches (PSMs), and 9 million precursors from 36,356 LC-MS/MS runs across ten instrument types and 55 diverse species. Through community collaboration, the data are shared via international, interactive, and living web resources. Enabled by the built-in MSNetLoader Python API for seamless and scalable data access--with native support for PyTorch and TensorFlow--{pi}-MSNet provides an AI-ready data framework for efficient training and systematic benchmarking of multiple models across three representative tasks (e.g., MS/MS spectrum prediction, retention time prediction, and de novo peptide sequencing). In particular, by retraining multiple models on {pi}-MSNet, we achieved consistent performance improvements over their original versions. These improved models were subsequently integrated into the {pi}-MSNet agent to enable interactive, deployment-free use. Through SDRF (Sample and Data Relationship Format) metadata, an open-source cloud analysis workflow, and a community-driven interactive data portal that supports continuous data submission, {pi}-MSNet serves as a living, AI-ready resource for reproducible benchmarking, robust model training, and accelerated AI innovation in proteomics.','https://www.biorxiv.org/content/10.64898/2026.04.13.718149v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(116,'Diffusion Decoding for Peptide De Novo Sequencing','2025-07-15','10.48550/arXiv.2507.10955','arXiv','Peptide de novo sequencing is a method used to reconstruct amino acid sequences from tandem mass spectrometry data without relying on existing protein sequence databases. Traditional deep learning approaches, such as Casanovo, mainly utilize autoregressive decoders and predict amino acids sequentially. Subsequently, they encounter cascading errors and fail to leverage high-confidence regions effectively. To address these issues, this paper investigates using diffusion decoders adapted for the discrete data domain. These decoders provide a different approach, allowing sequence generation to start from any peptide segment, thereby enhancing prediction accuracy. We experiment with three different diffusion decoder designs, knapsack beam search, and various loss functions. We find knapsack beam search did not improve performance metrics and simply replacing the transformer decoder with a diffusion decoder lowered performance. Although peptide precision and recall were still 0, the best diffusion decoder design with the DINOISER loss function obtained a statistically significant improvement in amino acid recall by 0.373 compared to the baseline autoregressive decoder-based Casanovo model. These findings highlight the potential of diffusion decoders to not only enhance model sensitivity but also drive significant advancements in peptide de novo sequencing.','https://arxiv.org/abs/2507.10955','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(117,'Metaproteomics Beyond Databases: Addressing the Challenges and Potentials of De Novo Sequencing','2025-01-31','10.1002/pmic.202400321','Wiley','Metaproteomics enables the large-scale characterization of microbial community proteins, offering crucial insights into their taxonomic composition, functional activities, and interactions within their environments. By directly analyzing proteins, metaproteomics offers insights into community phenotypes and the roles individual members play in diverse ecosystems. Although database-dependent search engines are commonly used for peptide identification, they rely on pre-existing protein databases, which can be limiting for complex, poorly characterized microbiomes. De novo sequencing presents a promising alternative, which derives peptide sequences directly from mass spectra without requiring a database. Over time, this approach has evolved from manual annotation to advanced graph-based, tag-based, and deep learning-based methods, significantly improving the accuracy of peptide identification. This Viewpoint explores the evolution, advantages, limitations, and future opportunities of de novo sequencing in metaproteomics. We highlight recent technological advancements that have improved its potential for detecting unsequenced species and for providing deeper functional insights into microbial communities.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/10.1002/pmic.202400321','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(118,'De novo sequencing of peptides by MS/MS','2010-02-18','10.1002/pmic.200900459','Wiley','The current status of de novo sequencing of peptides by MS/MS is reviewed with focus on collision cell MS/MS spectra. The relation between peptide structure and observed fragment ion series is discussed and the exhaustive extraction of sequence information from CID spectra of protonated peptide ions is described. The partial redundancy of the extracted sequence information and a high mass accuracy are recognized as key parameters for dependable de novo sequencing by MS. In addition, the benefits of special techniques enhancing the generation of long uninterrupted fragment ion series for de novo peptide sequencing are highlighted. Among these are terminal (18)O labeling, MS(n) of sodiated peptide ions, N-terminal derivatization, the use of special proteases, and time-delayed fragmentation. The emerging electron transfer dissociation technique and the recent progress of MALDI techniques for intact protein sequencing are covered. Finally, the integration of bioinformatic tools into peptide de novo sequencing is demonstrated.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/full/10.1002/pmic.200900459','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(119,'De Novo Peptide Sequencing for Data-independent Acquisition (DIA) Using Deep Learning','2025-05-01','10.12794/metadc2443151','PhD thesis','In proteomics, de novo peptide sequencing from tandem mass spectrometry (MS/MS) data is a critical technology for discovering novel peptide and protein sequences. Tandem mass spectrometry (MS/MS) stands as the predominant high-throughput technique for comprehensively analyzing protein content within biological samples. In recent years, substantial strides have been made in Data Independent Acquisition (DIA) strategies, facilitating impartial and non-targeted fragmentation of precursor ions. The DIA-generated MS/MS spectra present a formidable obstacle due to their inherent high multiplexing nature. This dissertation presents three deep-learning models designed to overcome the challenges of identifying novel peptide sequences directly from DIA spectra without relying on prior knowledge. First, we introduce ActiveNovo_DIA, an innovative framework that integrates the DeepNovo-DIA model with active learning algorithms. By employing various acquisition functions to selectively target the most informative spectra at each training iteration—rather than relying on random selection—this approach enhances the learning process and ultimately improves de novo sequencing performance. Next, we propose Transformer-DIA, a transformer-based de novo sequencing model specifically designed for DIA data. This model surpasses state-of-the-art (SOTA) methods by effectively addressing the inherent limitations of existing approaches. Its key contribution is expanding the spectrum encoder block, which enables the model to learn essential DIA spectral features more effectively. Finally, we extend the Transformer-DIA model by integrating a diffusion mechanism, leading to the development of DiffNovo. This enhancement not only improves model performance but also eliminates the need to compute high-dimensional features, addressing the limitations present in the original model. Our results demonstrate significant improvements over existing SOTA methods. Given the findings of two tools alongside three advanced models and their superior performance over current approaches, this dissertation contributes to advancing de novo peptide sequencing for DIA data, opening new avenues for proteomics research.','https://digital.library.unt.edu/ark:/67531/metadc2443151/',NULL,'thesis',NULL,'openalex');
INSERT INTO publication VALUES(120,'Transformer-Based De Novo Peptide Sequencing for Data-Independent Acquisition Mass Spectrometry','2023-12-04','10.1109/BIBE60311.2023.00013','Institute of Electrical and Electronics Engineers (IEEE)','Tandem mass spectrometry (MS/MS) stands as the predominant high-throughput technique for comprehensively analyzing protein content within biological samples. This methodology is a cornerstone driving the advancement of proteomics. In recent years, substantial strides have been made in Data-Independent Acquisition (DIA) strategies, facilitating impartial and non-targeted fragmentation of precursor ions. The DIA-generated MS/MS spectra present a formidable obstacle due to their inherent high multiplexing nature. Each spectrum encapsulates fragmented product ions originating from multiple precursor peptides. This intricacy poses a particularly acute challenge in de novo peptide/protein sequencing, where current methods are ill-equipped to address the multiplexing conundrum. In this paper, we introduce Casanovo-DIA, a deep-learning model based on transformer architecture. It deciphers peptide sequences from DIA mass spectrometry data. Our results show significant improvements over existing STOA methods, including DeepNovo-DIA and PepNet. Casanovo-DIA enhances precision by 15.14% to 34.8%, recall by 11.62% to 31.94% at the amino acid level, and boosts precision by 59% to 81.36% at the peptide level. Integrating DIA data and our Casanovo-DIA model holds considerable promise to uncover novel peptides and more comprehensive profiling of biological samples. Casanovo-DIA is freely available under the GNU GPL license at https://github.com/Biocomputing-Research-Group/Casanovo-DIA.','https://ieeexplore.ieee.org/document/10431866','2023 IEEE 23rd International Conference on Bioinformatics and Bioengineering (BIBE)','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(121,'Deep Active Learning for De Novo Peptide Sequencing from Data-independent-acquisition Mass Spectrometry','2022-07-22',NULL,NULL,NULL,'https://icml-compbio.github.io/icml-website-2022/2022/papers/WCBICML2022_paper_60.pdf','ICML 2022 Workshop on Computational Biology','ML conference',NULL,NULL);
INSERT INTO publication VALUES(122,'Zero-shot de novo peptide sequencing with open posttranslational modification discovery','2026-05-19','10.1038/s41587-026-03116-1','Springer Science and Business Media LLC','De novo peptide sequencing directly infers sequences from mass spectrometry data without relying on protein databases. Although recent deep learning models can also identify posttranslational modifications (PTMs), they require labeled training data for this task. Here we introduce rotary positional embedding-enhanced de novo sequencing algorithm (RNovA), a transformer-based de novo sequencing algorithm enhanced with relative positional embeddings and a reinforcement-learning-style sequential decision framework. RNovA enables open PTM discovery in a zero-shot setting-without retraining or a predefined list of candidate residues-while maintaining state-of-the-art performance on standard benchmarks. Demonstrating this capability, we successfully identified peptides modified by kynurenine-an uncommon and biologically relevant PTM-in clinical samples from patients with RA and validated this discovery with synthetically synthesized reference peptides. Furthermore, we demonstrated open de novo PTM discovery by analyzing the bacterial strain A1232E, which lacks a reference proteome, and detected an unannotated glutamic acid modification. RNovA enables exploration of previously inaccessible regions of the proteome, including peptides with unexpected or unannotated modifications.','https://www.nature.com/articles/s41587-026-03116-1','Nature Biotechnology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(123,'Antilope—A Lagrangian Relaxation Approach to the de novo Peptide Sequencing Problem','2012-03-01','10.1109/TCBB.2011.59','Institute of Electrical and Electronics Engineers (IEEE)','Peptide sequencing from mass spectrometry data is a key step in proteome research. Especially de novo sequencing, the identification of a peptide from its spectrum alone, is still a challenge even for state-of-the-art algorithmic approaches. In this paper, we present ANTILOPE, a new fast and flexible approach based on mathematical programming. It builds on the spectrum graph model and works with a variety of scoring schemes. ANTILOPE combines Lagrangian relaxation for solving an integer linear programming formulation with an adaptation of Yen’s k shortest paths algorithm. It shows a significant improvement in running time compared to mixed integer optimization and performs at the same speed like other state-of-the-art tools. We also implemented a generic probabilistic scoring scheme that can be trained automatically for a data set of annotated spectra and is independent of the mass spectrometer type. Evaluations on benchmark data show that ANTILOPE is competitive to the popular state-of-the-art programs PepNovo and NovoHMM both in terms of runtime and accuracy. Furthermore, it offers increased flexibility in the number of considered ion types. ANTILOPE will be freely available as part of the open source proteomics library OpenMS.','https://ieeexplore.ieee.org/document/5740842','IEEE/ACM Transactions on Computational Biology and Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(124,'Evaluating de novo sequencing in proteomics: already an accurate alternative to database-driven peptide identification?','2017-03-21','10.1093/bib/bbx033','Oxford University Press (OUP)','While peptide identifications in mass spectrometry (MS)-based shotgun proteomics are mostly obtained using database search methods, high-resolution spectrum data from modern MS instruments nowadays offer the prospect of improving the performance of computational de novo peptide sequencing. The major benefit of de novo sequencing is that it does not require a reference database to deduce full-length or partial tag-based peptide sequences directly from experimental tandem mass spectrometry spectra. Although various algorithms have been developed for automated de novo sequencing, the prediction accuracy of proposed solutions has been rarely evaluated in independent benchmarking studies. The main objective of this work is to provide a detailed evaluation on the performance of de novo sequencing algorithms on high-resolution data. For this purpose, we processed four experimental data sets acquired from different instrument types from collision-induced dissociation and higher energy collisional dissociation (HCD) fragmentation mode using the software packages Novor, PEAKS and PepNovo. Moreover, the accuracy of these algorithms is also tested on ground truth data based on simulated spectra generated from peak intensity prediction software. We found that Novor shows the overall best performance compared with PEAKS and PepNovo with respect to the accuracy of correct full peptide, tag-based and single-residue predictions. In addition, the same tool outpaced the commercial competitor PEAKS in terms of running time speedup by factors of around 12-17. Despite around 35% prediction accuracy for complete peptide sequences on HCD data sets, taken as a whole, the evaluated algorithms perform moderately on experimental data but show a significantly better performance on simulated data (up to 84% accuracy). Further, we describe the most frequently occurring de novo sequencing errors and evaluate the influence of missing fragment ion peaks and spectral noise on the accuracy. Finally, we discuss the potential of de novo sequencing for now becoming more widely used in the field.','https://academic.oup.com/bib/article/19/5/954/3076504','Briefings in Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(125,'PowerNovo2: A generative flow-based approach to non-autoregressive de novo peptide sequencing','2026-05-20','10.1371/journal.pcbi.1014298','Public Library of Science (PLoS)','Proteomics utilizes tandem mass spectrometry (MS/MS) to determine peptide sequences, traditionally through database searches constrained by prior knowledge. De novo sequencing offers a database-free alternative but struggles with accurately modeling complex MS/MS spectra. Most current tools use autoregressive decoding, which is prone to error propagation and computationally slow. Here we present PowerNovo2, a non-autoregressive model based on generative normalizing flows. By leveraging variational inference, it effectively captures intricate token dependencies and peptide-level uncertainties. PowerNovo2 outperforms existing de novo tools in accuracy and speed, matching state-of-the-art autoregressive models like Casanovo while being 4.3 times faster. It also demonstrates competitive performance against other non-autoregressive methods such as π-PrimeNovo, particularly on long peptides and low-resolution spectra. As the first flow-based de novo sequencer, PowerNovo2 provides a scalable, accurate solution for large-scale proteomic applications.','https://journals.plos.org/ploscompbiol/article?id=10.1371/journal.pcbi.1014298','PLOS Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(126,'pUniFind: a unified large pre-trained deep learning model pushing the limit of mass spectra interpretation','2025-06-30','10.48550/arXiv.2507.00087','arXiv','Deep learning has advanced mass spectrometry data interpretation, yet most models remain feature extractors rather than unified scoring frameworks. We present pUniFind, the first large-scale multimodal pre-trained model in proteomics that integrates end-to-end peptide-spectrum scoring with open, zero-shot de novo sequencing. Trained on over 100 million open search-derived spectra, pUniFind aligns spectral and peptide modalities via cross modality prediction and outperforms traditional engines across diverse datasets, particularly achieving a 42.6 percent increase in the number of identified peptides in immunopeptidomics. Supporting over 1,300 modifications, pUniFind identifies 60 percent more PSMs than existing de novo methods despite a 300-fold larger search space. A deep learning based quality control module further recovers 38.5 percent additional peptides including 1,891 mapped to the genome but absent from reference proteomes while preserving full fragment ion coverage. These results establish a unified, scalable deep learning framework for proteomic analysis, offering improved sensitivity, modification coverage, and interpretability.','https://arxiv.org/abs/2507.00087','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(127,'A large-scale unified deep learning model for peptide mass spectrum interpretation trained on multimodal data','2026-05-25','10.1038/s42256-026-01234-8','Springer Science and Business Media LLC',NULL,'https://www.nature.com/articles/s42256-026-01234-8','Nature Machine Intelligence','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(128,'A Dynamic Programming Approach to De Novo Peptide Sequencing via Tandem Mass Spectrometry','2001-06-01','10.1089/10665270152530872','SAGE Publications','Tandem mass spectrometry fragments a large number of molecules of the same peptide sequence into charged molecules of prefix and suffix peptide subsequences and then measures mass/charge ratios of these ions. The de novo peptide sequencing problem is to reconstruct the peptide sequence from a given tandem mass spectral data of k ions. By implicitly transforming the spectral data into an NC-spectrum graph G (V, E) where /V/ = 2k + 2, we can solve this problem in O(/V//E/) time and O(/V/2) space using dynamic programming. For an ideal noise-free spectrum with only b- and y-ions, we improve the algorithm to O(/V/ + /E/) time and O(/V/) space. Our approach can be further used to discover a modified amino acid in O(/V//E/) time. The algorithms have been implemented and tested on experimental data.','https://doi.org/10.1089/10665270152530872','Journal of Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(129,'A Suboptimal Algorithm for De Novo Peptide Sequencing via Tandem Mass Spectrometry','2003-02-01','10.1089/106652703763255633','SAGE Publications','Tandem mass spectrometry has emerged to be one of the most powerful high-throughput techniques for protein identification. Tandem mass spectrometry selects and fragments peptides of interest into N-terminal ions and C-terminal ions, and it measures the mass/charge ratios of these ions. The de novo peptide sequencing problem is to derive the peptide sequences from given tandem mass spectral data of k ion peaks without searching against protein databases. By transforming the spectral data into a matrix spectrum graph G = (V, E), where |V| = O(k(2)) and |E| = O(k(3)), we give the first polynomial time suboptimal algorithm that finds all the suboptimal solutions (peptides) in O(p|E|) time, where p is the number of solutions. The algorithm has been implemented and tested on experimental data. The program is available at http://hto-c.usc.edu:8000/msms/menu/denovo.htm.','https://doi.org/10.1089/106652703763255633','Journal of Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(130,'An effective algorithm for peptide de novo sequencing from MS/MS spectra','2005-05-01','10.1016/j.jcss.2004.12.001','Elsevier BV',NULL,'https://doi.org/10.1016/j.jcss.2004.12.001','Journal of Computer and System Sciences','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(131,'De Novo Analysis of Peptide Tandem Mass Spectra by Spectral Graph Partitioning','2006-03-01','10.1089/cmb.2006.13.364','SAGE Publications','We report on a new de novo peptide sequencing algorithm that uses spectral graph partitioning. In this approach, relationships between m/z peaks are represented by attractive and repulsive springs, and the vibrational modes of the spring system are used to infer information about the peaks (such as "likely b-ion" or "likely y-ion"). We demonstrate the effectiveness of this approach by comparison with other de novo sequencers on test sets of ion-trap and QTOF spectra, including spectra of mixtures of peptides. On all datasets, we outperform the other sequencers. Along with spectral graph theory techniques, the new de novo sequencer EigenMS incorporates another improvement of independent interest: robust statistical methods for recalibration of time-of-flight mass measurements. Robust recalibration greatly outperforms simple least-squares recalibration, achieving about three times the accuracy for one QTOF dataset.','https://doi.org/10.1089/cmb.2006.13.364','Journal of Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(132,'Performance Evaluation of Existing De Novo Sequencing Algorithms','2006-11-01','10.1021/pr060222h','American Chemical Society (ACS)','Two methods have been developed for protein identification from tandem mass spectra: database searching and de novo sequencing. De novo sequencing identifies peptide directly from tandem mass spectra. Among many proposed algorithms, we evaluated the performance of the five de novo sequencing algorithms, AUDENS, Lutefisk, NovoHMM, PepNovo, and PEAKS. Our evaluation methods are based on calculation of relative sequence distance (RSD), algorithm sensitivity, and spectrum quality. We found that de novo sequencing algorithms have different performance in analyzing QSTAR and LCQ mass spectrometer data, but in general, perform better in analyzing QSTAR data than LCQ data. For the QSTAR data, the performance order of the five algorithms is PEAKS > Lutefisk, PepNovo > AUDENS, NovoHMM. The performance of PEAKS, Lutefisk, and PepNovo strongly depends on the spectrum quality and increases with an increase of spectrum quality. However, AUDENS and NovoHMM are not sensitive to the spectrum quality. Compared with other four algorithms, PEAKS has the best sensitivity and also has the best performance in the entire range of spectrum quality. For the LCQ data, the performance order is NovoHMM > PepNovo, PEAKS > Lutefisk > AUDENS. NovoHMM has the best sensitivity, and its performance is the best in the entire range of spectrum quality. But the overall performance of NovoHMM is not significantly different from the performance of PEAKS and PepNovo. AUDENS does not give a good performance in analyzing either QSTAR and LCQ data.','https://doi.org/10.1021/pr060222h','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(133,'De Novo Peptide Identification via Tandem Mass Spectrometry and Integer Linear Optimization','2007-02-01','10.1021/ac0618425','American Chemical Society (ACS)','A novel methodology for the automated de novo identification of peptides via integer linear optimization (also referred to as integer linear programming or ILP) and tandem mass spectrometry is presented in this article. The various features of the mathematical model are presented and examples are used to illustrate the key concepts of the proposed approach. A variety of challenging peptide identification problems, accompanied by a comparative study with five state-of-the-art methods, are examined to illustrate the proposed method''s ability to address (a) residue-dependent fragmentation properties that result in missing ion peaks and (b) the variability of resolution in different mass analyzers. A preprocessing algorithm is utilized to identify important m/z values in the tandem mass spectrum. Missing peaks, due to residue-dependent fragmentation characteristics, are dealt with using a two-stage algorithmic framework. A cross-correlation approach is used to resolve missing amino acid assignments and to select the most probable peptide by comparing the theoretical spectra of the candidate sequences that were generated from the ILP sequencing stages with the experimental tandem mass spectrum. The novel, proposed de novo method, denoted as PILOT, is compared to existing popular methods such as Lutefisk, PEAKS, PepNovo, EigenMS, and NovoHMM for a set of spectra resulting from QTOF and ion trap instruments.','https://doi.org/10.1021/ac0618425','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(134,'A high-throughput de novo sequencing approach for shotgun proteomics using high-resolution tandem mass spectrometry','2010-03-05','10.1186/1471-2105-11-118','Springer Science and Business Media LLC','BACKGROUND: High-resolution tandem mass spectra can now be readily acquired with hybrid instruments, such as LTQ-Orbitrap and LTQ-FT, in high-throughput shotgun proteomics workflows. The improved spectral quality enables more accurate de novo sequencing for identification of post-translational modifications and amino acid polymorphisms. RESULTS: In this study, a new de novo sequencing algorithm, called Vonode, has been developed specifically for analysis of such high-resolution tandem mass spectra. To fully exploit the high mass accuracy of these spectra, a unique scoring system is proposed to evaluate sequence tags based primarily on mass accuracy information of fragment ions. Consensus sequence tags were inferred for 11,422 spectra with an average peptide length of 5.5 residues from a total of 40,297 input spectra acquired in a 24-hour proteomics measurement of Rhodopseudomonas palustris. The accuracy of inferred consensus sequence tags was 84%. According to our comparison, the performance of Vonode was shown to be superior to the PepNovo v2.0 algorithm, in terms of the number of de novo sequenced spectra and the sequencing accuracy. CONCLUSIONS: Here, we improved de novo sequencing performance by developing a new algorithm specifically for high-resolution tandem mass spectral data. The Vonode algorithm is freely available for download at http://compbio.ornl.gov/Vonode.','https://doi.org/10.1186/1471-2105-11-118','BMC Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(135,'UniNovo: a universal tool for de novo peptide sequencing','2013-08-15','10.1093/bioinformatics/btt338','Oxford University Press (OUP)','MOTIVATION: Mass spectrometry (MS) instruments and experimental protocols are rapidly advancing, but de novo peptide sequencing algorithms to analyze tandem mass (MS/MS) spectra are lagging behind. Although existing de novo sequencing tools perform well on certain types of spectra [e.g. Collision Induced Dissociation (CID) spectra of tryptic peptides], their performance often deteriorates on other types of spectra, such as Electron Transfer Dissociation (ETD), Higher-energy Collisional Dissociation (HCD) spectra or spectra of non-tryptic digests. Thus, rather than developing a new algorithm for each type of spectra, we develop a universal de novo sequencing algorithm called UniNovo that works well for all types of spectra or even for spectral pairs (e.g. CID/ETD spectral pairs). UniNovo uses an improved scoring function that captures the dependences between different ion types, where such dependencies are learned automatically using a modified offset frequency function. RESULTS: The performance of UniNovo is compared with PepNovo+, PEAKS and pNovo using various types of spectra. The results show that the performance of UniNovo is superior to other tools for ETD spectra and superior or comparable with others for CID and HCD spectra. UniNovo also estimates the probability that each reported reconstruction is correct, using simple statistics that are readily obtained from a small training dataset. We demonstrate that the estimation is accurate for all tested types of spectra (including CID, HCD, ETD, CID/ETD and HCD/ETD spectra of trypsin, LysC or AspN digested peptides). AVAILABILITY: UniNovo is implemented in JAVA and tested on Windows, Ubuntu and OS X machines. UniNovo is available at http://proteomics.ucsd.edu/Software/UniNovo.html along with the manual.','https://doi.org/10.1093/bioinformatics/btt338','Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(136,'AUDENS: A Tool for Automated Peptide de Novo Sequencing','2005-10-01','10.1021/pr050070a','American Chemical Society (ACS)','We present AUDENS, a new platform-independent open source tool for automated de novo sequencing of peptides from MS/MS data. We implemented a dynamic programming algorithm and combined it with a flexible preprocessing module which is designed to distinguish between signal and other peaks. By applying a user-defined set of heuristics, AUDENS screens through the spectrum and assigns high relevance values to putative signal peaks. The algorithm constructs a sequence path through the MS/MS spectrum using the peak relevances to score each suggested sequence path, i.e., the corresponding amino acid sequence. At present, we consider AUDENS a prototype that unfolds its biggest potential if used in parallel with other de novo sequencing tools. AUDENS is available open source and can be downloaded with further documentation at http://www.ti.inf.ethz.ch/pw/software/audens/ .','https://doi.org/10.1021/pr050070a','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(137,'Sequencing-Grade De novo Analysis of MS/MS Triplets (CID/HCD/ETD) From Overlapping Peptides','2013-06-07','10.1021/pr400173d','American Chemical Society (ACS)','Full-length de novo sequencing of unknown proteins remains a challenging open problem. Traditional methods that sequence spectra individually are limited by short peptide length, incomplete peptide fragmentation, and ambiguous de novo interpretations. We address these issues by determining consensus sequences for assembled tandem mass (MS/MS) spectra from overlapping peptides (e.g., by using multiple enzymatic digests). We have combined electron-transfer dissociation (ETD) with collision-induced dissociation (CID) and higher-energy collision-induced dissociation (HCD) fragmentation methods to boost interpretation of long, highly charged peptides and take advantage of corroborating b/y/c/z ions in CID/HCD/ETD. Using these strategies, we show that triplet CID/HCD/ETD MS/MS spectra from overlapping peptides yield de novo sequences of average length 70 AA and as long as 200 AA at up to 99% sequencing accuracy.','https://doi.org/10.1021/pr400173d','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(138,'De novo peptide sequencing using CID and HCD spectra pairs','2016-10-01','10.1002/pmic.201500251','Wiley','In tandem mass spectrometry (MS/MS), there are several different fragmentation techniques possible, including, collision-induced dissociation (CID) higher energy collisional dissociation (HCD), electron-capture dissociation (ECD), and electron transfer dissociation (ETD). When using pairs of spectra for de novo peptide sequencing, the most popular methods are designed for CID (or HCD) and ECD (or ETD) spectra because of the complementarity between them. Less attention has been paid to the use of CID and HCD spectra pairs. In this study, a new de novo peptide sequencing method is proposed for these spectra pairs. This method includes a CID and HCD spectra merging criterion and a parent mass correction step, along with improvements to our previously proposed algorithm for sequencing merged spectra. Three pairs of spectral datasets were used to investigate and compare the performance of the proposed method with other existing methods designed for single spectrum (HCD or CID) sequencing. Experimental results showed that full-length peptide sequencing accuracy was increased significantly by using spectra pairs in the proposed method, with the highest accuracy reaching 81.31%.','https://doi.org/10.1002/pmic.201500251','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(139,'Peptide de novo sequencing of mixture tandem mass spectra','2016-09-01','10.1002/pmic.201500549','Wiley','The impact of mixture spectra deconvolution on the performance of four popular de novo sequencing programs was tested using artificially constructed mixture spectra as well as experimental proteomics data. Mixture fragmentation spectra are recognized as a limitation in proteomics because they decrease the identification performance using database search engines. De novo sequencing approaches are expected to be even more sensitive to the reduction in mass spectrum quality resulting from peptide precursor co-isolation and thus prone to false identifications. The deconvolution approach matched complementary b-, y-ions to each precursor peptide mass, which allowed the creation of virtual spectra containing sequence specific fragment ions of each co-isolated peptide. Deconvolution processing resulted in equally efficient identification rates but increased the absolute number of correctly sequenced peptides. The improvement was in the range of 20-35% additional peptide identifications for a HeLa lysate sample. Some correct sequences were identified only using unprocessed spectra; however, the number of these was lower than those where improvement was obtained by mass spectral deconvolution. Tight candidate peptide score distribution and high sensitivity to small changes in the mass spectrum introduced by the employed deconvolution method could explain some of the missing peptide identifications.','https://doi.org/10.1002/pmic.201500549','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(140,'Spectra library assisted de novo peptide sequencing for HCD and ETD spectra pairs','2016-12-01','10.1186/s12859-016-1330-0','Springer Science and Business Media LLC','BACKGROUND: De novo peptide sequencing via tandem mass spectrometry (MS/MS) has been developed rapidly in recent years. With the use of spectra pairs from the same peptide under different fragmentation modes, performance of de novo sequencing is greatly improved. Currently, with large amount of spectra sequenced everyday, spectra libraries containing tens of thousands of annotated experimental MS/MS spectra become available. These libraries provide information of the spectra properties, thus have the potential to be used with de novo sequencing to improve its performance. RESULTS: In this study, an improved de novo sequencing method assisted with spectra library is proposed. It uses spectra libraries as training datasets and introduces significant scores of the features used in our previous de novo sequencing method for HCD and ETD spectra pairs. Two pairs of HCD and ETD spectral datasets were used to test the performance of the proposed method and our previous method. The results show that this proposed method achieves better sequencing accuracy with higher ranked correct sequences and less computational time. CONCLUSIONS: This paper proposed an advanced de novo sequencing method for HCD and ETD spectra pair and used information from spectra libraries and significant improved previous similar methods.','https://doi.org/10.1186/s12859-016-1330-0','BMC Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(141,'MRUniNovo: an efficient tool for de novo peptide sequencing utilizing the Hadoop distributed computing framework','2017-03-15','10.1093/bioinformatics/btw721','Oxford University Press (OUP)','Summary: Tandem mass spectrometry-based de novo peptide sequencing is a complex and time-consuming process. The current algorithms for de novo peptide sequencing cannot rapidly and thoroughly process large mass spectrometry datasets. In this paper, we propose MRUniNovo, a novel tool for parallel de novo peptide sequencing. MRUniNovo parallelizes UniNovo based on the Hadoop compute platform. Our experimental results demonstrate that MRUniNovo significantly reduces the computation time of de novo peptide sequencing without sacrificing the correctness and accuracy of the results, and thus can process very large datasets that UniNovo cannot. Availability and Implementation: MRUniNovo is an open source software tool implemented in java. The source code and the parameter settings are available at http://bioinfo.hupo.org.cn/MRUniNovo/index.php. Supplementary information: Supplementary data are available at Bioinformatics online.','https://doi.org/10.1093/bioinformatics/btw721','Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(142,'NIPTL-Novo: Non-isobaric peptide termini labeling assisted peptide de novo sequencing','2017-02-01','10.1016/j.jprot.2016.12.003','Elsevier BV','A simple and effective de novo sequencing strategy assisted by non-isobaric peptide termini labeling, NIPTL-Novo, was established. The y-series ions and b-series ions of peptides can be clearly distinguished according to the different mass tags incorporated in N-terminus and C-terminus. This is helpful for improving the accuracy of peptide sequencing and increasing the sequencing speed. For the spectra commonly identified by both de novo sequencing and database searching software (Mascot or Maxquant), NIPTL-Novo gave identical result to more than 85% of these spectra. Furthermore, the quantitative profiling of the sample can be performed simultaneously along with de novo sequencing. Finally, this strategy can be applied to discover the peptides with potential mutation sites by combining with mass-defect based isotopic labeling. Significance The aim of the research presented in this paper is to establish a simple but effective de novo sequencing strategy based on non-isobaric peptide termini labeling, named NIPTL-Novo. First, different mass tags incorporated in N-terminus and C-terminus generated by non-isobaric peptide termini labeling will help to distinguish both b and y ion series, which significantly simplify the MS/MS spectra and reduce the time consumption for de novo sequencing. Second, the isolation window of this strategy is just 4Da, much smaller than most existed labeling assisted de novo sequencing methods, which reduces the interferences caused by co-fragmentation ions. Third, the quantitative profiling of the sample can be performed simultaneously along with the de novo sequencing, and the quantitative accuracy is comparable to other chemical labeling methods. Finally, this strategy was expanded to the analysis of peptide mutation with combination of mass-defect based labeling, and two reliable mutated peptides were discovered.','https://doi.org/10.1016/j.jprot.2016.12.003','Journal of Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(143,'Algorithms for de novo peptide sequencing using tandem mass spectrometry','2004-03-01','10.1016/S1741-8364(04)02387-X','Elsevier BV',NULL,'https://doi.org/10.1016/S1741-8364(04)02387-X','Drug Discovery Today: BIOSILICO','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(144,'Algorithms for the de novo sequencing of peptides from tandem mass spectra','2011-10-01','10.1586/epr.11.54','Informa UK Limited','Proteomics is the study of proteins, their time- and location-dependent expression profiles, as well as their modifications and interactions. Mass spectrometry is useful to investigate many of the questions asked in proteomics. Database search methods are typically employed to identify proteins from complex mixtures. However, databases are not often available or, despite their availability, some sequences are not readily found therein. To overcome this problem, de novo sequencing can be used to directly assign a peptide sequence to a tandem mass spectrometry spectrum. Many algorithms have been proposed for de novo sequencing and a selection of them are detailed in this article. Although a standard accuracy measure has not been agreed upon in the field, relative algorithm performance is discussed. The current state of the de novo sequencing is assessed thereafter and, finally, examples are used to construct possible future perspectives of the field.','https://doi.org/10.1586/epr.11.54','Expert Review of Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(145,'De Novo Sequencing and Homology Searching','2012-02-01','10.1074/mcp.O111.014902','Elsevier BV','In proteomics, de novo sequencing is the process of deriving peptide sequences from tandem mass spectra without the assistance of a sequence database. Such analyses have traditionally been performed manually by human experts, and more recently by computer programs that have been developed because of the need for higher throughput. Although powerful, de novo sequencing often can only determine partially correct sequence tags because of imperfect tandem mass spectra. However, these sequence tags can then be searched in a sequence database to identify the exact or a homologous peptide. Homology searches are particularly useful for the study of organisms whose genomes have not been sequenced. This tutorial will present background important to understanding de novo sequencing, suggestions on how to do this manually, plus descriptions of computer algorithms used to automate this process and to subsequently carryout homology-based database searches. This Tutorial is part of the International Proteomics Tutorial Programme (IPTP 1).','https://doi.org/10.1074/mcp.O111.014902','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(146,'Lessons in de novo peptide sequencing by tandem mass spectrometry','2015-01-01','10.1002/mas.21406','Wiley','Mass spectrometry has become the method of choice for the qualitative and quantitative characterization of protein mixtures isolated from all kinds of living organisms. The raw data in these studies are MS/MS spectra, usually of peptides produced by proteolytic digestion of a protein. These spectra are "translated" into peptide sequences, normally with the help of various search engines. Data acquisition and interpretation have both been automated, and most researchers look only at the summary of the identifications without ever viewing the underlying raw data used for assignments. Automated analysis of data is essential due to the volume produced. However, being familiar with the finer intricacies of peptide fragmentation processes, and experiencing the difficulties of manual data interpretation allow a researcher to be able to more critically evaluate key results, particularly because there are many known rules of peptide fragmentation that are not incorporated into search engine scoring. Since the most commonly used MS/MS activation method is collision-induced dissociation (CID), in this article we present a brief review of the history of peptide CID analysis. Next, we provide a detailed tutorial on how to determine peptide sequences from CID data. Although the focus of the tutorial is de novo sequencing, the lessons learned and resources supplied are useful for data interpretation in general.','https://doi.org/10.1002/mas.21406','Mass Spectrometry Reviews','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(147,'Recent Developments in Computational Methods for De Novo Peptide Sequencing from Tandem Mass Spectrometry (MS/MS)','2015-09-23','10.2174/0929866522666150821113127','Bentham Science Publishers Ltd.','Tandem mass spectrometry (MS/MS) has emerged as a major technology for peptide sequencing. Typically, there are three kinds of methods for the peptide sequencing: database searching, peptide tagging, and de novo sequencing. De novo sequencing has drawn increasing attention because of its independence from existing protein databases and potential for identifying new proteins, proteins resulting from mutations, proteins with unexpected modifications and so on. Recently, with the improvements in the accuracy of MS/MS and development of alternative fragmentation modes of MS/MS, many new de novo sequencing methods have been formulated. This paper reviews these recently developed sequencing methods including those for alternative MS/MS spectra. The paper first introduces background knowledge on peptide sequencing and mass spectrometry, and then reviews de novo peptide sequencing methods for traditional CID spectra. After that, it focuses on the recent development of de novo methods for alternative MS/MS spectra. In addition, methods using multiple spectra from the same peptide are surveyed. Finally, conclusions and some directions of future work are discussed.','https://doi.org/10.2174/0929866522666150821113127','Protein & Peptide Letters','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(148,'Algorithms for de-novo sequencing of peptides by tandem mass spectrometry: A review','2023-08-01','10.1016/j.aca.2023.341330','Elsevier BV','Peptide sequencing is of great significance to fundamental and applied research in the fields such as chemical, biological, medicinal and pharmaceutical sciences. With the rapid development of mass spectrometry and sequencing algorithms, de-novo peptide sequencing using tandem mass spectrometry (MS/MS) has become the main method for determining amino acid sequences of novel and unknown peptides. Advanced algorithms allow the amino acid sequence information to be accurately obtained from MS/MS spectra in short time. In this review, algorithms from exhaustive search to the state-of-art machine learning and neural network for high-throughput and automated de-novo sequencing are introduced and compared. Impacts of datasets on algorithm performance are highlighted. The current limitations and promising direction of de-novo peptide sequencing are also discussed in this review.','https://doi.org/10.1016/j.aca.2023.341330','Analytica Chimica Acta','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(149,'Identification of Protein Modifications Using MS/MS de Novo Sequencing and the OpenSea Alignment Algorithm','2005-04-01','10.1021/pr049781j','American Chemical Society (ACS)','Algorithms that can robustly identify post-translational protein modifications from mass spectrometry data are needed for data-mining and furthering biological interpretations. In this study, we determined that a mass-based alignment algorithm (OpenSea) for de novo sequencing results could identify post-translationally modified peptides in a high-throughput environment. A complex digest of proteins from human cataractous lens, a tissue containing a high abundance of modified proteins, was analyzed using two-dimensional liquid chromatography, and data was collected on both high and low mass accuracy instruments. The data were analyzed using automated de novo sequencing followed by OpenSea mass-based sequence alignment. A total of 80 modifications were detected, 36 of which were previously unreported in the lens. This demonstrates the potential to identify large numbers of known and previously unknown protein modifications in a given tissue using automated data processing algorithms such as OpenSea.','https://doi.org/10.1021/pr049781j','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(150,'Lookup Peaks: A Hybrid of de Novo Sequencing and Database Search for Protein Identification by Tandem Mass Spectrometry','2007-02-01','10.1021/ac0617013','American Chemical Society (ACS)','A powerful technique for peptide and protein identification is tandem mass spectrometry followed by database search using a program such as SEQUEST or Mascot. These programs, however, become slow and lose sensitivity when allowing nonspecific cleavages or peptide modifications. De novo sequencing and hybrid methods such as sequence tagging offer speed and robustness for wider searches, yet these approaches require better spectra with more complete and consecutive fragmentation and, hence, are less sensitive to low-abundance peptides. Here we describe a new hybrid method that retains the sensitivity of pure database search. The method uses a small amount of de novo analysis to identify likely b- and y-ion peaks--"lookup peaks"--that can then be used to extract candidate peptides from the database, with the number of candidates tunable to fit a computing budget. We describe a program called ByOnic that implements this method, and we benchmark ByOnic on several data sets, including one of mouse blood plasma spiked with low concentrations of recombinant human proteins. We demonstrate that ByOnic is more sensitive than sequence tagging and, indeed, more sensitive than the three most popular pure database search tools--SEQUEST, Mascot, and X!Tandem--on both the peptide and protein levels. On the mouse plasma samples, ByOnic consistently found spiked proteins missed by the other tools.','https://doi.org/10.1021/ac0617013','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(151,'Application of de Novo Sequencing to Large-Scale Complex Proteomics Data Sets','2016-03-04','10.1021/acs.jproteome.5b00861','American Chemical Society (ACS)','Dependent on concise, predefined protein sequence databases, traditional search algorithms perform poorly when analyzing mass spectra derived from wholly uncharacterized protein products. Conversely, de novo peptide sequencing algorithms can interpret mass spectra without relying on reference databases. However, such algorithms have been difficult to apply to complex protein mixtures, in part due to a lack of methods for automatically validating de novo sequencing results. Here, we present novel metrics for benchmarking de novo sequencing algorithm performance on large-scale proteomics data sets and present a method for accurately calibrating false discovery rates on de novo results. We also present a novel algorithm (LADS) that leverages experimentally disambiguated fragmentation spectra to boost sequencing accuracy and sensitivity. LADS improves sequencing accuracy on longer peptides relative to that of other algorithms and improves discriminability of correct and incorrect sequences. Using these advancements, we demonstrate accurate de novo identification of peptide sequences not identifiable using database search-based approaches.','https://doi.org/10.1021/acs.jproteome.5b00861','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(152,'GA-Novo: De Novo Peptide Sequencing via Tandem Mass Spectrometry Using Genetic Algorithm','2019-03-30','10.1007/978-3-030-16692-2_6','Springer International Publishing','Proteomics is the large-scale analysis of the proteins. The common method for identifying proteins and characterising their amino acid sequences is to digest the proteins into peptides, analyse the peptides using mass spectrometry and assign the resulting tandem mass spectra (MS/MS) to peptides using database search tools. However, database search algorithms are highly dependent on a reference protein database and they cannot identify peptides and proteins not included in the database. Therefore, de novo sequencing algorithms are developed to overcome the problem by directly reconstructing the peptide sequence of an MS/MS spectrum without using any protein database. Current de novo sequencing algorithms often fail to construct the completely matched sequences, and produce partial matches. In this study, we propose a genetic algorithm based method, GA-Novo, to solve the complex optimisation task of de novo peptide sequencing, aiming at constructing full length sequences. Given an MS/MS spectrum, GA-Novo optimises the amino acid sequences to best fit the input spectrum. On the testing dataset, GA-Novo outperforms PEAKS, the most commonly used software for this task, by constructing 8% higher number of fully matched peptide sequences, and 4% higher recall at partially matched sequences.','https://doi.org/10.1007/978-3-030-16692-2_6','Lecture Notes in Computer Science','peer-reviewed',NULL,'pdf');
INSERT INTO publication VALUES(153,'Framework for de novo sequencing of peptide mixtures via network analysis and two-dimensional tandem mass spectrometry','2025-09-04','10.1039/d5sc03762j','Royal Society of Chemistry (RSC)','A 2D tandem mass spectrum of a peptide mixture is organized into a graphical structure. A graph partitioning algorithm extracts the fragmentation trees of individual peptides, and a de novo sequencing algorithm identifies the peptide sequences.','https://doi.org/10.1039/d5sc03762j','Chemical Science','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(154,'An algorithm for peptide de novo sequencing from a group of SILAC labeled MS/MS spectra','2025-06-01','10.1142/S0219720025500076','World Scientific Pub Co Pte Ltd','Shotgun proteomics coupled with high-performance liquid chromatography and mass spectrometry has been instrumental in identifying proteins in complex mixtures. Effective computational approaches are required to automate the spectra interpretation process to handle the vast amount of data collected in a single Liquid Chromatography-Tandem Mass Spectrometry (LC-MS/MS) run. De novo sequencing from MS/MS has emerged as a vital technology for peptide sequencing in proteomics. To enhance the accuracy and practicality of de novo sequencing, previous algorithms have utilized multiple spectra to identify peptide sequences. Here, our study focuses on de novo sequencing of multiple tandem mass spectra of peptides with stable isotope labeling with amino acids in cell culture (SILAC) by incorporating different isotope-labeled amino acids into newly synthesized proteins. Multiple MS/MS spectra for the same peptide sequence are produced by the spectrometer after the SILAC samples undergo processing by LC-MS/MS shotgun proteomics. Taking into consideration the factors such as retention time and precursor ion mass, we aim to identify the peptide sequence with specific SILAC modifications and their locations. To do so, we propose de novo sequencing algorithms to compute the potential candidate peptide sequence by using similarity scores, followed by refinement algorithms to evaluate them. We also use real experimental data to test the algorithms.','https://doi.org/10.1142/S0219720025500076','Journal of Bioinformatics and Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(155,'Shotgun Protein Sequencing by Tandem Mass Spectra Assembly','2004-12-01','10.1021/ac0489162','American Chemical Society (ACS)','The analysis of mass spectrometry data is still largely based on identification of single MS/MS spectra and does not attempt to make use of the extra information available in multiple MS/MS spectra from partially or completely overlapping peptides. Analysis of MS/MS spectra from multiple overlapping peptides opens up the possibility of assembling MS/MS spectra into entire proteins, similarly to the assembly of overlapping DNA reads into entire genomes. In this paper, we present for the first time a way to detect, score, and interpret overlaps between uninterpreted MS/MS spectra in an attempt to sequence entire proteins rather than individual peptides. We show that this approach not only extends the length of reconstructed amino acid sequences but also dramatically improves the quality of de novo peptide sequencing, even for low mass accuracy MS/MS data.','https://doi.org/10.1021/ac0489162','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(156,'De Novo Sequencing of Neuropeptides Using Reductive Isotopic Methylation and Investigation of ESI QTOF MS/MS Fragmentation Pattern of Neuropeptides with N-Terminal Dimethylation','2005-12-01','10.1021/ac051324e','American Chemical Society (ACS)','A stable-isotope dimethyl labeling strategy was previously shown to be a useful tool for quantitative proteomics. More recently, N-terminal dimethyl labeling was also reported for peptide sequencing in combination with database searching. Here, we extend these previous studies by incorporating N-terminal isotopic dimethylation for de novo sequencing of neuropeptides directly from tissue extract without any genomic information. We demonstrated several new sequencing applications of this method in addition to the identification of the N-terminal residue using the enhanced a(1) ion. The isotopic labeling also provides easier and more confident de novo sequencing of peptides by comparing similar MS/MS fragmentation patterns of the isotopically labeled peptide pairs. The current study on neuropeptides shows several distinct fragmentation patterns after N-terminal dimethylation which have not been reported previously. The y((n-1)) ion is enhanced in multiply charged peptides and is weak or missing in singly charged peptides. The MS/MS spectra of singly charged peptides are simplified due to the enhanced N-terminal fragments and suppressed internal fragments. The neutral loss of dimethylamine is also observed. The mechanisms for the above fragmentations are proposed. Finally, the structures of the immonium ion and related ions of N(alpha), N(epsilon)-tetramethylated lysine and N(epsilon)-dimethylated lysine are explored.','https://doi.org/10.1021/ac051324e','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(157,'Peptide Fragment Ion Analyser (PFIA): a simple and versatile tool for the interpretation of tandem mass spectrometric data and de novo sequencing of peptides','2007-09-30','10.1002/rcm.3179','Wiley','The software Peptide Fragment Ion Analyser (PFIA) aids in the analysis and interpretation of tandem mass spectrometric data of peptides. The software package has been designed to facilitate the analysis of product ions derived from acyclic and cyclic peptide natural products that possess unusual amino acid residues and are heavily post-translationally modified. The software consists of two programmes: (a) PFIA-I lists the amino acid compositions and their corresponding product ion types for ''a queried m/z value'' (z = +1) and (b) PFIA-II displays fragmentation pattern diagram(s) and lists all sequence-specific product ion types for the protonated adduct of ''a queried sequence''. The unique feature of PFIA-II is its ability to handle cyclic peptides. The two programmes used in combination can prove helpful for deriving peak assignments in the de novo sequencing of novel peptides.','https://doi.org/10.1002/rcm.3179','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(158,'Spectral Dictionaries: Integrating de novo Peptide Sequencing with Database Search of Tandem Mass Spectra','2009-01-01','10.1074/mcp.M800103-MCP200','Elsevier BV','Database search tools identify peptides by matching tandem mass spectra against a protein database. We study an alternative approach when all plausible de novo interpretations of a spectrum (spectral dictionary) are generated and then quickly matched against the database. We present a new MS-Dictionary algorithm for efficiently generating spectral dictionaries and demonstrate that MS-Dictionary can identify spectra that are missed in the database search. We argue that MS-Dictionary enables proteogenomics searches in six-frame translation of genomic sequences that may be prohibitively time-consuming for existing database search approaches. We show that such searches allow one to correct sequencing errors and find programmed frameshifts.','https://doi.org/10.1074/mcp.M800103-MCP200','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(159,'De Novo MS/MS Sequencing of Native Human Antibodies','2017-01-06','10.1021/acs.jproteome.6b00608','American Chemical Society (ACS)','One direct route for the discovery of therapeutic human monoclonal antibodies (mAbs) involves the isolation of peripheral B cells from survivors/sero-positive individuals after exposure to an infectious reagent or disease etiology, followed by single-cell sequencing or hybridoma generation. Peripheral B cells, however, are not always easy to obtain and represent only a small percentage of the total B-cell population across all bodily tissues. Although it has been demonstrated that tandem mass spectrometry (MS/MS) techniques can interrogate the full polyclonal antibody (pAb) response to an antigen in vivo, all current approaches identify MS/MS spectra against databases derived from genetic sequencing of B cells from the same patient. In this proof-of-concept study, we demonstrate the feasibility of a novel MS/MS antibody discovery approach in which only serum antibodies are required without the need for sequencing of genetic material. Peripheral pAbs from a cytomegalovirus-exposed individual were purified by glycoprotein B antigen affinity and de novo sequenced from MS/MS data. Purely MS-derived mAbs were then manufactured in mammalian cells to validate potency via antigen-binding ELISA. Interestingly, we found that these mAbs accounted for 1 to 2% of total donor IgG but were not detected in parallel sequencing of memory B cells from the same patient.','https://doi.org/10.1021/acs.jproteome.6b00608','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(160,'Computer program (SEQPEP) to aid in the interpretation of high-energy collision tandem mass spectra of peptides','1989-11-01','10.1002/bms.1200181102','Wiley','An algorithm (SEQPEP) that aids in the interpretation of high-energy (greater than 1 kV) collision-induced dissociation mass spectra of peptide ions generated by fast atom bombardment (FAB) ionization is described. The only required input is a list of product ion masses and relative abundances generated by the mass spectrometer data system, the mass of the precursor [M + H]+ ion, and the mass of any C-terminal modification, if present (e.g., amide). Possible N-terminal modifications and amino acid compositions are not required as input. In the output, sequences are ranked according to the fraction of total product ion current that can be accounted for as either sequence-specific or non-sequence-specific fragment ions. These are listed by ion type. One of the major advantages of this program over algorithms described earlier is the incorporation of ion types more recently discovered. Also, this program is much faster, requiring less than 5 min of central processing unit time for an input of as many as 100 product ions. The results obtained from 50 peptides, including some generated when sequencing a protein of previously unknown structure, are discussed.','https://doi.org/10.1002/bms.1200181102','Biological Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(161,'Peptide sequence determination from high-energy collision-induced dissociation spectra using artificial neural networks','1995-10-01','10.1016/1044-0305(95)00477-U','American Chemical Society (ACS)','This paper reports a newly developed technique that uses artificial neural networks to aid in the automated interpretation of peptide sequence from high-energy collision-induced dissociation (CID) tandem mass spectra of peptides. Two artificial neural networks classify fragment ions before the commencement of an iterative sequencing algorithm. The first neural network provides an estimation of whether fragment ions belong to 1 of 11 specific categories, whereas the second network attempts to determine to which category each ion belongs. Based upon numerical results from the two networks, the program generates an idealized spectrum that contains only a single ion type. From this simplified spectrum, the program''s sequencing module, which incorporates a small rule base of fragmentation knowledge, directly generates sequences in a stepwise fashion through a high-speed iterative process. The results with this prototype algorithm, in which the neural networks were trained on a set of reference spectra, suggest that this method is a viable approach to rapid computer interpretation of peptide CID spectra.','https://doi.org/10.1016/1044-0305(95)00477-U','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(162,'Automated interpretation of low-energy collision-induced dissociation spectra by SeqMS, a software aid for de novo sequencing by tandem mass spectrometry','2000-05-01','10.1002/(SICI)1522-2683(20000501)21:9<1694::AID-ELPS1694>3.0.CO;2-W','Wiley','SeqMS, a software aid for de novo sequencing by tandem mass spectrometry (MS/MS), which was initially developed for the automated interpretation of high-energy collision-induced dissociation (CID) MS/MS spectra of peptides, has been applied to the interpretation of low-energy CID and post-source decay (PSD) spectra of peptides. Based on peptide backbone fragmented ions and their related ions, which are the dominant ions observed in the latter two techniques, the types of ions and their propensities to be observed have been optimized for efficient interpretation of the spectra. In a typical example, the modified SeqMS allowed the complete sequencing of a 31-amino acid synthetic peptide, except for the isobaric amino acids (Leu or Ile, and Lys or Gln), based on only the low-energy CID-MS/MS spectrum.','https://doi.org/10.1002/(SICI)1522-2683(20000501)21:9<1694::AID-ELPS1694>3.0.CO;2-W','Electrophoresis','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(163,'De novo sequencing of peptides using MALDI/TOF-TOF','2002-07-01','10.1016/S1044-0305(02)00393-8','American Chemical Society (ACS)','The recently developed MALDI TOF-TOF instrument yields relatively complex but interpretable fragmentation spectra. When coupled with a straightforward sequence extension algorithm, it is possible to develop complete peptide sequences de novo from the spectra. This approach has been applied to a set of peptides derived from typtic digestion of electrophoretically separated sea urchin egg membrane proteins. When directed to proteins that have been described previously, the results were in essential agreement with those obtained by conventional data base searching approaches, with certain important exceptions. The present method detected errors in published sequences and was able to develop sequences from peptides differing in mass by one dalton (Da). These results show both the power of the present approach and the need for using de novo methods more frequently than may be otherwise appreciated.','https://doi.org/10.1016/S1044-0305(02)00393-8','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(164,'Sequit: software for de novo peptide sequencing by matrix-assisted laser desorption/ionization post-source decay mass spectrometry','2004-04-30','10.1002/rcm.1420','Wiley','Peptide sequencing by mass spectrometry is gaining increasing importance for peptide chemistry and proteomics. However, available tools for interpreting matrix-assisted laser desorption/ionization post-source decay (MALDI-PSD) mass spectra depend on databases, and identify peptides by matching experimental data with spectra calculated from database sequences. This severely obstructs the identification of proteins and peptides not listed in databases or of variations, e.g. mutated proteins. The development of a new computer program for database-independent peptide sequencing by MALDI-PSD mass spectrometry is reported here. This computer program was validated by the determination of the correct sequences for various peptides including sequences listed in the sequence databases, but also for peptides that deviate from database sequences or are completely artificial. This strategy should substantially facilitate the identification of novel or variant peptides and proteins, and increase the power of MALDI-PSD analyses in proteomics.','https://doi.org/10.1002/rcm.1420','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(165,'SPIDER: software for protein identification from sequence tags with de novo sequencing error','2005-06-01','10.1142/S0219720005001247','World Scientific Pub Co Pte Ltd','For the identification of novel proteins using MS/MS, de novo sequencing software computes one or several possible amino acid sequences (called sequence tags) for each MS/MS spectrum. Those tags are then used to match, accounting amino acid mutations, the sequences in a protein database. If the de novo sequencing gives correct tags, the homologs of the proteins can be identified by this approach and software such as MS-BLAST is available for the matching. However, de novo sequencing very often gives only partially correct tags. The most common error is that a segment of amino acids is replaced by another segment with approximately the same masses. We developed a new efficient algorithm to match sequence tags with errors to database sequences for the purpose of protein and peptide identification. A software package, SPIDER, was developed and made available on Internet for free public use. This paper describes the algorithms and features of the SPIDER software.','https://doi.org/10.1142/S0219720005001247','Journal of Bioinformatics and Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(166,'GutenTag: High-Throughput Sequence Tagging via an Empirically Derived Fragmentation Model','2003-12-01','10.1021/ac0347462','American Chemical Society (ACS)','Shotgun proteomics is a powerful tool for identifying the protein content of complex mixtures via liquid chromatography and tandem mass spectrometry. The most widely used class of algorithms for analyzing mass spectra of peptides has been database search software such as SEQUEST. A new sequence tag database search algorithm, called GutenTag, makes it possible to identify peptides with unknown posttranslational modifications or sequence variations. This software automates the process of inferring partial sequence "tags" directly from the spectrum and efficiently examines a sequence database for peptides that match these tags. When multiple candidate sequences result from the database search, the software evaluates which is the best match by a rapid examination of spectral fragment ions. We compare GutenTag''s accuracy to that of SEQUEST on a defined protein mixture, showing that both modified and unmodified peptides can be successfully identified by this approach. GutenTag analyzed 33,000 spectra from a human lens sample, identifying peptides that were missed in prior SEQUEST analysis due to sequence polymorphisms and posttranslational modifications. The software is available under license; visit http://fields.scripps.edu for information.','https://doi.org/10.1021/ac0347462','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(167,'Proteomics-Grade de Novo Sequencing Approach','2005-12-01','10.1021/pr050288x','American Chemical Society (ACS)','The conventional approach in modern proteomics to identify proteins from limited information provided by molecular and fragment masses of their enzymatic degradation products carries an inherent risk of both false positive and false negative identifications. For reliable identification of even known proteins, complete de novo sequencing of their peptides is desired. The main problems of conventional sequencing based on tandem mass spectrometry are incomplete backbone fragmentation and the frequent overlap of fragment masses. In this work, the first proteomics-grade de novo approach is presented, where the above problems are alleviated by the use of complementary fragmentation techniques CAD and ECD. Implementation of a high-current, large-area dispenser cathode as a source of low-energy electrons provided efficient ECD of doubly charged peptides, the most abundant species (65-80%), in a typical trypsin-based proteomics experiment. A new linear de novo algorithm is developed combining efficiency and speed, processing on a conventional 3 GHz PC, 1000 MS/MS data sets in 60 s. More than 6% of all MS/MS data for doubly charged peptides yielded complete sequences, and another 13% gave nearly complete sequences with a maximum gap of two amino acid residues. These figures are comparable with the typical success rates (5-15%) of database identification. For peptides reliably found in the database (Mowse score > or = 34), the agreement with de novo-derived full sequences was >95%. Full sequences were derived in 67% of the cases when full sequence information was present in MS/MS spectra. Thus the new de novo sequencing approach reached the same level of efficiency and reliability as conventional database-identification strategies.','https://doi.org/10.1021/pr050288x','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(168,'Spectral Profiles, a Novel Representation of Tandem Mass Spectra and Their Applications for de Novo Peptide Sequencing and Identification','2009-06-01','10.1074/mcp.M800535-MCP200','Elsevier BV','Despite many efforts in the last decade, the progress in de novo peptide sequencing has been slow with only 30-45% of all peptides correctly reconstructed. We argue that accurate full-length peptide sequencing may be an unattainable goal for some spectra and demonstrate how to accurately sequence gapped peptides instead. We further argue that gapped peptides are nearly as useful as full-length peptides for error-tolerant database searches. Gapped peptides occupy a niche between long but inaccurate full-length reconstructions and short but accurate peptide sequence tags. Our MS-Profile tool uses spectral profiles, a new representation of tandem mass spectra, to generate gapped peptides that are longer and more accurate than peptide sequence tags of length 3 traditionally used to speed up database searches in proteomics. In addition, spectral profiles also enable intuitive visualization of all high scoring de novo reconstructions of tandem mass spectra.','https://doi.org/10.1074/mcp.M800535-MCP200','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(169,'Identification of a novel Plasmopara halstedii elicitor protein combining de novo peptide sequencing algorithms and RACE-PCR','2010-05-10','10.1186/1477-5956-8-24','Springer Science and Business Media LLC','BACKGROUND: Often high-quality MS/MS spectra of tryptic peptides do not match to any database entry because of only partially sequenced genomes and therefore, protein identification requires de novo peptide sequencing. To achieve protein identification of the economically important but still unsequenced plant pathogenic oomycete Plasmopara halstedii, we first evaluated the performance of three different de novo peptide sequencing algorithms applied to a protein digests of standard proteins using a quadrupole TOF (QStar Pulsar i). RESULTS: The performance order of the algorithms was PEAKS online > PepNovo > CompNovo. In summary, PEAKS online correctly predicted 45% of measured peptides for a protein test data set.All three de novo peptide sequencing algorithms were used to identify MS/MS spectra of tryptic peptides of an unknown 57 kDa protein of P. halstedii. We found ten de novo sequenced peptides that showed homology to a Phytophthora infestans protein, a closely related organism of P. halstedii. Employing a second complementary approach, verification of peptide prediction and protein identification was performed by creation of degenerate primers for RACE-PCR and led to an ORF of 1,589 bp for a hypothetical phosphoenolpyruvate carboxykinase. CONCLUSIONS: Our study demonstrated that identification of proteins within minute amounts of sample material improved significantly by combining sensitive LC-MS methods with different de novo peptide sequencing algorithms. In addition, this is the first study that verified protein prediction from MS data by also employing a second complementary approach, in which RACE-PCR led to identification of a novel elicitor protein in P. halstedii.','https://doi.org/10.1186/1477-5956-8-24','Proteome Science','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(170,'Shotgun Protein Sequencing with Meta-contig Assembly','2012-10-01','10.1074/mcp.M111.015768','Elsevier BV','Full-length de novo sequencing from tandem mass (MS/MS) spectra of unknown proteins such as antibodies or proteins from organisms with unsequenced genomes remains a challenging open problem. Conventional algorithms designed to individually sequence each MS/MS spectrum are limited by incomplete peptide fragmentation or low signal to noise ratios and tend to result in short de novo sequences at low sequencing accuracy. Our shotgun protein sequencing (SPS) approach was developed to ameliorate these limitations by first finding groups of unidentified spectra from the same peptides (contigs) and then deriving a consensus de novo sequence for each assembled set of spectra (contig sequences). But whereas SPS enables much more accurate reconstruction of de novo sequences longer than can be recovered from individual MS/MS spectra, it still requires error-tolerant matching to homologous proteins to group smaller contig sequences into full-length protein sequences, thus limiting its effectiveness on sequences from poorly annotated proteins. Using low and high resolution CID and high resolution HCD MS/MS spectra, we address this limitation with a Meta-SPS algorithm designed to overlap and further assemble SPS contigs into Meta-SPS de novo contig sequences extending as long as 100 amino acids at over 97% accuracy without requiring any knowledge of homologous protein sequences. We demonstrate Meta-SPS using distinct MS/MS data sets obtained with separate enzymatic digestions and discuss how the remaining de novo sequencing limitations relate to MS/MS acquisition settings.','https://doi.org/10.1074/mcp.M111.015768','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(171,'Mass spectrometry-based protein identification by integrating de novo sequencing with database searching','2013-01-21','10.1186/1471-2105-14-S2-S24','Springer Science and Business Media LLC','BACKGROUND: Mass spectrometry-based protein identification is a very challenging task. The main identification approaches include de novo sequencing and database searching. Both approaches have shortcomings, so an integrative approach has been developed. The integrative approach firstly infers partial peptide sequences, known as tags, directly from tandem spectra through de novo sequencing, and then puts these sequences into a database search to see if a close peptide match can be found. However the current implementation of this integrative approach has several limitations. Firstly, simplistic de novo sequencing is applied and only very short sequence tags are used. Secondly, most integrative methods apply an algorithm similar to BLAST to search for exact sequence matches and do not accommodate sequence errors well. Thirdly, by applying these methods the integrated de novo sequencing makes a limited contribution to the scoring model which is still largely based on database searching. RESULTS: We have developed a new integrative protein identification method which can integrate de novo sequencing more efficiently into database searching. Evaluated on large real datasets, our method outperforms popular identification methods.','https://doi.org/10.1186/1471-2105-14-S2-S24','BMC Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(172,'Error-Tolerant Identification of Peptides in Sequence Databases by Peptide Sequence Tags','1994-12-15','10.1021/ac00096a002','American Chemical Society (ACS)','We demonstrate a new approach to the identification of mass spectrometrically fragmented peptides. A fragmentation spectrum usually contains a short, easily identifiable series of sequence ions, which yields a partial sequence. This partial sequence divides the peptide into three parts-regions 1, 2, and 3-characterized by the added mass m1 of region 1, the partial sequence of region 2, and the added mass m3 of region 3. We call the construct, m1 partial sequence m3, a "peptide sequence tag" and show that it is a highly specific identifier of the peptide. An algorithm developed here that uses the sequence tag to find the peptide in a sequence database is up to 1 million-fold more discriminating than the partial sequence information alone. Peptides can be identified even in the presence of an unknown posttranslational modification or an amino acid substitution between an entry in the sequence database and the measured peptide. These concepts are demonstrated with model and practical examples of electrospray mass spectrometry/mass spectrometry of tryptic peptides. Just two to three amino acid residues derived by fragmentation are enough to identify these peptides. In peptide mapping applications, even less information is necessary.','https://doi.org/10.1021/ac00096a002','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(173,'Rapid de novo peptide sequencing by a combination of nanoelectrospray, isotopic labeling and a quadrupole/time-of-flight mass spectrometer','1997-06-15','10.1002/(SICI)1097-0231(19970615)11:9<1015::AID-RCM958>3.0.CO;2-H','Wiley','Protein microanalysis usually involves the sequencing of gel-separated proteins available in very small amounts. While mass spectrometry has become the method of choice for identifying proteins in databases, in almost all laboratories ''de novo'' protein sequencing is still performed by Edman degradation. Here we show that a combination of the nanoelectrospray ion source, isotopic end labeling of peptides and a quadrupole/ time-of-flight instrument allows facile read-out of the sequences of tryptic peptides. Isotopic labeling was performed by enzymatic digestion of proteins in 1:1 16O/18O water, eliminating the need for peptide derivatization. A quadrupole/time-of-flight mass spectrometer was constructed from a triple quadrupole and an electrospray time-of-flight instrument. Tandem mass spectra of peptides were obtained with better than 50 ppm mass accuracy and resolution routinely in excess of 5000. Unique and error tolerant identification of yeast proteins as well as the sequencing of a novel protein illustrate the potential of the approach. The high data quality in tandem mass spectra and the additional information provided by the isotopic end labeling of peptides enabled automated interpretation of the spectra via simple software algorithms. The technique demonstrated here removes one of the last obstacles to routine and high throughput protein sequencing by mass spectrometry.','https://doi.org/10.1002/(SICI)1097-0231(19970615)11:9<1015::AID-RCM958>3.0.CO;2-H','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(174,'Peptide and protein de novo sequencing by mass spectrometry','2003-10-01','10.1016/j.sbi.2003.09.005','Elsevier BV','Although the advent of large-scale genomic sequencing has greatly simplified the task of determining the primary structures of peptides and proteins, the genomic sequences of many organisms are still unknown. Even for those that are known, modifications such as post-translational events may prevent the identification of all or part of the protein sequence. Thus, complete characterization of the protein primary structure often requires determination of the protein sequence by mass spectrometry with minimal assistance from genomic data - de novo protein sequencing. This task has been facilitated by technical developments during the past few years: ''soft'' ionization techniques, new forms of chemical modification (derivatization), new types of mass spectrometer and improved software.','https://doi.org/10.1016/j.sbi.2003.09.005','Current Opinion in Structural Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(175,'Rapid Validation of Protein Identifications with the Borderline Statistical Confidence via De Novo Sequencing and MS BLAST Searches','2006-09-01','10.1021/pr060200v','American Chemical Society (ACS)','Protein identifications with the borderline statistical confidence are typically produced by matching a few marginal quality MS/MS spectra to database peptide sequences and represent a significant bottleneck in the reliable and reproducible characterization of proteomes. Here, we present a method for rapid validation of borderline hits that circumvents the need in, often biased, manual inspection of raw MS/MS spectra. The approach takes advantage of the independent interpretation of corresponding MS/MS spectra by PepNovo de novo sequencing software followed by mass spectrometry-driven BLAST (MS BLAST) sequence-similarity database searches that utilize all partially inaccurate, degenerate and redundant candidate peptide sequences. In a case study involving the identification of more than 180 Caenorhabditis elegans proteins by nanoLC-MS/MS analysis on a linear ion trap LTQ mass spectrometer, the approach enabled rapid assignment (confirmation or rejection) of more than 70% of Mascot hits of borderline statistical confidence.','https://doi.org/10.1021/pr060200v','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(176,'Straightforward and de Novo Peptide Sequencing by MALDI-MS/MS Using a Lys-N Metalloendopeptidase','2009-04-01','10.1074/mcp.M800249-MCP200','Elsevier BV','In this work, we explore the potential of the metalloendopeptidase Lys-N for MALDI-MS/MS proteomics applications. Initially we digested a HEK293 cellular lysate with Lys-N and, for comparison, in parallel with the protease Lys-C. The resulting peptides were separated by strong cation exchange to enrich and isolate peptides containing a single N-terminal lysine. MALDI-MS/MS analysis of these peptides yielded CID spectra with clear and often complete sequence ladders of b-ions. To test the applicability for de novo sequencing we next separated an ostrich muscle tissue protein lysate by one-dimensional SDS-PAGE. A protein band at 42 kDa was in-gel digested with Lys-N. Relatively straightforward sequencing resulted in the de novo identification of the two ostrich proteins creatine kinase and actin. We therefore conclude that this method that combines Lys-N, strong cation exchange enrichment, and MALDI-MS/MS analysis provides a valuable alternative proteomics strategy.','https://doi.org/10.1074/mcp.M800249-MCP200','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(177,'Dimethyl isotope labeling assisted de novo peptide sequencing','2010-12-01','10.1016/j.jasms.2010.08.007','American Chemical Society (ACS)','Here, we explore a de novo sequencing strategy in which we combine Lys-N protein digestion with differential isotopic dimethyl labeling to facilitate the (de novo) identification of multiply charged peptides in ESI-MS, both under CID and ETD conditions. For a large fraction of the Lys-N generated peptides, all primary amines are present at the N-terminal lysine, enabling specific labeling of the N-terminus. Differential derivatization of only the peptide N-terminus in combination with the simultaneous fragmentation of the corresponding isotopologues allows the straightforward distinction of N-terminal fragments from C-terminal and internal fragments. Furthermore, also singly and multiply charged N-terminal fragments can easily be distinguished due to the mass differences of the isotope labeled fragment pairs. As a proof of concept, we applied this approach to proteins isolated from an avocado fruit, and were able to partially de novo sequence and correctly align, with green plant homologues, a previously uncharacterized avocado ascorbate peroxidase.','https://doi.org/10.1016/j.jasms.2010.08.007','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(178,'De novo peptide sequencing in an ion trap mass spectrometer with 18O labeling','1998-03-14','10.1002/(SICI)1097-0231(19980314)12:5<209::AID-RCM141>3.0.CO;2-S','Wiley','De novo peptide sequencing in an ion trap mass spectrometer coupled on-line with a capillary HPLC using 18O labeling provides a viable alternative to the method using the combination of nanospray, 18O labeling and a quadrupole/time-of-flight mass spectrometer. Seven to sixteen amino acid residues can be sequenced from the liquid chromatography/randem mass spectrometry (LC/MS/MS) spectra. This approach combines the benefit of capillary LC and the high sensitivity of the ion trap operated in the MS/MS mode. The wide availability of the LCQ mass spectrometer makes this approach readily adaptable to the biological mass spectrometry community.','https://doi.org/10.1002/(SICI)1097-0231(19980314)12:5<209::AID-RCM141>3.0.CO;2-S','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(179,'A method for high-sensitivity peptide sequencing using postsource decay matrix-assisted laser desorption ionization mass spectrometry','1999-06-22','10.1073/pnas.96.13.7131','National Academy of Sciences','A method has been developed for de novo peptide sequencing using matrix-assisted laser desorption ionization mass spectrometry. This method will facilitate biological studies that require rapid determination of peptide or protein sequences, e.g., determination of posttranslational modifications, identification of active compounds isolated from combinatorial peptide libraries, and the selective identification of proteins as part of proteome studies. The method involves fast, one-step addition of a sulfonic acid group to the N terminus of tryptic peptides followed by acquisition of postsource decay (PSD) fragment ion spectra. The derivatives are designed to promote efficient charge site-initiated fragmentation of the backbone amide bonds and to selectively enhance the detection of a single fragment ion series that contains the C terminus of the molecule (y-ions). The overall method has been applied to pmol quantities of peptides. The resulting PSD fragment ion spectra often exhibit uninterrupted sequences of 20 or more amino acid residues. However, fragmentation efficiency decreases considerably at amide bonds on the C-terminal side of Pro. The spectra are simple enough that de novo sequence tagging is routine. The technique has been successfully applied to peptide mixtures, to high-mass peptides (up to 3,600 Da) and to the unambiguous identification of proteins isolated from two-dimensional gel electrophoresis. The PSD spectra of these derivatized peptides often allow far more selective protein sequence database searches than those obtained from the spectra of native peptides.','https://doi.org/10.1073/pnas.96.13.7131','Proceedings of the National Academy of Sciences','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(180,'Derivatization procedures to facilitate de novo sequencing of lysine-terminated tryptic peptides using postsource decay matrix-assisted laser desorption/ionization mass spectrometry','2000-12-30','10.1002/1097-0231(20001230)14:24<2348::AID-RCM175>3.0.CO;2-8','Wiley','Guanidination of the epsilon-amino group of lysine-terminated tryptic peptides can be accomplished selectively in one step with O-methylisourea hydrogen sulfate. This reaction converts lysine residues into more basic homoarginine residues. It also protects the epsilon-amino groups against unwanted reaction with sulfonation reagents, which can then be used to selectively modify the N-termini of tryptic peptides. The combined reactions convert lysine-terminated tryptic peptides into modified peptides that are suitable for de novo sequencing by postsource decay matrix-assisted laser desorption/ionization (MALDI) mass spectrometry. The guanidination reaction is very pH dependent. Product yields and reaction kinetics were studied in aqueous solution using either NaOH or diisopropylethylamine as the base. Methods are reported for derivatizing and sequencing lysine-terminated tryptic peptides at low pmole levels. The postsource decay (PSD) MALDI tandem mass spectra of a model peptide (VGGYGYGAK), the homoarginine analog and the sulfonated homoarginine analog are compared. These spectra show the influence that each chemical modification has on the peptide fragmentation pattern. Finally, we demonstrate that definitive protein identifications can be achieved by PSD MALDI sequencing of derivatized peptides obtained from solution digests of model proteins and from in-gel digests of 2D-gel separated proteins.','https://doi.org/10.1002/1097-0231(20001230)14:24<2348::AID-RCM175>3.0.CO;2-8','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(181,'Quantitation and Facilitated de Novo Sequencing of Proteins by Isotopic N-Terminal Labeling of Peptides with a Fragmentation-Directing Moiety','2000-09-01','10.1021/ac000265w','American Chemical Society (ACS)','We describe a method for comparative quantitation and de novo peptide sequencing of proteins separated either by standard chromatographic methods or by one- and two-dimensional polyacrylamide gel electrophoresis. The approach is based on the use of an isotopically labeled reagent to quantitate (by mass spectrometry) the ratio of peptides from digests of a protein being expressed under different conditions. The method allows quantitation of the changes occurring in spots or bands that contain more than one protein and has a greater dynamic range than most staining methods. Since the reagent carries a fixed positive charge under acidic conditions and labels only the N-terminal of peptides, the interpretation of tandem mass spectra to obtain sequence information is greatly simplified. The sequences can easily be extracted for homology searches instead of using indirect mass spectral-based searches and are independent of posttranslational modifications.','https://doi.org/10.1021/ac000265w','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(182,'De novo peptide sequencing and quantitative profiling of complex protein mixtures using mass-coded abundance tagging','2002-02-01','10.1038/nbt0202-163','Springer Science and Business Media LLC','Proteomic studies require efficient, robust, and practical methods of characterizing proteins present in biological samples. Here we describe an integrated strategy for systematic proteome analysis based on differential guanidination of C-terminal lysine residues on tryptic peptides followed by capillary liquid chromatography-electrospray tandem mass spectrometry. The approach, termed mass-coded abundance tagging (MCAT), facilitates the automated, large-scale, and comprehensive de novo determination of peptide sequence and relative quantitation of proteins in biological samples in a single analysis. MCAT offers marked advantages as compared with previously described methods and is simple, economic, and effective when applied to complex proteomic mixtures. MCAT is used to identify proteins, including polymorphic variants, from complex mixtures and measure variation in protein levels from diverse cell types.','https://doi.org/10.1038/nbt0202-163','Nature Biotechnology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(183,'De Novo Peptide Sequencing via Manual Interpretation of MS/MS Spectra','2002-03-01','10.1002/0471140864.ps1611s27','Wiley','Databases of complete genome sequences are rapidly appearing, and a recent trend in interpretation of peptide MS/MS spectra is database matching. A caveat of database matching is that it can only be successful if the database being searched contains the identical amino acid sequence, or one with high homology, to the peptide being investigated. In instances where high-quality MS/MS spectra are obtained for which there is no corresponding database match (e.g., when the peptide of interest is derived from a novel protein from an organism whose genome is not known, has post-translationally modified amino acids, or has multiple amino acid substitutions as compared to the homologous sequence from a different species), de novo (or manual) interpretation of the MS/MS spectrum, as described here, is required. Methods are also provided for verification of the results of the de novo analysis through chemical modification and limited manual Edman degradation of the peptide.','https://doi.org/10.1002/0471140864.ps1611s27','Current Protocols in Protein Science','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(184,'Searching Sequence Databases via De Novo Peptide Sequencing by Tandem Mass Spectrometry','2002-12-01','10.1385/MB:22:3:301','Springer Science and Business Media LLC','There are many computer programs that can match tandem mass spectra of peptides to database-derived sequences; however, situations can arise where mass spectral data cannot be correlated with any database sequence. In such cases, sequences can be automatically deduced de novo, without recourse to sequence databases, and the resulting peptide sequences can be used to perform homologous nonexact searches of sequence databases. This article describes details on how to implement both a de novo sequencing program called "Lutefisk," and a version of FASTA that has been modified to account for sequence ambiguities inherent in tandem mass spectrometry data.','https://doi.org/10.1385/MB:22:3:301','Molecular Biotechnology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(185,'New computational approaches for de novo peptide sequencing from MS/MS experiments','2002-12-01','10.1109/JPROC.2002.805301','Institute of Electrical and Electronics Engineers (IEEE)','We describe computational methods to solve the problem of identifying novel proteins from tandem mass spectrometry (tandem MS or MS/MS) data and introduce new approaches that will give more accurate solutions. These new approaches integrate chemical information and knowledge into a graph-theoretic framework. Two sources of chemical information that we investigate are mass tagging and dissociation chemistry in the tandem MS process itself. We describe machine learning techniques that are used to classify peaks according to ion types based on known dissociation chemistry. We describe the algorithms that are implemented in a software code called PepSUMS. Using PepSUMS, we give results on the effectiveness of the new methods on the ultimate goal of improved protein identification.','https://doi.org/10.1109/JPROC.2002.805301','Proceedings of the IEEE','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(186,'DeNovoID: a web-based tool for identifying peptides from sequence and mass tags deduced from de novo peptide sequencing by mass spectroscopy','2005-07-01','10.1093/nar/gki461','Oxford University Press (OUP)','One of the core activities of high-throughput proteomics is the identification of peptides from mass spectra. Some peptides can be identified using spectral matching programs like Sequest or Mascot, but many spectra do not produce high quality database matches. De novo peptide sequencing is an approach to determine partial peptide sequences for some of the unidentified spectra. A drawback of de novo peptide sequencing is that it produces a series of ordered and disordered sequence tags and mass tags rather than a complete, non-degenerate peptide amino acid sequence. This incomplete data is difficult to use in conventional search programs such as BLAST or FASTA. DeNovoID is a program that has been specifically designed to use degenerate amino acid sequence and mass data derived from MS experiments to search a peptide database. Since the algorithm employed depends on the amino acid composition of the peptide and not its sequence, DeNovoID does not have to consider all possible sequences, but rather a smaller number of compositions consistent with a spectrum. DeNovoID also uses a geometric indexing scheme that reduces the number of calculations required to determine the best peptide match in the database. DeNovoID is available at http://proteomics.mcw.edu/denovoid.','https://doi.org/10.1093/nar/gki461','Nucleic Acids Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(187,'A mixed-integer optimization framework for de novo peptide identification','2007-01-01','10.1002/aic.11061','Wiley','A novel methodology for the de novo identification of peptides by mixed-integer optimization and tandem mass spectrometry is presented in this article. The various features of the mathematical model are presented and examples are used to illustrate the key concepts of the proposed approach. Several problems are examined to illustrate the proposed method''s ability to address (1) residue-dependent fragmentation properties and (2) the variability of resolution in different mass analyzers. A preprocessing algorithm is used to identify important m/z values in the tandem mass spectrum. Missing peaks, resulting from residue-dependent fragmentation characteristics, are dealt with using a two-stage algorithmic framework. A cross-correlation approach is used to resolve missing amino acid assignments and to identify the most probable peptide by comparing the theoretical spectra of the candidate sequences that were generated from the MILP sequencing stages with the experimental tandem mass spectrum.','https://doi.org/10.1002/aic.11061','AIChE Journal','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(188,'Assessing peptide de novo sequencing algorithms performance on large and diverse data sets','2007-09-01','10.1002/pmic.200700224','Wiley','De novo peptide sequencing algorithms are often tested on relatively small data sets made of excellent spectra. Since there are always more and more tandem mass spectra available, we have assembled six large, reliable, and diverse (three mass spectrometer types) data sets intended for such tests and we make them accessible via a web server. To exemplify their use we investigate the performance of Lutefisk, PepNovo, and PepNovoTag, three well-established peptide de novo sequencing programs.','https://doi.org/10.1002/pmic.200700224','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(189,'DirecTag: Accurate Sequence Tags from Peptide MS/MS through Statistical Scoring','2008-09-05','10.1021/pr800154p','American Chemical Society (ACS)','In shotgun proteomics, tandem mass spectra of peptides are typically identified through database search algorithms such as Sequest. We have developed DirecTag, an open-source algorithm to infer partial sequence tags directly from observed fragment ions. This algorithm is unique in its implementation of three separate scoring systems to evaluate each tag on the basis of peak intensity, m/ z fidelity, and complementarity. In data sets from several types of mass spectrometers, DirecTag reproducibly exceeded the accuracy and speed of InsPecT and GutenTag, two previously published algorithms for this purpose. The source code and binaries for DirecTag are available from http://fenchurch.mc.vanderbilt.edu.','https://doi.org/10.1021/pr800154p','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(190,'De novo peptide sequencing by tandem MS using complementary CID and electron transfer dissociation','2009-11-01','10.1002/elps.200900332','Wiley','De novo sequencing of peptides using tandem MS is difficult due to missing fragment ions in the spectra commonly obtained after CID of peptide precursor ions. Complementing CID spectra with spectra obtained in an ion-trap mass spectrometer upon electron transfer dissociation (ETD) significantly increases the sequence coverage with diagnostic ions. In the de novo sequencing algorithm CompNovo presented here, a divide-and-conquer approach was combined with an efficient mass decomposition algorithm to exploit the complementary information contained in CID and ETD spectra. After optimizing the parameters for the algorithm on a well-defined training data set obtained for peptides from nine known proteins, the CompNovo algorithm was applied to the de novo sequencing of peptides derived from a whole protein extract of Sorangium cellulosum bacteria. To 2406 pairs of CID and ETD spectra contained in this data set, 675 fully correct sequences were assigned, which represent a success rate of 28.1%. It is shown that the CompNovo algorithm yields significantly improved sequencing accuracy as compared with published approaches using only CID spectra or combined CID and ETD spectra.','https://doi.org/10.1002/elps.200900332','Electrophoresis','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(191,'ADEPTS: Advanced peptide de novo sequencing with a pair of tandem mass spectra','2010-12-01','10.1142/S0219720010005099','World Scientific Pub Co Pte Ltd','De novo sequencing is an important task in proteomics to identify novel peptide sequences. Traditionally, only one MS/MS spectrum is used for the sequencing of a peptide; however, the use of multiple spectra of the same peptide with different types of fragmentation has the potential to significantly increase the accuracy and practicality of de novo sequencing. Research into the use of multiple spectra is in a nascent stage. We propose a general framework to combine the two different types of MS/MS data. Experiments demonstrate that our method significantly improves the de novo sequencing of existing software.','https://doi.org/10.1142/S0219720010005099','Journal of Bioinformatics and Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(192,'Constrained De Novo Sequencing of Conotoxins','2012-08-03','10.1021/pr300312h','American Chemical Society (ACS)','De novo peptide sequencing by mass spectrometry (MS) can determine the amino acid sequence of an unknown peptide without reference to a protein database. MS-based de novo sequencing assumes special importance in focused studies of families of biologically active peptides and proteins, such as hormones, toxins, and antibodies, for which amino acid sequences may be difficult to obtain through genomic methods. These protein families often exhibit sequence homology or characteristic amino acid content; yet, current de novo sequencing approaches do not take advantage of this prior knowledge and, hence, search an unnecessarily large space of possible sequences. Here, we describe an algorithm for de novo sequencing that incorporates sequence constraints into the core graph algorithm and thereby reduces the search space by many orders of magnitude. We demonstrate our algorithm in a study of cysteine-rich toxins from two cone snail species (Conus textile and Conus stercusmuscarum) and report 13 de novo and about 60 total toxins.','https://doi.org/10.1021/pr300312h','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(193,'Multienzyme deep learning models improve peptide de novo sequencing by mass spectrometry proteomics','2023-01-20','10.1371/journal.pcbi.1010457','Public Library of Science (PLoS)','Generating and analyzing overlapping peptides through multienzymatic digestion is an efficient procedure for de novo protein using from bottom-up mass spectrometry (MS). Despite improved instrumentation and software, de novo MS data analysis remains challenging. In recent years, deep learning models have represented a performance breakthrough. Incorporating that technology into de novo protein sequencing workflows require machine-learning models capable of handling highly diverse MS data. In this study, we analyzed the requirements for assembling such generalizable deep learning models by systemcally varying the composition and size of the training set. We assessed the generated models'' performances using two test sets composed of peptides originating from the multienzyme digestion of samples from various species. The peptide recall values on the test sets showed that the deep learning models generated from a collection of highly N- and C-termini diverse peptides generalized 76% more over the termini-restricted ones. Moreover, expanding the training set''s size by adding peptides from the multienzymatic digestion with five proteases of several species samples led to a 2-3 fold generalizability gain. Furthermore, we tested the applicability of these multienzyme deep learning (MEM) models by fully de novo sequencing the heavy and light monomeric chains of five commercial antibodies (mAbs). MEMs extracted over 10000 matching and overlapped peptides across six different proteases mAb samples, achieving a 100% sequence coverage for 8 of the ten polypeptide chains. We foretell that the MEMs'' proven improvements to de novo analysis will positively impact several applications, such as analyzing samples of high complexity, unknown nature, or the peptidomics field.','https://doi.org/10.1371/journal.pcbi.1010457','PLOS Computational Biology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(194,'Comprehensive evaluation of peptide de novo sequencing tools for monoclonal antibody assembly','2023-01-19','10.1093/bib/bbac542','Oxford University Press (OUP)','Monoclonal antibodies are biotechnologically produced proteins with various applications in research, therapeutics and diagnostics. Their ability to recognize and bind to specific molecule structures makes them essential research tools and therapeutic agents. Sequence information of antibodies is helpful for understanding antibody-antigen interactions and ensuring their affinity and specificity. De novo protein sequencing based on mass spectrometry is a valuable method to obtain the amino acid sequence of peptides and proteins without a priori knowledge. In this study, we evaluated six recently developed de novo peptide sequencing algorithms (Novor, pNovo 3, DeepNovo, SMSNet, PointNovo and Casanovo), which were not specifically designed for antibody data. We validated their ability to identify and assemble antibody sequences on three multi-enzymatic data sets. The deep learning-based tools Casanovo and PointNovo showed an increased peptide recall across different enzymes and data sets compared with spectrum-graph-based approaches. We evaluated different error types of de novo peptide sequencing tools and their performance for different numbers of missing cleavage sites, noisy spectra and peptides of various lengths. We achieved a sequence coverage of 97.69-99.53% on the light chains of three different antibody data sets using the de Bruijn assembler ALPS and the predictions from Casanovo. However, low sequence coverage and accuracy on the heavy chains demonstrate that complete de novo protein sequencing remains a challenging issue in proteomics that requires improved de novo error correction, alternative digestion strategies and hybrid approaches such as homology search to achieve high accuracy on long protein sequences.','https://doi.org/10.1093/bib/bbac542','Briefings in Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(195,'The Hunt Lab Guide to De Novo Peptide Sequence Analysis by Tandem Mass Spectrometry','2024-11-07','10.1016/j.mcpro.2024.100875','Elsevier BV','Donald Hunt has made seminal contributions to the fields of proteomics, immunology, epigenetics, and glycobiology. The foundation of every important work to come out of the Hunt Laboratory is de novo peptide sequencing. For decades, he taught hundreds of students, postdocs, engineers, and scientists to directly interpret mass spectral data. To honor his legacy and ensure that the art of de novo sequencing is not lost, we have adapted his teaching materials into "The Hunt Lab Guide to De Novo Peptide Sequence Analysis by Tandem Mass Spectrometry". In addition to the de novo sequencing tutorials, we present two freely available software tools that facilitate manual interpretation of mass spectra and validation of search results. The first, "Hunt Lab Peptide Fragment Calculator", calculates precursor and fragment mass-to-charge ratios for any peptide. The second program, "Predator Protein Fragment Calculator", was inspired in part by the fragment calculator developed in the Hunt Lab. Its capabilities are enhanced to facilitate interpretation of mass spectral data derived from intact proteins. We hope that the combination of these educational tools will continue to benefit students and researchers by empowering them to interpret data on their own.','https://doi.org/10.1016/j.mcpro.2024.100875','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(196,'QuasiNovo: Algorithms for De Novo Peptide Sequencing','2013-01-01',NULL,'PhD thesis','High-throughput proteomics analysis involves the rapid identification and characterization of large sets of proteins in complex biological samples. Tandem mass spectrometry (MS/MS) has become the leading approach for the experimental identification of proteins. Accurate analysis of the data produced is a computationally challenging process that relies on a complex understanding of molecular dynamics, signal processing, and pattern classification. In this work we address these modeling and classification problems, and introduce an additional data-driven evolutionary information source into the analysis pipeline. The particular problem being solved is peptide sequencing via MS/MS. The objective in solving this problem is to decipher the amino acid sequence of digested proteins (peptides) from the MS/MS spectra produced in a typical experimental protocol. Our approach sequences peptides using only the information contained in the experimental spectrum (de novo) and distributions of amino acid usage learned from large sets of protein sequence data. In this dissertation we pursue three main objectives: an ion classifier based on a neural network which selects informative ions from the spectrum, a peptide sequencer which uses dynamic programming and a scoring function to generate candidate peptide sequences, and a candidate peptide scoring function. Candidate peptide sequences are generated via a dynamic programming graph algorithm, and then scored using a combination of the neural network score, the amino acid usage score, and an edge frequency score. In addition to a complete de novo peptide sequencer, we also examine the use of amino acid usage models independently for reranking candidate peptides.','https://scholarcommons.sc.edu/etd/3586/',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(197,'Orthrus: an AI-powered, cloud-ready, and open-source hybrid approach for metaproteomics','2024-11-15','10.1101/2024.11.15.623814','Cold Spring Harbor Laboratory','While metaproteomics provides invaluable insight into microbial communities and functions, significant bioinformatics challenges persist due to data complexity and the limitations of database searching. Orthrus is a hybrid approach combining transformer-based de novo sequencing with Casanovo and database searching with Sage plus Mokapot rescoring. Benchmarking against PEAKS 11, MaxQuant, and MetaNovo demonstrated high peptide outputs, taxonomic diversity, and proteome coverage. Orthrus is Python-based and accessible via Google Colaboratory.','https://www.biorxiv.org/content/10.1101/2024.11.15.623814v1','bioRxiv','preprint','v1',NULL);
INSERT INTO publication VALUES(198,'Ozboneprot: A de novo sequencing workflow to enable shotgun palaeoproteomics on Australian zooarchaeological and paleontological samples','2026-06-02','10.21203/rs.3.rs-9603698/v1','Research Square','Bone fragmentation comprises a major challenge in the interpretation of past human behaviour and past biodiversity from palaeontological and zooarchaeological assemblages. In many archaeological assemblages, bone elements identifiable to taxa comprise less than 10% of all bone recovered, as the identification of fragmented postcranial elements impedes conclusive taxonomic assignments. To overcome these limitations, the analysis of ancient bone protein (palaeoproteomics) has emerged as a promising approach complementing traditional morphological identifications. Nevertheless, shotgun palaeoproteomics has not been extensively applied to Australian contexts, in part due to the lack of accessible published protein reference sequences. Here we introduce Ozboneprot, a project aimed at the creation of de novo sequences for 21 common proteins likely to be preserved in postcranial zooarchaeological and palaeontological skeletal elements. Through the combination of homology predicted sequences, tandem mass-spectrometry analysis, manual validation and label-free quantification of identified unique peptides, Ozboneprot proposes a methodological pipeline for the publication of open access protein sequences to facilitate zooarchaeological and palaeontological analysis of Australian marsupials, a workflow readily applicable to other species of interest.','https://www.researchsquare.com/article/rs-9603698/v1','Research Square','preprint','v1','crossref');
INSERT INTO publication VALUES(199,'Simultaneous polyclonal antibody sequencing and epitope mapping by cryo electron microscopy and mass spectrometry','2025-04-23','10.7554/eLife.101322.3','eLife Sciences Publications, Ltd','Antibodies are a major component of adaptive immunity against invading pathogens. Here, we explore possibilities for an analytical approach to characterize the antigen-specific antibody repertoire directly from the secreted proteins in convalescent serum. This approach aims to perform simultaneous antibody sequencing and epitope mapping using a combination of single particle cryo-electron microscopy (cryoEM) and bottom-up proteomics techniques based on mass spectrometry (LC-MS/MS). We evaluate the performance of the deep-learning tool ModelAngelo in determining de novo antibody sequences directly from reconstructed 3D volumes of antibody-antigen complexes. We demonstrate that while map quality is a critical bottleneck, it is possible to sequence antibody variable domains from cryoEM reconstructions with accuracies of up to 80–90%. While the rate of errors exceeds the typical levels of somatic hypermutation, we show that the ModelAngelo-derived sequences can be used to assign the used V-genes. This provides a functional guide to assemble de novo peptides from LC-MS/MS data more accurately and improves the tolerance to a background of polyclonal antibody sequences. Following this proof-of-principle, we discuss the feasibility and future directions of this approach to characterize antigen-specific antibody repertoires.','https://elifesciences.org/articles/101322','eLife','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(200,'DLDN-Bench: A Benchmark Framework for Deep Learning de Novo Peptide Sequencing in Proteomics','2026-06-10','10.64898/2026.06.10.728383','Cold Spring Harbor Laboratory','De novo peptide sequencing is an essential approach for analyzing mass spectrometry data because it enables the identification of novel peptides without relying on protein sequence databases. Recent advances in deep learning have substantially improved the performance of de novo sequencing methods, but the rapid emergence of new models has led to heterogeneous evaluation practices and limited comparability. To address this, we introduce DLDN-Bench, a benchmark framework including a set of benchmark datasets derived from human muscle biopsy mass spectrometry data retrieved from PRIDE and annotated through consensus across multiple widely used database search engines. Using these datasets, we systematically benchmark recent deep learning-based de novo sequencing tools alongside traditional approaches. Performance is assessed using established metrics, including precision and coverage relative to a pseudo-ground truth defined by cross-engine agreement. To demonstrate the utility of DLDN-Bench, we benchmark four recent deep learning models and make all results publicly available. This benchmark framework provides a standardized basis for comparing state-of-the-art methods and offers an extensible resource for evaluating future tools in de novo peptide sequencing. Code availabilityhttps://github.com/ddz-icb/DLDN-Bench Data availabilityhttps://doi.org/10.5281/zenodo.19627459','https://www.biorxiv.org/content/10.64898/2026.06.10.728383v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(201,'Multi-Modal Mass Spectrometry Identifies a Conserved Protective Epitope in S. pyogenes Streptolysin O','2023-12-02','10.1101/2023.12.02.569700','Cold Spring Harbor Laboratory','An important element of antibody-guided vaccine design is the use of neutralizing/opsonic monoclonal antibodies to define protective epitopes in their native three-dimensional conformation. Here, we demonstrate a multi-modal mass spectrometry-based strategy for in-depth characterization of antigen-antibody complexes to enable the identification of protective epitopes using the cytolytic exotoxin Streptolysin O (SLO) from Streptococcus pyogenes as a showcase. We first discovered a monoclonal antibody with an undisclosed sequence capable of neutralizing SLO-mediated cytolysis. The amino acid sequence of both the antibody light and the heavy chain was determined using mass spectrometry-based de novo sequencing, followed by chemical crosslinking mass spectrometry to generate distance constraints between the antibody fragment antigen-binding region and SLO. Subsequent integrative computational modeling revealed a discontinuous epitope located in Domain 3 of SLO that was experimentally validated by hydrogen-deuterium exchange mass spectrometry and reverse-engineering of the targeted epitope. The results show that the antibody inhibits SLO-mediated cytolysis by binding to a discontinuous epitope in Domain 3, likely preventing oligomerization and subsequent secondary structure changes critical for pore-formation. The epitope is highly conserved across >98% of the characterized S. pyogenes isolates, making it an attractive target for antibody-based therapy and vaccine design against severe streptococcal infections.','https://www.biorxiv.org/content/10.1101/2023.12.02.569700v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(202,'MemNovo: Look Back at the Spectrum for Balanced De Novo Peptide Sequencing from Mass Spectrometry','2026-06-10','10.48550/arXiv.2606.11868','arXiv','De novo peptide sequencing from tandem mass spectrometry is pivotal in proteomics, enabling identification of novel peptides without reference databases. While recent Transformer-based encoder-decoder models have achieved remarkable performance, we uncover a critical pathology in their inference dynamics. Through comprehensive feature scaling experiments, we demonstrate that existing auto-regressive peptide decoders tend to over-rely on generated-sequence priors while progressively under-utilizing fine-grained physical evidence from the input mass spectrum. This phenomenon leads to suboptimal results, where generated peptide sequences are biologically plausible yet not faithful to the input spectrum. To rectify this, we propose MemNovo, a training-free and plug-and-play mechanism that re-balances peptide and spectral contributions at inference time. MemNovo alleviates the information bottleneck by establishing a persistent spectral memory bank and injecting retrieved features directly into the final decoding stage via an ultra-conservative residual connection. Theoretical analysis confirms that this mechanism restores the mutual information between the decoder state and the raw spectrum. Extensive experiments on the Nine Species benchmark with two representative baselines, Casanovo and InstaNovo, demonstrate that MemNovo consistently improves both amino acid precision and peptide precision, achieving up to 39.1% relative improvement in peptide precision for Casanovo and up to 3.9% for InstaNovo, with negligible computational overhead.','https://arxiv.org/abs/2606.11868','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(203,'Multimodal Mass Spectrometry Identifies a Conserved Protective Epitope in S. pyogenes Streptolysin O','2024-05-03','10.1021/acs.analchem.4c00596','American Chemical Society (ACS)','High Resolution Image Download MS PowerPoint Slide An important element of antibody-guided vaccine design is the use of neutralizing or opsonic monoclonal antibodies to define protective epitopes in their native three-dimensional conformation. Here, we demonstrate a multimodal mass spectrometry-based strategy for in-depth characterization of antigen–antibody complexes to enable the identification of protective epitopes using the cytolytic exotoxin Streptolysin O (SLO) from Streptococcus pyogenes as a showcase. We first discovered a monoclonal antibody with an undisclosed sequence capable of neutralizing SLO-mediated cytolysis. The amino acid sequence of both the antibody light and the heavy chain was determined using mass-spectrometry-based de novo sequencing, followed by chemical cross-linking mass spectrometry to generate distance constraints between the antibody fragment antigen-binding region and SLO. Subsequent integrative computational modeling revealed a discontinuous epitope located in domain 3 of SLO that was experimentally validated by hydrogen–deuterium exchange mass spectrometry and reverse engineering of the targeted epitope. The results show that the antibody inhibits SLO-mediated cytolysis by binding to a discontinuous epitope in domain 3, likely preventing oligomerization and subsequent secondary structure transitions critical for pore-formation. The epitope is highly conserved across >98% of the characterized S. pyogenes isolates, making it an attractive target for antibody-based therapy and vaccine design against severe streptococcal infections.','https://pubs.acs.org/doi/10.1021/acs.analchem.4c00596','Analytical Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(204,'DeNovoGUI: An Open Source Graphical User Interface for de Novo Sequencing of Tandem Mass Spectra','2014-01-07','10.1021/pr4008078','American Chemical Society (ACS)','De novo sequencing is a popular technique in proteomics for identifying peptides from tandem mass spectra without having to rely on a protein sequence database. Despite the strong potential of de novo sequencing algorithms, their adoption threshold remains quite high. We here present a user-friendly and lightweight graphical user interface called DeNovoGUI for running parallelized versions of the freely available de novo sequencing software PepNovo+, greatly simplifying the use of de novo sequencing in proteomics. Our platform-independent software is freely available under the permissible Apache2 open source license. Source code, binaries, and additional documentation are available at http://denovogui.googlecode.com .','https://pubs.acs.org/doi/full/10.1021/pr4008078','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(205,'SearchGUI: A Highly Adaptable Common Interface for Proteomics Search and de Novo Engines','2018-05-18','10.1021/acs.jproteome.8b00175','American Chemical Society (ACS)','Mass-spectrometry-based proteomics has become the standard approach for identifying and quantifying proteins. A vital step consists of analyzing experimentally generated mass spectra to identify the underlying peptide sequences for later mapping to the originating proteins. We here present the latest developments in SearchGUI, a common open-source interface for the most frequently used freely available proteomics search and de novo engines that has evolved into a central component in numerous bioinformatics workflows.','https://pubs.acs.org/doi/10.1021/acs.jproteome.8b00175','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(206,'The dental proteome of Homo antecessor','2020-04-01','10.1038/s41586-020-2153-8','Springer Science and Business Media LLC','The phylogenetic relationships between hominins of the Early Pleistocene epoch in Eurasia, such as Homo antecessor, and hominins that appear later in the fossil record during the Middle Pleistocene epoch, such as Homo sapiens, are highly debated1–5. For the oldest remains, the molecular study of these relationships is hindered by the degradation of ancient DNA. However, recent research has demonstrated that the analysis of ancient proteins can address this challenge6–8. Here we present the dental enamel proteomes of H. antecessor from Atapuerca (Spain)9,10 and Homo erectus from Dmanisi (Georgia)1, two key fossil assemblages that have a central role in models of Pleistocene hominin morphology, dispersal and divergence. We provide evidence that H. antecessor is a close sister lineage to subsequent Middle and Late Pleistocene hominins, including modern humans, Neanderthals and Denisovans. This placement implies that the modern-like face of H. antecessor—that is, similar to that of modern humans—may have a considerably deep ancestry in the genus Homo, and that the cranial morphology of Neanderthals represents a derived form. By recovering AMELY-specific peptide sequences, we also conclude that the H. antecessor molar fragment from Atapuerca that we analysed belonged to a male individual. Finally, these H. antecessor and H. erectus fossils preserve evidence of enamel proteome phosphorylation and proteolytic digestion that occurred in vivo during tooth formation. Our results provide important insights into the evolutionary relationships between H. antecessor and other hominin groups, and pave the way for future studies using enamel proteomes to investigate hominin biology across the existence of the genus Homo. Analyses of the proteomes of dental enamel from Homo antecessor and Homo erectus demonstrate that the Early Pleistocene H. antecessor is a close sister lineage of later Homo sapiens, Neanderthal and Denisovan populations in Eurasia.','https://doi.org/10.1038/s41586-020-2153-8','Nature','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(207,'Early Pleistocene enamel proteome from Dmanisi resolves Stephanorhinus phylogeny','2019-09-11','10.1038/s41586-019-1555-y','Springer Science and Business Media LLC','The sequencing of ancient DNA has enabled the reconstruction of speciation, migration and admixture events for extinct taxa 1 . However, the irreversible post-mortem degradation 2 of ancient DNA has so far limited its recovery-outside permafrost areas-to specimens that are not older than approximately 0.5 million years (Myr) 3 . By contrast, tandem mass spectrometry has enabled the sequencing of approximately 1.5-Myr-old collagen type I 4 , and suggested the presence of protein residues in fossils of the Cretaceous period 5 -although with limited phylogenetic use 6 . In the absence of molecular evidence, the speciation of several extinct species of the Early and Middle Pleistocene epoch remains contentious. Here we address the phylogenetic relationships of the Eurasian Rhinocerotidae of the Pleistocene epoch 7-9 , using the proteome of dental enamel from a Stephanorhinus tooth that is approximately 1.77-Myr old, recovered from the archaeological site of Dmanisi (South Caucasus, Georgia) 10 . Molecular phylogenetic analyses place this Stephanorhinus as a sister group to the clade formed by the woolly rhinoceros (Coelodonta antiquitatis) and Merck''s rhinoceros (Stephanorhinus kirchbergensis). We show that Coelodonta evolved from an early Stephanorhinus lineage, and that this latter genus includes at least two distinct evolutionary lines. The genus Stephanorhinus is therefore currently paraphyletic, and its systematic revision is needed. We demonstrate that sequencing the proteome of Early Pleistocene dental enamel overcomes the limitations of phylogenetic inference based on ancient collagen or DNA. Our approach also provides additional information about the sex and taxonomic assignment of other specimens from Dmanisi. Our findings reveal that proteomic investigation of ancient dental enamel-which is the hardest tissue in vertebrates 11 , and is highly abundant in the fossil record-can push the reconstruction of molecular evolution further back into the Early Pleistocene epoch, beyond the currently known limits of ancient DNA preservation.','https://doi.org/10.1038/s41586-019-1555-y','Nature','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(208,'Enamel proteome shows that Gigantopithecus was an early diverging pongine','2019-11-13','10.1038/s41586-019-1728-8','Springer Science and Business Media LLC','Gigantopithecus blacki was a giant hominid that inhabited densely forested environments of Southeast Asia during the Pleistocene epoch 1 . Its evolutionary relationships to other great ape species, and the divergence of these species during the Middle and Late Miocene epoch (16-5.3 million years ago), remain unclear 2,3 . Hypotheses regarding the relationships between Gigantopithecus and extinct and extant hominids are wide ranging but difficult to substantiate because of its highly derived dentognathic morphology, the absence of cranial and post-cranial remains 1,3-6 , and the lack of independent molecular validation. We retrieved dental enamel proteome sequences from a 1.9-million-year-old G. blacki molar found in Chuifeng Cave, China 7,8 . The thermal age of these protein sequences is approximately five times greater than that of any previously published mammalian proteome or genome. We demonstrate that Gigantopithecus is a sister clade to orangutans (genus Pongo) with a common ancestor about 12-10 million years ago, implying that the divergence of Gigantopithecus from Pongo forms part of the Miocene radiation of great apes. In addition, we hypothesize that the expression of alpha-2-HS-glycoprotein, which has not been previously observed in enamel proteomes, had a role in the biomineralization of the thick enamel crowns that characterize the large molars in Gigantopithecus 9,10 . The survival of an Early Pleistocene dental enamel proteome in the subtropics further expands the scope of palaeoproteomic analysis into geographical areas and time periods previously considered incompatible with the preservation of substantial amounts of genetic information.','https://doi.org/10.1038/s41586-019-1728-8','Nature','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(209,'Protein sequences bound to mineral surfaces persist into deep time','2016-09-27','10.7554/eLife.17092','eLife Sciences Publications, Ltd','Proteins persist longer in the fossil record than DNA, but the longevity, survival mechanisms and substrates remain contested. Here, we demonstrate the role of mineral binding in preserving the protein sequence in ostrich (Struthionidae) eggshell, including from the palaeontological sites of Laetoli (3.8 Ma) and Olduvai Gorge (1.3 Ma) in Tanzania. By tracking protein diagenesis back in time we find consistent patterns of preservation, demonstrating authenticity of the surviving sequences. Molecular dynamics simulations of struthiocalcin-1 and -2, the dominant proteins within the eggshell, reveal that distinct domains bind to the mineral surface. It is the domain with the strongest calculated binding energy to the calcite surface that is selectively preserved. Thermal age calculations demonstrate that the Laetoli and Olduvai peptides are 50 times older than any previously authenticated sequence (equivalent to ~16 Ma at a constant 10°C).','https://doi.org/10.7554/eLife.17092','eLife','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(210,'Prosit: proteome-wide prediction of peptide tandem mass spectra by deep learning','2019-05-27','10.1038/s41592-019-0426-7','Springer Science and Business Media LLC','In mass-spectrometry-based proteomics, the identification and quantification of peptides and proteins heavily rely on sequence database searching or spectral library matching. The lack of accurate predictive models for fragment ion intensities impairs the realization of the full potential of these approaches. Here, we extended the ProteomeTools synthetic peptide library to 550,000 tryptic peptides and 21 million high-quality tandem mass spectra. We trained a deep neural network, termed Prosit, resulting in chromatographic retention time and fragment ion intensity predictions that exceed the quality of the experimental data. Integrating Prosit into database search pipelines led to more identifications at >10× lower false discovery rates. We show the general applicability of Prosit by predicting spectra for proteases other than trypsin, generating spectral libraries for data-independent acquisition and improving the analysis of metaproteomes. Prosit is integrated into ProteomicsDB, allowing search result re-scoring and custom spectral library generation for any organism on the basis of peptide sequence alone.','https://doi.org/10.1038/s41592-019-0426-7','Nature Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(211,'MS2Rescore: Data-Driven Rescoring Dramatically Boosts Immunopeptide Identification Rates','2022-08-01','10.1016/j.mcpro.2022.100266','Elsevier BV','Immunopeptidomics aims to identify major histocompatibility complex (MHC)-presented peptides on almost all cells that can be used in anti-cancer vaccine development. However, existing immunopeptidomics data analysis pipelines suffer from the nontryptic nature of immunopeptides, complicating their identification. Previously, peak intensity predictions by MS 2 PIP and retention time predictions by DeepLC have been shown to improve tryptic peptide identifications when rescoring peptide-spectrum matches with Percolator. However, as MS 2 PIP was tailored toward tryptic peptides, we have here retrained MS 2 PIP to include nontryptic peptides. Interestingly, the new models not only greatly improve predictions for immunopeptides but also yield further improvements for tryptic peptides. We show that the integration of new MS 2 PIP models, DeepLC, and Percolator in one software package, MS 2 Rescore, increases spectrum identification rate and unique identified peptides with 46% and 36% compared to standard Percolator rescoring at 1% FDR. Moreover, MS 2 Rescore also outperforms the current state-of-the-art in immunopeptide-specific identification approaches. Altogether, MS 2 Rescore thus allows substantially improved identification of novel epitopes from existing immunopeptidomics workflows.','https://doi.org/10.1016/j.mcpro.2022.100266','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(212,'PeptideShaker enables reanalysis of MS-derived proteomics data sets','2015-01-09','10.1038/nbt.3109','Springer Science and Business Media LLC',NULL,'https://doi.org/10.1038/nbt.3109','Nature Biotechnology','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(213,'A Review and Database of Snake Venom Proteomes','2017-09-18','10.3390/toxins9090290','MDPI AG','Advances in the last decade combining transcriptomics with established proteomics methods have made possible rapid identification and quantification of protein families in snake venoms. Although over 100 studies have been published, the value of this information is increased when it is collated, allowing rapid assimilation and evaluation of evolutionary trends, geographical variation, and possible medical implications. This review brings together all compositional studies of snake venom proteomes published in the last decade. Compositional studies were identified for 132 snake species: 42 from 360 (12%) Elapidae (elapids), 20 from 101 (20%) Viperinae (true vipers), 65 from 239 (27%) Crotalinae (pit vipers), and five species of non-front-fanged snakes. Approximately 90% of their total venom composition consisted of eight protein families for elapids, 11 protein families for viperines and ten protein families for crotalines. There were four dominant protein families: phospholipase A₂s (the most common across all front-fanged snakes), metalloproteases, serine proteases and three-finger toxins. There were six secondary protein families: cysteine-rich secretory proteins, l-amino acid oxidases, kunitz peptides, C-type lectins/snaclecs, disintegrins and natriuretic peptides. Elapid venoms contained mostly three-finger toxins and phospholipase A₂s and viper venoms metalloproteases, phospholipase A₂s and serine proteases. Although 63 protein families were identified, more than half were present in <5% of snake species studied and always in low abundance. The importance of these minor component proteins remains unknown.','https://doi.org/10.3390/toxins9090290','Toxins','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(214,'Human plasma IgG1 repertoires are simple, unique, and dynamic','2021-12-01','10.1016/j.cels.2021.08.008','Elsevier BV','Although humans can produce billions of IgG1 variants through recombination and hypermutation, the diversity of IgG1 clones circulating in human blood plasma has largely eluded direct characterization. Here, we combined several mass-spectrometry-based approaches to reveal that the circulating IgG1 repertoire in human plasma is dominated by a limited number of clones in healthy donors and septic patients. We observe that each individual donor exhibits a unique serological IgG1 repertoire, which remains stable over time but can adapt rapidly to changes in physiology. We introduce an integrative protein- and peptide-centric approach to obtain and validate a full sequence of an individual plasma IgG1 clone de novo. This IgG1 clone emerged at the onset of a septic episode and exhibited a high mutation rate (13%) compared with the closest matching germline DNA sequence, highlighting the importance of de novo sequencing at the protein level. A record of this paper''s transparent peer review process is included in the supplemental information.','https://doi.org/10.1016/j.cels.2021.08.008','Cell Systems','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(215,'MS2PIP: a tool for MS/MS peak intensity prediction','2013-09-27','10.1093/bioinformatics/btt544','Oxford University Press (OUP)','MOTIVATION: Tandem mass spectrometry provides the means to match mass spectrometry signal observations with the chemical entities that generated them. The technology produces signal spectra that contain information about the chemical dissociation pattern of a peptide that was forced to fragment using methods like collision-induced dissociation. The ability to predict these MS(2) signals and to understand this fragmentation process is important for sensitive high-throughput proteomics research. RESULTS: We present a new tool called MS(2)PIP for predicting the intensity of the most important fragment ion signal peaks from a peptide sequence. MS(2)PIP pre-processes a large dataset with confident peptide-to-spectrum matches to facilitate data-driven model induction using a random forest regression learning algorithm. The intensity predictions of MS(2)PIP were evaluated on several independent evaluation sets and found to correlate significantly better with the observed fragment-ion intensities as compared with the current state-of-the-art PeptideART tool. AVAILABILITY: MS(2)PIP code is available for both training and predicting at http://compomics.com/.','https://doi.org/10.1093/bioinformatics/btt544','Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(216,'Awesome De Novo Peptide Sequencing','2026-06-24','10.5281/zenodo.20825737','Zenodo','A comprehensive, curated, and interactive map of the de novo peptide sequencing field — algorithms, post-processors, downstream applications, and adjacent tools, covering both deep-learning and classical approaches. Includes a SQLite database of papers, models, authors, affiliations, and venues, alongside a Quarto-based interactive website with Observable JS visualisations tracking publication impact, journal metrics, and GitHub activity across the field.','https://doi.org/10.5281/zenodo.20825737','Zenodo','resource','v0.1.0','openalex');
INSERT INTO publication VALUES(217,'Awesome-Denovo-Peptide-Sequencing','2024-04-10',NULL,'GitHub',NULL,'https://github.com/jingbo02/Awesome-Denovo-Peptide-Sequencing','GitHub','resource',NULL,NULL);
INSERT INTO publication VALUES(218,'Foundation model for mass spectrometry proteomics','2025-05-16','10.48550/arXiv.2505.10848','arXiv','Mass spectrometry is the dominant technology in the field of proteomics, enabling high-throughput analysis of the protein content of complex biological samples. Due to the complexity of the instrumentation and resulting data, sophisticated computational methods are required for the processing and interpretation of acquired mass spectra. Machine learning has shown great promise to improve the analysis of mass spectrometry data, with numerous purpose-built methods for improving specific steps in the data acquisition and analysis pipeline reaching widespread adoption. Here, we propose unifying various spectrum prediction tasks under a single foundation model for mass spectra. To this end, we pre-train a spectrum encoder using de novo sequencing as a pre-training task. We then show that using these pre-trained spectrum representations improves our performance on the four downstream tasks of spectrum quality prediction, chimericity prediction, phosphorylation prediction, and glycosylation status prediction. Finally, we perform multi-task fine-tuning and find that this approach improves the performance on each task individually. Overall, our work demonstrates that a foundation model for tandem mass spectrometry proteomics trained on de novo sequencing learns generalizable representations of spectra, improves performance on downstream tasks where training data is limited, and can ultimately enhance data acquisition and analysis in proteomics experiments.','https://arxiv.org/abs/2505.10848','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(219,'π-HelixNovo2: Making Accurate Online De Novo Peptide Sequencing Available to All','2026-06-25','10.1093/gpbjnl/qzag049','Oxford University Press (OUP)','De novo peptide sequencing, the mainstream technique for identifying novel peptides, has recently seen remarkable improvements due to deep learning approaches. However, existing models struggle to effectively enhance the encoding of mass spectra and the decoding of amino acids, which limits their overall performance. Moreover, these models lack peptide filtering for de novo peptides, and often present challenges for users without programming expertise. Here, we propose π-HelixNovo2, a de novo peptide sequencing model that integrates complementary spectrum and bidirectional decoding within a Transformer framework. We further propose a peptide filtering strategy to identify the correct peptide-spectrum matches from the results of π-HelixNovo2. Our experiments demonstrate that π-HelixNovo2 outperforms state-of-the-art models, offering reliable performance in identifying antibody peptides, multi-enzyme cleavage peptides, non-enzymatic peptides, and analyzing the gut metaproteome. Finally, we trained π-HelixNovo2 on the large-scale MassIVE-KB dataset, and present an open, user-friendly, and online computational platform to make π-HelixNovo2 freely available to all (https://openi.pcl.ac.cn/OpenI/pi-HelixNovo-NPU).','https://academic.oup.com/gpb/advance-article/doi/10.1093/gpbjnl/qzag049/8716247','Genomics, Proteomics & Bioinformatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(220,'Learning Fragmentation Physics or Exploiting Sequence Priors? Benchmarking Bias in Deep Learning Models for De Novo Peptide Sequencing','2026-06-23','10.64898/2026.06.23.734131','Cold Spring Harbor Laboratory','Deep learning models have advanced de novo peptide sequencing, but their predictions may reflect both physics-based spectral evidence and learned peptide-sequence priors. Systematically measuring such prior-associated behavior is important for benchmarking model robustness beyond conventional proteomics data. Here, we introduce the Prior Bias Index (PBI), a general framework for measuring the extent to which model behavior shifts toward prior-associated reference patterns under controlled conditions, and implement it as DeNovo-PBI, a benchmark for quantifying prior bias in de novo peptide sequencing models. DeNovo-PBI combines benchmark dataset construction, in silico sequence and spectral perturbation workflows, PBI-based metrics, and analysis algorithms to evaluate three forms of prior-associated behavior: sequence-distribution dependence, database amino-acid-pair order preference, and mutation-group prediction consistency under shared sequence context. In addition to experimentally acquired peptide spectra, we generated in silico spectra from random, natural, and mutated peptide sequences and selectively removed fragment ions that distinguish N-terminal residue orders. Across these assays, deep learning models showed peptide-sequence-distribution-dependent performance and strong directional amino-acid-pair order preferences even when order-diagnostic spectral evidence was removed. DeNovo-PBI provides a quantitative benchmark for measuring, comparing, and interpreting learned bias in de novo peptide sequencing models.','https://www.biorxiv.org/content/10.64898/2026.06.23.734131v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(221,'False discovery rate control for trustworthy AI-based de novo peptide sequencing','2026-06-29','10.64898/2026.06.29.735174','Cold Spring Harbor Laboratory','AI-based de novo peptide sequencing predicts peptide sequences from tandem mass spectra, enabling identification beyond predefined databases but leaving prediction reliability difficult to assess, particularly with respect to false discovery rate (FDR). In database search, FDR control is provided by target-decoy competition over a finite search space, whereas de novo predictions are generated in open sequence space and lack naturally matched sequence-level decoys. Here we introduce Counterpart Calibration Theory (CCT), a theory-guided framework that reframes de novo FDR control as a four-group score-ranking and threshold-selection problem over target-side predictions and matched counterpart-side comparators. Implemented in {pi}-NovoQC, CCT provides dual-level FDR control at the peptide-spectrum match and peptide levels. Across models, datasets, instruments and acquisition modes, {pi}-NovoQC achieves stable FDR control while preserving identification yield. In large-scale proteomic applications, {pi}-NovoQC recovers low-abundance in-database peptides missed by database search and provides de novo-supported protein-group and variant evidence.','https://www.biorxiv.org/content/10.64898/2026.06.29.735174v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(222,'Regressor-guided Diffusion Model for De Novo Peptide Sequencing with Explicit Mass Control','2026-02-23','10.48550/arXiv.2602.20209','arXiv','The discovery of novel proteins relies on sensitive protein identification, for which de novo peptide sequencing (DNPS) from mass spectra is a crucial approach. While deep learning has advanced DNPS, existing models inadequately enforce the fundamental mass consistency constraint, that a predicted peptide''s mass must match the experimental measured precursor mass. Previous DNPS methods often treat this critical information as a simple input feature or use it in post-processing, leading to numerous implausible predictions that do not adhere to this fundamental physical property. To address this limitation, we introduce DiffuNovo, a novel regressor-guided diffusion model for de novo peptide sequencing that provides explicit peptide-level mass control. Our approach integrates the mass constraint at two critical stages: during training, a novel peptide-level mass loss guides model optimization, while at inference, regressor-based guidance from gradient-based updates in the latent space steers the generation to compel the predicted peptide adheres to the mass constraint. Comprehensive evaluations on established benchmarks demonstrate that DiffuNovo surpasses state-of-the-art methods in DNPS accuracy. Additionally, as the first DNPS model to employ a diffusion model as its core backbone, DiffuNovo leverages the powerful controllability of diffusion architecture and achieves a significant reduction in mass error, thereby producing much more physically plausible peptides. These innovations represent a substantial advancement toward robust and broadly applicable DNPS. The source code is available in the supplementary material.','https://arxiv.org/abs/2602.20209','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(223,'Improving the Results of De novo Peptide Identification via Tandem Mass Spectrometry Using a Genetic Programming-based Scoring Function for Re-ranking Peptide-Spectrum Matches','2019-08-12','10.48550/arXiv.1908.08010','arXiv','De novo peptide sequencing algorithms have been widely used in proteomics to analyse tandem mass spectra (MS/MS) and assign them to peptides, but quality-control methods to evaluate the confidence of de novo peptide sequencing are lagging behind. A fundamental part of a quality-control method is the scoring function used to evaluate the quality of peptide-spectrum matches (PSMs). Here, we propose a genetic programming (GP) based method, called GP-PSM, to learn a PSM scoring function for improving the rate of confident peptide identification from MS/MS data. The GP method learns from thousands of MS/MS spectra. Important characteristics about goodness of the matches are extracted from the learning set and incorporated into the GP scoring functions. We compare GP-PSM with two methods including Support Vector Regression (SVR) and Random Forest (RF). The GP method along with RF and SVR, each is used for post-processing the results of peptide identification by PEAKS, a commonly used de novo sequencing method. The results show that GP-PSM outperforms RF and SVR and discriminates accurately between correct and incorrect PSMs. It correctly assigns peptides to 10% more spectra on an evaluation dataset containing 120 MS/MS spectra and decreases the false positive rate (FPR) of peptide identification.','https://arxiv.org/abs/1908.08010','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(224,'GA-Novo: De Novo Peptide Sequencing via Tandem Mass Spectrometry using Genetic Algorithm','2019-02-03','10.48550/arXiv.1902.00845','arXiv','Proteomics is the large-scale analysis of the proteins. The common method for identifying proteins and characterising their amino acid sequences is to digest the proteins into peptides, analyse the peptides using mass spectrometry and assign the resulting tandem mass spectra (MS/MS) to peptides using database search tools. However, database search algorithms are highly dependent on a reference protein database and they cannot identify peptides and proteins not included in the database. Therefore, de novo sequencing algorithms are developed to overcome the problem by directly reconstructing the peptide sequence of an MS/MS spectrum without using any protein database. Current de novo sequencing algorithms often fail to construct the completely matched sequences, and produce partial matches. In this study, we propose a genetic algorithm based method, GA-Novo, to solve the complex optimisation task of de novo peptide sequencing, aiming at constructing full length sequences. Given an MS/MS spectrum, GA-Novo optimises the amino acid sequences to best fit the input spectrum. On the testing dataset, GA-Novo outperforms PEAKS, the most commonly used software for this task, by constructing 8% higher number of fully matched peptide sequences, and 4% higher recall at partially matched sequences.','https://arxiv.org/abs/1902.00845','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(225,'Protein identification with deep learning: from abc to xyz','2017-10-08','10.48550/arXiv.1710.02765','arXiv','Proteins are the main workhorses of biological functions in a cell, a tissue, or an organism. Identification and quantification of proteins in a given sample, e.g. a cell type under normal/disease conditions, are fundamental tasks for the understanding of human health and disease. In this paper, we present DeepNovo, a deep learning-based tool to address the problem of protein identification from tandem mass spectrometry data. The idea was first proposed in the context of de novo peptide sequencing [1] in which convolutional neural networks and recurrent neural networks were applied to predict the amino acid sequence of a peptide from its spectrum, a similar task to generating a caption from an image. We further develop DeepNovo to perform sequence database search, the main technique for peptide identification that greatly benefits from numerous existing protein databases. We combine two modules de novo sequencing and database search into a single deep learning framework for peptide identification, and integrate de Bruijn graph assembly technique to offer a complete solution to reconstruct protein sequences from tandem mass spectrometry data. This paper describes a comprehensive protocol of DeepNovo for protein identification, including training neural network models, dynamic programming search, database querying, estimation of false discovery rate, and de Bruijn graph assembly. Training and testing data, model implementations, and comprehensive tutorials in form of IPython notebooks are available in our GitHub repository (https://github.com/nh2tran/DeepNovo).','https://arxiv.org/abs/1710.02765','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(226,'Antilope – A Lagrangian Relaxation Approach to the de novo Peptide Sequencing Problem','2011-02-19','10.48550/arXiv.1102.4016','arXiv','Peptide sequencing from mass spectrometry data is a key step in proteome research. Especially de novo sequencing, the identification of a peptide from its spectrum alone, is still a challenge even for state-of-the-art algorithmic approaches. In this paper we present Antilope, a new fast and flexible approach based on mathematical programming. It builds on the spectrum graph model and works with a variety of scoring schemes. Antilope combines Lagrangian relaxation for solving an integer linear programming formulation with an adaptation of Yen''s k shortest paths algorithm. It shows a significant improvement in running time compared to mixed integer optimization and performs at the same speed like other state-of-the-art tools. We also implemented a generic probabilistic scoring scheme that can be trained automatically for a dataset of annotated spectra and is independent of the mass spectrometer type. Evaluations on benchmark data show that Antilope is competitive to the popular state-of-the-art programs PepNovo and NovoHMM both in terms of run time and accuracy. Furthermore, it offers increased flexibility in the number of considered ion types. Antilope will be freely available as part of the open source proteomics library OpenMS.','https://arxiv.org/abs/1102.4016','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(227,'Protein Sequencing with an Adaptive Genetic Algorithm from Tandem Mass Spectrometry','2008-04-08','10.48550/arXiv.0804.1201','arXiv','In Proteomics, only the de novo peptide sequencing approach allows a partial amino acid sequence of a peptide to be found from a MS/MS spectrum. In this article a preliminary work is presented to discover a complete protein sequence from spectral data (MS and MS/MS spectra). For the moment, our approach only uses MS spectra. A Genetic Algorithm (GA) has been designed with a new evaluation function which works directly with a complete MS spectrum as input and not with a mass list like the other methods using this kind of data. Thus the mono isotopic peak extraction step which needs a human intervention is deleted. The goal of this approach is to discover the sequence of unknown proteins and to allow a better understanding of the differences between experimental proteins and proteins from databases.','https://arxiv.org/abs/0804.1201','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(228,'Lactation-stage specific protein shifts in koala milk mirror the joey''s growth needs','2026-04-01','10.1016/j.ijbiomac.2026.151640','Elsevier BV','Koalas (Phascolarctos cinereus) give birth to highly altricial young that rely on maternal milk for nutritional support and immune protection in the first year of life. This study applied proteomics to analyse stage-specific shifts in the koala milk proteome across early-, mid-, and late-lactation. Proteins were extracted from seven samples and analysed using liquid chromatography-tandem mass spectrometry. Quantitative profiling identified 874, 1220, and 498 proteins in early-, mid- and late-lactation stages, respectively. The most abundant proteins-including β-lactoglobulin, caseins, clusterin, trichosurin, albumin and lactotransferrin-were consistently detected across all stages, reflecting crucial roles in nutrition, immune function, and detoxification. Protein-protein interaction analyses revealed functionally important protein clusters associated with energy metabolism, translation, protein transportation, and these clusters exhibited shifts in abundance that align with the developmental and metabolic demands of the joey. Gene set variation analysis revealed stage-dependent regulation of immune pathway proteins, supporting foundational immune development in early-lactation, heightened neuroimmune protection in mid-lactation, and increased immune competence in late-lactation. These findings provide comprehensive insight into the dynamic adaptation of koala milk composition to joey development and may inform the design of nutritionally and immunologically optimised milk replacers for koala conservation and rehabilitation.','https://www.sciencedirect.com/science/article/pii/S0141813026015667','International Journal of Biological Macromolecules','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(229,'Characterisation of pouch secretions from breeding Tasmanian devils','2026-03-24','10.1093/reprod/xaag024','Oxford University Press (OUP)','Tasmanian devils (Sarcophilus harrisii), like all marsupials, give birth to altricial young. Here we employ proteomic analysis to identify components of devil pouch secretions that may contribute to offspring survival and development. Proteins were extracted from five samples and analysed by liquid chromatography-tandem mass spectrometry. Peptide-level evidence revealed proteins involved in a diverse set of immune pathways, including those mediating iron-ion transport, defence responses to bacteria, innate immune responses, and antigen processing. A core set of 200 proteins was identified across at least three samples, 63 of which were associated with antimicrobial or immunoregulatory functions. These included immunoglobulins, components of complement and the coagulation cascade, and antimicrobial proteins and peptides. These findings provide preliminary evidence that the Tasmanian devil''s pouch secretions could be involved in microbiome restructuring during lactation through their immune protein content. Moreover, the data indicate that these proteins may act synergistically in pathways triggered by immune challenges or physiological stress.','https://academic.oup.com/reproduction/article/171/3/xaag024/8529050','Reproduction','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(230,'MARLOWE: Taxonomic Characterization of Unknown Samples for Forensics Using De Novo Peptide Identification','2025-06-02','10.1101/2024.09.30.615220','Cold Spring Harbor Laboratory','We present a computational tool, MARLOWE, for source organism characterization of unknown, forensic biological samples. The intent of MARLOWE is to address a gap in applying proteomics data analysis to forensic applications. MARLOWE produces a list of potential source organisms given confident peptide tags derived from de novo peptide sequencing and a statistical approach to assign peptides to organisms in a probabilistic manner, based on a broad sequence database. In this way, the algorithm assumes no a priori knowledge of potential sources, and the probabilistic way peptides are taxonomically assigned and then scored enables results to be unbiased (within the constraints of the sequence database). In a proof-of-concept study, we examined MARLOWEs performance on two datasets, the Biodiversity dataset and the Bacillus cereus superspecies dataset. Not only did MARLOWE demonstrate successful characterization to true contributors in single source and binary mixtures in the Biodiversity dataset, but also provided sufficient specificity to distinguish species within a bacterial superspecies group. We also compared MARLOWEs results to those of MiCId, a leading microbial identification/characterization tool based on proteomics database search. Comparison of the two tools using 225 mass spectrometry data files yielded comparable performance, with slightly higher accuracy and specificity for MiCId. At the species level, MARLOWE achieved a specificity of 91.4% at 5% FDR. These results suggest that MARLOWE is suitable for candidate- or lead-generation identification of single-organism and binary samples that can generate forensic leads and aid in selecting appropriate follow-on analyses in a forensic context.','https://www.biorxiv.org/content/10.1101/2024.09.30.615220v2','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(231,'Identification of Species-Specific Peptide Markers in Highly Processed Meat Products Using De Novo Sequencing','2026-06-26','10.3390/foods15132294','MDPI AG','Processed meat products represent a major challenge for proteomic species identification due to extensive thermal treatment and protein structural changes. In this study, species-specific peptides in pork, chicken, and bovine meat products were identified using a directed fragmentation-assisted de novo sequencing workflow that combines 4-formylbenzene-1,3-disulfonic acid (FBDA) peptide derivatization, dual-polarity data-independent mass spectrometry (DIA-MS), and Protein Acrobat de novo sequencing software. Comparative analysis of non-fractionated and strong cation exchange (SCX)-fractionated pork luncheon samples improved peptide and protein identification after fractionation, with 312 peptides and 115 protein groups detected exclusively in fractionated samples. Species-specific peptides were predominantly assigned to conserved muscle-related proteins, including myosin, troponin, and tropomyosin, while sequence variability enabled reliable species discrimination despite protein conservation across species. To evaluate applicability for food fraud detection, mixed meat samples containing 10% chicken in pork or bovine matrices were analyzed, reflecting potential economically motivated adulteration through substitution with lower-cost meat components. Several chicken-specific peptides remained detectable in both mixtures, demonstrating robustness of the FBDA-assisted peptide sequencing combined with SCX fractionation and DIA-MS for detection of adulteration in complex processed food matrices. These findings establish a mass spectrometry-driven orthogonal method to ELISA testing for fast, reliable and accurate metaproteome analysis of highly processed food.','https://www.mdpi.com/2304-8158/15/13/2294','Foods','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(232,'Direct Identification of Urinary Tract Pathogens by MALDI-TOF/TOF Analysis and De Novo Peptide Sequencing','2022-08-25','10.3390/molecules27175461','MDPI AG','For mass spectrometry-based diagnostics of microorganisms, matrix-assisted laser desorption ionization time-of-flight mass spectrometry (MALDI-TOF MS) is currently routinely used to identify urinary tract pathogens. However, it requires a lengthy culture step for accurate pathogen identification, and is limited by a relatively small number of available species in peptide spectral libraries (≤3329). Here, we propose a method for pathogen identification that overcomes the above limitations, and utilizes the MALDI-TOF/TOF MS instrument. Tandem mass spectra of the analyzed peptides were obtained by chemically activated fragmentation, which allowed mass spectrometry analysis in negative and positive ion modes. Peptide sequences were elucidated de novo, and aligned with the non-redundant National Center for Biotechnology Information Reference Sequence Database (NCBInr). For data analysis, we developed a custom program package that predicted peptide sequences from the negative and positive MS/MS spectra. The main advantage of this method over a conventional MALDI-TOF MS peptide analysis is identification in less than 24 h without a cultivation step. Compared to the limited identification with peptide spectra libraries, the NCBI database derived from genome sequencing currently contains 20,917 bacterial species, and is constantly expanding. This paper presents an accurate method that is used to identify pathogens grown on agar plates, and those isolated directly from urine samples, with high accuracy.','https://www.mdpi.com/1420-3049/27/17/5461','Molecules','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(233,'Metaproteomic Characterization of Forensic Samples','2022-06-16','10.2139/ssrn.4135651','Elsevier BV (SSRN)','To date, the field of forensic proteomics has focused on the identification of specific target organisms, tissues, or proteins in unknown source samples. Numerous published studies have demonstrated the ability of bottom-up proteomics to perform reliable and accurate unknown protein identification. However, to our knowledge, none of the published methods address the problem of a true protein-containing unknown, a sample where nothing is known a priori about its contents. In this work, we suggest how proteomics might be used to generate leads in an investigation. Specifically, we ask the question ''can shotgun proteomics be used to reduce the list of potential protein sources in a true unknown''? To answer this question, we employ approaches developed for metaproteomics, a field of study concerned with characterizing proteins in complex, poorly characterized microbial communities. Our approach relies on de novo peptide sequencing followed by taxonomic assignment and statistical scoring to identify potential protein sources in a sample. We test our forensic metaproteomics workflow on 90 high-resolution LC-MS/MS datasets from a wide diversity of bacterial samples, along with 144 simulated mixtures constructed from these original datasets. Results show that this approach effectively isolates the protein sources in in our test datasets, suggesting that forensic metaproteomics may play a useful role in unknown sample characterization and lead generation.','https://papers.ssrn.com/sol3/papers.cfm?abstract_id=4135651','SSRN Electronic Journal','preprint',NULL,'crossref');
INSERT INTO publication VALUES(234,'A method combining SPITC and 18O labeling for simultaneous protein identification and relative quantification','2014-05-01','10.1002/jms.3357','Wiley','The relative quantification and identification of proteins by matrix-assisted laser desorption ionization time-of-flight MS is very important in /MS is very important in protein research and is usually conducted separately. Chemical N-terminal derivatization with 4-sulphophenyl isothiocyanate facilitates de novo sequencing analysis and accurate protein identification, while (18)O labeling is simple, specific and widely applicable among the isotopic labeling methods used for relative quantification. In the present study, a method combining 4-sulphophenyl isothiocyanate derivatization with (18)O isotopic labeling was established to identify and quantify proteins simultaneously in one experiment. Reaction conditions were first optimized using a standard peptide (fibrin peptide) and tryptic peptides from the model protein (bovine serum albumin). Under the optimized conditions, these two independent labeling steps show good compatibility, and the linear relativity of quantification within the ten times dynamic range was stable as revealed by correlation coefficient analysis (R(2) value = 0.998); moreover, precursor peaks in MS/MS spectrum could provide accurate quantitative information, which is usually acquired from MS spectrum, enabling protein identification and quantification in a single MS/MS spectrum. Next, this method was applied to native peptides isolated from spider venoms. As expected, the de novo sequencing results of each peptide matched with the known sequence precisely, and the measured quantitative ratio of each peptide corresponded well with the theoretical ratio. Finally, complex protein mixtures of spider venoms from male and female species with unknown genome information were analyzed. Differentially expressed proteins were successfully identified, and their quantitative information was also accessed. Taken together, this protein identification and quantification method is simple, reliable and efficient, which has a good potential in the exploration of peptides/proteins from species with unknown genome.',NULL,'Journal of Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(235,'Revealing the functional structure of a new PLA2 K49 from Bothriopsis taeniata snake venom employing automatic "de novo" sequencing using CID/HCD/ETD MS/MS analyses','2015-10-22','10.1016/j.jprot.2015.10.020','Elsevier BV','Snake venoms are composed of approximately 90% of proteins with several pharmacological activities having high potential in research as biological tools. One of the most abundant compounds is phospholipases A2 (PLA2), which are the most studied venom protein due to their wide pharmacological activity. Using a combination of chromatographic steps, a new PLA2 K49 was isolated and purified from the whole venom of the Bothriopsis taeniata and submitted to analyses mass spectrometry. An automatic “de novo” sequencing of this new PLA2 K49 denominated Btt-TX was performed using Peaks Studio 6 for analysis of the spectra. Additionally, a triplex approach CID/HCD/ETD has been performed, to generate higher coverage of the sequence of the protein. Structural studies correlating biological activities were made associating specific Btt-TX regions and myotoxic activity. Lysine acetylation was performed to better understand the mechanism of membrane interaction, identifying the extreme importance of the highly hydrophobic amino acids L, P and F for disruption of the membrane. Our myotoxical studies show a possible membrane disruption mechanism by Creatine Kinase release without a noticeable muscle damage, that probably occurred without phospholipid hydrolyses, but with a probable penetration of the hydrophobic amino acids present in the C-terminal region of the protein.',NULL,'Journal of Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(236,'Mass spectrometry-assisted venom profiling of Hypnale hypnale found in the Western Ghats of India incorporating de novo sequencing approaches','2018-07-07','10.1016/j.ijbiomac.2018.07.016','Elsevier BV','Hypnale hypnale (hump-nosed pit viper) is considered to be one among the medically important venomous snake species of India and Sri Lanka. In the present study, venom proteome profiling of a single Hypnale hypnale from Western Ghats of India was achieved using SDS-PAGE based protein separation followed by LC-MS/MS analysis. The identities of the proteins that were not established using the Mascot search were determined through de novo sequencing tools such as Novor followed by MS-BLAST based sequence similarity search algorithm and PEAKS proteomics software. The combined proteomics analysis revealed a total of 37 proteins belonging to nine different snake venom families, in which 7 proteins were exclusively identified through de novo strategies. The enzymatic and non-enzymatic venom protein families identified include serine proteases, metalloproteases, phospholipase A 2 , thrombin-like enzymes, phospholipase B, C-type lectins/snaclecs, disintegrins, cysteine rich secretory proteins and nerve growth factor. Among these, disintegrins, nerve growth factor, phospholipase B and cysteine rich secretory protein families were identified for the first time in HPV venom. This could possibly explain the regiospecific venom variation seen across snake species. Taken together, the venom proteome profiling on Indian Hypnale hypnale venom correlates with the clinical manifestations often seen in the envenomed victims.',NULL,'International Journal of Biological Macromolecules','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(237,'Identification of <10 KD peptides in the water extraction of Venenum Bufonis from Bufo gargarizans using Nano LC-MS/MS and De novo sequencing','2018-05-19','10.1016/j.jpba.2018.05.027','Elsevier BV','Skins of anurans (frogs and toads) are rich sources of bioactive peptides. However, the peptides secreted by the skin glands of Bufo gargarizans, the most common toad in China, remained unexplored to date. Here, a strategy combines LC-MS/MS, RNA sequencing and bioinformation analysis was applied to unravel the peptides in the Bufo gargarizans secretions. Data-dependent LC-MS/MS acquisitions of intact peptides followed by automated chromatographic alignment, De novo analysis, database and homology searches with manual validations showed that the venom is composed by 939 features, with masses ranging from 0.7-4 kDa. These peptides derived from 85 proteins were identified using the PEAKS software with acquired MS and MS/MS spectra of Venenum Bufonis against the house-built protein database using De novo RNA sequencing, while only 23 peptides from 8 proteins were found when searching known amphibian database. Moreover, it was found that many peptides with high abundance in Venenum Bufonis derived from proteolytic processing of a larger precursor protein, named as CL4590. Molecular cloning was applied to validate a short domain of CL4590 to evident the accuracy of these obtained sequences. Although the bioactivities of peptides identified by MS/MS are unknown, the next function annotation showed that they may involve in the cell killing, immune and metabolic process, antioxidant activity and antimicrobial actions. Therefore, the peptidomics analysis on Bufo gargarizans discover abundant novel toad peptides which broaden our horizons on the secretion multiplicity and supplied an assortment of pharmacological candidates.',NULL,'Journal of Pharmaceutical and Biomedical Analysis','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(238,'Proteomic Analysis of the Venom from the Ruby Ant Myrmica rubra and the Isolation of a Novel Insecticidal Decapeptide','2019-02-01','10.3390/insects10020042','MDPI AG','Ants are a biodiverse group of insects that have evolved toxic venom containing many undiscovered bioactive molecules. In this study, we found that the venom of the ruby ant Myrmica rubra is a rich source of peptides. LC-MS analysis revealed the presence of 142 different peptides varying in molecular weight, sequence length, and hydrophobicity. One of the most abundant peaks was selected for further biochemical and functional characterization. Combined Edman degradation and de novo peptide sequencing revealed the presence of a novel decapeptide (myrmicitoxin) with the amino acid sequence NH2-IDPKLLESLA-CONH2. The decapeptide was named U-MYRTX-MRArub1 and verified against a synthetic standard. The amidated peptide was tested in a synthetic form to determine the antimicrobial activity towards the bacterial pathogens and insecticidal potential against pea aphids (Acyrthosiphon pisum). This peptide did not show antimicrobial activity but it significantly reduced the survival of aphids. It also increased the sensitivity of the aphids to two commonly used chemical insecticides (imidacloprid and methomyl). Since ant venom research is still in its infancy, the findings of this first study on venom peptides derived from M. rubra highlight these insects as an important and rich source for discovery of novel lead structures with potential application in pest control.',NULL,'Insects','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(239,'Extended Snake Venomics by Top-Down In-Source Decay: Investigating the Newly Discovered Anatolian Meadow Viper Subspecies, Vipera anatolica senliki','2020-03-17','10.1021/acs.jproteome.9b00869','American Chemical Society (ACS)','Herein, we report on the venom proteome of Vipera anatolica senliki, a recently discovered and hitherto unexplored subspecies of the critically endangered Anatolian meadow viper endemic to the Antalya Province of Turkey. Integrative venomics, including venom gland transcriptomics as well as complementary bottom-up and top-down proteomics analyses, were applied to fully characterize the venom of V. a. senliki . Furthermore, the classical top-down venomics approach was extended to elucidate the venom proteome by an alternative in-source decay (ISD) proteomics workflow using the reducing matrix 1,5-diaminonaphthalene. Top-down ISD proteomics allows for disulfide bond counting and effective de novo sequencing-based identification of high-molecular-weight venom constituents, both of which are difficult to achieve by commonly established top-down approaches. Venom gland transcriptome analysis identified 96 toxin transcript annotations from 18 toxin families. Relative quantitative snake venomics revealed snake venom metalloproteinases (42.9%) as the most abundant protein family, followed by several less dominant toxin families. Online mass profiling and top-down venomics provide a detailed insight into the venom proteome of V. a. senliki and facilitate a comparative analysis of venom variability for the closely related subspecies, Vipera anatolica anatolica .',NULL,'Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(240,'Delineating the venom toxin arsenal of Malabar pit viper (Trimeresurus malabaricus) from the Western Ghats of India and evaluating its immunological cross-reactivity and in vitro cytotoxicity','2020-01-23','10.1016/j.ijbiomac.2020.01.226','Elsevier BV','The venom protein components of Malabar pit viper (Trimeresurus malabaricus) were identified by combining SDS-PAGE and ion-exchange chromatography pre-fractionation techniques with LC-MS/MS incorporating Novor and PEAKS-assisted de novo sequencing strategies. Total 97 proteins that belong to 16 protein families such as L-amino acid oxidase, metalloprotease, serine protease, phospholipase A 2 , 5''-nucleotidase, C-type lectins/snaclecs and disintegrin were recognized from the venom of a single exemplar species. Of the 97 proteins, eighteen were identified through de novo approaches. Immunological cross-reactivity assessed through ELISA and western blot indicate that the Indian antivenoms binds less effectively to Malabar pit viper venom components compared to that of Russell''s viper venom. The in vitro cell viability assays suggest that compared to the normal cells, MPV venom induces concentration dependent cell death in various cancer cells. Moreover, crude venom resulted in chromatin condensation and apoptotic bodies implying the induction of apoptosis. Taken together, the present study enabled in dissecting the venom proteome of Trimeresurus malabaricus and revealed the immuno-cross-reactivity profiles of commercially available Indian polyvalent antivenoms that, in turn, is expected to provide valuable insights on the need in improving antivenom preparations against its bite.',NULL,'International Journal of Biological Macromolecules','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(241,'Venomics and antivenomics of Indian spectacled cobra (Naja naja) from the Western Ghats','2022-01-28','10.1016/j.actatropica.2022.106324','Elsevier BV','Venom proteome profiling of Naja naja from the Western Ghats region in Kerala was achieved through SDS-PAGE and RP-HPLC followed by Q-TOF LC-MS/MS analysis, incorporating PEAKS and Novor assisted de novo sequencing methodologies. A total of 115 proteins distributed across 17 different enzymatic and non-enzymatic venom protein families were identified through conventional and 39 peptides through homology-driven proteomics approaches. Fourteen peptides derived through de novo complements the Mascot data indicating the importance of homology-driven approaches in improving protein sequence information. Among the protein families identified, glutathione peroxidase and endonuclease were reported for the first time in the Indian cobra venom. Immunological cross-reactivity assessed using Indian polyvalent antivenoms suggested that VINS showed better EC 50 (2.48 µg/mL) value than that of PSAV (6.04 µg/mL) and Virchow (6.03 µg/mL) antivenoms. Western blotting experiments indicated that all the antivenoms elicited poor binding specificities, especially towards low molecular mass proteins. Second-generation antivenomics studies revealed that VINS antivenom was less efficient to detect many low molecular mass proteins such as three-finger toxins and Kunitz-type serine protease Inhibitors. Taken together, the present study enabled a large-scale characterization of the venom proteome of Naja naja from the Western Ghats and emphasized the need for developing more efficient antivenoms.',NULL,'Acta Tropica','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(242,'Unveiling the Diversity and Modifications of Short Peptides in Scorpion Venom through Liquid Chromatography-High Resolution Mass Spectrometry','2024-03-16','10.3390/toxins16030155','MDPI AG','More recently, short peptides in scorpion venom have received much attention because of their potential for drug discovery. Although various biological effects of these short peptides have been found, their studies have been hindered by the lack of structural information especially in modifications. In this study, small peptides from scorpion venom were investigated using high-performance liquid chromatography high-resolution mass spectrometry followed by de novo sequencing. A total of 156 sequences consisting of 2~12 amino acids were temporarily identified from Buthus martensii scorpion venom. The identified peptides exhibited various post-translational modifications including N-terminal and C-terminal modifications, in which the N-benzoyl modification was first found in scorpion venom. Moreover, a short peptide Bz-ARF-NH2 demonstrated both N-terminal and C-terminal modifications simultaneously, which is extremely rare in natural peptides. In conclusion, this study provides a comprehensive insight into the diversity, modifications, and potential bioactivities of short peptides in scorpion venom.',NULL,'Toxins','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(243,'Identification of Daboia siamensis venome using integrated multi-omics data','2022-07-30','10.1038/s41598-022-17300-1','Springer Science and Business Media LLC','Snakebite, classified by World Health Organization as a neglected tropical disease, causes more than 100,000 deaths and 2 million injuries per year. Currently, available antivenoms do not bind with strong specificity to target toxins, which means that severe complications can still occur despite treatment. Moreover, the cost of antivenom is expensive. Knowledge of venom compositions is fundamental for producing a specific antivenom that has high effectiveness, low side effects, and ease of manufacture. With advances in mass spectrometry techniques, venom proteomes can now be analyzed in great depth at high efficiency. However, these techniques require genomic and transcriptomic data for interpreting mass spectrometry data. This study aims to establish and incorporate genomics, transcriptomics, and proteomics data to study venomics of a venomous snake, Daboia siamensis. Multiple proteins that have not been reported as venom components of this snake such as hyaluronidase-1, phospholipase B, and waprin were discovered. Thus, multi-omics data are advantageous for venomics studies. These findings will be valuable not only for antivenom production but also for the development of novel therapeutics.','https://www.nature.com/articles/s41598-022-17300-1','Scientific Reports','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(244,'Quantification of snake venom proteomes by mass spectrometry - considerations and perspectives','2023-05-08','10.1002/mas.21850','Wiley','The advent of soft ionization mass spectrometry-based proteomics in the 1990s led to the development of a new dimension in biology that conceptually allows for the integral analysis of whole proteomes. This transition from a reductionist to a global-integrative approach is conditioned to the capability of proteomic platforms to generate and analyze complete qualitative and quantitative proteomics data. Paradoxically, the underlying analytical technique, molecular mass spectrometry, is inherently nonquantitative. The turn of the century witnessed the development of analytical strategies to endow proteomics with the ability to quantify proteomes of model organisms in the sense of "an organism for which comprehensive molecular (genomic and/or transcriptomic) resources are available." This essay presents an overview of the strategies and the lights and shadows of the most popular quantification methods highlighting the common misuse of label-free approaches developed for model species'' when applied to quantify the individual components of proteomes of nonmodel species (In this essay we use the term "non-model" organisms for species lacking comprehensive molecular (genomic and/or transcriptomic) resources, a circumstance that, as we detail in this review-essay, conditions the quantification of their proteomes.). We also point out the opportunity of combining elemental and molecular mass spectrometry systems into a hybrid instrumental configuration for the parallel identification and absolute quantification of venom proteomes. The successful application of this novel mass spectrometry configuration in snake venomics represents a proof-of-concept for a broader and more routine application of hybrid elemental/molecular mass spectrometry setups in other areas of the proteomics field, such as phosphoproteomics, metallomics, and in general in any biological process where a heteroatom (i.e., any atom other than C, H, O, N) forms integral part of its mechanism.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/10.1002/mas.21850','Mass Spectrometry Reviews','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(245,'Expanding the repertoire of conopeptides from the venom of the vermivorous snail Conus regius','2025-08-23','10.1016/j.toxicon.2025.108551','Elsevier BV','This study presents a comprehensive proteomic characterization of Conus regius venom. Venom samples were fractionated using reversed-phase chromatography and analyzed by Q-TOF mass spectrometry. Spectral data were processed with Peaks Studio V7.0 and searched against a Conus protein database. A total of 520 peptide and protein sequences were identified, with most corresponding to conopeptides. Among these, eight presented similarities to disulfide-poor conopeptides of the Conantokin, ConoGay, and ConoCAP classes, as well as two sequences not classified in the literature. Additionally, 284 peptides showed similarity to conotoxins from 13 gene superfamilies (M, A, T, P, S, I1, Conodipine, O1, Insulin, G2, O2, Q, and H), while 102 sequences were linked to undetermined superfamilies. Of the identified sequences, 21 had been previously described in C. regius venom, while many others shared similarities with conotoxins from other Conus species. Most conotoxins identified were associated with the M and A superfamilies, suggesting their predominance in the venom. This study expands the known repertoire of C. regius venom components and provides valuable insights into its molecular diversity, supporting future research into its biotechnological potential.','https://doi.org/10.1016/j.toxicon.2025.108551','Toxicon','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(246,'Mass Spectrometric Proof of Predicted Peptides: Novel Adipokinetic Hormones in Insects','2022-10-01','10.3390/molecules27196469','MDPI AG','The importance of insects in our ecosystems is undeniable. The indiscriminate use of broad-spectrum insecticides is a factor in the decline in insect biomass. We identify and sequence a prominent neuropeptide hormone in insects with an overarching goal to elucidate relatedness and create a database of bioactive peptides that could inform possible cross-activity in biological assays for the identification of a biorational lead compound. The major task of an adipokinetic hormone (AKH) in an insect is the regulation of metabolic events, such as carbohydrate and lipid breakdown in storage tissue during intense muscular work. From genomic and/or transcriptomic information one may predict the genes encoding neuropeptides such as the AKHs of insects. Definite elucidation of the primary structure of the mature peptide with putative post-translational modifications needs analytical chemical methods. Here we use high-resolution mass spectrometry coupled with liquid chromatography to identify unequivocally the AKHs of five insect species (one cockroach, two moths, and two flies) of which either genomic/transcriptomic information was available or sequences from related species. We confirm predicted sequences and discover novel AKH sequences, including one with a post-translational hydroxyproline modification. The additional sequences affirm an evolutionary pattern of dipteran AKHs and a conserved pattern in crambid moths.','https://doi.org/10.3390/molecules27196469','Molecules','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(247,'Comprehensive identification of native medium-sized and short bioactive peptides in sea bass muscle','2020-10-22','10.1016/j.foodchem.2020.128443','Elsevier BV','Native peptides from sea bass muscle were analyzed by two different approaches: medium-sized peptides by peptidomics analysis, whereas short peptides by suspect screening analysis employing an inclusion list of exact m/z values of all possible amino acid combinations (from 2 up to 4). The method was also extended to common post-translational modifications potentially interesting in food analysis, as well as non-proteolytic aminoacyl derivatives, which are well-known taste-active building blocks in pseudo-peptides. The medium-sized peptides were identified by de novo and combination of de novo and spectra matching to a protein sequence database, with up to 4077 peptides (2725 modified) identified by database search and 2665 peptides (223 modified) identified by de novo only; 102 short peptide sequences were identified (with 12 modified ones), and most of them had multiple reported bioactivities. The method can be extended to any peptide mixture, either endogenous or by protein hydrolysis, from other food matrices.','https://doi.org/10.1016/j.foodchem.2020.128443','Food Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(248,'SequenceAssembler: A tool for protein sequence assembly from mass spectrometry data','2025-10-08','10.1016/j.jprot.2025.105542','Elsevier BV','Accurate sequencing of complete proteoforms-that is, all molecular variants generated by post-translational modification or sequence change-is essential for advancing our understanding of biological systems, guiding biopharmaceutical development, and enabling new biotechnological applications. We present SequenceAssembler (SA), a user-friendly software post-identification tool designed to assemble full-length protein sequences by integrating both peptide-spectrum matching (PSM) and de novo sequencing data. SA is compatible with widely used proteomics tools, including Novor Cloud, PEAKS Studio, and PatternLab for Proteomics, from which it efficiently aggregates input data. Our software offers an accessible and intuitive interface, enhancing its usability. We demonstrated SA''s effectiveness by analyzing bovine serum albumin and the monoclonal antibody trastuzumab, each subjected to multiple enzymatic digestions followed by high-resolution mass spectrometry. The results were consistent with those of established tools like Stitch, with performance varying depending on threshold parameters. Notably, SA distinguishes itself through its user-friendly graphical interface, one-click installation, and streamlined workflow, making it an attractive solution for a wide range of proteomics researchers. The software is freely available for academic use at http://patternlabforproteomics.org/sa. SIGNIFICANCE: SequenceAssembler fills a critical gap in proteomics by unifying peptide-spectrum matching and de novo sequencing into a single assembly platform, enabling reconstruction of full-length proteins. The intuitive graphical interface lowers barriers to adoption in core laboratories, minimizing manual steps and enhancing reproducibility. By streamlining sequence assembly workflows, SequenceAssembler empowers rapid protein sequencing to broad protein research applications.','https://doi.org/10.1016/j.jprot.2025.105542','Journal of Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(249,'Limitations of de novo sequencing in resolving sequence ambiguity','2025-08-19','10.1101/2025.08.19.671052','Cold Spring Harbor Laboratory','De novo peptide sequencing enables peptide identification from fragmentation spectra without relying on sequence databases. However, incomplete spectra create ambiguity, making unambiguous identification challenging. Recent deep learning advances have produced numerous de novo models that predict sequences and refine peptide-spectrum matches under such conditions. Yet, their relative strengths, weaknesses, and ability to handle spectrum ambiguity remain unclear. Here, we benchmark eight state-of-the-art models on three publicly available proteomics datasets, comparing performance using established metrics and quantifying inter-model agreement. We assess post-processing approaches, including iterative refinement, rescoring, and reranking, for their ability to improve identification accuracy, and perform an error analysis to identify common mispredictions and their causes. Model performance varied, with considerable overlap of correct identifications. Post-processing yielded no or only modest improvements. Most sequencing errors were model-independent and driven by limited fragment ion coverage, a limitation also observed in database searches with large search spaces.','https://www.biorxiv.org/content/10.1101/2025.08.19.671052v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(250,'Wastewater metaproteomics: tracking microbial and human protein biomarkers','2025-12-18','10.1093/ismeco/ycaf243','Oxford University Press (OUP)','Wastewater-based surveillance has become a powerful tool for monitoring the spread of pathogens, antibiotic resistance genes, and measuring population-level exposure to pharmaceuticals and chemicals. While surveillance methods commonly target small molecules, DNA, or RNA, wastewater also contains a vast spectrum of proteins. However, despite recent advances in environmental proteomics, large-scale monitoring of protein biomarkers in wastewater is still far from routine. Analyzing raw wastewater presents a challenge due to its heterogeneous mixture of organic and inorganic substances, microorganisms, cellular debris, and various chemical pollutants. To overcome these obstacles, we developed a wastewater metaproteomics approach including efficient protein extraction and an optimized data-processing pipeline. The pipeline utilizes de novo sequencing to customize large public sequence databases to enable comprehensive metaproteomic coverage. Using this approach, we analyzed wastewater samples collected over approximately three months from two urban locations. This revealed a core microbiome comprising a broad spectrum of microbes, gut bacteria and potential opportunistic pathogens. Additionally, we identified nearly 200 human proteins, including promising population-level health indicators, such as immunoglobulins, uromodulin, and cancer-associated proteins.','https://doi.org/10.1093/ismeco/ycaf243','ISME Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(251,'InstaNovo-P: a de novo peptide sequencing model for phosphoproteomics','2026-07-10','10.1038/s41467-026-75138-x','Springer Science and Business Media LLC','Phosphorylation, a crucial post-translational modification (PTM), plays a central role in cellular signaling and disease mechanisms. Mass spectrometry-based phosphoproteomics is widely used for system-wide characterization of phosphorylation events. However, traditional methods struggle with accurate phosphorylated site localization, complex search spaces, and detecting sequences outside the reference database. Advances in de novo peptide sequencing offer opportunities to address these limitations, but have yet to become integrated and adapted for phosphoproteomics datasets. Here, we present InstaNovo-P, a phosphorylation specific version of our transformer-based InstaNovo model, fine-tuned on extensive phosphoproteomics datasets. InstaNovo-P significantly surpasses existing methods in phosphorylated peptide detection and phosphorylated site localization accuracy across multiple datasets, including complex experimental scenarios. Our model robustly identifies peptides with single and multiple phosphorylated sites, effectively localizing phosphorylation events on serine, threonine, and tyrosine residues. We experimentally validate our model predictions by studying FGFR2 signaling, further demonstrating that InstaNovo-P uncovers phosphorylated sites previously missed by traditional database searches. These predictions align with critical biological processes, confirming the model’s capacity to yield valuable biological insights. InstaNovo-P adds value to phosphoproteomics experiments by effectively identifying biologically relevant phosphorylation events without prior information, providing a powerful analytical tool for the dissection of signaling pathways.','https://www.nature.com/articles/s41467-026-75138-x','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(252,'Identification of Unknown Biological Toxin Proteins Using Mass Spectrometry: A Case Study on De Novo Sequencing of Ricin','2025-11-18','10.3390/toxins17110564','MDPI AG','BACKGROUND: The rapid and reliable identification of unknown or highly variable biological toxin proteins, such as the potent Ricin toxin, remains a critical challenge in biodefense and public security. METHODS: To address this, we developed a Heuristic De Novo Sequencing (HDPS) strategy, which combines multiple enzymatic and microwave-assisted acid hydrolysis to generate diverse peptides, followed by a two-stage assembly process integrating de novo sequencing with homology-based database searching for robust error correction. RESULTS: When applied to Ricin, this approach achieved 100% sequence coverage for both its A and B chains, with amino acid-level accuracies of 98.13% and 98.47%, respectively, and successfully corrected potential sequencing ambiguities. CONCLUSIONS: These results demonstrate that HDPS is a highly accurate and effective method for the de novo sequencing of full-length proteins, making it particularly valuable for characterizing unknown or mutated toxins in the absence of comprehensive reference databases.','https://doi.org/10.3390/toxins17110564','Toxins','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(253,'CasanovoGUI: a cross-platform desktop application for deep learning-based de novo peptide sequencing with Casanovo','2026-07-11','10.64898/2026.07.11.737889','Cold Spring Harbor Laboratory','De novo peptide sequencing detects peptides directly from tandem mass spectra without a protein sequence database, and deep learning has substantially advanced its performance. Casanovo, one such widely used model, is distributed as a Python command-line program. Consequently, installation, GPU and dependency configuration, and manual parameterization can be challenging for many bench scientists and are a recurring source of errors. Interpreting and validating the resulting predictions poses a further challenge. We present CasanovoGUI, an open-source Java-based desktop application that makes all of Casanovos main analysis functions available through a point-and-click interface on Windows, macOS, and Linux. On first use, CasanovoGUI automatically installs a private Python environment and Casanovo with a GPU-matched build, requiring no prior software setup. The GUI provides access to Casanovos analysis functions and configuration parameters, streams live progress, and integrates results interpretation: annotated spectra with per-residue confidence scores in the PDV viewer, and mismatch-tolerant mapping of de novo peptides back to a reference proteome. CasanovoGUI is available at https://github.com/Noble-Lab/CasanovoGUI.','https://www.biorxiv.org/content/10.64898/2026.07.11.737889v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(254,'Discrete Diffusion with Physical Mass Constraints for De Novo Peptide Sequencing','2026-07-04',NULL,'OpenReview',NULL,'https://openreview.net/forum?id=tIG4D44jn9','ICML 2026','ML conference',NULL,NULL);
INSERT INTO publication VALUES(255,'Prime-DiffNovo: Accurate Peptide De Novo Sequencing via Non-autoregressive Generation and Diffusion Refinement','2026-07-15','10.1007/978-981-92-3719-7_16','Springer Nature Singapore',NULL,'https://link.springer.com/chapter/10.1007/978-981-92-3719-7_16','Lecture Notes in Computer Science (ISBRA 2026)','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(256,'A potential golden age to come—current tools, recent use cases, and future avenues for de novo sequencing in proteomics','2018-09-01','10.1002/pmic.201700150','Wiley','In shotgun proteomics, peptide and protein identification is most commonly conducted using database search engines, the method of choice when reference protein sequences are available. Despite its widespread use the database-driven approach is limited, mainly because of its static search space. In contrast, de novo sequencing derives peptide sequence information in an unbiased manner, using only the fragment ion information from the tandem mass spectra. In recent years, with the improvements in MS instrumentation, various new methods have been proposed for de novo sequencing. This review article provides an overview of existing de novo sequencing algorithms and software tools ranging from peptide sequencing to sequence-to-protein mapping. Various use cases are described for which de novo sequencing was successfully applied. Finally, limitations of current methods are highlighted and new directions are discussed for a wider acceptance of de novo sequencing in the community.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/abs/10.1002/pmic.201700150','Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(257,'Flying blind, or just flying under the radar? The underappreciated power of de novo methods of mass spectrometric peptide identification','2020-09-01','10.1002/pro.3919','Wiley','Mass spectrometry-based proteomics is a popular and powerful method for precise and highly multiplexed protein identification. The most common method of analyzing untargeted proteomics data is called database searching, where the database is simply a collection of protein sequences from the target organism, derived from genome sequencing. Experimental peptide tandem mass spectra are compared to simplified models of theoretical spectra calculated from the translated genomic sequences. However, in several interesting application areas, such as forensics, archaeology, venomics, and others, a genome sequence may not be available, or the correct genome sequence to use is not known. In these cases, de novo peptide identification can play an important role. De novo methods infer peptide sequence directly from the tandem mass spectrum without reference to a sequence database, usually using graph-based or machine learning algorithms. In this review, we provide a basic overview of de novo peptide identification methods and applications, briefly covering de novo algorithms and tools, and focusing in more depth on recent applications from venomics, metaproteomics, forensics, and characterization of antibody drugs.','https://onlinelibrary.wiley.com/doi/abs/10.1002/pro.3919','Protein Science','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(258,'Automated de novo protein sequencing of monoclonal antibodies','2008-12-01','10.1038/nbt1208-1336','Springer Science and Business Media LLC',NULL,'https://www.nature.com/articles/nbt1208-1336','Nature Biotechnology','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(259,'A living proteomics benchmark for comprehensive evaluation of deep learning-based de novo peptide sequencing tools','2026-03-12','10.6084/m9.figshare.31680883','figshare','Mass spectrometry-based proteomics is essential for understanding protein composition and function, yet traditional sequence database-based methods face challenges in identifying novel peptides, post-translational modifications, and diverse proteomes. De novo peptide sequencing, which operates independently of sequence databases, offers a powerful approach for uncovering these unknown peptides. However, the lack of consistent evaluation frameworks for the growing array of deep learning-based de novo sequencing tools limits their adoption and effective application. Here, we introduce a comprehensive, community-driven benchmarking resource designed to assess the performance of various de novo sequencing tools across a broad range of experimental conditions and proteomic applications. Our benchmark employs heterogeneous datasets to establish a standardizedevaluation framework, providing a transparent, evolving resource accessible through an interactive online dashboard. This benchmark is anticipated to offer key insights into tool performance, aiding researchers in selecting suitable tools and identifying areas for future refinement and development in de novo peptide sequencing.','https://doi.org/10.6084/m9.figshare.31680883','Nature Methods (Registered Report)','preprint',NULL,'openalex');
INSERT INTO publication VALUES(260,'PSMtags improve peptide sequencing and throughput in sensitive proteomics','2025-05-22','10.1101/2025.05.22.655509','Cold Spring Harbor Laboratory','Mass spectrometry-based proteomics enables comprehensive characterization of protein abundance, function, and interactions. Label-free approaches are simple to implement but challenging to scale to thousands of samples per day. Multiplexed techniques, such as plexDIA, can address these limitations but remain restricted by the lack of mass tags optimized for data-independent acquisition (DIA) workflows. Here, we present a systematic approach screening a library of 576 compounds that identifies several small molecules that, when conjugated to peptides, improve their detection and sequence identification by mass spectrometry. The lead molecule, PSMtag, substantially increases the detection of fragment b-ions, which increases the confidence of sequence identification and enhances de novo sequencing. PSMtags allow 9-plexDIA, using only stable isotopes of carbon, oxygen and nitrogen. As a result, it allows simultaneously increasing proteome coverage and sample throughput for plexDIA workflows without compromising quantitative accuracy. We demonstrate 240 samples-per-day with 9-plexDIA, while acquiring 28,359 protein data points in the same time label-free methods acquire 4,340. Our approach constitutes an expandable framework for designing mass tags to overcome existing limitations in multiplexed proteomics and provides plexDIA reagents capable of analyzing over 1,000 samples per day when using 10 minute runs. By facilitating higher throughput and improved identification, this innovation holds significant potential for accelerating proteomic studies across diverse biological and clinical applications.','https://www.biorxiv.org/content/10.1101/2025.05.22.655509v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(261,'A Hidden Markov Model for de Novo Peptide Sequencing','2004-12-13',NULL,'MIT Press','De novo sequencing of peptides poses one of the most challenging tasks in data analysis for proteome research. In this paper, a generative hidden Markov model (HMM) of mass spectra for de novo peptide sequencing which constitutes a novel view on how to solve this problem in a Bayesian framework is proposed. Further extensions of the model structure to a graphical model and a factorial HMM to substantially improve the peptide identification results are demonstrated. Inference with the graphical model for de novo peptide sequencing estimates posterior probabilities for amino acids rather than scores for single symbols in the sequence. Our model outperforms state-of-the-art methods for de novo peptide sequencing on a large test set of spectra.','https://papers.nips.cc/paper_files/paper/2004/hash/5ac8bb8a7d745102a978c5f8ccdb61b8-Abstract.html','NIPS 2004','ML conference',NULL,'openalex');
INSERT INTO publication VALUES(262,'De novo sequencing of proteins by mass spectrometry','2020-10-01','10.1080/14789450.2020.1831387','Taylor & Francis','Introduction Proteins are crucial for every cellular activity and unraveling their sequence and structure is a crucial step to fully understand their biology. Early methods of protein sequencing were mainly based on the use of enzymatic or chemical degradation of peptide chains. With the completion of the human genome project and with the expansion of the information available for each protein, various databases containing this sequence information were formed.Areas covered De novo protein sequencing, shotgun proteomics and other mass-spectrometric techniques, along with the various software are currently available for proteogenomic analysis. Emphasis is placed on the methods for de novo sequencing, together with potential and shortcomings using databases for interpretation of protein sequence data.Expert opinion As mass-spectrometry sequencing performance is improving with better software and hardware optimizations, combined with user-friendly interfaces, de-novo protein sequencing becomes imperative in shotgun proteomic studies. Issues regarding unknown or mutated peptide sequences, as well as, unexpected post-translational modifications (PTMs) and their identification through false discovery rate searches using the target/decoy strategy need to be addressed. Ideally, it should become integrated in standard proteomic workflows as an add-on to conventional database search engines, which then would be able to provide improved identification.','https://doi.org/10.1080/14789450.2020.1831387','Expert Review of Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(263,'AI proteomics: from protein identification to virtual cells','2026-07-28','10.1038/s41592-026-03085-y','Springer Science and Business Media LLC','Artificial intelligence (AI) is transforming scientific research, including proteomics. In this Perspective, we highlight key mass spectrometry (MS)-based proteomics areas where AI is driving innovation, ranging from protein identification to building AI virtual cells. These include improving peptide and protein identification and quantification; characterizing protein-protein interactions and protein complexes; advancing spatial and perturbation proteomics; integrating multi-omics data; and, ultimately, enabling AI virtual cells. Finally, we call for global collaboration among data producers, data consumers and other stakeholders to establish an AI-friendly ecosystem for MS-based proteomics, laying the foundation for transformative advancements in proteomics driven by AI.','https://doi.org/10.1038/s41592-026-03085-y','Nature Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(264,'Accurate and ultra-fast de novo HLA-I immunopeptide sequencing with FoxNovo','2026-08-03','10.65215/LTSpreprints.2026.08.02.000299','LangTaoSha Preprint Server','We present FoxNovo, a hybrid deep learning-combinatorial framework for de novo sequencing of immunopeptides trained on a large-scale HLA-I immunopeptidomics dataset assembled and reprocessed from public mass spectrometry (MS) repositories. This integration achieved >90% peptide accuracy on the reported benchmarks while enabling repository-scale analysis at ~2,800 spectra per second—more than 100-fold faster than the evaluated beam-search baseline under the reported benchmark conditions. To mimic the heterogeneous spectral quality encountered in experimental MS analyses, we constructed controlled peak-removal stress tests, in which FoxNovo retained higher accuracy than the evaluated methods at different simulation levels. We subsequently re-analyzed 168 million spectra from all collected 4,423 MS raw files in only 18 hours on a single GPU, equivalent to ~245 raw files per hour. This repository-scale application yielded score-filtered canonical and putative ncORF-mapped peptide predictions and recovered 41 of 42 non-canonical HLA-I peptides previously validated by targeted MS. FoxNovo demonstrates the potential of integrating AI with combinatorial decoding for scalable immunopeptidomics. The source code is available at https://github.com/fennomix/fennomix.novo.','https://langtaosha.org.cn/lts/en/preprint/view/299','LangTaoSha (LTS) Preprint','preprint',NULL,'openalex');
INSERT INTO publication VALUES(265,'Tandem Mass Spectra Representation Design for Transformer-Based De Novo Peptide Sequencing','2026-07-27',NULL,'MSc thesis','De novo peptide sequencing predicts peptide sequences directly from tandem mass spectra without relying on a predefined peptide database. This thesis studies how spectral peaks should be represented for Transformer-based de novo peptide sequencing. A fixed Transformer backbone is used while the peak representation is changed, including additive m/z-intensity embedding, separated feature embeddings, precursor-normalized peak-mass features, zero-vector controls, and probability-aware embeddings. Experiments are conducted on a non-probability spectral-library dataset and a probability-augmented spectral dataset, with model dimensionality kept fixed across embedding variants. The results show that separating peak features improves performance over the additive baseline. Precursor-normalized mass information further improves the non-probability setting, while the best probability-augmented result is obtained when externally generated signal probability is combined with intensity and mass-based features. These results show that peak representation design meaningfully affects Transformer-based de novo peptide sequencing.','https://hdl.handle.net/20.500.14721/40077',NULL,'thesis',NULL,'pdf');
INSERT INTO publication VALUES(266,'Reference-free protein sequencing by consensus assembly of redundant de novo peptide reads','2026-08-13','10.64898/2026.08.13.744110','Cold Spring Harbor Laboratory','Reading a protein''s sequence from tandem mass spectra without a reference is limited by single-spectrum accuracy, most acutely across the hypervariable complementarity-determining regions of antibodies. Broadly specific proteases tile a protein with long, overlapping peptides, so every residue is covered by many independent de novo reads. borgonovo assembles their per-step probability profiles into a reference-free per-residue consensus, seeding templates from mass-closure-consistent reads and recruiting the rest by substitution-tolerant alignment and per-column voting. Re-decoding each spectrum with a prior from its consensus position lifts amino acid accuracy on placed spectra from 0.80 to 0.87. On the therapeutic antibody trastuzumab, nine proteases cover its heavy and light chains completely at 0.88 fixed-window identity and 0.93 on the pruned assembly once local indels are accommodated. Applied unchanged to five secretome proteins and trastuzumab with three proteases, it reaches 0.87 mean fixed-window identity over 82% coverage. borgonovo is open source and works with most de novo sequencers, so redundant digestion turns any of them into a protein sequencer where no reference exists.','https://www.biorxiv.org/content/10.64898/2026.08.13.744110v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(267,'Generalizable Direct Protein Sequencing With InstaNexus','2026-03-02','10.1016/j.mcpro.2026.101547','Elsevier BV','Protein-based therapeutics, such as antibodies and nanobodies, are not encoded in reference genomes, challenging their accurate characterization via standard proteomics. Current methods rely on indirect inference, fragmented outputs, and labor-intensive workflows, which hinder functional insights and routine application. Here, we present a generalizable, end-to-end workflow for direct protein sequencing, combining streamlined sample preparation, AI-driven de novo peptide sequencing, and tailored assembly to reconstruct contiguous protein sequences. A novel composite scoring framework prioritises longer assemblies and coverage, enhancing accuracy and reducing ambiguity. Validation across diverse protein modalities demonstrates its utility and ability to robustly sequence functionally critical regions of selected proteins. This workflow represents an advance in precision proteomics with promising applications in therapeutic discovery, immune profiling, and protein science.','https://doi.org/10.1016/j.mcpro.2026.101547','Molecular & Cellular Proteomics','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(268,'Generalizable direct protein sequencing with InstaNexus','2025-07-25','10.1101/2025.07.25.666861','Cold Spring Harbor Laboratory','Protein-based therapeutics, such as antibodies and nanobodies, are not encoded in reference genomes, challenging their accurate characterization via standard proteomics. Current methods rely on indirect inference, fragmented outputs, and labor-intensive workflows, which hinder functional insights and routine application. Here, we present a generalizable, end-to-end workflow for direct protein sequencing, combining streamlined sample preparation, AI-driven de novo peptide sequencing, and tailored assembly to reconstruct contiguous protein sequences. A novel composite scoring framework prioritises longer assemblies and coverage, enhancing accuracy and reducing ambiguity. Validation across diverse protein modalities demonstrates its utility and ability to robustly sequence functionally critical regions of selected proteins. This workflow represents an advance in precision proteomics with promising applications in therapeutic discovery, immune profiling, and protein science.','https://www.biorxiv.org/content/10.1101/2025.07.25.666861v1','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(269,'Pairwise Attention: Leveraging Mass Differences to Enhance De Novo Sequencing of Mass Spectra','2025-06-02','10.1021/acs.jproteome.5c00063','American Chemical Society (ACS)','A fundamental challenge in mass spectrometry-based proteomics is determining which peptide generated a given MS2 spectrum. Peptide sequencing typically relies on matching spectra against a known sequence database, which in some applications is not available. Deep learning-based de novo sequencing can address this limitation by directly predicting peptide sequences from MS2 data. We have seen the application of the transformer architecture to de novo sequencing produce state-of-the-art results on the so-called nine-species benchmark. In this study, we propose an improved transformer encoder inspired by the heuristics used in the manual interpretation of spectra. We modify the attention mechanism with a learned bias based on pairwise mass differences, termed Pairwise Attention (PA). Adding PA improves average peptide precision at 100% coverage by 12.7% (5.9 percentage points) over our base transformer on the original nine-species benchmark. We have also achieved a 7.4% increase over the previously published model Casanovo. Our MS2 encoding strategy is largely orthogonal to other transformer-based models encoding MS2 spectra, enabling straightforward integration into existing deep-learning approaches. Our results show that integrating domain-specific knowledge into transformers boosts de novo sequencing performance.','https://doi.org/10.1021/acs.jproteome.5c00063','Journal of Proteome Research','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(270,'Modanovo: A Unified Model for Post-translational Modification-Aware De Novo Sequencing Using Experimental Spectra From In Vivo and Synthetic Peptides','2025-12-23','10.1016/j.mcpro.2025.101501','Elsevier BV','Post-translational modifications (PTMs) play a central role in cellular regulation and are implicated in numerous diseases. Database searching remains the standard for identifying modified peptides from tandem mass spectra but is hindered by the combinatorial expansion of modification types and sites. De novo peptide sequencing offers an attractive alternative, yet existing methods remain limited to unmodified peptides or a narrow set of PTMs. Here, we curated a large dataset of spectra from endogenous and synthetic peptides from ProteomeTools spanning 19 biologically relevant amino acid-PTM combinations, covering phosphorylation, acetylation, and ubiquitination. We used this dataset to develop Modanovo, an extension of the Casanovo transformer architecture for de novo peptide sequencing. Modanovo achieved robust performance across these amino acid-PTM combinations (median area under the precision-coverage curve 0.92), while maintaining performance on unmodified peptides (0.93), nearly identical to Casanovo (0.94). The model outperformed π-PrimeNovo-PTM and InstaNovo-P and showed increased precision and complementarity to the database search tool MSFragger. Robustness was confirmed across independent datasets, particularly at peptide lengths frequently represented in the curated dataset. Applied to a phosphoproteomics dataset from monkeypox virus-infected cells, Modanovo recovered numerous confident peptides not reported by database search, including new viral phosphosites supported by spectral evidence, thereby demonstrating its complementarity to database-driven identification approaches. These results establish Modanovo as a broadly applicable model for comprehensive de novo sequencing of both modified and unmodified peptides.','https://doi.org/10.1016/j.mcpro.2025.101501','Molecular & Cellular Proteomics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(271,'Improvements to Casanovo, a Deep Learning De Novo Peptide Sequencer','2025-12-30','10.1021/acs.jproteome.5c00706','American Chemical Society (ACS)','Casanovo is a state-of-the-art deep learning model for de novo peptide sequencing from mass spectrometry and proteomics data. Here, we report on a series of enhancements to Casanovo, aimed at improving the interpretability of the scores assigned to predicted peptides, generalizing the software for use in database searches, speeding up training and prediction runtimes, and providing workflows and visualization tools to facilitate adoption of Casanovo and interpretation of its results. Our goal is to make Casanovo accurate and easy to use for applications such as metaproteomics, antibody sequencing, immunopeptidomics, and the discovery of novel peptide sequences in standard proteomics analyses. Casanovo is available as open source at https://github.com/Noble-Lab/casanovo.','https://doi.org/10.1021/acs.jproteome.5c00706','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(272,'De Novo Peptide Sequencing Daily Report (DNPS-DR)','2026-08-27',NULL,'Hugging Face',NULL,'https://huggingface.co/spaces/yangtingpeng/DNPS-DR','Hugging Face','resource',NULL,NULL);
INSERT INTO publication VALUES(273,'Learning from tandem mass spectra at scale with a self-supervised foundation model for proteomics','2026-09-03','10.64898/2026.09.03.747733','Cold Spring Harbor Laboratory','Mass spectrometry-based proteomics increasingly relies on machine learning, yet existing models are trained for defined supervised tasks such as peptide identification, de novo sequencing or fragment intensity prediction, limiting transfer across datasets, instruments and acquisition methods. Here we present InstaNovo-FM, a self-supervised foundation model for bottom-up proteomics trained to reconstruct masked regions of tandem mass spectra. We assemble a diverse training corpus spanning 1.47 billion MS/MS spectra and 184.6 million high-confidence annotations. We train an encoder-only transformer on the annotated tier using a physics-aware masked reconstruction objective. We demonstrate that the InstaNovo-FM embeddings encode fundamental experimental and biological properties, including fragmentation method, sequence properties and post-translational modifications, without requiring peptide labels. Furthermore, this foundation model directly enables diverse downstream applications, including de novo peptide sequencing, database-free identification and analytical run classification. InstaNovo-FM establishes a unified representation space for peptide fragmentation spectra, enabling robust transferability across the proteomics ecosystem.','https://doi.org/10.64898/2026.09.03.747733','bioRxiv','preprint',NULL,NULL);
INSERT INTO publication VALUES(274,'Spectra Fragment-Ion and Amino Acid Probability Prediction for Peptide Sequencing','2026-08-18',NULL,'MSc thesis','Reliable tandem mass-spectral analysis requires distinguishing sequence-informative fragment evidence from noise and incomplete observations. This problem is important in peptide-spectrum interpretation, including database-assisted analysis and de novo peptide sequencing, because an observed peak is not necessarily a sequence-informative fragment, whereas an unobserved fragment may still be valid. This thesis formulates two local probability-prediction tasks. Fragment-Ion Probability estimates whether a peak-supported mass position represents a sequence-informative fragment ion, and Amino Acid Probability estimates whether two mass-consistent positions are adjacent fragments connected by a candidate residue. CNN and encoder-only Transformer models are developed for both tasks. In the controlled downstream experiment, using the evaluated probability models achieve higher Amino Acid Recall, Amino Acid Precision, and Peptide Recall, showing that the predicted probability provides useful complementary spectral evidence.','https://hdl.handle.net/20.500.14721/40424',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(275,'De novo sequencing of multiple tandem mass spectra of peptide containing SILAC labeling','2023-03-29',NULL,'PhD thesis','The systematic studies of proteins has gradually become fundamental in the research related to molecular biology. Shotgun proteomics use bottom-up proteomics techniques in identifying proteins contained in complex mixtures using a combination of high performance liquid chromatography coupled with mass spectrometry technology. Current mass spectrometers equipped with high sensitivity and accuracy can produce thousands of tandem mass spectrometry (MS/MS) spectra in a single run. The large amount of data collected in a single LC-MS/MS run requires effective computational approaches to automate the process of spectra interpretation. De novo peptide sequencing from tandem mass spectrometry (MS/MS) has emerged as an important technology for peptide sequencing in proteomics. However, the low identification rate of the acquired mass spectral limits the efficiency of computational approaches. To increase the accuracy and practicality of de novo sequencing, some previous algorithms used multiple spectra to identify the peptide sequence. In this thesis, we focus on de novo sequencing of multiple SILAC labeled tandem mass spectra. Compared with previous approach, our research develop de novo sequencing algorithms based on different idea of how to use multiple spectra. SILAC technology uses medium containing different kinds of isotope-labeled essential amino acids, usually Arginine(R) and Lysine(K), to label newly synthesized proteins with stable isotopes during cell growth. Multiple MS/MS spectra for the same peptide sequence are produced by spectrometer after the SILAC samples are processed by LC-MS/MS shotgun proteomics. Based on the factors such as the type of isotope labeling, retention time, precursor ion mass, multiple spectra with different type of SILAC modifications for the same peptide in the sample can be used to identify the peptide sequence. In this study, not only are we aiming to identify the peptide sequence with specific SILAC modifications, but we are also pinpointing locations of SILAC modifications from multiple SILAC labeled MS/MS spectra. We propose two de novo sequencing algorithms to compute the peptide sequence which are based on total number of SILAC modifications and based on the combinations of SILAC modifications of Arginine(R) and Lysine(K). With two dynamic programming algorithms to identify peptide sequence and locating its SILAC modifications, the potential candidates are computed with similarity scores and then refinement algorithms are applied. Finally, a confident score is designed to measure all of the candidate sequence. To verify the performance of our algorithm, we compare the experimental results. We also compare the output candidates between our approach and PEAKS de novo.','https://hdl.handle.net/20.500.14721/32961',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(276,'Discrimination of Leucine and Isoleucine in De Novo peptide sequencing using deep neural networks','2020-08-21',NULL,'MSc thesis','De novo peptide sequencing from tandem MS data is a key technology in proteomics for understanding the structure of proteins, especially for first seen sequences. Although this technique has advanced rapidly in recent years and become more effective, one crucial problem remained unsolved. Due to the isomerism of leucine and isoleucine, they are practically indistinguishable in de novo sequencing using traditional tandem MS data. Some experimental attempts have been made to resolve this ambiguity such as EThCD fragmentation process. In this study, we took a data focused approach rather than only looking for characteristic satellite ions produced by the EThCD fragmentation. We utilized cutting edge deep neural networks to digest raw spectra data in a broader range searching for other unknown evidence in the spectra in hopes to increase the reliability discriminating two isometric amino acids, while also explored the capabilities of such tools when dealing with tandem MS spectra data.','https://hdl.handle.net/20.500.14721/30298',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(277,'Sparse Autoencoders for Interpretability of InstaNovo','2026-06-25',NULL,'MSc thesis','Transformer models for de novo peptide sequencing reconstruct peptide sequences from mass spectra with high accuracy but offer no insight into which spectral features drive their predictions. This work investigates whether sparse autoencoders can uncover chemically meaningful representations inside InstaNovo, a de novo peptide sequencer. We train sparse autoencoders at four depths of the model''s encoder and pair them with a fragment-ion annotation pipeline that labels each spectral peak with chemical concepts derived from first principles, allowing us to ask which learned features correspond to which chemical events. The trained autoencoders reconstruct the encoder''s internal representations with greater than 92% fidelity at every layer while preserving more than 99.5% of the model''s sequencing loss. A substantial fraction of features associate significantly with specific chemical concepts, and these associations are organised by depth: physical spectral properties are represented most sharply in early layers, while chemically specific properties such as cleavage specificity and modification localisation emerge in the deeper layers. Causal ablation experiments establish the degree to which these associations reflect genuine use by the model rather than coincidental correlation. The findings show that sparse autoencoders are a viable tool for mechanistic interpretability of transformer models used in proteomics, while exposing a structural limitation in how correlation-based feature ranking interacts with the chemical concepts that co-occur throughout mass spectrometry data.','https://jeroen.vangoey.be/files/theses/interpretability-sparse-autoencoders-instanovo.pdf',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(278,'Diffusion-based Foundation Model For Mass Spectrometry Via Self-Supervised Learning on Unlabelled Data','2026-06-11',NULL,'MSc thesis','The identification of mass spectra is key to proteomics, which is a technology used in a wide range of biological and medical applications. With the surge of machine learning applications in proteomics, this data needs to be processed into representations suitable for AI models to learn from. However, mass spectrum data contains noise from different sources and instrument configurations, which can reduce its utility in downstream machine learning models. Current approaches, such as the InstaNovo and Casanovo models, that use encoders to provide these representations in the form of embeddings are also limited, as they do not fully reduce the impact of noise in the data and originate from models optimized for the singular task of de novo peptide sequencing. In addition, some of these methods require supervised learning, which relies on labelled data, yet a large amount of mass spectrum data currently remains unlabelled. In this study, a diffusion-based encoder is trained using a self-supervised masked spectrum prediction task to learn robust representations of mass spectra from unlabelled data. The resulting embeddings should provide general-purpose spectrum representations that can be transferred to downstream proteomics tasks, reducing reliance on task-specific supervised models and enabling more effective use of large-scale mass spectrometry datasets. Overall, our model achieves an R² of 0.784 for precursor m/z at large-scale compared to the baseline (0.923), while learning compact and organised latent representations. This indicates a trade-off between representation compactness and predictive accuracy. For classification, the foundation model achieves a precursor charge accuracy of 0.647 on the full dataset, which is below the majority-class baseline of approximately 0.734 given the strong class imbalance (charge 2 dominates 73.4% of spectra), while the InstaDeep baseline achieves 0.942, indicating strong performance far above trivial baselines. For fragmentation type, the model achieves 0.624 compared to a majority-class baseline of 0.547 and a random baseline of 0.250, indicating marginal but non-trivial performance. Based on the small-scale ablations, the results suggest that the diffusion-based encoder using masking and the multi-loss objective supports learning organised and compact latent representations, however, additional mechanisms, such as parameter tuning at scale, are required to improve predictive performance of the current model, particularly under imbalanced classification settings and at a large dataset scale. In addition, our findings show that the centroid loss requires mechanisms, such as AdaLN modulation, to reduce its performance penalty on learned embeddings.','https://jeroen.vangoey.be/files/theses/diffusion-foundation-model-mass-spectrometry.pdf',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(279,'INSearch: AI-native framework for large scale proteomic database search via contrastive joint embeddings and transformer-based scoring function','2026-06-29',NULL,'MSc thesis','In mass spectrometry-based proteomics, identifying the peptide sequence that generated a specific spectrum is a complex challenge. The main method that is used for peptide-spectrum matching is searching against a reference database using traditional search engines; these search engines use a tailored score function to assign a score to each match based on certain criteria. However, as datasets grow in size, the search space expands combinatorially due to the inclusion of many organism proteomes or post-translational modifications, and the time complexity of these search engines is O(S × ρP) (Kalogeropoulos et al., 2026), where S and P are the number of query spectra and peptides, respectively. The aim of this project is to design a preliminary framework prototype called INSearch. The INSearch objective is to provide a sublinear candidate retrieval complexity O(S(log P + K)) while efficiently maintaining identification accuracy in large-scale database searches. INSearch utilises a dual-encoder architecture to jointly project the experimental tandem mass spectra and theoretical peptide sequences into a shared latent space so that the spectra and their corresponding ground truth peptides align. The standard contrastive loss was used as the objective loss function with an additional component, variance regularisation (Bardes et al., 2022), to prevent feature collapse. Another loss function was used as an alternative to the standard contrastive loss, alignment and uniformity loss (Wang and Isola, 2020) that optimises the contrastive learning objective asymptotically. The similarity search is conducted through an approximate nearest neighbour search algorithm to retrieve the top-k peptide candidates for a certain spectrum query, providing a sublinear time complexity. Since the similarity search is approximate, the retrieved candidate list undergoes a neural re-ranking stage: the decoder of InstaNovo (Eloff et al., 2025) is used in teacher-forcing mode as a scoring function to assign residue-specific log-probabilities, which are aggregated using the geometric mean into a final confidence score for each match. On the nine-species benchmark, the two-stage INSearch achieved strong recall on the held-out yeast test split: a Stage-1 Recall@1/5/100 of 60.0/78.9/91.9%, with the neural re-scoring stage lifting Recall@1 to 82.9%, indicating cross-species generalisation. On the more challenging S. brodae proteome the results were more moderate (a Stage-1 Recall@100 of 55.5%), indicating a further need for scaling and training on massive datasets.','https://jeroen.vangoey.be/files/theses/ai-guided-database-search-proteomics.pdf',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(280,'Enhancing Peptide Mass Spectra Encoder through Pretraining using Contrastive Predictive Coding','2024-06-16',NULL,'MSc thesis','Proteins are an important elements of life which plays an important role in several applications, including therapies and materials. Proteins are represented by a sequence, a specific order of amino acids linked together. Identification of protein sequences is necessary to perform various tasks that include designing new drugs, predicting protein function, and determining protein structure. Low cost sequencing technologies enables the identification of massive volume of new protein sequences. However, analyzing these vast datasets presents a challenge and require sophisticated tools. Database search-based algorithms have emerged as the predominant methods for sequence identification from mass spectra. However, one notable disadvantage of these approaches is the small number of peptide sequences available in the database compared to the huge array of peptides observed in nature. Deep learning techniques enabled advanced peptide mass spectrum sequencing. Despite advances in deep learning, de novo peptide sequencing remains challenging for peptide identification from spectra. Current methods struggle with both Post Translational Modification (PTMs) due to limited training data and noisy/incomplete spectra. One possible approach to overcome the challenge of the current methods is by using unsupervised learning to pretrain the networks. There are a massive volume of unlabelled mass spectra data that can be harnessed to pre-train the de novo architectures. This study aims to improve de novo peptide sequencing by pretraining transformer encoder using Contrastive Predictive Coding (CPC) based unsupervised learning. The result highlights CPC''s effectiveness for spectra library search task. On the 9-species-V2 dataset, CPC outperform OpenMS by 3.73% and 4.15% in average amino acid level precision and recall, respectively. It also shows a 3.8% improvement in peptide-level recall, highlighting the effectiveness of CPC pre-training method. Comparison on inference speed revealed that CPC significantly outperforms OpenMS on various dataset size, indicating that it is scalable at large dataset size. This research has established a solid groundwork for the effective pretraining of mass spectra encoders using CPC.','https://jeroen.vangoey.be/files/theses/spectra-encoder-cpc-pretraining.pdf',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(281,'Advancing De Novo Glycopeptide Sequencing with InstaNovo in Glycoproteomics','2025-06-12',NULL,'MSc thesis','This study investigates the adaptation of InstaNovo, a transformer-based model originally designed for de novo peptide sequencing, to the more complex domain of glycoproteomics. Through a series of fine-tuning experiments on glycopeptide datasets, we observe that while the model shows some capacity to learn from glyco spectra, the overall improvements remain limited. Notably, fine-tuning on unfiltered spectra, which partially overlap with a dataset the model was trained on, results in stronger learning signals. However, across all fine-tuning settings, the model suffers from catastrophic forgetting, losing accuracy on peptide sequences it previously handled well. Even when using unfiltered spectra, which provide stronger learning signals for glycopeptides, this forgetting effect persists. PCA (Principal Component Analysis) projections of spectrum embeddings further reveal a significant domain shift, which helps explain why InstaNovo struggles on glycopeptides sequencing adaptation. To address this, we propose treating overlapping, glyco spectra not as outliers to discard, but as informative examples that help the model distinguish between glycosylated and non-glycosylated peptides. While fine-tuning strategies prove insufficient for reliable glycopeptide sequencing, our results highlight promising directions for improvement. Future work should explore richer datasets, multi-task learning, attention-guided learning mechanism, contrastive learning, and transformations that preserve the embedding of the original InstaNovo spectra while shifting glyco spectra closer to them in embedding space, helping align their distributions.','https://jeroen.vangoey.be/files/theses/glyco-finetuning-instanovo.pdf',NULL,'thesis',NULL,NULL);
INSERT INTO publication VALUES(282,'Detection of Short Peptides as Putative Biosignatures of Psychrophiles via Laser Desorption Mass Spectrometry','2023-06-01','10.1089/ast.2022.0138','Mary Ann Liebert','Studies of psychrophilic life on Earth provide chemical clues as to how extraterrestrial life could maintain viability in cryogenic environments. If living systems in ocean worlds (e.g., Enceladus) share a similar set of 3-mer and 4-mer peptides to the psychrophile Colwellia psychrerythraea on Earth, spaceflight technologies and analytical methods need to be developed to detect and sequence these putative biosignatures. We demonstrate that laser desorption mass spectrometry, as implemented by the CORALS spaceflight prototype instrument, enables the detection of protonated peptides, their dimers, and metal adducts. The addition of silicon nanoparticles promotes the ionization efficiency, improves mass resolving power and mass accuracies via reduction of metastable decay, and facilitates peptide de novo sequencing. The CORALS instrument, which integrates a pulsed UV laser source and an Orbitrap mass analyzer capable of ultrahigh mass resolving powers and mass accuracies, represents an emerging technology for planetary exploration and a pathfinder for advanced technique development for astrobiological objectives.','https://www.liebertpub.com/doi/10.1089/ast.2022.0138','Astrobiology','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(283,'BiATNovo: A Self-Attention based Bidirectional Peptide Sequencing Method','2023-05-14','10.1101/2023.05.11.540352','Cold Spring Harbor Laboratory','Traditional database-based peptide sequencing methods have shortcomings in discoverability and universality, while de novo sequencing is the essential way to analyze unknown proteins and discover new peptides and proteins. Most existing de novo sequencing algorithms have the problem of accumulated deviation and unbalanced output. At the same time, some algorithms could be more suitable for Data-Independent Acquisition Mass Spectrometry (DIA-MS) data. This paper designed a bidirectional peptide sequencing method to alleviate the problems of unbalanced output and deviation accumulation in the sequencing process. The self-attention mechanism was applied to de novo sequencing to increase the interaction within the peptide sequence and the interaction between the MS/MS spectra and the peptide sequence. On the DIA-MS dataset, the peptide prediction accuracy improved by an average of 15.6% compared with the state-of-the-art method. On the DDA-MS dataset, our method achieved the best performance on partial datasets, the amino acid accuracy improved by an average of 3%. At the same time, two new evaluation scores, Position-BLEU and Alignment score, were proposed to evaluate the misalignment between the predicted sequence and the reference sequence, and the partial absence of fragment ions.','https://www.biorxiv.org/content/10.1101/2023.05.11.540352v1','bioRxiv','preprint','v1',NULL);
INSERT INTO publication VALUES(284,'Sequence-Resolved Discovery of Immunomodulatory Peptides from Cricket Protein Hydrolysate as a Functional Alternative Protein Ingredient','2026-07-13','10.2139/ssrn.7102266','Elsevier BV (SSRN)','Cricket protein hydrolysate (CPH) is a promising alternative-protein-derived ingredient, but the active peptide sequences and mechanisms underlying its potential bioactivity remain difficult to define. In this study, CPH was evaluated in LPS-stimulated BV2 microglial cells using an integrated strategy combining cellular assays, transcriptomics, LC–MS/MS-based de novo peptidomics, structure-based screening, and peptide validation. CPH attenuated LPS-induced inflammatory activation, as shown by reduced pro-inflammatory cytokine production, nitric oxide release, and ROS accumulation. Transcriptomic analysis showed that CPH broadly modulated inflammation-related pathways, including TNF, Toll-like receptor, NOD-like receptor, IL-17, and JAK–STAT signaling. JAK–STAT signaling was further examined because of its biological link with IL-6-mediated microglial inflammatory responses. De novo peptidomics identified abundant short-chain peptides in CPH, followed by peptide characterization, bioinformatic filtering, structure-based prioritization, molecular dynamics simulations, and cellular validation of selected candidates. Several CPH-derived peptides showed predicted compatibility with the STAT3 SH2 domain and reduced LPS-induced IL-6 and TNF-α secretion, oxidative stress, IBA1-associated microglial activation, and STAT3 phosphorylation. Mechanistic assays further indicated that suppression of LPS-induced IL-6 production contributed to the reduced STAT3 activation observed in peptide-treated cells. Collectively, these findings establish a sequence-resolved workflow for identifying immunomodulatory peptides from cricket protein hydrolysate and support CPH as a promising source of functional peptides capable of modulating IL-6-associated microglial inflammatory signaling.','https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7102266','SSRN Electronic Journal','preprint',NULL,'crossref');
INSERT INTO publication VALUES(285,'Sequence-resolved discovery and cellular validation of immunomodulatory peptides from cricket protein hydrolysate','2026-09-18','10.1016/j.fufo.2026.101187','Elsevier BV','Cricket protein hydrolysate (CPH) is a promising alternative-protein-derived ingredient, but the active peptide sequences and mechanisms underlying its potential bioactivity remain difficult to define. In this study, CPH was evaluated in LPS-stimulated BV2 microglial cells using an integrated strategy combining cellular assays, transcriptomics, LC–MS/MS-based de novo peptidomics, structure-based screening, and peptide validation. CPH attenuated LPS-induced inflammatory activation, as shown by reduced pro-inflammatory cytokine production, nitric oxide release, and ROS accumulation. Transcriptomic analysis showed that CPH broadly modulated inflammation-related pathways, including TNF, Toll-like receptor, NOD-like receptor, IL-17, and JAK–STAT signaling. JAK–STAT signaling was subsequently selected as a biologically relevant cytokine-responsive pathway for further investigation rather than as the dominant transcriptomic response. De novo peptidomics revealed that CPH contained predominantly short peptides, which were subsequently subjected to peptide characterization, bioinformatic filtering, structure-based prioritization, molecular dynamics simulations, and cellular validation. Several CPH-derived peptides showed predicted compatibility with the STAT3 SH2 domain. Selected peptides reduced LPS-induced IL-6 and TNF-α secretion, while their effects on oxidative stress, IBA1 expression, and STAT3 phosphorylation varied among peptide sequences. CPH also reduced LPS-induced STAT3 phosphorylation, providing a link between the hydrolysate-level and peptide-level findings. Together, these results suggest that selected CPH-derived peptides may modulate STAT3-associated inflammatory signaling. Collectively, this study establishes a sequence-resolved workflow for identifying immunomodulatory peptides from cricket protein hydrolysate and supports CPH as a source of candidate functional peptides with cellular anti-inflammatory activity.','https://doi.org/10.1016/j.fufo.2026.101187','Future Foods','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(286,'Characterization of the Agent of "High Plains Disease": Mass Spectrometry Determines the Sequence of the Disease-specific Protein','2004-01-01','10.1074/jbc.M308506200','American Society for Biochemistry and Molecular Biology','The "32-kDa" protein specifically associated with high plains disease was characterized by time-of-flight mass spectrometry, after the agent had been isolated in pure culture by "vascular puncture inoculation," a novel mechanical means of transmission. Two isolates from different geographic locations each consisted of a mixture of subpopulations that were highly homologous to an amino acid sequence derived from a nucleotide sequence (U60141) deposited in GenBank trade mark by the Nebraska group as "the probable N-protein of high plains virus." However, the U60141 sequence was found to be incomplete; de novo sequencing of peptides produced by proteolytic digestions of the 32-kDa band from an SDS-PAGE separation showed that an additional 18 amino acid residues were present at the N terminus. BLAST (basic local alignment search tool) examination of the sequence showed no significant homology with any protein in the databases, indicating that the infectious agent of high plains disease is likely a member of a hitherto unclassified virus group.','https://doi.org/10.1074/jbc.M308506200','Journal of Biological Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(287,'Immune Responses Are Characterized by Specific Shared Immunoglobulin Peptides That Can Be Detected by Proteomic Techniques','2010-09-01','10.1074/jbc.M110.139071','American Society for Biochemistry and Molecular Biology','In the adaptive immune response, immunoglobulins develop that bind specifically to the antigens to which the organism was exposed. Immunoglobulins may bind to known or unknown antigens in a variety of diseases and have been used in the past to identify novel antigens for use as a biomarker. We propose that the immunoglobulins themselves could also be used as biomarkers in antibody-mediated disease. In this proteomic study, rats were immunized with one of two purified antigens, and immunoglobulins from pre- and postimmune sera were analyzed with nano-LC coupled mass spectrometry. It was found that the two treatment groups could be distinguished based on cluster analysis of the immunoglobulin peptides from the immune sera. In addition, we identified 684 specific peptides that were differentially present in one of the two treated groups. We could find an amino acid sequence for 44% of the features in the mass spectra by combining database-driven and de novo sequencing techniques. The latter were essential for sequence identification, as the more common database-driven approach suffers from a poor representation of immunoglobulins in the available databases. Our data show that the development of immunoglobulins during an immune response is not a fully random process, but that instead selection pressures exist that favor the best binding amino acid sequences, and that this selection is shared between different animals. This finding implies that immunoglobulin peptides could indeed be a powerful and easily accessible class of biomarkers.','https://doi.org/10.1074/jbc.M110.139071','Journal of Biological Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(288,'High Immunogenicity of the Human Leukocyte Antigen Peptidomes of Melanoma Tumor Cells','2012-09-01','10.1074/jbc.M112.358903','American Society for Biochemistry and Molecular Biology','Human leukocyte antigens (HLA) bind peptides generated by limited proteolysis in cells and present them at the cell surfaces for recognition by T cells. Through this antigen presentation function they control the specificity of T cell responses and thereby adaptive immune responses. Knowledge of HLA-bound peptides is thus key to understanding adaptive immunity and to the development of vaccines and other specific immune intervention strategies. To gain insight into the antigenicity of melanomas, peptides were extracted from HLA isolated from the tumor cells, separated by two-dimensional HPLC, and sequenced by mass spectrometry. The spectra were analyzed by database-dependent MASCOT searches and database-independent de novo sequencing and, where required, confirmed with synthetic peptides, which were also used to determine their immunogenicity. Comparing four different melanoma cell lines, little overlap of the HLA-bound peptides was found, suggesting a high degree of individualization of the HLA peptidomes. This notwithstanding, the peptidomes were highly immunogenic in the patients from whom the tumor cells had been established and in unrelated patients. This broad cross-patient immunogenicity was only exceptionally related to individual peptides. The majority of the identified epitopes were derived from low to medium abundance proteins, mostly involved in sensitive cellular processes such as cell cycle control, DNA replication, control of gene expression, tumor suppressor function, and protein metabolism. The peptidomes thus provide insights into processes potentially related to tumorigenesis. Furthermore, analyses of the peptide sequences yield information on the specificity of peptide selection by HLA applicable to the developing prediction algorithms for T cell epitopes.','https://doi.org/10.1074/jbc.M112.358903','Journal of Biological Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(289,'A Proteomics Approach to the Identification of Mammalian Mitochondrial Small Subunit Ribosomal Proteins','2000-10-01','10.1074/jbc.M003596200','American Society for Biochemistry and Molecular Biology','Mammalian mitochondrial small subunit ribosomal proteins were separated by two-dimensional polyacrylamide gel electrophoresis. The proteins in six individual spots were subjected to in-gel tryptic digestion. Peptides were separated by capillary liquid chromatography, and the sequences of selected peptides were obtained by electrospray tandem mass spectrometry. The peptide sequences obtained were used to screen human expressed sequence tag data bases, and complete consensus cDNAs were assembled. Mammalian mitochondrial small subunit ribosomal proteins from six different classes of ribosomal proteins were identified. Only two of these proteins have significant sequence similarities to ribosomal proteins from prokaryotes. These proteins correspond to Escherichia coli S10 and S14. Homologs of two human mitochondrial proteins not found in prokaryotes were observed in the genomes of Drosophila melanogaster and Caenorhabditis elegans. A homolog of one of these proteins was observed in D. melanogaster but not in C. elegans, while a homolog of the other was present in C. elegans but not in D. melanogaster. A homolog of one of the ribosomal proteins not found in prokaryotes was tentatively identified in the yeast genome. This latter protein is the first reported example of a ribosomal protein that is shared by mitochondrial ribosomes from lower and higher eukaryotes that does not have a homolog in prokaryotes.','https://doi.org/10.1074/jbc.M003596200','Journal of Biological Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(290,'MassLynx NT BioLynx & ProteinLynx Guide','2001-12-10',NULL,'Micromass UK Ltd',NULL,'https://help.waters.com/content/dam/waters/de/support/usermanuals/2003/715000391/biolynx_proteinlynx_40.pdf',NULL,'resource',NULL,NULL);
INSERT INTO publication VALUES(291,'Rubisco activase requires residues in the large subunit N terminus to remodel inhibited plant Rubisco','2020-11-01','10.1074/jbc.RA120.015759','American Society for Biochemistry and Molecular Biology','The photosynthetic CO 2 fixing enzyme ribulose 1,5-bisphosphate carboxylase/oxygenase (Rubisco) forms dead-end inhibited complexes while binding multiple sugar phosphates, including its substrate ribulose 1,5-bisphosphate. Rubisco can be rescued from this inhibited form by molecular chaperones belonging to the ATPases associated with diverse cellular activities (AAA+ proteins) termed Rubisco activases (Rcas). The mechanism of green-type Rca found in higher plants has proved elusive, in part because until recently higher-plant Rubiscos could not be expressed recombinantly. Identifying the interaction sites between Rubisco and Rca is critical to formulate mechanistic hypotheses. Toward that end here we purify and characterize a suite of 33 Arabidopsis Rubisco mutants for their ability to be activated by Rca. Mutation of 17 surface-exposed large subunit residues did not yield variants that were perturbed in their interaction with Rca. In contrast, we find that Rca activity is highly sensitive to truncations and mutations in the conserved N terminus of the Rubisco large subunit. Large subunits lacking residues 1–4 are functional Rubiscos but cannot be activated. Both T5A and T7A substitutions result in functional carboxylases that are poorly activated by Rca, indicating the side chains of these residues form a critical interaction with the chaperone. Many other AAA+ proteins function by threading macromolecules through a central pore of a disc-shaped hexamer. Our results are consistent with a model in which Rca transiently threads the Rubisco large subunit N terminus through the axial pore of the AAA+ hexamer.','https://doi.org/10.1074/jbc.RA120.015759','Journal of Biological Chemistry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(292,'A neural network approach to the identification of b-/y-ions in MS/MS spectra','2012-10-01','10.1109/BIBM.2012.6392625','Institute of Electrical and Electronics Engineers (IEEE)','The effectiveness of de novo peptide sequencing algorithms depends on the quality of MS/MS spectra. Since most of the peaks in a spectrum are uninterpretable `noise'' peaks it is necessary to carefully pre-filter the spectra to identify the `signal'' peaks that likely correspond to b-/y-ions. Selecting the optimal set of peaks for candidate peptide generation is essential for obtaining accurate results. A careful balance must be maintained between the precision and recall of peaks that are selected for further processing and candidate peptide generation. If too many peaks are selected the search space will be too large and the problem becomes intractable. If too few peaks are selected cleavage sites will be missed, the resulting candidate peptides will have large gaps, and sequencing results will be poor. For this reason pre-filtering of MS/MS spectra and accurate selection of peaks for peptide candidate generation is essential to any de novo peptide sequencing algorithm. We present a novel neural network approach for the selection of b-/y-ions using known fragmentation characteristics, and leveraging neural network probability estimates of flanking and complementary ions. We show a significant improvement in precision and recall of peaks corresponding to b-/y-ions and a reduction in search space over approaches used by other de novo peptide sequencing algorithms.','https://ieeexplore.ieee.org/document/6392625','2012 IEEE International Conference on Bioinformatics and Biomedicine (BIBM)','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(293,'Identification of b-/y-ions in MS/MS spectra using a two stage neural network','2013-11-07','10.1186/1477-5956-11-S1-S4','Springer Science and Business Media LLC','Independent of the approach used, the ability to correctly interpret tandem MS data depends on the quality of the original spectra. Even in the case of the highest quality spectra, the majority of spectral peaks can not be reliably interpreted. The accuracy of sequencing algorithms can be improved by filtering out such ''noise'' peaks. Preprocessing MS/MS spectra to select informative ion peaks increases accuracy and reduces the processing time. Intuitively, the mix of informative versus non-informative peaks has a direct effect on the quality and size of the resulting candidate peptide search space. As the number of selected peaks increases, the corresponding search space increases exponentially. If we select too few peaks then the ion-ladder interpretation of the spectrum will contain gaps that can only be explained by permutations of combinations of amino acids. This will result in a larger candidate peptide search space and poorer quality candidates. The dependency that peptide sequencing accuracy has on an initial peak selection regime makes this preprocessing step a crucial facet of any approach, whether de novo or not, to MS/MS spectra interpretation. We have developed a novel approach to address this problem. Our approach uses a staged neural network to model ion fragmentation patterns and estimate the posterior probability of each ion type. Our method improves upon other preprocessing techniques and shows a significant reduction in the search space for candidate peptides without sacrificing candidate peptide quality.','https://doi.org/10.1186/1477-5956-11-S1-S4','Proteome Science','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(294,'De novo protein sequencing of antibodies for identification of neutralizing antibodies in human plasma post SARS-CoV-2 vaccination','2024-10-10','10.1038/s41467-024-53105-8','Springer Science and Business Media LLC','The antibody response to vaccination and infection is a key component of the immune response to pathogens. Sequencing of peripheral B cells may not represent the complete B cell receptor repertoire. Here we present a method for sequencing human plasma-derived polyclonal IgG using a combination of mass spectrometry and B-cell sequencing. We investigate the IgG response to the Moderna Spikevax COVID-19 vaccine. From the sequencing data of the natural polyclonal response to vaccination, we generate 12 recombinant antibodies. Six derived recombinant antibodies, including four generated with de novo protein sequencing, exhibit similar or higher binding affinities than the original natural polyclonal antibody. Neutralization tests reveal that the six antibodies possess neutralizing capabilities against the target antigen. This research provides insights into sequencing polyclonal IgG antibodies and the potential of our approach in generating recombinant antibodies with robust binding affinity and neutralization capabilities. Directly examining the circulating IgG pool is crucial due to potential misrepresentations by B-cell analysis alone.','https://doi.org/10.1038/s41467-024-53105-8','Nature Communications','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(295,'An Information Theoretic Approach to Rescoring Peptides Produced by De Novo Peptide Sequencing','2010-10-29','10.5281/zenodo.1070516','WASET','Tandem mass spectrometry (MS/MS) is the engine driving high-throughput protein identification. Protein mixtures possibly representing thousands of proteins from multiple species are treated with proteolytic enzymes, cutting the proteins into smaller peptides that are then analyzed generating MS/MS spectra. The task of determining the identity of the peptide from its spectrum is currently the weak point in the process. Current approaches to de novo sequencing are able to compute candidate peptides efficiently. The problem lies in the limitations of current scoring functions. In this paper we introduce the concept of proteome signature. By examining proteins and compiling proteome signatures (amino acid usage) it is possible to characterize likely combinations of amino acids and better distinguish between candidate peptides. Our results strongly support the hypothesis that a scoring function that considers amino acid usage patterns is better able to distinguish between candidate peptides. This in turn leads to higher accuracy in peptide prediction.','https://publications.waset.org/8237/an-information-theoretic-approach-to-rescoring-peptides-produced-by-de-novo-peptide-sequencing','World Academy of Science, Engineering and Technology','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(296,'N-Terminal Coumarin Derivatization-Aided De Novo Peptide Sequencing and Its Application to Peptidomics Using LC-Trapped Ion Mobility Spectrometry-qTOF/MS','2026-06-30','10.1021/acs.analchem.6c01542','American Chemical Society (ACS)','De novo peptide sequencing using LC-MS/MS enables database-independent sequence determination and facilitates the discovery of bioactive peptides and biomarkers in untargeted peptidomics. However, conventional MS/MS analyses often produce fragment ions that are insufficient for complete sequencing. Here, we established an LC-MS/MS workflow using N -succinimidyl 7-methoxycoumarin-3-carboxylate (Me-Cou) as an N -terminal tag to improve de novo sequencing performance. Me-Cou derivatization generated highly informative fragment ions, particularly b 1 -b 3 ions, for (Gly) 4 at 1 μmol/L, surpassing the performance of established tags, such as 2,4,6-trinitrobenzenesulfonic acid, 3-aminopyridyl-hydroxy-succinimidyl carbamate, and N -succinimidyl [tris(2,4,6-trimethoxyphenyl)phosphonio]acetate bromide. The Me-Cou tag also enabled confident sequencing of (Gly) 10 , generating abundant b 1 -b 9 ions. Notably, intact de novo sequencing identified 74 peptides with 32 misidentified peptides that were not included in a 132-standard peptide mixture (86 dipeptides and 46 oligopeptides). However, all peptides were correctly identified using Me-Cou-aided de novo sequencing with no misidentification, demonstrating high specificity and accuracy. Additionally, Me-Cou-aided de novo sequencing successfully identified 328 peptides in casein peptone, all of which were assigned as casein protein fragments. Overall, Me-Cou-based LC-MS/MS significantly enhanced peptide detection and the characterization of sequence diversity compared with intact analysis. This methodology is a promising strategy for untargeted peptidomics, enabling comprehensive characterization of endogenous peptides in both protein hydrolysates and biological fluids.','https://pubs.acs.org/doi/10.1021/acs.analchem.6c01542','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(297,'N-terminal Coumarin Derivatization-aided De Novo Peptide Sequencing and its Application to Peptidomics using LC-trapped Ion Mobility Spectrometry-qTOF/MS','2026-03-03','10.26434/chemrxiv.15000573/v1','ChemRxiv','De novo peptide sequencing using LC-MS/MS enables database-independent sequence determination and facilitates the discovery of novel bioactive peptides and biomarkers in untargeted peptidomics. However, conventional MS/MS analyses often produces fragment ions that are insufficient for complete sequencing. Here, we established an LC-MS/MS workflow using N -succinimidyl 7-methoxycoumarin-3-carboxylate (Me-Cou) as an N -terminal tag to improve de novo sequencing performance. Me-Cou derivatization generated highly informative fragment ions, particularly b₁-b₃ ions, for (Gly)₄ at 1 μmol/L, surpassing the performance of established tags, such as 2,4,6-trinitrobenzenesulfonic acid, 3-aminopyridyl-hydroxy-succinimidyl carbamate, and N -succinimidyl [tris(2,4,6-trimethoxyphenyl)phosphonio]acetate bromide. The Me-Cou tag also enabled confident sequencing of (Gly)₁₀, generating abundant b₁-b9 ions. Notably, intact de novo sequencing identified 74 peptides with 32 misannotated peptides that were not included in a 132 standard peptide mixture (86 dipeptides and 46 oligopeptides). However, all peptides were correctly identified using Me-Cou-aided de novo sequencing with no misannotations, demonstrating high specificity and accuracy. Additionally, Me-Cou-aided de novo sequencing successfully identified 328 peptides in casein peptone, all of which were assigned as casein protein fragments. Overall, Me-Cou-based LC-MS/MS significantly enhanced peptide detection and the characterization of sequence diversity compared with intact analysis. This methodology is a promising strategy for untargeted peptidomics, enabling comprehensive characterization of endogenous peptides in both protein hydrolysates and biological fluids.','https://chemrxiv.org/doi/full/10.26434/chemrxiv.15000573/v1','ChemRxiv','preprint',NULL,'crossref');
INSERT INTO publication VALUES(298,'Towards the establishment of a comprehensive food inspection system: An approach to utilize de novo peptide sequencing from MS/MS spectra','2026-07-16','10.1016/j.foohum.2026.101356','Elsevier BV','Ensuring food safety and preventing food fraud require analytical methods capable of identifying unknown and unexpected contaminants in foods. This study developed a proteomics-based strategy centered on de novo sequencing, in which peptide sequences are directly determined from MS/MS spectra without reliance on protein databases. To obtain high-confidence peptide sequences, mass spectrometry conditions were optimized using tryptic digests of K562 cells. Among the tested platforms, ZenoTOF 7600 operated with a Zeno trap accumulation time of 25 ms and 80 MS/MS events yielded the highest number of peptide sequences, averaging 1,057 peptides with an Average Local Confidence score of ≥99. The resulting peptide sequences were used for species identification and quantitative analysis, with database searching applied as a complementary step. Application of this strategy to oyster extract-supplemented soy sauce enabled identification of species associated with added ingredients and the manufacturing process, demonstrating its potential for detecting unknown adulteration and unexpected contamination.','https://www.sciencedirect.com/science/article/pii/S2949824426003642','Food and Humanity','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(299,'Towards the establishment of a comprehensive food inspection system: an approach to utilise de novo peptide sequencing from MS/MS spectra','2026-02-13','10.2139/ssrn.6234726','Elsevier BV (SSRN)','Ensuring food safety and preventing food fraud require analytical methods capable of identifying unknown and unexpected contaminants in foods. This study developed a proteomics-based strategy centered on de novo sequencing, in which peptide sequences are directly determined from MS/MS spectra without reliance on protein databases. To obtain high-confidence peptide sequences, mass spectrometry conditions were optimized using tryptic digests of K562 cells. Among the tested platforms, ZenoTOF 7600 operated with a Zeno trap accumulation time of 25 ms and 80 MS/MS events yielded the highest number of peptide sequences, averaging 1,057 peptides with an Average Local Confidence score of ≥99. The resulting peptide sequences were used for species identification and quantitative analysis, with database searching applied as a complementary step. Application of this strategy to oyster extract-supplemented soy sauce enabled identification of species associated with added ingredients and the manufacturing process, demonstrating its potential for detecting unknown adulteration and unexpected contamination.','https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6234726','SSRN Electronic Journal','preprint',NULL,'crossref');
INSERT INTO publication VALUES(300,'Automated Antibody De Novo Sequencing and Its Utility in Biopharmaceutical Discovery','2017-05-01','10.1007/s13361-016-1580-0','American Chemical Society (ACS)','Applications of antibody de novo sequencing in the biopharmaceutical industry range from the discovery of new antibody drug candidates to identifying reagents for research and determining the primary structure of innovator products for biosimilar development. When murine, phage display, or patient-derived monoclonal antibodies against a target of interest are available, but the cDNA or the original cell line is not, de novo protein sequencing is required to humanize and recombinantly express these antibodies, followed by in vitro and in vivo testing for functional validation. Availability of fully automated software tools for monoclonal antibody de novo sequencing enables efficient and routine analysis. Here, we present a novel method to automatically de novo sequence antibodies using mass spectrometry and the Supernovo software. The robustness of the algorithm is demonstrated through a series of stress tests. Graphical Abstract ᅟ.','https://link.springer.com/article/10.1007/s13361-016-1580-0','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(301,'Decoding Protein Glycosylation by an Integrative Mass Spectrometry-Based De Novo Sequencing Strategy','2025-01-22','10.1021/jacsau.4c00960','American Chemical Society (ACS)','Glycoproteins, representing more than 50% of human proteins and most biopharmaceuticals, are crucial for regulating various biological processes. The complexity of multiple glycosylation sites often leads to incomplete sequence coverage and ambiguous glycan modification profiles. Here, we developed an integrative mass spectrometry-based approach for decoding unknown glycoproteins, which is featured with the combination of deglycosylation-mediated de novo sequencing with glycosylation site characterization. We utilized the enzymatic deglycosylation of N- / O- glycans to achieve comprehensive sequence coverage. Additionally, EThcD fragmentation enables the identification of high-quality long peptides, facilitating precise protein assembly. We subsequently applied this method to de novo sequencing of the highly glycosylated therapeutic fusion protein Etanercept (Enbrel). We also sequenced three new tumor necrosis factor receptor:Fc-fusion biologics with largely unknown sequences, unveiling subtle distinctions in the primary sequences. Furthermore, we characterized N- and O- glycosylation modifications of these proteins at subunit, glycopeptide, and glycan levels. This strategy bridges the gap between the de novo sequencing and glycosylation modification, providing comprehensive information on the primary structure and glycosylation modifications for glycoproteins. Notably, our method could be a robust solution for accurate sequencing of the glycoproteins and has practical value not only in basic research but also in the biopharmaceutical industry.','https://pubs.acs.org/doi/10.1021/jacsau.4c00960','JACS Au','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(302,'DiNovo enables high-coverage and high-confidence de novo peptide sequencing via mirror proteases and deep learning','2026-03-05','10.1038/s41467-026-70224-6','Springer Science and Business Media LLC','Despite the recent advancements driven by deep learning, de novo peptide sequencing is still constrained by incomplete peptide fragmentation and insufficient protein digestion in current single protease-based proteomic experiments. Here, we present a software system, named DiNovo, for high-coverage and high-confidence de novo peptide sequencing by leveraging the complementarity of mirror proteases. DiNovo is empowered by several innovative algorithms, including a mirror-spectra recognition algorithm independent of pre-sequencing, two sequencing algorithms based on deep learning and graph theory, respectively, and target-decoy mapping, a method for sequencing result evaluation free of prior peptide identification. Compared with the trypsin protease used alone, DiNovo using two pairs of mirror proteases leads to two to three times high-confidence amino acids sequenced. Compared with previous single-protease de novo sequencing algorithms, DiNovo achieves much higher sequence coverage. DiNovo also shows great potential as a practical and powerful alternative to database search for peptide identification with quality control.','https://www.nature.com/articles/s41467-026-70224-6','Nature Communications','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(303,'High-Throughput Identification of Proteins and Unanticipated Sequence Modifications Using a Mass-Based Alignment Algorithm for MS/MS de Novo Sequencing Results','2004-04-01','10.1021/ac035258x','American Chemical Society (ACS)','With the increasing availability of de novo sequencing algorithms for interpreting high-mass accuracy tandem mass spectrometry (MS/MS) data, there is a growing need for programs that accurately identify proteins from de novo sequencing results. De novo sequences derived from tandem mass spectra of peptides often contain ambiguous regions where the exact amino acid order cannot be determined. One problem this poses for sequence alignment algorithms is the difficulty in distinguishing discrepancies due to de novo sequencing errors from actual genomic sequence variation and posttranslational modifications. We present a novel, mass-based approach to sequence alignment, implemented as a program called OpenSea, to resolve these problems. In this approach, de novo and database sequences are interpreted as masses of residues, and the masses, rather than the amino acid codes, are compared. To provide further flexibility, the masses can be aligned in groups, which can resolve many de novo sequencing errors. The performance of OpenSea was tested with three types of data: a mixture of known proteins, a mixture of unknown proteins that commonly contain sequence variations, and a mixture of posttranslationally modified known proteins. In all three cases, we demonstrate that OpenSea can identify more peptides and proteins than commonly used database-searching programs (SEQUEST and ProteinLynx) while accurately locating sequence variation sites and unanticipated posttranslational modifications in a high-throughput environment.','https://pubs.acs.org/doi/10.1021/ac035258x','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(304,'Charting the Proteomes of Organisms with Unsequenced Genomes by MALDI-Quadrupole Time-of-Flight Mass Spectrometry and BLAST Homology Searching','2001-05-01','10.1021/ac0013709','American Chemical Society (ACS)','MALDI-quadrupole time-of-flight mass spectrometry was applied to identify proteins from organisms whose genomes are still unknown. The identification was carried out by successively searching a sequence database-first with a peptide mass fingerprint, then with a packet of noninterpreted MS/MS spectra, and finally with peptide sequences obtained by automated interpretation of the MS/MS spectra. A "MS BLAST" homology searching protocol was developed to overcome specific limitations imposed by mass spectrometric data, such as the limited accuracy of de novo sequence predictions. This approach was tested in a small-scale proteomic project involving the identification of 15 bands of gel-separated proteins from the methylotrophic yeast Pichia pastoris, whose genome has not yet been sequenced and which is only distantly related to other fungi.','https://pubs.acs.org/doi/10.1021/ac0013709','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(305,'PAAS 3: A computer program to determine probable sequence of peptides from mass spectrometric data','1984-08-01','10.1002/bms.1200110806','Wiley','The computer program PAAS 3 is developed to determine the probable amino acid sequences of a peptide from sequence ion peaks experimentally obtained by mass spectrometry.','https://onlinelibrary.wiley.com/doi/10.1002/bms.1200110806','Biological Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(306,'Fast algorithm for peptide sequencing by mass spectroscopy','1990-06-01','10.1002/bms.1200190607','Wiley','An automatic algorithm for sequencing polypeptides from fast atom bombardment tandem mass spectra is presented.Based on graph theory considerations it finds the most probable sequences, even if the amino acid composition is unknown, by scoring mass differences. The algorithm is fast as the computing time increases by less than the square of the number of amino acids. Pairs of two or three amino acids are proposed to explain the gap if peaks are missing.','https://onlinelibrary.wiley.com/doi/10.1002/bms.1200190607','Biological Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(307,'De Novo Sequencing of Peptides from Tandem Mass Spectra and Applications in Proteogenomics','2024-10-23','10.1007/978-1-0716-4152-1_1','Springer US','The changes in protein expression are hallmarks of development and disease. Protein expression can be established qualitatively and quantitatively using mass spectrometry (MS). Samples are prepared, proteins extracted and then analyzed using MS and MS/MS. The resulting spectra need to be processed computationally to assign peptide spectrum match. Database searches employ sequence databases or spectral libraries for matching possible peptides with the measured spectra. This route is well established but fails when peptides are not found in sequence repositories. In this case, de novo sequencing of MS/MS spectra can be employed. Many computational algorithms that establish the peptide sequence from MS/MS spectrum alone are available. While de novo sequencing assigns a sequence to an MS/MS spectrum, this assignment can be used in further processes for genome annotation. For example, novel exons can be assigned, known exons can be extended, and splice sites can be validated at the protein level. We compiled an extensive list of such algorithms, grouped them, and discussed the selected approaches. We also provide a roadmap of how de novo sequencing can enter mainstream proteogenomic analysis. In the future, de novo predictions can be added to sample-specific protein databases, including RNA-seq translations. These enriched databases can then be used for proteogenomics studies with existing pipelines.','https://link.springer.com/protocol/10.1007/978-1-0716-4152-1_1','Methods in Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(308,'Current state, existing challenges, and promising progress for de novo sequencing and assembly of monoclonal antibodies','2022-07-22','10.1101/2022.07.21.500409','Cold Spring Harbor Laboratory','Monoclonal antibodies (mAbs) are biotechnologically produced proteins with various applications in research, therapeutics, and diagnostics. Their ability to recognize and bind to specific molecule structures makes them essential research tools and therapeutic agents. Sequence information of antibodies is helpful for understanding antibody-antigen interactions and ensuring their affinity and specificity. De novo protein sequencing based on mass spectrometry is a useful method to obtain the amino acid sequence of peptides and proteins without a priori knowledge. Deep learning-based approaches have been developed and applied more frequently to increase the accuracy of de novo sequencing. In this study, we evaluated five recently developed de novo sequencing algorithms (Novor, pNovo 3, DeepNovo, SMSNet, and PointNovo) in their ability to identify and assemble antibody sequences. The deep learning-based tools PointNovo and SMSNet showed an increased peptide recall across different enzymes and datasets compared to spectrum-graph-based approaches. We evaluated different error types of de novo peptide sequencing tools and their performance for different numbers of missing cleavage sites, noisy spectra, and peptides of various lengths. We achieved a sequence coverage of 93.15% to 99.07% on the light chains of three different antibody datasets using the de Bruijn assembler ALPS and the predictions from PointNovo. However, low sequence coverage and accuracy on the heavy chains demonstrate that complete de novo protein sequencing remains a challenging issue in proteomics that requires improved de novo error correction, alternative digestion strategies, and hybrid approaches such as homology search to achieve high accuracy on long protein sequences.','https://www.biorxiv.org/content/10.1101/2022.07.21.500409','bioRxiv','preprint',NULL,'crossref');
INSERT INTO publication VALUES(309,'Complete De Novo Assembly of Monoclonal Antibody Sequences','2016-08-26','10.1038/srep31730','Springer Science and Business Media LLC','De novo protein sequencing is one of the key problems in mass spectrometry-based proteomics, especially for novel proteins such as monoclonal antibodies for which genome information is often limited or not available. However, due to limitations in peptides fragmentation and coverage, as well as ambiguities in spectra interpretation, complete de novo assembly of unknown protein sequences still remains challenging. To address this problem, we propose an integrated system, ALPS, which for the first time can automatically assemble full-length monoclonal antibody sequences. Our system integrates de novo sequencing peptides, their quality scores and error-correction information from databases into a weighted de Bruijn graph to assemble protein sequences. We evaluated ALPS performance on two antibody data sets, each including a heavy chain and a light chain. The results show that ALPS was able to assemble three complete monoclonal antibody sequences of length 216-441 AA, at 100% coverage, and 96.64-100% accuracy.','https://www.nature.com/articles/srep31730','Scientific Reports','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(310,'De Novo Sequencing of Proteins and Peptides: Algorithms, Applications, Perspectives','2018-01-01','10.18097/bmcrm00005','Institute of Biochemistry','Determination of the primary structure of proteins and peptides constitutes an important step in studying their properties. Currently, mass spectrometry is commonly applied to this end. The results of mass spectrometric measurements can be interpreted by means of either a database search or de novo sequencing methods. The appeal of the latter is due to their applicability to investigating unknown proteins, as well as the ones that cannot be analyzed with genomics or transcriptomics methods. In this paper, we briefly review the existing approaches to de novo sequencing of proteins and peptides, along with the problems that can be solved using those, and indicate directions and perspectives for their further development.','https://doi.org/10.18097/bmcrm00005','Biomedical Chemistry: Research and Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(311,'InsPecT: Identification of Posttranslationally Modified Peptides from Tandem Mass Spectra','2005-07-01','10.1021/ac050102d','American Chemical Society (ACS)','Reliable identification of posttranslational modifications is key to understanding various cellular regulatory processes. We describe a tool, InsPecT, to identify posttranslational modifications using tandem mass spectrometry data. InsPecT constructs database filters that proved to be very successful in genomics searches. Given an MS/MS spectrum S and a database D, a database filter selects a small fraction of database D that is guaranteed (with high probability) to contain a peptide that produced S. InsPecT uses peptide sequence tags as efficient filters that reduce the size of the database by a few orders of magnitude while retaining the correct peptide with very high probability. In addition to filtering, InsPecT also uses novel algorithms for scoring and validating in the presence of modifications, without explicit enumeration of all variants. InsPecT identifies modified peptides with better or equivalent accuracy than other database search tools while being 2 orders of magnitude faster than SEQUEST, and substantially faster than X!TANDEM on complex mixtures. The tool was used to identify a number of novel modifications in different data sets, including many phosphopeptides in data provided by Alliance for Cellular Signaling that were missed by other tools.','https://pubs.acs.org/doi/10.1021/ac050102d','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(312,'Precision De Novo Peptide Sequencing Using Mirror Proteases of Ac-LysargiNase and Trypsin for Large-scale Proteomics','2019-04-01','10.1074/mcp.tir118.000918','Elsevier BV','De novo peptide sequencing for large-scale proteomics remains challenging because of the lack of full coverage of ion series in tandem mass spectra. We developed a mirror protease of trypsin, acetylated LysargiNase (Ac-LysargiNase), with superior activity and stability. The mirror spectrum pairs derived from the Ac-LysargiNase and trypsin treated samples can generate full b and y ion series, which provide mutual complementarity of each other, and allow us to develop a novel algorithm, pNovoM, for de novo sequencing. Using pNovoM to sequence peptides of purified proteins, the accuracy of the sequence was close to 100%. More importantly, from a large-scale yeast proteome sample digested with trypsin and Ac-LysargiNase individually, 48% of all tandem mass spectra formed mirror spectrum pairs, 97% of which contained full coverage of ion series, resulting in precision de novo sequencing of full-length peptides by pNovoM. This enabled pNovoM to successfully sequence 21,249 peptides from 3,753 proteins and interpreted 44-152% more spectra than pNovo+ and PEAKS at a 5% FDR at the spectrum level. Moreover, the mirror protease strategy had an obvious advantage in sequencing long peptides. We believe that the combination of mirror protease strategy and pNovoM will be an effective approach for precision de novo sequencing on both single proteins and proteome samples.','https://www.mcponline.org/article/S1535-9476(20)30058-4/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(313,'Shotgun Protein Sequencing: Assembly of Peptide Tandem Mass Spectra from Mixtures of Modified Proteins','2007-07-01','10.1074/mcp.m700001-mcp200','Elsevier BV','Despite significant advances in the identification of known proteins, the analysis of unknown proteins by MS/MS still remains a challenging open problem. Although Klaus Biemann recognized the potential of MS/MS for sequencing of unknown proteins in the 1980s, low throughput Edman degradation followed by cloning still remains the main method to sequence unknown proteins. The automated interpretation of MS/MS spectra has been limited by a focus on individual spectra and has not capitalized on the information contained in spectra of overlapping peptides. Indeed the powerful shotgun DNA sequencing strategies have not been extended to automated protein sequencing. We demonstrate, for the first time, the feasibility of automated shotgun protein sequencing of protein mixtures by utilizing MS/MS spectra of overlapping and possibly modified peptides generated via multiple proteases of different specificities. We validate this approach by generating highly accurate de novo reconstructions of multiple regions of various proteins in western diamondback rattlesnake venom. We further argue that shotgun protein sequencing has the potential to overcome the limitations of current protein sequencing approaches and thus catalyze the otherwise impractical applications of proteomics methodologies in studies of unknown proteins.','https://www.mcponline.org/article/S1535-9476(20)31126-X/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(314,'Spectrum Fusion: Using Multiple Mass Spectra for De Novo Peptide Sequencing','2009-08-01','10.1089/cmb.2009.0122','SAGE Publications','We report on a new algorithm for combining the information from several mass spectra of the same peptide. The algorithm automatically learns peptide fragmentation patterns, so that it can handle spectra from any instrument and fragmentation technique. We demonstrate the utility of the algorithm, and the power of multiple spectra, by showing that combining pairs of spectra (one CID and one ETD) greatly improves de novo sequencing success rates.','https://www.liebertpub.com/doi/10.1089/cmb.2009.0122','Journal of Computational Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(315,'De novo Peptide Sequencing','2016-11-23','10.1039/9781782626732-00015','The Royal Society of Chemistry','De novo peptide sequencing refers to the process of determining a peptide’s amino acid sequence from its MS/MS spectrum alone. The principle of this process is fairly straightforward: a high-quality spectrum may present a ladder of fragment ion peaks. The mass difference between every two adjacent peaks in the ladder is used to determine a residue of the peptide. However, most practical spectra do not have sufficient quality to support this straightforward process. Therefore, research in de novo sequencing has largely been a battle against the errors in the data. This chapter reviews some of the major developments in this field. The chapter starts with a quick review of the history in Section 1. Then manual de novo sequencing is examined in Section 2. Section 3 introduces a few commonly used de novo sequencing algorithms. An important aspect of automated de novo sequencing software is a good scoring function that serves as the optimization goal of the algorithm. Thus, Section 4 is devoted for the methods to define good scoring functions. Section 5 reviews a list of relevant software. The chapter concludes with a discussion of the applications and limitations of de novosequencing in Section 6.','https://books.rsc.org/books/edited-volume/732/chapter/377797','Proteome Informatics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(316,'Lys-Sequencer: An algorithm for de novo sequencing of peptides by paired single residue transposed Lys-C and Lys-N digestion coupled with high-resolution mass spectrometry','2020-02-15','10.1002/rcm.8574','Wiley','Rationale Database-dependent identification of proteins by mass spectrometry is well established, but has limitations when there are novel proteins, mutations, splice variants, and post-translational modifications (PTMs) not available in the established reference database. De novo sequencing as a database-independent approach could address these limitations by deducing peptide sequences directly from experimental tandem mass spectrometry spectra, while concomitantly yielding residue-by-residue confidence metrics. Methods Equal amounts of bovine serum albumin (BSA) sample aliquots were digested separately with Lys-C and Lys-N complementary peptidases, separated by reversed-phase ultra-high-performance liquid chromatography (UPLC), and analyzed by collision-induced dissociation (CID)-based mass spectrometry on an Orbitrap mass spectrometer. In the Lys-Sequencer algorithm, matched tandem mass spectra with equal precursor ion mass from complementary digestions were paired, and fragment ion types were identified based on the unique mass relationship between fragment ions extracted from a spectrum pair followed by de novo sequencing of peptides with identification confidence assigned at the residue level. Results In all the matched spectrum pairs, 34 top-ranked BSA peptides were identified, from which 391 amino acid residues were identified correctly, covering ~67% of the full sequence of BSA (583 residues) with only ~6% (35 residues) exhibiting ambiguity in the sequence order (although amino acid compositions were still correctly assigned). Of note, this approach identified peptide sequences up to 17 amino acids in length without ambiguity, with the exception of the N-terminal or C-terminal peptides containing lysine (18-mer). Conclusions The algorithm ("Lys-Sequencer") developed in this work achieves high precision for de novo sequencing of peptides. This method facilitates the identification of point mutation and new PTMs in the protein characterization and discovery of new peptides and proteins with varying levels of confidence.','https://analyticalsciencejournals.onlinelibrary.wiley.com/doi/10.1002/rcm.8574','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(317,'The impact of noise and missing fragmentation cleavages on de novo peptide identification algorithms','2022-03-23','10.1016/j.csbj.2022.03.008','American Association for the Advancement of Science (AAAS)','Proteomics aims to characterise system-wide protein expression and typically relies on mass-spectrometry and peptide fragmentation, followed by a database search for protein identification. It has wide ranging applications from clinical to environmental settings and virtually impacts on every area of biology. In that context, de novo peptide sequencing is becoming increasingly popular. Historically its performance lagged behind database search methods but with the integration of machine learning, this field of research is gaining momentum. To enable de novo peptide sequencing to realise its full potential, it is critical to explore the mass spectrometry data underpinning peptide identification. In this research we investigate the characteristics of tandem mass spectra using 8 published datasets. We then evaluate two state of the art de novo peptide sequencing algorithms, Novor and DeepNovo, with a particular focus on their performance with regard to missing fragmentation cleavage sites and noise. DeepNovo was found to perform better than Novor overall. However, Novor recalled more correct amino acids when 6 or more cleavage sites were missing. Furthermore, less than 11% of each algorithms'' correct peptide predictions emanate from data with more than one missing cleavage site, highlighting the issues missing cleavages pose. We further investigate how the algorithms manage to correctly identify peptides with many of these missing fragmentation cleavages. We show how noise negatively impacts the performance of both algorithms, when high intensity peaks are considered. Finally, we provide recommendations regarding further algorithms'' improvements and offer potential avenues to overcome current inherent data limitations.','https://www.sciencedirect.com/science/article/pii/S2001037022000794','Computational and Structural Biotechnology Journal','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(318,'Algorithms for Peptide Identification from Mixture Tandem Mass Spectra','2015-09-01',NULL,'PhD thesis',NULL,'https://uwo.scholaris.ca/items/00880792-7b69-48b8-a358-59ae5f59e78c','','thesis',NULL,NULL);
INSERT INTO publication VALUES(319,'De novo sequencing, peptide composition analysis, and composition-based sequencing: A new strategy employing accurate mass determination by Fourier transform ion cyclotron resonance mass spectrometry','2004-05-01','10.1016/j.jasms.2004.01.007','American Chemical Society (ACS)','A new strategy is described for the determination of amino acid sequences of unknown peptides. Different from the well-known but often inefficient de novo sequencing approach, the new method is based on a two-step process. In the first step the amino acid composition of an unknown peptide is determined on the basis of accurate mass values of the peptide precursor ion and a small number of accurate fragment ion mass values, and, as in de novo sequencing, without employing protein database information or other pre-information. In the second step the sequence of the found amino acids of the peptide is determined by scoring the agreement between expected and observed fragment ion signals of the permuted sequences. It was found that the new approach is highly efficient if accurate mass values are available and that it easily outstrips common approaches of de novo sequencing being based on lower accuracies and detailed knowledge of fragmentation behavior. Simple permutation and calculation of all possible amino acid sequences, however, is only efficient if the composition is known or if possible compositions are at least reduced to a small list. The latter requires the highest possible instrumental mass accuracy, which is currently provided only by fourier transform ion cyclotron resonance mass spectrometry. The connection between mass accuracy and peptide composition variability is described and an example of peptide compositioning and composition-based sequencing is presented.','https://pubs.acs.org/doi/10.1016/j.jasms.2004.01.007','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(320,'Algorithm Development of de novo Peptide Sequencing Via Tandem Mass Spectrometry','2010-12-20','10.3724/sp.j.1206.2010.00226','China Science Publishing & Media Ltd.','High-throughput mass spectrometry-based proteomics is developing rapidly in recent years. A key and essential issue in proteomics data processing is to identify proteins via tandem mass spectra. De novo peptide sequencing approach is database independent, which is a distinct advantage compared to database searching approach, so it can be used to analyze the data of new organisms or unsequenced organisms. De novo peptide sequencing problem is briefly described at first, and then the state-of-the-art of this problem is introduced from different aspects, which include the strategies with their advantages and disadvantages, frequently used algorithms and tools, criteria for algorithm assessment, and frequently used datasets for algorithm comparison. At last, the characteristics of some algorithms are summarized and some possible improvements of de novo peptide sequencing algorithm design are proposed.','https://www.pibb.ac.cn/pibben/article/abstract/20100226','Progress in Biochemistry and Biophysics','peer-reviewed',NULL,NULL);
INSERT INTO publication VALUES(321,'ProbPS: A new model for peak selection based on quantifying the dependence of the existence of derivative peaks on primary ion intensity','2011-08-17','10.1186/1471-2105-12-346','Springer Science and Business Media LLC','Background The analysis of mass spectra suggests that the existence of derivative peaks is strongly dependent on the intensity of the primary peaks. Peak selection from tandem mass spectrum is used to filter out noise and contaminant peaks. It is widely accepted that a valid primary peak tends to have high intensity and is accompanied by derivative peaks, including isotopic peaks, neutral loss peaks, and complementary peaks. Existing models for peak selection ignore the dependence between the existence of the derivative peaks and the intensity of the primary peaks. Simple models for peak selection assume that these two attributes are independent; however, this assumption is contrary to real data and prone to error. Results In this paper, we present a statistical model to quantitatively measure the dependence of the derivative peak''s existence on the primary peak''s intensity. Here, we propose a statistical model, named ProbPS, to capture the dependence in a quantitative manner and describe a statistical model for peak selection. Our results show that the quantitative understanding can successfully guide the peak selection process. By comparing ProbPS with AuDeNS we demonstrate the advantages of our method in both filtering out noise peaks and in improving de novo identification. In addition, we present a tag identification approach based on our peak selection method. Our results, using a test data set, suggest that our tag identification method (876 correct tags in 1000 spectra) outperforms PepNovoTag (790 correct tags in 1000 spectra). Conclusions We have shown that ProbPS improves the accuracy of peak selection which further enhances the performance of de novo sequencing and tag identification. Thus, our model saves valuable computation time and improving the accuracy of the results.','https://bmcbioinformatics.biomedcentral.com/articles/10.1186/1471-2105-12-346','BMC Bioinformatics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(322,'Tandem Mass Spectrum Sequencing: An Alternative to Database Search Engines in Shotgun Proteomics','2016-12-15','10.1007/978-3-319-41448-5_10','Springer International Publishing','Protein identification via database searches has become the gold standard in mass spectrometry based shotgun proteomics. However, as the quality of tandem mass spectra improves, direct mass spectrum sequencing gains interest as a database-independent alternative. In this chapter, the general principle of this so-called de novo sequencing is introduced along with pitfalls and challenges of the technique. The main tools available are presented with a focus on user friendly open source software which can be directly applied in everyday proteomic workflows.','https://link.springer.com/chapter/10.1007/978-3-319-41448-5_10','Advances in Experimental Medicine and Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(323,'Protein identification by spectral networks analysis','2007-04-10','10.1073/pnas.0701130104','National Academy of Sciences','Advances in tandem mass spectrometry (MS/MS) steadily increase the rate of generation of MS/MS spectra. As a result, the existing approaches that compare spectra against databases are already facing a bottleneck, particularly when interpreting spectra of modified peptides. Here we explore a concept that allows one to perform an MS/MS database search without ever comparing a spectrum against a database. We propose to take advantage of spectral pairs, which are pairs of spectra obtained from overlapping (often nontryptic) peptides or from unmodified and modified versions of the same peptide. Having a spectrum of a modified peptide paired with a spectrum of an unmodified peptide allows one to separate the prefix and suffix ladders, to greatly reduce the number of noise peaks, and to generate a small number of peptide reconstructions that are likely to contain the correct one. The MS/MS database search is thus reduced to extremely fast pattern-matching (rather than time-consuming matching of spectra against databases). In addition to speed, our approach provides a unique paradigm for identifying posttranslational modifications by means of spectral networks analysis.','https://www.pnas.org/doi/10.1073/pnas.0701130104','Proceedings of the National Academy of Sciences','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(324,'Tutorial on de novo peptide sequencing using MS/MS mass spectrometry','2012-12-01','10.1142/s0219720012310026','World Scientific Pub Co Pte Lt','This paper is a self-contained introductory tutorial on the problem in proteomics known as peptide sequencing using tandem mass spectrometry. This tutorial deals specifically with de novo sequencing methods (as opposed to database search methods). We first give an introduction to peptide sequencing, its importance and history and some background on proteins. Next we show the relationship between a peptide and the final spectrum produced from a tandem mass spectrometer, together with a description of the various sources of complications that arise during the process of generating the mass spectrum. From there we model the computational problem of de novo peptide sequencing, which is basically the reverse problem of identifying the peptide which produced the spectrum. We then present several major approaches to solve it (including reviewing some of the current algorithms in each approach), and also discuss related problems and post-processing approaches.','https://www.worldscientific.com/doi/10.1142/S0219720012310026','Journal of Bioinformatics and Computational Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(325,'Cumulating MS Signal enables polyclonal antibody analysis','2025-04-05','10.1101/2025.03.31.645874','Cold Spring Harbor Laboratory','Unraveling the complexities of protein systems via Mass Spectrometry (MS), particularly polyclonal antibodies, demands innovative analytical strategies. Here, we introduce the cumulative MS score (cMS), a novel mathematical framework that transcends traditional spectrum-matching, integrating MS evidence across multiple sample injections to achieve robust de novo peptide sequencing annotation. This approach, shifting from isolated spectrum analysis to a holistic MS signal-based methodology, was rigorously evaluated and validated across diverse sample types and experimental conditions. We applied this framework to characterize a complex polyclonal antibody mixture of Streptococcus pyogenes M1 protein binders derived from intravenous immunoglobulin (IVIG), revealing predominant variable heavy (VH) and light (VL) chain subgroups consistent with established genetic studies. Furthermore, we successfully identified conserved complementarity-determining region (CDR) features and predicted stable antibody-antigen interactions through molecular dynamics simulations, demonstrating the method’s potential for dissecting intricate antibody responses. This work establishes a powerful alternative to conventional tandem mass spectrometry MS/MS data analysis, enabling deeper insights into protein systems and paving the way for targeted therapeutic development.','https://www.biorxiv.org/content/10.1101/2025.03.31.645874','bioRxiv','preprint',NULL,'crossref');
INSERT INTO publication VALUES(326,'Do-It-Yourself De Novo Antibody Sequencing Workflow that Achieves Complete Accuracy of the Variable Regions','2025-06-06','10.1021/acs.jproteome.5c00210','American Chemical Society (ACS)','Antibodies are widely used as research tools or therapeutic agents. Knowing the sequences of the variable regions of an antibody─both the heavy chain and the light chain─is a prerequisite for the production of recombinant antibodies. Mass spectrometry-based de novo sequencing is a frequently used, and sometimes the only approach to gaining this information. Here, we describe a workflow that enables accurate sequence determination of monoclonal antibodies based on mass spectrometry data and freely available software tools. This workflow, which we developed using a homemade anti-FLAG monoclonal antibody as a reference sample, achieved 100% accuracy of the variable regions with clear distinction between leucine (L) and isoleucine (I). Using this workflow, we successfully decoded a monoclonal anti-HA antibody, for which we had no prior knowledge of its sequence. Based on the de novo sequencing result, we generated a recombinant anti-HA antibody, and demonstrated that it has the same specificity, sensitivity, and affinity as the commercial antibody.','https://pubs.acs.org/doi/10.1021/acs.jproteome.5c00210','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(327,'Role of Accurate Mass Measurement (±10 ppm) in Protein Identification Strategies Employing MS or MS/MS and Database Searching','1999-07-01','10.1021/ac9810516','American Chemical Society (ACS)','We describe the impact of advances in mass measurement accuracy, +/- 10 ppm (internally calibrated), on protein identification experiments. This capability was brought about by delayed extraction techniques used in conjunction with matrix-assisted laser desorption ionization (MALDI) on a reflectron time-of-flight (TOF) mass spectrometer. This work explores the advantage of using accurate mass measurement (and thus constraint on the possible elemental composition of components in a protein digest) in strategies for searching protein, gene, and EST databases that employ (a) mass values alone, (b) fragment-ion tagging derived from MS/MS spectra, and (c) de novo interpretation of MS/MS spectra. Significant improvement in the discriminating power of database searches has been found using only molecular weight values (i.e., measured mass) of > 10 peptide masses. When MALDI-TOF instruments are able to achieve the +/- 0.5-5 ppm mass accuracy necessary to distinguish peptide elemental compositions, it is possible to match homologous proteins having > 70% sequence identity to the protein being analyzed. The combination of a +/- 10 ppm measured parent mass of a single tryptic peptide and the near-complete amino acid (AA) composition information from immonium ions generated by MS/MS is capable of tagging a peptide in a database because only a few sequence permutations > 11 AA''s in length for an AA composition can ever be found in a proteome. De novo interpretation of peptide MS/MS spectra may be accomplished by altering our MS-Tag program to replace an entire database with calculation of only the sequence permutations possible from the accurate parent mass and immonium ion limited AA compositions. A hybrid strategy is employed using de novo MS/MS interpretation followed by text-based sequence similarity searching of a database.','https://pubs.acs.org/doi/10.1021/ac9810516','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(328,'De Novo Sequencing Methods in Proteomics','2009-12-05','10.1007/978-1-60761-444-9_8','Humana Press','The review describes methods of de novo sequencing of peptides by mass spectrometry. De novo methods utilize computational approaches to deduce the sequence or partial sequence of peptides directly from the experimental MS/MS spectra. The concepts behind a number of de novo sequencing methods are discussed. The other approach to identify peptides by tandem mass spectrometry is to match the fragment ions with virtual peptide ions generated from a genomic or protein database. De novo methods are essential to identify proteins when the genomes are not known but they are also extremely useful even when the genomes are known since they are not affected by errors in a search database. Another advantage of de novo methods is that the partial sequence can be used to search for posttranslation modifications or for the identification of mutations by homology based software.','https://link.springer.com/protocol/10.1007/978-1-60761-444-9_8','Methods in Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(329,'A Ranking-Based Scoring Function for Peptide-Spectrum Matches','2009-05-01','10.1021/pr800678b','American Chemical Society (ACS)','The analysis of the large volume of tandem mass spectrometry (MS/MS) proteomics data that is generated these days relies on automated algorithms that identify peptides from their mass spectra. An essential component of these algorithms is the scoring function used to evaluate the quality of peptide-spectrum matches (PSMs). In this paper, we present new approach to scoring of PSMs. We argue that since this problem is at its core a ranking task (especially in the case of de novo sequencing), it can be solved effectively using machine learning ranking algorithms. We developed a new discriminative boosting-based approach to scoring. Our scoring models draw upon a large set of diverse feature functions that measure different qualities of PSMs. Our method improves the performance of our de novo sequencing algorithm beyond the current state-of-the-art, and also greatly enhances the performance of database search programs. Furthermore, by increasing the efficiency of tag filtration and improving the sensitivity of PSM scoring, we make it practical to perform large-scale MS/MS analysis, such as proteogenomic search of a six-frame translation of the human genome (in which we achieve a reduction of the running time by a factor of 15 and a 60% increase in the number of identified peptides, compared to the InsPecT database search tool). Our scoring function is incorporated into PepNovo+ which is available for download or can be run online at http://bix.ucsd.edu.','https://pubs.acs.org/doi/10.1021/pr800678b','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(330,'Automated protein (re)sequencing with MS/MS and a homologous database yields almost full coverage and accuracy','2009-09-01','10.1093/bioinformatics/btp366','Oxford University Press (OUP)','Motivation The bottom-up tandem mass spectrometry (MS/MS) is regularly used in proteomics nowadays for identifying proteins from a sequence database. De novo sequencing software is also available for sequencing novel peptides with relatively short sequence lengths. However, automated sequencing of novel proteins from MS/MS remains a challenging problem. Results Very often, although the target protein is novel, it has a homologous protein included in a known database. When this happens, we propose a novel algorithm and automated software tool, named Champs, for sequencing the complete protein from MS/MS data of a few enzymatic digestions of the purified protein. Validation with two standard proteins showed that our automated method yields >99% sequence coverage and 100% sequence accuracy on these two proteins. Our method is useful to sequence novel proteins or ''re-sequence'' a protein that has mutations comparing with the database protein sequence.','https://academic.oup.com/bioinformatics/article/25/17/2174/211002','Bioinformatics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(331,'De Novo Sequencing of Peptides from Top-Down Tandem Mass Spectra','2015-11-06','10.1021/pr501244v','American Chemical Society (ACS)','De novo sequencing of proteins and peptides is one of the most important problems in mass spectrometry-driven proteomics. A variety of methods have been developed to accomplish this task from a set of bottom-up tandem (MS/MS) mass spectra. However, a more recently emerged top-down technology, now gaining more and more popularity, opens new perspectives for protein analysis and characterization, implying a need for efficient algorithms to process this kind of MS/MS data. Here, we describe a method that allows for the retrieval, from a set of top-down MS/MS spectra, of long and accurate sequence fragments of the proteins contained in the sample. To this end, we outline a strategy for generating high-quality sequence tags from top-down spectra, and introduce the concept of a T-Bruijn graph by adapting to the case of tags the notion of an A-Bruijn graph widely used in genomics. The output of the proposed approach represents the set of amino acid strings spelled out by optimal paths in the connected components of a T-Bruijn graph. We illustrate its performance on top-down data sets acquired from carbonic anhydrase 2 (CAH2) and the Fab region of alemtuzumab.','https://pubs.acs.org/doi/10.1021/pr501244v','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(332,'A Handle on Mass Coincidence Errors in De Novo Sequencing of Antibodies by Bottom-up Proteomics','2024-08-02','10.1021/acs.jproteome.4c00188','American Chemical Society (ACS)','Antibody sequences can be determined at 99% accuracy directly from the polypeptide product by using bottom-up proteomics techniques. Sequencing accuracy at the peptide level is limited by the isobaric residues leucine and isoleucine, incomplete fragmentation spectra in which the order of two or more residues remains ambiguous due to lacking fragment ions for the intermediate positions, and isobaric combinations of amino acids, of potentially different lengths, for example, GG = N and GA = Q. Here, we present several updates to Stitch (v1.5), which performs template-based assembly of de novo peptides to reconstruct antibody sequences. This version introduces a mass-based alignment algorithm that explicitly accounts for mass coincidence errors. In addition, it incorporates a postprocessing procedure to assign I/L residues based on secondary fragments (satellite ions, i.e. , w- ions). Moreover, evidence for sequence assignments can now be directly evaluated with the addition of an integrated spectrum viewer. Lastly, input data from a wider selection of de novo peptide sequencing algorithms are allowed, now including Casanovo, PEAKS, Novor.Cloud, pNovo, and MaxNovo, in addition to flat text and FASTA. Combined, these changes make Stitch compatible with a larger range of data processing pipelines and improve its tolerance to peptide-level sequencing errors.','https://pubs.acs.org/doi/10.1021/acs.jproteome.4c00188','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(333,'Peptide de Novo Sequencing Using 157 nm Photodissociation in a Tandem Time-of-Flight Mass Spectrometer','2010-02-01','10.1021/ac902050y','American Chemical Society (ACS)','It has previously been shown that photodissociation of tryptic peptide ions with 157 nm light in a matrix-assisted laser desorption/ionization (MALDI) tandem time-of-flight (TOF) mass spectrometer generates an abundance of x-type ions. A peptide de novo sequencing algorithm has now been developed to interpret these data. By combination of photodissociation and postsource decay (PSD) spectra, the algorithm identifies x-type ions and derives peptide sequences. The confidence of amino acid assignments is evaluated by observing complementary y-, v-, and w-type ions that provide additional constraints to sequence identification. In the analysis of 31 tryptic peptides from 4 model proteins, the algorithm identified 322 (or 90.7%) of the 355 amino acids and made only 3 incorrect assignments. The other 30 amino acids were not identified because specific needed x-type ions were not detected. Based on the observation of v- and w-type ions, 45 of 50 detected leucine and isoleucine residues were successfully distinguished and there was only one mistake. The remaining four residues were not distinguished because the corresponding v- and w-type ions were not detected. These de novo sequencing results translated into successful identification of proteins through homology searches. To evaluate the robustness of the present sequencing approach, a collection of 266 tryptic peptides from 23 model proteins were analyzed and then sequenced. A total of 167 peptides yielded sequence tags of 5 or more residues. In 5 peptides, 1 or 2 residues were incorrectly assigned.','https://pubs.acs.org/doi/10.1021/ac902050y','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(334,'De Novo Sequencing of Peptides Using Selective 351 nm Ultraviolet Photodissociation Mass Spectrometry','2013-10-15','10.1021/ac402309h','American Chemical Society (ACS)','Although in silico database search methods remain more popular for shotgun proteomics methods, de novo sequencing offers the ability to identify peptides derived from proteins lacking sequenced genomes and ones with subtle splice variants or truncations. Ultraviolet photodissociation (UVPD) of peptides derivatized by selective attachment of a chromophore at the N-terminus generates a characteristic series of y ions. The UVPD spectra of the chromophore-labeled peptides are simplified and thus amenable to de novo sequencing. This method resulted in an observed sequence coverage of 79% for cytochrome C (eight peptides), 47% for β-lactoglobulin (five peptides), 25% for carbonic anhydrase (six peptides), and 51% for bovine serum albumin (33 peptides). This strategy also allowed differentiation of proteins with high sequence homology as evidenced by de novo sequencing of two variants of green fluorescent protein.','https://pubs.acs.org/doi/10.1021/ac402309h','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(335,'MultiTag: Multiple Error-Tolerant Sequence Tag Search for the Sequence-Similarity Identification of Proteins by Mass Spectrometry','2003-03-01','10.1021/ac026199a','American Chemical Society (ACS)','The characterization of proteomes by mass spectrometry is largely limited to organisms with sequenced genomes. To identify proteins from organisms with unsequenced genomes, database sequences from related species must be employed for sequence-similarity protein identifications. Peptide sequence tags (Mann, 1994) have been used successfully for the identification of proteins in sequence databases using partially interpreted tandem mass spectra of tryptic peptides. We have extended the ability of sequence tag searching to the identification of proteins whose sequences are yet unknown but are homologous to known database entries. The MultiTag method presented here assigns statistical significance to matches of multiple error-tolerant sequence tags to a database entry and ranks alignments by their significance. The MultiTag approach has the distinct advantage over other sequence-similarity approaches of being able to perform sequence-similarity identifications using only very short (2-4) amino acid residue stretches of peptide sequences, rather than complete peptide sequences deduced by de novo interpretation of tandem mass spectra. This feature facilitates the identification of low abundance proteins, since noisy and low-intensity tandem mass spectra can be utilized.','https://pubs.acs.org/doi/10.1021/ac026199a','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(336,'Complexity and scoring function of MS/MS peptide de novo sequencing','2006-07-01','10.1142/9781860947575_0043','World Scientific Pub Co Pte Lt','Tandem mass spectrometry (MS/MS) has become a standard way for identifying peptides and proteins. A scoring function plays an important role in the MS/MS data analysis. De novo sequencing is the computational step to derive a peptide sequence from an MS/MS spectrum, normally by constructing the peptide that maximizes the scoring function. A number of polynomial time algorithms have been developed based on scoring functions that consider only either the N-terminal or C-terminal fragment ions of the peptide. It remains unknown whether the consideration of the internal fragment ions will still be polynomial time solvable. In this paper, we prove that the internal fragment ions make the de novo sequencing problem NP-complete. We also propose a regression model based scoring method to incorporate correlations between the fragment ions. Our scoring function is combined with PEAKS de novo sequencing algorithm and tested on ion trap data. The experimental results show that the regression model based scoring method can remarkably improve the de novo sequencing accuracy.','https://www.worldscientific.com/doi/10.1142/9781860947575_0043','Computational Systems Bioinformatics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(337,'TVNovo: De novo peptide sequencing for high resolution LTQ-FT mass spectrometry using virtual database searching','2010-10-01','10.1109/bmei.2010.5639865','Institute of Electrical and Electronics Engineers (IEEE)','De novo peptide sequencing is one of the most challenging topics in the field of computational proteomics. In this manuscript, a novel method based on virtual database searching is presented to improve the performance of de novo sequencing for the data from high resolution LTQ-FT mass spectrometry. Our method directly generates a virtual database from each spectrum and applies a search engine to match spectrum against the calculated virtual database. Two datasets from different sources are employed to compare our method to other existing de novo sequencing algorithms and the results show that our method outperforms other methods.','https://ieeexplore.ieee.org/document/5639865','2010 3rd International Conference on Biomedical Engineering and Informatics','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(338,'Neutron-encoded Signatures Enable Product Ion Annotation From Tandem Mass Spectra','2013-12-01','10.1074/mcp.m113.028951','Elsevier BV','We report the use of neutron-encoded (NeuCode) stable isotope labeling of amino acids in cell culture for the purpose of C-terminal product ion annotation. Two NeuCode labeling isotopologues of lysine, (13)C6(15)N2 and (2)H8, which differ by 36 mDa, were metabolically embedded in a sample proteome, and the resultant labeled proteins were combined, digested, and analyzed via liquid chromatography and mass spectrometry. With MS/MS scan resolving powers of ~50,000 or higher, product ions containing the C terminus (i.e. lysine) appear as a doublet spaced by exactly 36 mDa, whereas N-terminal fragments exist as a single m/z peak. Through theory and experiment, we demonstrate that over 90% of all y-type product ions have detectable doublets. We report on an algorithm that can extract these neutron signatures with high sensitivity and specificity. In other words, of 15,503 y-type product ion peaks, the y-type ion identification algorithm correctly identified 14,552 (93.2%) based on detection of the NeuCode doublet; 6.8% were misclassified (i.e. other ion types that were assigned as y-type products). Searching NeuCode labeled yeast with PepNovo(+) resulted in a 34% increase in correct de novo identifications relative to searching through MS/MS only. We use this tool to simplify spectra prior to database searching, to sort unmatched tandem mass spectra for spectral richness, for correlation of co-fragmented ions to their parent precursor, and for de novo sequence identification.','https://www.mcponline.org/article/S1535-9476(20)33188-0/fulltext','Molecular & Cellular Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(339,'Evolutionary Algorithms for Improving De Novo Peptide Sequencing','2020-01-01','10.26686/wgtn.17145581.v1','PhD thesis','De novo peptide sequencing algorithms have been developed for peptide identification in proteomics from tandem mass spectra (MS/MS), which can be used to identify and discover novel peptides and proteins that do not have a database available. Despite improvements in MS instrumentation and de novo sequencing methods, a significant number of CID MS/MS spectra still remain unassigned with the current algorithms, often leading to low confidence of peptide assignments to the spectra. Moreover, current algorithms often fail to construct the completely matched sequences, and produce partial matches. Therefore, identification of full-length peptides remains challenging. Another major challenge is the existence of noise in MS/MS spectra which makes the data highly imbalanced. Also missing peaks, caused by incomplete MS fragmentation makes it more difficult to infer a full-length peptide sequence. In addition, the large search space of all possible amino acid sequences for each spectrum leads to a high false discovery rate. This thesis focuses on improving the performance of current methods by developing new algorithms corresponding to three steps of preprocessing, sequence optimisation and post-processing using machine learning for more comprehensive interrogation of MS/MS datasets. From the machine learning point of view, the three steps can be addressed by solving different tasks such as classification, optimisation, and symbolic regression. Since Evolutionary Algorithms (EAs), as effective global search techniques, have shown promising results in solving these problems, this thesis investigates the capability of EAs in improving the de novo peptide sequencing. In the preprocessing step, this thesis proposes an effective GP-based method for classification of signal and noise peaks in highly imbalanced MS/MS spectra with the purpose of having a positive influence on the reliability of the peptide identification. The results show that the proposed algorithm is the most stable classification method across various noise ratios, outperforming six other benchmark classification algorithms. The experimental results show a significant improvement in high confidence peptide assignments to MS/MS spectra when the data is preprocessed by the proposed GP method. Moreover, the first multi-objective GP approach for classification of peaks in MS/MS data, aiming at maximising the accuracy of the minority class (signal peaks) and the accuracy of the majority class (noise peaks) is also proposed in this thesis. The results show that the multi-objective GP method outperforms the single objective GP algorithm and a popular multi-objective approach in terms of retaining more signal peaks and removing more noise peaks. The multi-objective GP approach significantly improved the reliability of peptide identification. This thesis proposes a GA-based method to solve the complex optimisation task of de novo peptide sequencing, aiming at constructing full-length sequences. The proposed GA method benefits the GA capability of searching a large search space of potential amino acid sequences to find the most likely full-length sequence. The experimental results show that the proposed method outperforms the most commonly used de novo sequencing method at both amino acid level and peptide level. This thesis also proposes a novel method for re-scoring and re-ranking the peptide spectrum matches (PSMs) from the result of de novo peptide sequencing, aiming at minimising the false discovery rate as a post-processing approach. The proposed GP method evolves the computer programs to perform regression and classification simultaneously in order to generate an effective scoring function for finding the correct PSMs from many incorrect ones. The results show that the new GP-based PSM scoring function significantly improves the identification of full-length peptides when it is used to post-process the de novo sequencing results.','https://openaccess.wgtn.ac.nz/articles/thesis/Evolutionary_Algorithms_for_Improving_De_Novo_Peptide_Sequencing/17145581','','thesis',NULL,'openalex');
INSERT INTO publication VALUES(340,'The Current State-of-the-Art Identification of Unknown Proteins Using Mass Spectrometry Exemplified on De Novo Sequencing of a Venom Protease from Bothrops moojeni','2022-08-05','10.3390/molecules27154976','MDPI AG','(1) Background: The amino acid sequence elucidation of peptides from the gas phase fragmentation mass spectra, de novo sequencing, is a valuable method for the identification of unknown proteins complementary to Edman sequencing. It is increasingly used in shot-gun mass spectrometry (MS)-based proteomics experiments. We review the current state-of-the-art and use the identification of an unknown snake venom protein targeting the human tissue factor (TF) as an example to describe the analysis process based on manual spectrum interrogation. (2) Methods: The immobilized TF was incubated with a crude B. moojeni venom solution. The potential binding partners were eluted and further purified by gel electrophoresis. Edman degradation was performed to elucidate the N-terminus of the 31 kDa protein of interest. High-resolution MS with collision-induced dissociation was employed to generate peptide fragmentation spectra. Sequence tags were deduced and used for searches in the NCBI and Uniprot databases. Protein matches from the snake species were further validated by target MS/MS. (3) Results: Sequence tag D [K/Q] D [I/L] VDD [K/Q] led to a snake venom serine protease (SVSP) from lancehead B. jararaca (P81824). With target MS/MS, 24% of the SVSP sequence were confirmed; an additional 41% were tentatively assigned by data-independent MS. Edman sequencing provided information for 10 N-terminal amino acid residues, also confirming the match to SVSP. (4) Conclusions: The identification of unknown proteins continues to be a challenge despite major advances in MS instrumentation and bioinformatic tools. The main requirement is the generation of meaningful, high-quality MS peptide fragmentation spectra. These are used to elucidate sufficiently long sequence tags, which can subsequently be submitted to searches in protein databases. This basic method does not require extensive bioinformatics because peptide MS/MS spectra, especially of doubly-charged ions, can be analysed manually. We demonstrated the procedure with the elucidation of SVSP. While de novo sequencing quickly indicates the correct protein group, the validation of the entire protein sequence of amino acid-by-amino acid will take time. Reasons are the need to properly assign isobaric amino acid residues and modifications. With the ongoing efforts in genomics and transcriptomics and the availability of ever more data in public databases, the need for de novo MS sequencing will decrease. Still, not every animal and plant species will be sequenced, so the combination of MS and Edman sequencing will continue to be of importance for the identification of unknown proteins.','https://www.mdpi.com/1420-3049/27/15/4976','Molecules','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(341,'Benchmarking the identification of a single degraded protein to explore optimal search strategies for ancient proteins','2023-12-15','10.1101/2023.12.15.571577','Cold Spring Harbor Laboratory','Palaeoproteomics is a rapidly evolving discipline, and practitioners are constantly developing novel strategies for the analyses and interpretations of complex, degraded protein mixtures. The community has also established standards of good practice to interrogate our data. However, there is a lack of a systematic exploration of how these affect the identification of peptides, post-translational modifications (PTMs), proteins and their significance (through the False Discovery Rate) and correctness. We systematically investigated the performance of a wide range of sequencing tools and search engines in a controlled system: the experimental degradation of the single purified bovine β-lactoglobulin (BLG), heated at 95 °C and pH 7 for 0, 4 and 128 days. We target BLG since it is one of the most robust and ubiquitous proteins in the archaeological record. We tested different reference database choices, a targeted dairy protein one, and the whole bovine proteome and the three digestion options (tryptic-, semi-tryptic- and non-specific searches), in order to evaluate the effects of search space and the identification of peptides. We also explored alternative strategies, including open search that allows for the global identification of PTMs based upon wide precursor mass tolerance and de novo sequencing to boost sequence coverage. We analysed the samples using Mascot, MaxQuant, Metamorpheus, pFind, Fragpipe and DeNovoGUI (pepNovo+, DirecTag, Novor), benchmarked these tools and discuss the optimal strategy for the characterisation of ancient proteins. We also studied physicochemical properties of the BLG that correlate with bias in the identification coverage.','https://www.biorxiv.org/content/10.1101/2023.12.15.571577','bioRxiv','preprint',NULL,'crossref');
INSERT INTO publication VALUES(342,'Benchmarking the identification of a single degraded protein to explore optimal search strategies for ancient proteins','2024-11-21','10.24072/pcjournal.491','Peer Community In','Palaeoproteomics is a rapidly evolving discipline, and practitioners are constantly developing novel strategies for the analyses and interpretations of complex, degraded protein mixtures. The community has also established standards of good practice to interrogate our data. However, there is a lack of a systematic exploration of how these affect the identification of peptides, post-translational modifications (PTMs), proteins and their significance (through the False Discovery Rate) and correctness. We systematically investigated the performance of a wide range of sequencing tools and search engines in a controlled system: the experimental degradation of the single purified bovine β-lactoglobulin (BLG), heated at 95°C and pH 7 for 0, 4 and 128 days. We target BLG since it is one of the most robust and ubiquitous proteins in the archaeological record. We tested different reference database choices, a targeted dairy protein one, and the whole bovine proteome and the three digestion options (tryptic-, semi-tryptic- and non-specific searches), in order to evaluate the effects of search space and the identification of peptides. We also explored alternative strategies, including open search that allows for the global identification of PTMs based upon wide precursor mass tolerance and de novo sequencing to boost sequence coverage. We analysed the samples using Mascot, MaxQuant, Metamorpheus, pFind, Fragpipe and DeNovoGUI (pepNovo+, DirecTag, Novor), benchmarked these tools and discuss the optimal strategy for the characterisation of ancient proteins. We also studied physicochemical properties of the BLG that correlate with bias in the identification coverage.','https://peercommunityjournal.org/articles/10.24072/pcjournal.491/','Peer Community Journal','peer-reviewed',NULL,'crossref');
INSERT INTO publication VALUES(343,'A better scoring model for de novo peptide sequencing: the symmetric difference between explained and measured masses','2017-05-11','10.1186/s13015-017-0104-1','Springer Science and Business Media LLC','Background Given a peptide as a string of amino acids, the masses of all its prefixes and suffixes can be found by a trivial linear scan through the amino acid masses. The inverse problem is the ideal de novo peptide sequencing problem : Given all prefix and suffix masses, determine the string of amino acids. In biological reality, the given masses are measured in a lab experiment, and measurements by necessity are noisy. The (real, noisy) de novo peptide sequencing problem therefore has a noisy input: a few of the prefix and suffix masses of the peptide are missing and a few other masses are given in addition. For this setting, we ask for an amino acid string that explains the given masses as accurately as possible. Results Past approaches interpreted accuracy by searching for a string that explains as many masses as possible. We feel, however, that it is not only bad to not explain a mass that appears, but also to explain a mass that does not appear. We propose to minimize the symmetric difference between the set of given masses and the set of masses that the string explains. For this new optimization problem, we propose an efficient algorithm that computes both the best and the k best solutions. Proof-of-concept experiments on measurements of synthesized peptides show that our approach leads to better results compared to finding a string that explains as many given masses as possible. Conclusions We conclude that considering the symmetric difference as optimization goal can improve the identification rates for de novo peptide sequencing. A preliminary version of this work has been presented at WABI 2016.','https://link.springer.com/article/10.1186/s13015-017-0104-1','Algorithms for Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(344,'Improved de novo peptide sequencing using LC retention time information','2018-08-29','10.1186/s13015-018-0132-5','Springer Science and Business Media LLC','Background Liquid chromatography combined with tandem mass spectrometry is an important tool in proteomics for peptide identification. Liquid chromatography temporally separates the peptides in a sample. The peptides that elute one after another are analyzed via tandem mass spectrometry by measuring the mass-to-charge ratio of a peptide and its fragments. De novo peptide sequencing is the problem of reconstructing the amino acid sequences of a peptide from this measurement data. Past de novo sequencing algorithms solely consider the mass spectrum of the fragments for reconstructing a sequence. Results We propose to additionally exploit the information obtained from liquid chromatography. We study the problem of computing a sequence that is not only in accordance with the experimental mass spectrum, but also with the chromatographic retention time. We consider three models for predicting the retention time and develop algorithms for de novo sequencing for each model. Conclusions Based on an evaluation for two prediction models on experimental data from synthesized peptides we conclude that the identification rates are improved by exploiting the chromatographic information. In our evaluation, we compare our algorithms using the retention time information with algorithms using the same scoring model, but not the retention time.','https://link.springer.com/article/10.1186/s13015-018-0132-5','Algorithms for Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(345,'SWPepNovo: An Efficient De Novo Peptide Sequencing Tool for Large-scale MS/MS Spectra Analysis','2019-07-03','10.7150/ijbs.32142','Ivyspring International Publisher','Tandem mass spectrometry (MS/MS)-based de novo peptide sequencing is a powerful method for high-throughput protein analysis. However, the explosively increasing size of MS/MS spectra dataset inevitably and exponentially raises the computational demand of existing de novo peptide sequencing methods, which is an issue urgently to be solved in computational biology. This paper introduces an efficient tool based on SW26010 many-core processor, namely SWPepNovo, to process the large-scale peptide MS/MS spectra using a parallel peptide spectrum matches (PSMs) algorithm. Our design employs a two-level parallelization mechanism: (1) the task-level parallelism between MPEs using MPI based on a data transformation method and a dynamic feedback task scheduling algorithm, (2) the thread-level parallelism across CPEs using asynchronous task transfer and multithreading. Moreover, three optimization strategies, including vectorization, double buffering and memory access optimizations, have been employed to overcome both the compute-bound and the memory-bound bottlenecks in the parallel PSMs algorithm. The results of experiments conducted on multiple spectra datasets demonstrate the performance of SWPepNovo against three state-of-the-art tools for peptide sequencing, including PepNovo+, PEAKS and DeepNovo-DIA. The SWPepNovo also shows high scalability in experiments on extremely large datasets sized up to 11.22 GB. The software and the parameter settings are available at https://github.com/ChuangLi99/SWPepNovo.','https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6743289/','International Journal of Biological Sciences','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(346,'A Framework for Database Search with AI Models in Mass Spectrometry-Based Proteomics','2026-05-01','10.1021/acs.jproteome.5c01153','American Chemical Society (ACS)','Database search remains the primary strategy for peptide detection in mass spectrometry-based proteomics, but growing data sets and increasingly expansive peptide search spaces now challenge its computational limits. At the same time, machine learning has transformed multiple aspects of spectrum identification and is increasingly applied directly to peptide-spectrum matching. Neural network models have been proposed as core engines for database search, yet the computational complexities of such approaches have not been systematically defined or compared. Here, we present a range of emerging approaches for database search and a theoretical framework for runtime and scaling in spectrum identification, contrasting classical search strategies with emerging neural network-based methods. We analyze asymptotic complexity in the number of spectra and peptide candidates and estimate practical wall time and memory requirements under realistic hardware assumptions. Our framework highlights trade-offs and provides a guide for selecting and developing scalable peptide search strategies in the era of large models and proteomics data sets. We therefore consider whether learned scoring models may progressively replace or augment classical similarity functions at the peptide-spectrum scoring level.','https://pubs.acs.org/doi/10.1021/acs.jproteome.5c01153','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(347,'From Identification to Insight: Making Full Use of the Diagnostic Potential of MS/MS Proteotyping in Clinical Microbiology Using Efficient Bioinformatics','2025-11-07','10.1021/acs.jproteome.5c00733','American Chemical Society (ACS)','Accurate and rapid pathogen identification is critical for modern diagnostics, driving the need for technologies that combine speed, specificity, and functional insight. In this context, mass spectrometry (MS)-based proteomics is rapidly emerging as a transformative approach in clinical microbiology, offering comprehensive characterization of microorganisms and direct identification of protein biomarkers relevant to infectious disease diagnostics. While MS1-based approaches such as MALDI-TOF Biotyper have revolutionized species-level microbial identification through rapid and cost-effective workflows, they remain fundamentally limited in resolving strain-level differences and in detecting antimicrobial resistance (AMR) determinants. In contrast, so-called proteotyping enables the identification of organisms and resistance-associated proteins based on peptide sequence information obtained by tandem mass spectrometry (MS/MS), most commonly using shotgun proteomics. However, the clinical utility of proteotyping depends on the availability of efficient and accurate bioinformatics tools capable of handling large databases, disambiguating shared peptide sequences, and providing taxonomic and functional assignments with clinical relevance. This perspective highlights the diagnostic potential of MS/MS proteotyping and argues that advances in bioinformatics pipelines are needed for moving from microbial identification to actionable clinical insight.','https://pubs.acs.org/doi/10.1021/acs.jproteome.5c00733','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(348,'Mass Spectrometry-Based Profiling of Personalized Immunopeptidomes in Thai Renal Cell Carcinoma','2026-09-04','10.1021/acs.jproteome.6c00141','American Chemical Society (ACS)','This study profiles the personalized immunopeptidomes of 13 Thai patients with renal cell carcinoma (RCC), addressing a critical knowledge gap in Southeast Asian populations characterized by distinct HLA allele distributions. We combined whole-exome sequencing (WES)-based personalized proteome construction with liquid chromatography-tandem mass spectrometry (LC-MS/MS), using both database-driven searches and de novo peptide sequencing. HLA typing identified several class I allotypes that are underrepresented in publicly available immunopeptidome resources, including seven alleles not previously represented in the databases examined; HLA-A*11:01 was the most frequent allele in this cohort. Database-based analysis identified a single tumor-specific neoantigen derived from a mutant JADE2 peptide in the patient with the highest tumor mutational burden, which was validated by a mutant-specific ELISPOT response. In contrast, de novo sequencing revealed numerous noncanonical peptides, a subset of which were supported by proteogenomic validation using PepQuery and detected exclusively in cancer proteomes but not in normal tissue data sets, indicating their potential as tumor-associated antigen candidates. Together, these results establish an integrated and scalable framework for identifying HLA-presented tumor-derived peptides and provide a foundational immunopeptidome resource to support personalized cancer immunotherapy development in Southeast Asia.','https://pubs.acs.org/doi/10.1021/acs.jproteome.6c00141','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(349,'Mass-Invariant Natural Log-Transformed Mass Spectra Enable Internal Calibration and De Novo Sequencing of Intact Proteins','2026-01-27','10.1021/acs.analchem.5c06165','American Chemical Society (ACS)','A key limitation of top-down proteomics is reliance on averagine-based deconvolution to estimate monoisotopic masses, which introduces systematic errors when isotope envelopes are distorted. We present a framework that bypasses averagine by operating directly in natural log-transformed m / z space, where charge-state spacing is mass-invariant and provides an intrinsic reference for internal calibration on both FT-ICR and Orbitrap analyzers. Isotopologue pairing in this domain supports de novo sequencing and discriminates near-isobaric residues. By shifting the paradigm from monoisotopic mass estimation to connectivity-driven inference, the approach offers resilience against distorted isotope envelopes and unknown PTMs, establishing a database-independent strategy for discovery-oriented proteoform characterization without known calibrants.','https://pubs.acs.org/doi/10.1021/acs.analchem.5c06165','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(350,'Precise Discovery of Novel N-Terminal Proteoforms beyond the Limitations of Proteogenomics and De Novo Sequencing','2025-08-12','10.1021/acs.analchem.5c02498','American Chemical Society (ACS)','Alternative splicing-mediated protein N-terminal sequence variation is closely associated with diseases, but its identification by mass spectrometry faces technical bottlenecks. Traditional proteogenomic methods cannot identify novel N-terminal proteins undetected in transcriptome data, while de novo sequencing has limitations in accuracy and traceability. To address this, we developed the first dedicated algorithm, NovelNSeq, which is specifically designed to parse signature peptides (novel N-terminal extension peptides) of novel N-terminal proteins from mass spectrometry data without relying on transcriptome data or de novo sequencing. NovelNSeq fully exploits peptide encoding rules, demonstrating significantly higher accuracy than de novo sequencing algorithms such as PEAKS, pNovo3, SpliceNovo, Casanovo, and InstaNovo, and enables tracing back the peptide encoding mechanisms. Using NovelNSeq, we identified and validated novel N-terminal proteoforms from human genes CALM2, CAPNS1, and CPNE7 in mass spectrometry data where large-scale proteogenomics failed to detect them, which establishes NovelNSeq as an essential complement to conventional approaches. Furthermore, we revealed that a recently reported AAG-initiated novel N-terminus in human ATP9A is actually generated through translational frameshifting from the canonical ATG start codon, highlighting the need for rigorous validation of noncanonical start codon annotations in novel N-terminal proteoforms.','https://pubs.acs.org/doi/10.1021/acs.analchem.5c02498','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(351,'High-accuracy glycan de novo prediction for N- and O-linked glycopeptides across multiple fragmentation techniques','2026-09-10','10.1038/s41467-026-77012-2','Springer Science and Business Media LLC','N- and O-glycosylation are structurally diverse post-translational modifications that affect a range of biological functions. Glycoproteomics faces substantial challenges, particularly in the analysis of O-glycans due to their diversity compared to that of N-glycans. In addition, tandem mass spectrometry data patterns exhibit variability between different fragmentation methods. Existing de novo algorithms often lack sensitivity and are limited to sceHCD fragmentation, restricting their practical application. To address these limitations, we introduce DeepGlycan, a deep-learning-based method for de novo glycopeptide sequencing that captures relationships between glycopeptide spectra and fragment ions from both N- and O-glycans. DeepGlycan achieves over 92% glycan recall and around 95% glycan precision on N-glycopeptide spectra generated using both sceHCD and EThcD. In addition, it enables O-glycan de novo sequencing without additional training. Beyond benchmarking, DeepGlycan identifies an O-glycopeptide in mouse heart tissue whose assignment is supported by exoglycosidase treatment and comparison with a synthetic standard.','https://www.nature.com/articles/s41467-026-77012-2','Nature Communications','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(352,'Universal Biological Sequence Reranking for Improved De Novo Peptide Sequencing','2025-05-23','10.48550/arXiv.2505.17552','arXiv','De novo peptide sequencing is a critical task in proteomics. However, the performance of current deep learning-based methods is limited by the inherent complexity of mass spectrometry data and the heterogeneous distribution of noise signals, leading to data-specific biases. We present RankNovo, the first deep reranking framework that enhances de novo peptide sequencing by leveraging the complementary strengths of multiple sequencing models. RankNovo employs a list-wise reranking approach, modeling candidate peptides as multiple sequence alignments and utilizing axial attention to extract informative features across candidates. Additionally, we introduce two new metrics, PMD (Peptide Mass Deviation) and RMD (residual Mass Deviation), which offer delicate supervision by quantifying mass differences between peptides at both the sequence and residue levels. Extensive experiments demonstrate that RankNovo not only surpasses its base models used to generate training candidates for reranking pre-training, but also sets a new state-of-the-art benchmark. Moreover, RankNovo exhibits strong zero-shot generalization to unseen models whose generations were not exposed during training, highlighting its robustness and potential as a universal reranking framework for peptide sequencing. Our work presents a novel reranking strategy that fundamentally challenges existing single-model paradigms and advances the frontier of accurate de novo sequencing. Our source code is provided on GitHub.','https://arxiv.org/abs/2505.17552','arXiv','postprint',NULL,'arxiv');
INSERT INTO publication VALUES(353,'π-MNovo improves de novo peptide sequencing through microbial-domain adaptation and evidence-guided candidate selection','2026-09-24','10.64898/2026.09.22.753549','Cold Spring Harbor Laboratory','The high taxonomic and strain-level diversity of microbial communities makes it difficult for reference databases to fully represent the protein sequences present in metaproteomic samples, limiting database-dependent peptide identification. De novo peptide sequencing can recover peptide sequences directly from tandem mass spectra without relying on reference databases, providing complementary peptide evidence for metaproteomics. However, most existing de novo sequencing models were developed largely from non-microbial proteomic data and lack specific adaptation to microbial spectra. Here, we established a dedicated microbial spectral resource comprising more than 10 million annotated high-quality tandem mass spectra from 72 cultured microbial isolates, with peptide digests from each isolate separated into five high-pH reversed-phase fractions to increase the opportunity for deeper and more diverse peptide sampling. Using this resource, we developed {pi}-MNovo, which combines adaptation to microbial spectra with evidence-guided candidate selection to improve full-length peptide sequencing precision. On a seven-species external benchmark, {pi}-MNovo achieved 66.30% complete-peptide recall under the same residue-mass-based complete-peptide matching criterion applied to all models, exceeding four published models by 6.9-21.7% in relative recall, with consistent gains across species and peptide-length groups. In two independent metaproteomic datasets, {pi}-MNovo increased reference-supported taxonomic coverage, while synthetic-community analysis recapitulated the designed abundance ranking. From pFind-unidentified spectra, {pi}-MNovo recovered 1,587 pFind-unreported, reference-matched peptides that passed spectrum-evidence filtering. These results show that {pi}-MNovo expands recoverable peptide evidence and enhances the utility of de novo sequencing for metaproteomic analysis.','https://www.biorxiv.org/content/10.64898/2026.09.22.753549v1','bioRxiv','preprint',NULL,'biorxiv');
INSERT INTO publication VALUES(354,'GyroNovo: Error-Guided Fragment Imputation with Mass-Aware Attention for De Novo Peptide Sequencing','2026-09-24','10.48550/arXiv.2609.30542','arXiv','De novo peptide sequencing from tandem mass spectra is essential for identifying peptides without relying on reference databases. Despite advances in deep learning, accurate sequencing remains challenging because experimental spectra are often sparse, noisy, and incomplete, leaving informative b- and y-ion fragments unobserved. Existing methods attempt to recover this missing evidence via latent-space imputation before autoregressive decoding. However, they typically treat imputation as a fixed reconstruction task, without considering which missing fragments are most relevant to decoder errors. Moreover, existing peak representations do not explicitly model mass differences between peaks, despite their fundamental importance. We introduce GyroNovo, a framework with two main contributions. First, we use decoder errors observed during training to adapt the imputation objective, prioritizing fragments associated with frequent decoding errors. We further use the decoder error distribution to construct easy and hard augmented views of each spectrum, enabling the decoder to learn under varying degrees of spectral corruption and missing-fragment severity. Second, we introduce a mass-aware inductive bias into self-attention by using rotary embeddings to encode pairwise mass differences between spectral peaks. Together, these components align missing-fragment recovery with decoder behavior while explicitly incorporating the mass relationships that underlie peptide fragmentation. At inference time, GyroNovo retains a standard encoder-imputer-decoder architecture and requires neither additional inputs nor auxiliary search procedures. Experiments on NovoBench show gains of about 9 percentage points in peptide-level precision and 7 percentage points in amino-acid-level precision over the state-of-the-art baseline. Code: https://github.com/UBC-NLP/gyronovo.','https://arxiv.org/abs/2609.30542','arXiv','preprint',NULL,'arxiv');
INSERT INTO publication VALUES(355,'Identification of Antimicrobial Peptides from HAN-J6 Hemp Seeds Using Mass Spectrometry and De Novo Peptide Sequencing','2026-09-24','10.13021/jssr2026.5545','George Mason University','Antimicrobial peptides (AMPs) extracted from natural sources, especially plants, have been shown to effectively inhibit microbes and are therefore promising alternatives to conventional antimicrobial agents. Hemp seeds (Cannabis sativa L.) have a high protein concentration and may serve as an abundant source of bioactive peptides. However, little is known about the presence and diversity of AMPs derived from hemp seed proteins. This study aimed to extract and identify AMPs from HAN-J6 strain hemp seeds using de novo peptide sequencing with mass spectrometry, an approach that has not yet been used to characterize hemp seed-derived AMPs. HAN-J6 strain hemp seed cakes were first defatted and then subjected to alkaline extraction and acid precipitation to extract proteins for mass spectrometry analysis. The protein sample then underwent protein precipitation, trypsin/Lys-C digestion, and ZipTip desalting prior to mass spectrometry analysis. Liquid chromatography-mass spectrometry (LC-MS), performed with two initial injections and one injection that utilized an exclusion list revealed 3,985 peptide sequences through analysis with PEAKS 12 software. Two prediction algorithms, CAMP R3 and AMP Scanner_V2, were used to screen the sequences; CAMP R3 predicted 56 AMPs, while AMP Scanner_V2 predicted 260 AMPs from de novo sequence compiled list (ALC 80% and above). Twenty-seven peptides were predicted to be AMPs by both algorithms, making them the most likely antimicrobial candidates for future testing. Our results support that hemp is a previously underexplored source of AMPs and could be valuable for pathogen-fighting applications in fields such as agriculture and pharmaceuticals.','https://journals.gmu.edu/jssr/article/view/5545','Journal of Student-Scientists'' Research','abstract',NULL,'openalex');
INSERT INTO publication VALUES(356,'Discovering Antimicrobial Peptides in Red-Legged Salamander Skin Secretions using De Novo Protein Sequencing','2026-09-24','10.13021/jssr2026.5544','George Mason University','Antibiotic resistance has emerged as a major global health challenge due to the overuse and misuse of antibiotics. Previous studies have investigated the antimicrobial properties of frogs and toads as potential sources of novel therapeutics for combating antibiotic-resistant bacteria. Salamanders, including the red-legged salamander examined in this study, produce antimicrobial skin secretions that protect them from harmful bacteria and fungi in their environment. However, comparatively little is known about the peptide composition of salamander skin secretions. In this study, proteins were extracted from red-legged salamander skin secretions and analyzed using nano liquid-chromatography mass spectrometry (nanoLC-MS/MS). Peptides were identified through de novo sequencing using PEAKS software, and putative antimicrobial peptides were predicted using antimicrobial peptide (AMP) prediction tools, including CAMP-R3 and AMP Scanner. Across four sample injections, 135 unique peptides were identified, of which 36 were predicted to possess antimicrobial activity. These candidate peptides represent promising targets for further investigation. Future studies will evaluate their antimicrobial activity against bacterial and fungal pathogens and assess their potential as lead compounds for the development of novel therapeutics to combat antibiotic-resistant infections.','https://journals.gmu.edu/jssr/article/view/5544','Journal of Student-Scientists'' Research','abstract',NULL,'openalex');
INSERT INTO publication VALUES(357,'Abstract 4402 De Novo Peptidomics and Bioprospecting Reveal Antimicrobial Peptide Candidates in Cryptobranchus alleganiensis (Hellbender) Skin Secretions','2026-05-01','10.1016/j.jbc.2026.112633','American Society for Biochemistry and Molecular Biology',NULL,'https://doi.org/10.1016/j.jbc.2026.112633','Journal of Biological Chemistry','abstract',NULL,NULL);
INSERT INTO publication VALUES(358,'Transformer Architectures for De Novo Peptide Sequencing and Peptide Property Prediction in LC–MS/MS Proteomics','2026-09-01','10.1016/j.ailsci.2026.100184','Elsevier BV','Transformer architectures are increasingly used to interpret peptide-centred liquid chromatography-tandem mass spectrometry (LC-MS/MS) data, yet reported gains remain difficult to compare because studies differ in tasks, training corpora, peptide-overlap controls, acquisition settings, metrics and deployment criteria. This scoping review mapped Transformer and Transformer-hybrid applications in de novo peptide sequencing and peptide property prediction, with attention to architecture, evaluation validity, determinants of performance, reproducibility and research-workflow readiness. PubMed/MEDLINE, Scopus and Web of Science Core Collection were searched for English-language studies published from January 2017 through June 2026. Of 439 records identified, 207 remained after deduplication, 49 full texts were assessed and 27 studies were included. Thirteen studies primarily addressed de novo sequencing, 12 addressed property prediction and two covered both. Encoder-decoder models predominated in spectrum-to-sequence generation, whereas encoder-style and hybrid architectures were common for fragment intensity, retention time, collision cross section and ion-mobility prediction. Performance depended on architecture, but also on training-data quality, acquisition context, peptide length, fragment completeness, post-translational-modification representation, domain adaptation, physicochemical constraints and decoding strategy. Cross-study comparison was limited by heterogeneous benchmarks, incomplete sequence-overlap auditing, scarce calibrated uncertainty and inconsistent reporting of compute and reproducibility. Property prediction offered the clearest route to reusable workflow integration, while de novo sequencing remained a confidence-sensitive complement to established identification methods. Future evaluations require versioned benchmarks, auditable data independence, broader distribution-shift testing and standardised reporting of uncertainty and efficiency.','https://www.sciencedirect.com/science/article/pii/S2667318526000322','Artificial Intelligence in the Life Sciences','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(359,'NovoRank: Machine Learning Based Post-processing for Performance Improvement in De Novo Peptide Sequencing','2022-08-01',NULL,'MSc thesis','To identify peptides in mass spectrometry-based proteomics, tandem mass (MS/MS) spectra are analyzed using database search or de novo sequencing tools. In contrast to database search approaches, de novo sequencing directly deduces peptide sequences from MS/MS spectra without any reference to sequence databases. De novo sequencing method often generates incorrect peptide identifications due to its practically unlimited search space and its peptide identification performance does not reach that of database search methods. Instead, de novo sequencing has the advantage of finding novel peptides that are not a part of the sequence database, thus is an essential method for discovering peptides of as yet unknown, biologically important functions. Here, we propose a machine learning based post-processer for de novo sequencing tools, named NovoRank, that can improve the performance of de novo sequencing and is applicable with any de novo peptide sequencing tools. NovoRank uses DBSCAN, a well-known density-based clustering algorithm, and adopts deep learning techniques so that candidate peptide reordering can give a better top-ranked sequence. Given a large-scale synthetic peptide dataset (ProteomeTools), NovoRank increased the peptide recall by 8.63~12.66% when applied with de novo sequencing results from three different software tools.','https://repository.hanyang.ac.kr/handle/20.500.11754/174145','','thesis',NULL,NULL);
INSERT INTO publication VALUES(360,'From decay to discovery: A new antimicrobial peptide from Chrysomya megacephala (Diptera: Calliphoridae) larvae','2026-08-10','10.1007/s42770-026-02047-y','Springer Science and Business Media LLC','The larvae of Chrysomya megacephala (Diptera: Calliphoridae) thrive in environments rich in decaying organic matter and dead animals, which are often colonized by bacteria. This adaptation suggests the larvae possess antimicrobial substances that provide them with a defense against bacterial infection. The hemolymph from around 200 C. megacephala larvae previously exposed to methicillin-resistant Staphylococcus aureus (MRSA) (clinical isolate) was collected, purified, and isolated utilizing Reverse Phase High Performance Liquid Chromatography (RP-HPLC). Fractions exhibiting antimicrobial properties underwent further analysis using Quadrupole Time-of-Flight Liquid Chromatography Mass Spectrometry (QTOF-LCMS). The resulting mass spectra were translated into amino acid sequences through de novo algorithms. Antimicrobial prediction tools from repositories such as APD3, Database of Antimicrobial Activity and Structure of Peptides (DBSAAP), Database of Antimicrobial Peptide (DBAMP), and Collection of Antimicrobial Peptide Version 4 (CAMPR4) were employed to validate the peptide sequences. We found the peptide (HGCGRLSKWFRQPGLLLSVKR) exhibited partial similarity with C. megacephala''s heat shock protein 70 (hsp70). The peptide demonstrated activity against Staphylococcus aureus, including MRSA, Micrococcus luteus, Staphylococcus epidermidis, and Bacillus subtilis with a minimum inhibitory concentration (MIC) of 0.06 mg/ml and an inhibition zone ranging from 8 to 11 mm at a concentration of 1 mg/ml. The cytotoxicity test of the peptide on immortalized keratinocyte cells (HaCat) and human corneal epithelial cells (HCEC) revealed an average cell viability > 80% at concentration of 0.06 mg/ml. In conclusion, the novel peptide (HGCGRLSKWFRQPGLLLSVKR) exhibits a broad spectrum of activity against Gram-positive bacteria while demonstrating minimal toxicity towards human cells.','https://link.springer.com/article/10.1007/s42770-026-02047-y','Brazilian Journal of Microbiology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(361,'Template-Assisted De Novo Sequencing of SARS-CoV-2 and Influenza Monoclonal Antibodies by Mass Spectrometry','2022-07-01','10.1021/acs.jproteome.1c00913','American Chemical Society (ACS)','In this study, we used multiple enzyme digestions, coupled with higher-energy collisional dissociation (HCD) and electron-transfer/higher-energy collision dissociation (EThcD) fragmentation to develop a mass-spectrometric (MS) method for determining the complete protein sequence of monoclonal antibodies (mAbs). The method was refined on an mAb of a known sequence, a SARS-CoV-1 antireceptor binding domain (RBD) spike monoclonal antibody. The data were searched using Supernovo to generate a complete template-assisted de novo sequence for this and two SARS-CoV-2 mAbs of known sequences resulting in correct sequences for the variable regions and correct distinction of Ile and Leu residues. We then used the method on a set of 25 antihemagglutinin (HA) influenza antibodies of unknown sequences and determined high confidence sequences for >99% of the complementarity determining regions (CDRs). The heavy-chain and light-chain genes were cloned and transfected into cells for recombinant expression followed by affinity purification. The recombinant mAbs displayed binding curves matching the original mAbs with specificity to the HA influenza antigen. Our findings indicate that this methodology results in almost complete antibody sequence coverage with high confidence results for CDR regions on diverse mAb sequences.','https://pubs.acs.org/doi/10.1021/acs.jproteome.1c00913','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(362,'Discrimination of Leucine and Isoleucine in Peptides Sequencing with Orbitrap Fusion Mass Spectrometer','2014-07-15','10.1021/ac501200h','American Chemical Society (ACS)','An efficient approach to easy and reliable differentiation between isomeric leucine and isoleucine in peptide sequencing utilizes multistage electron transfer dissociation and higher energy collision activated dissociation in the Orbitrap Fusion mass spectrometer. The MS(3) method involves production and isolation of primary odd-electron z(•) ions, followed by radical site initiation of their fragmentation with formation of w-ions, characteristic of the isomeric amino acid residues. Six natural nontryptic peptides isolated from the secretion of frog Rana ridibunda were studied. Their lengths were in the range between 15 and 37 amino acids and the number of targeted isomeric (Leu/Ile) residues varied between 1 and 7. The experiments were successful in all 22 cases of Leu/Ile residues, leaving no doubts in identification. The method is extremely selective as the targeted w-ions appear to be the most intense in the spectra. The proposed approach may be incorporated into shotgun proteomics algorithms and allows for the development of an exclusively mass spectrometric method for automated complete de novo sequencing of various peptides and proteins.','https://pubs.acs.org/doi/10.1021/ac501200h','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(363,'Evaluation of charge derivatization of a proteolytic protein digest for improved mass spectrometric analysis:de novo sequencing by matrix-assisted laser desorption/ionization post-source decay mass spectrometry','1999-11-01','10.1002/(sici)1096-9888(199911)34:11<1154::aid-jms875>3.0.co;2-8','Wiley','A simple mass spectrometric method to sequence a recombinant phosphoenolpyruvate carboxykinase of known structure and a novel variant of unknown structure isolated from Anaerobiospirillum succiniciproducens and Actinobacillus succinogenes 130Z, respectively, was evaluated. The proteolytic digests of the proteins were each chemically derivatized at the N-terminus by addition of a tris(trimethoxyphenyl)phosphoniumacetyl (TMPP(+)-Ac) group to produce peptides with a fixed positive charge. The derivatized digests were then partially separated by reversed-phase high-performance liquid chromatography. The fractions collected were subjected to matrix-assisted laser desorption/ionization post-source decay (MALDI/PSD) mass spectrometric analysis. The resulting spectra are sufficiently simple to allow the sequence to be read directly without extensive interpretation. This is in contrast to spectra of underivatized peptides obtained by MALDI/PSD or conventional tandem mass spectrometry, where full sequence interpretation can be challenging. Aided with a set of very simple established rules, it was shown that the sequence of TMPP(+)-Ac derivatives can be derived strictly from predictable fragment ion series. In most cases, this is sufficient to determine extensive, unambiguous, peptide sequences de novo. The partial sequence (35%) of the unknown phosphoenolpyruvate carboxykinase from Actinobacillus succinogenes 130Z was obtained entirely by the mass spectrometric method evaluated here, which provided the basis for evaluating homology and for the design of oligonucleotide probes for cloning the corresponding gene.','https://doi.org/10.1002/(sici)1096-9888(199911)34:11<1154::aid-jms875>3.0.co;2-8','Journal of Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(364,'Automatedde novo sequencing of proteins using the differential scanning technique','2001-04-01','10.1002/1615-9861(200104)1:5<668::aid-prot668>3.0.co;2-s','Wiley','Despite the progress in genomic DNA sequencing de novo sequencing of peptides is still required in a biological research environment since many experiments are done in organisms whose genomes are not sequenced. A way to unambiguously retrieve a peptide sequence from a tandem mass spectrum is to assign the correct ion type to the fragments. Here we describe a method which improves the specificity in y-ion assignment throughout the spectrum. The differential scanning technique requires that the peptides are partially 18O labelled at their C-terminus and that two fragment spectra are acquired for each peptide, one selecting the 16O/18O isotopic cluster and a second fragmenting only the 18O labelled ions. When the spectra are acquired with a quadrupole time of flight mass spectrometer y-ions can be very specifically filtered from the spectrum using a computer algorithm. Partial or complete peptide sequences can be assigned automatically simply by finding the most abundant series of fragments spaced by amino acid residue masses. This method was used extensively in a project investigating vesicular transport in bovine brain cells. Human or mouse homologues to the bovine proteins were found in EST databases facilitating rapid cloning of the human homologues.','https://doi.org/10.1002/1615-9861(200104)1:5<668::aid-prot668>3.0.co;2-s','PROTEOMICS','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(365,'A case study of de novo sequence analysis of N-sulfonated peptides by MALDI TOF/TOF mass spectrometry','2004-12-01','10.1016/j.jasms.2004.08.010','American Chemical Society (ACS)','The simplicity and sensitivity of matrix-assisted laser desorption/ionization time-of-flight mass spectrometry have increased its application in recent years. The most common method of "peptide mass fingerprint" analysis often does not provide robust identification. Additional sequence information, obtained by post-source decay or collision induced dissociation, provides additional constraints for database searches. However, de novo sequencing by mass spectrometry is not yet common practice, most likely because of the difficulties associated with the interpretation of high and low energy CID spectra. Success with this type of sequencing requires full sequence coverage and demands better quality spectra than those typically used for data base searching. In this report we show that full-length de novo sequencing is possible using MALDI TOF/TOF analysis. The interpretation of MS/MS data is facilitated by N-terminal sulfonation after protection of lysine side chains (Keough et al., Proc. Natl. Acad. Sci. U.S.A. 1999, 96, 7131-7136). Reliable de novo sequence analysis has been obtained using sub-picomol quantities of peptides and peptide sequences of up to 16 amino acid residues in length have been determined. The simple, predictable fragmentation pattern allows routine de novo interpretation, either manually or using software. Characterization of the complete primary structure of a peptide is often hindered because of differences in fragmentation efficiencies and in specific fragmentation patterns for different peptides. These differences are controlled by various structural parameters including the nature of the residues present. The influence of the presence of internal Pro, acidic and basic residues on the TOF/TOF fragmentation pattern will be discussed, both for underivatized and guanidinated/sulfonated peptides.','https://doi.org/10.1016/j.jasms.2004.08.010','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(366,'Enhancing TOF/TOF-based de Novo Sequencing Capability for High Throughput Protein Identification with Amino Acid-Coded Mass Tagging','2005-02-01','10.1021/pr049850u','American Chemical Society (ACS)','Because of the intrinsic physical properties of single- or double-charged ions, MALDI-based CID on these peptide precursor ions tends to be incomplete, resulting in a large number of MS/MS spectra unassigned or ambiguously identified. Consequently, the TOF/TOF high throughput capability may not be fully explored and utilized. Here, we describe a novel method for de novo sequence assignment of those MALDI TOF/TOF MS/MS spectra with incomplete or weak fragment ion series. In this approach, the deuterium-labeled lysine and leucine precursors were used in parallel to mass-tag the proteome of a metastatic human hepatocellular carcinoma (HCC) cell line during in vivo cell culturing. These stable isotope precursor markers not only position at terminal but at internal MS/MS fragment ions with the characteristic isotope pattern induced by multiple mass tagging in parallel. This enhanced signal specificity evidently resolved ambiguities in those sparse poor-quality TOF/TOF spectra by providing critical sequential links among MS/MS fragment ions. Our data-dependent approach was able to reduce many false-positives in current genome sequence-based peptide sequencing. With developing new algorithms accordingly, our approach is amenable for automation that will lead to more comprehensive and reliable identification for proteomes.','https://doi.org/10.1021/pr049850u','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(367,replace('An algorithm for interpretation of low‐energy collision‐induced dissociation product ion spectra for\n                    <i>de novo</i>\n                    sequencing of peptides','\n',char(10)),'2005-04-30','10.1002/rcm.1892','Wiley','An algorithm for interpretation of product ion spectra of peptides generated from ion trap mass spectrometry is developed for de novo amino acid sequencing of peptides for the purpose of protein identification. It is based on a multi-pass analysis of product ion data using a rigorous data extraction and sequence interpretation protocol in the initial pass. The extraction/interpretation algorithm becomes more relaxed in subsequent passes, considering more of the fragment ions, and potentially more sequence candidates. The possible peptide sequences generated by the algorithm are scored according to those sequences which best explain the fragment ion spectrum. These sequences are searched against a protein database using a BLAST search engine to find likely protein candidates. The method is also suitable for locating and determining protein modifications, and can be applied to de novo interpretation of peptide fragment ions in the tandem mass (MS/MS) spectrum produced from a mixture of two peptides having similar nominal mass, but different sequences. Using a known protein, bovine serum albumin, as an example, it is illustrated that this method is rapid and efficient for MS/MS spectral interpretation. This method combined with BLAST programs is then applied to search homologies and to generate information on post-translational modifications of an unknown protein isolated from shark cartilage that does not have a complete genome or proteome database.','https://doi.org/10.1002/rcm.1892','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(368,'Infrared Multiphoton Dissociation for Enhanced de Novo Sequence Interpretation of N-Terminal Sulfonated Peptides in a Quadrupole Ion Trap','2006-10-01','10.1021/ac060760d','American Chemical Society (ACS)','Infrared multiphoton dissociation (IRMPD) of N-terminal sulfonated peptides improves de novo sequencing capabilities in a quadrupole ion trap mass spectrometer. Not only does IRMPD promote highly efficient dissociation of the N-terminal sulfonated peptides but also the entire series of y ions down to the y(1) fragment may be detected due to alleviation of the low-mass cutoff problem associated with conventional collisional activated dissociation (CAD) methods in a quadrupole ion trap. Commercial de novo sequencing software was applied for the interpretation of CAD and IRMPD MS/MS spectra collected for seven unmodified peptides and the corresponding N-terminal sulfonated species. In most cases, the additional information obtained by N-terminal sulfonation in combination with IRMPD provided significant improvements in sequence identification. The software sequence tag results were combined with a commercial database searching algorithm to interpret sequence information of a tryptic digest on alpha-casein s1. Energy-variable CAD studies confirmed a 30-40% reduction in the critical energies of the N-terminal sulfonated peptides relative to unmodified peptides. This reduction in dissociation energy facilitates IRMPD in a quadrupole ion trap.','https://doi.org/10.1021/ac060760d','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(369,'Improving de Novo Sequencing of Peptides Using a Charged Tag and C-Terminal Digestion','2007-02-01','10.1021/ac061670b','American Chemical Society (ACS)','An improved method for peptide de novo sequencing by MALDI mass spectrometry is presented. The method couples a charge derivatization reaction with C-terminal digestion to modify tryptic peptides. The charge derivatization attaches a fixed charge group onto the N-termini of peptides, and the enzymatic digestion after the derivatization step removes C-terminal basic amino acid residues such as arginine and lysine. The fragmentation of the modified peptide(s) under low-energy CID conditions (MALDI Q-TOF mass spectrometer) yields a simplified yet complete ion series of the peptide sequence. The validity of the method is demonstrated by the results from several model protein digests, where peptide sequences were correctly deduced either manually or through an automated sequencing program.','https://doi.org/10.1021/ac061670b','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(370,'Sequence similarity‐driven proteomics in organisms with unknown genomes by LC‐MS/MS and automated <b><i>de novo</i></b> sequencing','2007-07-01','10.1002/pmic.200700003','Wiley','LC-MS/MS analysis on a linear ion trap LTQ mass spectrometer, combined with data processing, stringent, and sequence-similarity database searching tools, was employed in a layered manner to identify proteins in organisms with unsequenced genomes. Highly specific stringent searches (MASCOT) were applied as a first layer screen to identify either known (i.e. present in a database) proteins, or unknown proteins sharing identical peptides with related database sequences. Once the confidently matched spectra were removed, the remainder was filtered against a nonannotated library of background spectra that cleaned up the dataset from spectra of common protein and chemical contaminants. The rectified spectral dataset was further subjected to rapid batch de novo interpretation by PepNovo software, followed by the MS BLAST sequence-similarity search that used multiple redundant and partially accurate candidate peptide sequences. Importantly, a single dataset was acquired at the uncompromised sensitivity with no need of manual selection of MS/MS spectra for subsequent de novo interpretation. This approach enabled a completely automated identification of novel proteins that were, otherwise, missed by conventional database searches.','https://doi.org/10.1002/pmic.200700003','PROTEOMICS','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(371,replace('Specific isolation of N‐terminal fragments from proteins and their high‐fidelity\n                    <i>de novo</i>\n                    sequencing','\n',char(10)),'2007-10-30','10.1002/rcm.3215','Wiley','A new method to determine N-terminal amino acid sequences of multiple proteins at low pmol level by a parallel processing has been developed. The method contains the following five steps: (1) reduction, S-alkylation and guanidination for targeted proteins; (2) coupling with sulfosucccimidyl-2-(biotinamido)ethyl-1,3-dithiopropionate(sulfo-NHS-SS-biotin) to N(alpha)-amino groups of proteins; (3) digestion of the modified proteins by an appropriate protease; (4) specific isolation of N-terminal fragments of proteins by affinity capture using the biotin-avidin system; (5) de novo sequence analysis of peptides by MALDI-TOF-/MALDI-TOF-PSD mass spectrometry with effective utilization of the CAF (chemically assisted fragmentation) method.1 This method is also effective for N-terminal sequencing of each protein in a mixture of several proteins, and for sequencing components of a multiprotein complex. It is expected to become an essential proteomics tool for identifying proteins, especially when used in combination with a C-terminal sequencing method.','https://doi.org/10.1002/rcm.3215','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(372,replace('Lys Tag: an easy and robust chemical modification for improved\n                    <i>de novo</i>\n                    sequencing with a matrix‐assisted laser desorption/ionization tandem time‐of‐flight mass spectrometer','\n',char(10)),'2008-06-30','10.1002/rcm.3555','Wiley','Mass spectrometry using a matrix-assisted laser desorption/ionization (MALDI) time-of-flight (TOF) instrument is a widespread technique for various types of proteomic analysis. Along with an expanding interest in proteomics, there is a strong requirement for the identification of proteins with high confidence from biological samples. Peptide modification by a wide variety of post-translational modifications (PTMs), the existence of different protein isoforms and the presence of uncharacterized genomes of many species, make protein identification through peptide mass fingerprinting (PMF) often unachievable. Peptide de novo sequencing has been proven to be a useful approach to overcome these variables, and efficient derivatization processes are important tools to achieve this goal. In the present work we describe the methodology and experimental applications of a fast, efficient and cheap lysine derivatization. This chemical modification improves the signals from lysine-terminated peptides and can be efficiently used as a lysine-blocking agent in combination with other derivatization techniques. Most importantly, upon peptide fragmentation it generates a neat series of predominantly y-ions, allowing the determination of unambiguous amino acid sequences. Moreover, this chemical compound was used with target-eluted samples, enabling a second, alternative analysis of the same sample in the MALDI mass spectrometer.','https://doi.org/10.1002/rcm.3555','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(373,replace('An improved method for\n                    <i>de novo</i>\n                    sequencing of arginine‐containing, N\n                    <sup>α</sup>\n                    ‐tris(2,4,6‐trimethoxyphenyl)phosphonium‐acetylated peptides','\n',char(10)),'2008-07-15','10.1002/rcm.3587','Wiley','An improved method for de novo sequencing of arginine-containing peptides modified with succinimidyloxycarbonylmethyl tris(2,4,6-trimethoxyphenyl)phosphonium bromide (TMPP-Ac-OSu) is reported. A tagging reagent, TMPP-Ac-OSu, was introduced to improve the sequence analysis of peptides owing to the simplified fragmentation pattern. However, peptides containing arginine residues did not fragment efficiently even after TMPP-Ac modification at their N-termini. This report describes how fragmentation efficiency of TMPP-Ac-modified arginine-containing peptides was significantly improved by modifying the guanidino group on the side chain of arginine with acetylacetone.','https://doi.org/10.1002/rcm.3587','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(374,'A method for N-terminal de novo sequence analysis of proteins by matrix-assisted laser desorption/ionization mass spectrometry','2008-09-01','10.1016/j.ab.2008.05.053','Elsevier BV','A novel method for isolation and de novo sequencing of N-terminal peptides from proteins is described. The method presented here combines selective chemical tagging using succinimidyloxycarbonylmethyl tris(2,4,6-trimethoxyphenyl)phosphonium bromide (TMPP-Ac-OSu) at the N(alpha)-amino group of peptides after digestion by metalloendopeptidase (from Grifola frondosa) and selective capture procedures using p-phenylenediisothiocyanate resin, by which the N-terminal peptide can be isolated, whether or not it is N-terminally blocked. The isolated N-terminal peptide modified N-terminally with TMPP-Ac-OSu reagent produces a simple fragmentation pattern under tandem mass spectrometric analysis to significantly facilitate sequencing.','https://doi.org/10.1016/j.ab.2008.05.053','Analytical Biochemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(375,'De Novo Sequencing of Unique Sequence Tags for Discovery of Post-Translational Modifications of Proteins','2008-10-15','10.1021/ac801123p','American Chemical Society (ACS)','De novo sequencing is a spectrum analysis approach for mass spectrometry data to discover post-translational modifications in proteins; however, such an approach is still in its infancy and is still not widely applied to proteomic practices due to its limited reliability. In this work, we describe a de novo sequencing approach for the discovery of protein modifications based on identification of the proteome UStags (Shen, Y.; Tolić, N.; Hixson, K. K.; Purvine, S. O.; Pasa-Tolić, L.; Qian, W. J.; Adkins, J. N.; Moore, R. J.; Smith, R. D. Anal. Chem. 2008, 80, 1871-1882). The de novo information was obtained from Fourier-transform tandem mass spectrometry data for peptides and polypeptides from a yeast lysate, and the de novo sequences obtained were selected based on filter levels designed to provide a limited yet high quality subset of UStags. The DNA-predicted database protein sequences were then compared to the UStags, and the differences observed across or in the UStags (i.e., the UStags'' prefix and suffix sequences and the UStags themselves) were used to infer possible sequence modifications. With this de novo-UStag approach, we uncovered some unexpected variances within several yeast protein sequences due to amino acid mutations and/or multiple modifications to the predicted protein sequences. To determine false discovery rates, two random (false) databases were independently used for sequence matching, and ~3% false discovery rates were estimated for the de novo-UStag approach. The factors affecting the reliability (e.g., existence of de novo sequencing noise residues and redundant sequences) and the sensitivity of the approach were investigated and described. The combined de novo-UStag approach complements the UStag method previously reported by enabling the discovery of new protein modifications.','https://doi.org/10.1021/ac801123p','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(376,'Dereplication and de novo sequencing of nonribosomal peptides','2009-08-01','10.1038/nmeth.1350','Springer Science and Business Media LLC','Nonribosomal peptides (NRPs) are of great pharmacological importance, but there is currently no technology for high-throughput NRP ''dereplication'' and sequencing. We used multistage mass spectrometry followed by spectral alignment algorithms for sequencing of cyclic NRPs. We also developed an algorithm for comparative NRP dereplication that establishes similarities between newly isolated and previously identified similar but nonidentical NRPs, substantially reducing dereplication efforts.','https://doi.org/10.1038/nmeth.1350','Nature Methods','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(377,'C-terminal de novo sequencing of peptides using oxazolone-based derivatization with bromine signature','2011-12-01','10.1016/j.ab.2011.08.011','Elsevier BV','Due to almost identical chemical properties of C-terminal and side-chain carboxylic groups, selective C-terminal derivatization has been difficult. Although oxazolone-based C-terminal derivatization is the only selective C-terminal modification available, it has not been used widely because of its low derivatization efficiency. In this paper, an improved oxazolone chemistry for incorporation of Br signature to C-terminus is reported. MS/MS analysis of the brominated peptides led to a series of y ions with Br signature, facilitating de novo C-terminal sequencing.','https://doi.org/10.1016/j.ab.2011.08.011','Analytical Biochemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(378,'De novo analysis of protein N-terminal sequence utilizing MALDI signal enhancing derivatization with Br signature','2012-02-01','10.1007/s00216-011-5642-7','Springer Science and Business Media LLC','De novo analysis of protein N-terminal sequence is important for identification of N-terminal proteolytic processing such as N-terminal methionine or signal peptide removal, or for the genome annotation of uncharacterized proteins. We introduce a de novo sequencing method of protein N terminus utilizing matrix-assisted laser desorption/ionization (MALDI) signal enhancing picolinamidination with bromine isotopic tag incorporated to the N terminus. The doublet signature of bromine in the tandem mass (MS/MS) spectrum distinguished N-terminal ion series from C-terminal ion series, facilitating de novo N-terminal sequencing of protein. The dual advantage of MALDI signal enhancement by the basic picolinamidine and b-ion selection aided by Br signature is demonstrated using a variety of peptides. The N-terminal sequences of myoglobin and hemoglobin as model proteins were determined by incorporating the Br tag to the N terminus of the proteins and obtaining a series of b-ions with Br signature by MS/MS analysis after chymotryptic digestion of the tagged proteins. The N-terminal peptide was selected for MS/MS analysis from the chymotryptic digest based on the Br signature in the mass spectrum. Identification of phosphorylation site as well as N-terminal sequencing of a phosphopeptide was straightforward.','https://doi.org/10.1007/s00216-011-5642-7','Analytical and Bioanalytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(379,'193 nm Ultraviolet Photodissociation of Imidazolinylated Lys-N Peptides for <i>De Novo</i> Sequencing','2012-03-06','10.1021/ac203227y','American Chemical Society (ACS)','The goal of many MS/MS de novo sequencing strategies is to generate a single product ion series that can be used to determine the precursor ion sequence. Most methods fall short of achieving such simplified spectra, and the presence of additional ion series impede peptide identification. The present study aims to solve the problem of confounding ion series by enhancing the formation of "golden" sets of a, b, and c ions for sequencing. Taking advantage of the characteristic mass differences between the golden ions allows N-terminal fragments to be readily identified while other ion series are excluded. By combining the use of Lys-N, an alternate protease, to produce peptides with lysine residues at each N-terminus with subsequent imidazolinylation of the ε-amino group of each lysine, peptides with highly basic sites localized at each N-terminus are generated. Subsequent MS/MS analysis by using 193 nm ultraviolet photodissociation (UVPD) results in enhanced formation of the diagnostic golden pairs and golden triplets that are ideal for de novo sequencing.','https://doi.org/10.1021/ac203227y','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(380,'Identification of phosphopeptides with unknown cleavage specificity by a de novo sequencing assisted database search strategy','2014-11-01','10.1002/pmic.201400268','Wiley','In theory, proteases with broad cleavage specificity could be applied to digest protein samples to improve the phosphoproteomic analysis coverage. However, in practice this approach is seldom employed. This is because the identification of phosphopeptides without enzyme specificity by conventional database search strategy is extremely difficult due to the huge search space. In this study, we investigated the performance of a de novo sequencing assisted database search strategy for the identification of such phosphopeptides. Firstly, we compared the performance of conventional database search strategy and the de novo sequencing assisted database search strategy for the identification of peptides and phosphopeptides without stetting enzyme specificity. It was found that the identification sensitivity dropped significantly for the conventional one while it was only slightly decreased for the new approach. Then, this new search strategy was applied to identify phosphopeptides generated by Proteinase K digestion, which resulted in the identification of 717 phosphopeptides. Finally, this strategy was utilized for the identification of serum endogenous phosphopeptides, which were generated in vivo by different kinds of proteases and kinases, and the identification of 68 unique serum endogenous phosphopepitdes was successfully achieved.','https://doi.org/10.1002/pmic.201400268','PROTEOMICS','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(381,'CycloBranch: De Novo Sequencing of Nonribosomal Peptides from Accurate Product Ion Mass Spectra','2015-10-01','10.1007/s13361-015-1211-1','American Chemical Society (ACS)','Nonribosomal peptides have a wide range of biological and medical applications. Their identification by tandem mass spectrometry remains a challenging task. A new open-source de novo peptide identification engine CycloBranch was developed and successfully applied in identification or detailed characterization of 11 linear, cyclic, branched, and branch-cyclic peptides. CycloBranch is based on annotated building block databases the size of which is defined by the user according to ribosomal or nonribosomal peptide origin. The current number of involved nonisobaric and isobaric building blocks is 287 and 521, respectively. Contrary to all other peptide sequencing tools utilizing either peptide libraries or peptide fragment libraries, CycloBranch represents a true de novo sequencing engine developed for accurate mass spectrometric data. It is a stand-alone and cross-platform application with a graphical and user-friendly interface; it supports mzML, mzXML, mgf, txt, and baf file formats and can be run in parallel on multiple threads. It can be downloaded for free from http://ms.biomed.cas.cz/cyclobranch/ , where the User''s manual and video tutorials can be found.','https://doi.org/10.1007/s13361-015-1211-1','Journal of the American Society for Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(382,'De Novo Sequencing Assisted Approach for Characterizing Mixture MS/MS Spectra','2016-03-01','10.1109/tnb.2016.2519841','Institute of Electrical and Electronics Engineers (IEEE)','Extensive research has been conducted for the computational analysis of mass spectrometry based proteomics data. However, there are still remaining challenges, among which, one particular challenge is the low identification rate of the collected spectral data. A specific contributing factor is the existence of mixture spectra in the collected MS/MS spectra which are generated by the concurrent fragmentation of multiple precursors in one sequencing attempt. The quite frequently observed mixture spectra necessitates the development of effective computational approaches to characterize those non-conventional spectral data. In this research, we proposed an approach for matching the query mixture spectra with a pair of peptide sequences acquired from the protein database by incorporating a special de novo assisted filtration strategy. The experiment results on two different datasets of MS/MS spectra containing mixed ion fragments from multiple peptides demonstrated the efficiency of the integrated filtration strategy in reducing examination space and verified the effectiveness of the proposed matching scheme as well.','https://doi.org/10.1109/tnb.2016.2519841','IEEE Transactions on NanoBioscience','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(383,'Top-down analysis of protein samples by <i>de novo</i> sequencing techniques','2016-09-15','10.1093/bioinformatics/btw307','Oxford University Press (OUP)','Motivation Recent technological advances have made high-resolution mass spectrometers affordable to many laboratories, thus boosting rapid development of top-down mass spectrometry, and implying a need in efficient methods for analyzing this kind of data. Results We describe a method for analysis of protein samples from top-down tandem mass spectrometry data, which capitalizes on de novo sequencing of fragments of the proteins present in the sample. Our algorithm takes as input a set of de novo amino acid strings derived from the given mass spectra using the recently proposed Twister approach, and combines them into aggregated strings endowed with offsets. The former typically constitute accurate sequence fragments of sufficiently well-represented proteins from the sample being analyzed, while the latter indicate their location in the protein sequence, and also bear information on post-translational modifications and fragmentation patterns. Availability and implementation Freely available on the web at http://bioinf.spbau.ru/en/twister Contact or Supplementary information Supplementary data are available at Bioinformatics online.','https://doi.org/10.1093/bioinformatics/btw307','Bioinformatics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(384,'De Novo Sequencing of Top-Down Tandem Mass Spectra: A Next Step towards Retrieving a Complete Protein Sequence','2017-02-08','10.3390/proteomes5010006','MDPI AG','De novo sequencing of tandem (MS/MS) mass spectra represents the only way to determine the sequence of proteins from organisms with unknown genomes, or the ones not directly inscribed in a genome-such as antibodies, or novel splice variants. Top-down mass spectrometry provides new opportunities for analyzing such proteins; however, retrieving a complete protein sequence from top-down MS/MS spectra still remains a distant goal. In this paper, we review the state-of-the-art on this subject, and enhance our previously developed Twister algorithm for de novo sequencing of peptides from top-down MS/MS spectra to derive longer sequence fragments of a target protein.','https://doi.org/10.3390/proteomes5010006','Proteomes','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(385,'De Novo Sequencing of Tryptic Phosphopeptides Using Matrix-Assisted Laser Desorption/Ionization Based Tandem Mass Spectrometry with Hydrogen Atom Attachment','2018-02-20','10.1021/acs.analchem.7b04635','American Chemical Society (ACS)','Phosphorylation is the most abundant protein modification, and tandem mass spectrometry (MS/MS) with radical-based fragmentation techniques has proven to be a promising method for phosphoproteomic applications, owing to its ability to determine phosphorylation sites on proteins. The radical-induced fragmentation technique involves the attachment or abstraction of hydrogen to peptides in an ion trap mass spectrometer, in a process called hydrogen attachment/abstraction dissociation (HAD), which has only been recently developed. In the present investigation, we have analyzed model phosphopeptides and phosphoprotein digests using HAD-MS/MS, combined with matrix-assisted laser desorption/ionization (MALDI), in order to demonstrate the usefulness of the HAD-MS/MS-based analytical method. The tryptic peptides were categorized as arginine- and lysine-terminated peptides, and MALDI HAD-MS/MS is found to facilitate the sequencing of arginine-terminated tryptic peptides, because of the selective observation of C-terminal side fragment ions. In contrast, MALDI HAD-MS/MS of lysine-terminated tryptic peptides produced both N- and C-terminal side fragments, such that the mass spectra were complex. The guanidination of peptide converted lysine into homoarginine, which facilitated the interpretation of MALDI HAD-MS/MS mass spectra. The present method was useful for de novo sequencing of tryptic phosphopeptides.','https://doi.org/10.1021/acs.analchem.7b04635','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(386,'Use of PASEF for Accelerated Protein Sequence Confirmation and De Novo Sequencing with High Data Quality','2022-01-01','10.1007/978-1-0716-1450-1_12','Springer US','Biopharmaceutical sequences can be well confirmed by multiple protease digests-e.g., trypsin, elastase, and chymotrypsin-followed by LC-MS/MS data analysis. High quality data can be used for de novo sequencing as well. PASEF (Parallel Accumulation and Serial Fragmentation) on the timsTOF instrument has been used to accelerate proteome and protein sequence studies and increase sequence coverage concomitantly.Here we describe the protein chemical and LC-MS methods in detail to generate high quality samples for sequence characterization from only 3 digests. We applied PASEF to generate exhaustive protein sequence coverage maps by combination of results from the three enzyme digests using a short LC gradient. The data quality obtained was high and adequate for determining antibody sequences de novo.Nivolumab and dulaglutide were digested by 3 enzymes individually. For nivolumab, 94/94/90% sequence coverage and 86/84/85% fragment coverage were obtained from the individual digest analysis with trypsin/chymotrypsin/elastase, respectively. For dulaglutide, 96/100/90% sequence coverage and 92/90/83% fragment coverage were obtained. The merged peptide map from the 3 digests for nivolumab resulted in ∼550 peptides; enough to safely confirm the full sequences and to determine the nivolumab sequence de novo.','https://doi.org/10.1007/978-1-0716-1450-1_12','Methods in Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(387,'Facile de Novo Sequencing of Tetrazine‐Cyclized Peptides through UV‐Induced Ring‐Opening and Cleavage from the Solid Phase','2023-02-14','10.1002/cbic.202200590','Wiley','While most FDA-approved peptide drugs are cyclic, the robust cyclization chemistry of peptides and the deconvolution of cyclic peptide sequences by using tandem mass spectrometry render cyclic peptide drug discovery difficult. Here we present the successful design of cyclic peptides on solid phase that addresses both of these problems. We demonstrate that this peptide cyclization method using dichloro-s-tetrazine on solid phase allows successful cyclization of a panel of random peptide sequences with various charges and hydrophobicities. The cyclic peptides can be linearized and cleaved from the solid phase by simple UV light irradiation, and we demonstrate that accurate sequence information can be obtained for the UV-cleaved linearized peptides by using tandem mass spectrometry. The tetrazine linker used in the cyclic peptides can further be explored for inverse electron-demand Diels-Alder (IEDDA) reactions for screening or bioconjugation applications in the future.','https://doi.org/10.1002/cbic.202200590','ChemBioChem','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(388,replace('<i>De novo</i>\n                    sequencing of novel neuropeptides directly from\n                    <i>Ascaris suum</i>\n                    tissue using matrix‐assisted laser desorption/ionization time‐of‐flight/time‐of‐flight','\n',char(10)),'2003-12-30','10.1002/rcm.1240','Wiley','Direct analysis of tissue by matrix-assisted laser desorption/ionization mass spectrometry (MALDI-MS) allows for the rapid profiling of biological molecules with minimal loss of sample or degradation and reduced likelihood of chemical modification. However, there are still considerable challenges to overcome due to the complexity of tissue and the low quantity of endogenous peptide in a single cell. These problems are exacerbated in the nematode Ascaris suum because of the small size of individual neurons and the paucity of peptide per cell. In an effort to address these difficulties, the recently developed matrix-assisted laser desorption/ionization time-of-flight/time-of-flight (MALDI-TOF/TOF) technology was used in combination with an on-target derivatization in order to sequence novel neuropeptides directly from Ascaris nervous tissue. Direct MALDI-TOF/TOF analysis of Ascaris tissue provided the complete amino acid sequences for a previously characterized neuropeptide as well as for three novel peptides with homologues found in other nematodes. These results demonstrate a method for the rapid characterization of sub-femtomolar amounts of peptide directly from tissue using MALDI-TOF/TOF.','https://doi.org/10.1002/rcm.1240','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(389,'<i>De novo</i> sequencing of antimicrobial peptides isolated from the venom glands of the wolf spider <i>Lycosa singoriensis</i>','2004-02-01','10.1002/jms.577','Wiley','Antimicrobial peptides (AMPs), named lycocitin 1, 2 and 3, and a peptide with a monoisotopic molecular mass of 3038.70 Da were detected in the venom glands of the wolf spider Lycosa singoriensis. Two of the peptides, lycocitin 1 and 2, are new AMPs whereas lycocitin 3 is highly homologous to lycotoxin II isolated from the venom of spider Lycosa carolinensis. In addition, two other peptides with monoisotopic masses of 2034.20 and 2340.28 Da showing the motif typical for antimicrobial peptides were also identified. These peptides and lycocitin 1, 2 and 3 were de novo sequenced using electron capture dissociation and low-energy collisional tandem mass spectrometry. The amino acid sequence of lycocitin 1 was determined as GKLQAFLAKMKEIAAQTL-NH(2). Lycocitin 2 differs from lycocitin 1 by a replacement of a lysine residue for an arginine residue at the second position. Lycocitin 3 differs from the known lycotoxin II consisting of 27 amino acid residues by a deletion of Gly-26. Both lycocitin 1 and 2 inhibit growth of Gram-positive (Staphylococcus aureus, Bacillus subtilis) and Gram-negative (Escherichia coli) bacteria and fungi (Candida albicans, Pseudomonas aeruginosa) at micromolar concentrations.','https://doi.org/10.1002/jms.577','Journal of Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(390,'Identification of proteins induced by polycyclic aromatic hydrocarbon in <b><i>Mycobacterium vanbaalenii</i></b> PYR‐1 using two‐dimensional polyacrylamide gel electrophoresis and <b><i>de novo</i></b> sequencing methods','2004-12-01','10.1002/pmic.200400872','Wiley','Protein profiles of Mycobacterium vanbaalenii PYR-1 grown in the presence of high-molecular-weight polycyclic aromatic hydrocarbons (HMW PAHs) were examined by two-dimensional gel electrophoresis (2-DE). Cultures of M. vanbaalenii PYR-1 were incubated with pyrene, pyrene-4,5-quinone (PQ), phenanthrene, anthracene, and fluoranthene. Soluble cellular protein fractions were analyzed and compared, using immobilized pH gradient (IPG) strips. More than 1000 gel-separated proteins were detected using a 2-DE analysis program within the window of isoelectric point (pI) 4-7 and a molecular mass range of 10-100 kDa. We observed variations in the protein composition showing the upregulation of multiple proteins for the five PAH treatments compared with the uninduced control sample. By N-terminal sequencing or mass spectrometry, we further analyzed the proteins separated by 2-DE. Due to the lack of genome sequence information for this species, protein identification provided an analytical challenge. Several PAH-induced proteins were identified including a catalase-peroxidase, a putative monooxygenase, a dioxygenase small subunit, a small subunit of naphthalene-inducible dioxygenase, and aldehyde dehydrogenase. We also identified proteins related to carbohydrate metabolism (enolase, 6-phosphogluconate dehydrogenase, indole-3-glycerol phosphate synthase, and fumarase), DNA translation (probable elongation factor Tsf), heat shock proteins, and energy production (ATP synthase). Many proteins from M. vanbaalenii PYR-1 showed similarity with protein sequences from M. tuberculosis and M. leprae. Some proteins were detected uniquely upon exposure to a specific PAH whereas others were common to more than one PAH, which indicates that induction triggers not only specific responses but a common response in this strain.','https://doi.org/10.1002/pmic.200400872','PROTEOMICS','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(391,'De novo proteomic sequencing of a monoclonal antibody raised against OX40 ligand','2006-05-01','10.1016/j.ab.2006.02.001','Elsevier BV','De novo sequencing of a full-length monoclonal antibody raised against OX40 ligand is described. Using a combination of overlapping complementary proteolytic and chemical digestions, with analysis by mass spectrometry and Edman degradation, both the heavy and light chains were fully sequenced. Particular attention was paid to those modifications that could be susceptible to degradation in the complementarity determining region and Fc region. An overview of the protocol is described, and suggestions for improvements to aid in such sequencing projects in the future are discussed.','https://doi.org/10.1016/j.ab.2006.02.001','Analytical Biochemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(392,'De Novo Sequencing and Disulfide Mapping of a Bromotryptophan-Containing Conotoxin by Fourier Transform Ion Cyclotron Resonance Mass Spectrometry','2006-12-01','10.1021/ac0607764','American Chemical Society (ACS)','T-1-family conotoxins belong to the T-superfamily and are composed of 10-17 amino acids. They share a common cysteine framework and disulfide connectivity and exhibit unusual posttranslational modifications, such as tryptophan bromination, glutamic acid carboxylation, and threonine glycosylation. We have isolated and characterized a novel peptide, Mo1274, containing 11 amino acids, that shows the same cysteine pattern, -CC-CC, and disulfide linkage as those of the T-1-family members. The complete sequence, GNWCCSARVCC, in which W denotes bromotryptophan, was derived from MS-based de novo sequencing. The FT-ICR MS/MS techniques of electron capture dissociation (ECD), infrared multiphoton dissociation, and collision-induced dissociation served to detect and localize the tryptophan bromination. The bromine contributes a distinctive isotopic distribution in all fragments that contain bromotryptophan. ECD fragmentation results in the loss of bromine and return to the normal isotopic distribution. Disulfide connectivity of Mo1274, between cysteine pairs 1-3 and 2-4, was determined by mass spectrometry in combination with chemical derivatization employing tris(2-carboxyethyl)phosphine, followed by differential alkylation with N-ethylmaleimide and iodoacetamide. The ECD spectra of the native and partially modified peptide reveal a loss of bromine in a process that requires the presence of a disulfide bond.','https://doi.org/10.1021/ac0607764','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(393,'De novo protein sequence analysis of Macaca mulatta','2007-01-01','10.1186/1471-2164-8-270','Springer Science and Business Media LLC','Background Macaca mulatta is one of the most utilized non-human primate species in biomedical research offering unique behavioral, neuroanatomical, and neurobiochemcial similarities to humans. This makes it a unique organism to model various diseases such as psychiatric and neurodegenerative illnesses while also providing insight into the complexities of the primate brain. A major obstacle in utilizing rhesus monkey models for human disease is the paucity of protein annotations for this species (~42,000 protein annotations) compared to 330,210 protein annotations for humans. The lack of available information limits the use of rhesus monkey for proteomic scale studies which rely heavily on database searches for protein identification. While characterization of proteins of interest from Macaca mulatta using the standard database search engines (e.g., MASCOT) can be accomplished, searches must be performed using a ''broad species database'' which does not provide optimal confidence in protein annotation. Therefore, it becomes necessary to determine partial or complete amino acid sequences using either manual or automated de novo peptide sequence analysis methods. Results The recently popularized MALDI-TOF-TOF mass spectrometer yields a complex MS/MS fragmentation pattern difficult to characterize by manual de novo sequencing method on a proteomics scale. Therefore, PEAKS assisted de novo sequencing was performed on nucleus accumbens cytosolic proteins from Macaca mulatta. The most abundant peptide fragments ''b-ions and y-ions'', the less abundant peptide fragments ''a-ions'' as well as the immonium ions were utilized to develop confident and complete peptide sequences de novo from MS/MS spectra. The generated sequences were used to perform homology searches to characterize the protein identification. Conclusion The current study validates a robust method to confidently characterize the proteins from an incomplete sequence database of Macaca mulatta, using the PEAKS de novo sequencing software, facilitating the use of this animal model in various neuroproteomics studies.','https://doi.org/10.1186/1471-2164-8-270','BMC Genomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(394,'<i>De novo</i> sequencing of a 21‐kDa cytochrome <i>c</i><sub>4</sub> from <i>Thiocapsa roseopersicina</i> by nanoelectrospray ionization ion‐trap and Fourier‐transform ion‐cyclotron resonance mass spectrometry','2007-12-01','10.1002/jms.1337','Wiley','We have determined the primary structure of cytochrome c(4) from Thiocapsa roseopersicina by de novo protein sequencing using the ''bottom up'' approach. Three different enzymes (trypsin, endoproteinase Lys-C, and endoproteinase Glu-C) were employed to prepare four different sets of proteolytic digests. The digestion strategy was designed to permit a gradual buildup of smaller peptides into larger ones that were overlapped to yield the complete protein sequence. In this way we countered the main problem: peptides larger than about 1500 Da were difficult to sequence fully by tandem mass spectrometry. Direct infusion and online liquid chromatography were used on a linear ion trap Fourier-transform ion-cyclotron resonance hybrid instrument. The high resolving power, high mass accuracy and the availability of electron capture dissociation and collision-induced dissociation were essential to achieve full sequence coverage. The software DeNovoX complemented by manual interpretation was used to generate sequence information from tandem mass spectra. The predominantly automated nature of data acquisition and handling allowed for a relatively straightforward and fast procedure, which could compete with the mainstream alternative of nucleotide sequence determination.','https://doi.org/10.1002/jms.1337','Journal of Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(395,'Combining Bottom-Up and Top-Down Mass Spectrometric Strategies for De Novo Sequencing of the Crustacean Hyperglycemic Hormone from Cancer borealis','2009-01-01','10.1021/ac801910g','American Chemical Society (ACS)','The crustacean hyperglycemic hormone (CHH) is a 72-amino acid residue polypeptide with multiple physiological effects. The X-organ/sinus gland is the primary source for CHH and its family members. However, the amino acid sequence of CHH in Cancer borealis , a premier model system for neuromodulation, has not been characterized. In this study, a novel hybrid strategy combining "bottom-up" and "top-down" methodologies enabled direct sequencing of CHH peptide in the sinus gland of C. borealis . Multiple mass spectrometry (MS)-based techniques were employed to characterize the CHH peptide, including direct tissue analysis by MALDI-FT-ICR-MS, de novo sequencing of tryptic digested CHH by nano-LC/ESI-Q-TOF MS and intact CHH analysis by LC/FT-ICR-MS. In-trap cleaning removed the extensive matrix adducts of CHH in the direct tissue analysis by MALDI-FT-ICR-MS. Fragmentation efficiency of the intact CHH was drastically improved after the reduction-alkylation of the disulfide bonds. The sequence coverage was further enhanced by employing multiple complementary fragmentation techniques. Overall, this example is the largest neuropeptide de novo sequenced in C. borealis by mass spectrometric methods.','https://doi.org/10.1021/ac801910g','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(396,replace('<i>De novo</i>\n                    sequencing of two new cyclic\n                    <i>θ</i>\n                    ‐defensins from baboon (\n                    <i>Papio hamadryas</i>\n                    ) leukocytes by matrix‐assisted laser desorption/ionization mass spectrometry','\n',char(10)),'2010-03-15','10.1002/rcm.4424','Wiley','Two cyclic theta-defensin peptides were isolated from leukocytes of the hamadryas baboon, Papio hamadryas, and purified to homogeneity by gel electrophoresis and reversed-phase high-performance liquid chromatography. Both peptides had high in vitro activity against Escherichia coli, Listeria monocytogenes, methicillin-resistant Staphylococcus aureus (MRSA) and Candida albicans. Here, we report their de novo sequencing by matrix-assisted laser desorption/ionization tandem time-of-flight mass spectrometry (MALDI-TOF/TOF-MS). This was accomplished by combining conventional enzymatic digestion with N-terminal derivatization by 2-sulfobenzoic acid cyclic anhydride (SACA) or 4-sulfophenylisothiocyanate (SPITC) to facilitate the interpretation of fragment ion spectra. In addition to the two cyclic theta-defensins (PhTDs) we also sequenced a novel Papio hamadryas alpha-defensin, PhD-4, which showed high sequence homology to rhesus alpha-defensin RMAD-1 and human alpha-defensin HNP-1.','https://doi.org/10.1002/rcm.4424','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(397,'Top-Down <i>de Novo</i> Protein Sequencing of a 13.6 kDa Camelid Single Heavy Chain Antibody by Matrix-Assisted Laser Desorption Ionization-Time-of-Flight/Time-of-Flight Mass Spectrometry','2010-04-15','10.1021/ac1000515','American Chemical Society (ACS)','The primary structure of a 13.6 kDa single heavy chain camelid antibody (V(H)H) was determined by matrix-assisted laser desorption ionization-time-of-flight/time-of-flight (MALDI-TOF/TOF) top-down sequence analysis. The majority of the sequence was obtained by mass spectrometric de novo sequencing, with the N-terminal 14 amino acid residues being determined using T(3)-sequencing and database interrogation. The determined sequence was confirmed by liquid chromatography-tandem mass spectrometry (LC-MS/MS) analysis of a tryptic digest, which also provided high-energy collisionally induced dissociation (CID) data permitting the clear assignment of 3 of the 14 isobaric Leu/Ile residues. Five of the 11 Leu/Ile ambiguities could be resolved by homology comparisons with known V(H)H sequences. The monoisotopic molecular weight of the V(H)H was determined by ultrahigh-resolution orthogonal electrospray (ESI)-TOF analysis and found to be 13 610.6066 Da, in excellent agreement with the established sequence. To our knowledge, this is the first time that the entire primary structure of a protein with a molecular weight >13 kDa has been established by mass spectrometric top-down sequencing.','https://doi.org/10.1021/ac1000515','Analytical Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(398,'Analysis of Root Plasma Membrane Aquaporins from <i>Brassica oleracea</i>: Post-Translational Modifications, <i>de novo</i> Sequencing and Detection of Isoforms by High Resolution Mass Spectrometry','2010-07-02','10.1021/pr901150g','American Chemical Society (ACS)','Plasma membrane Intrinsic Proteins (PIPs), a subfamily of aquaporins, are ubiquitous membrane channel proteins that play a crucial role in water uptake in plants. The use of high-performance liquid chromatography coupled to tandem mass spectrometry (HPLC-MS/MS) analysis of peptides has previously shown to be a valuable tool to differentiate among PIP homologues sharing a high sequence homology and also to characterize their post-translational modifications (PTMs). The recent introduction of mass spectrometers able to measure peptide mass with high mass accuracy, together with new alternative ways of peptide fragmentation allows the identification and characterization of proteins from nonsequenced organisms, such as broccoli. In this study, we combined three endoproteases (trypsin, Glu-C and Lys-C) with HPLC-MS/MS analysis and two types of peptide fragmentations, CID (collision induced dissociation) and HCD (higher-energy C-trap dissociation), to identify PIP isoforms and PTMs from broccoli roots. After de novo sequencing analysis, eight peptides showing homology to Arabidopsis thaliana PIPs were identified. Although Arabidopsis nomenclature of PIP isoforms has not been defined for broccoli, our results agree with the occurrence of seven AtPIP isoforms (PIP 1;1, PIP 1;2, PIP 1;3 and PIP2;2, PIP 2;3, PIP2;1 and PIP2;7) in broccoli roots, as compared to the plant model A. thaliana. To our knowledge, these results represent the deepest characterization of the PIPs isolated from the roots of broccoli, a crop with increasing agronomical interest.','https://doi.org/10.1021/pr901150g','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(399,'Extensive <i>De Novo</i> Sequencing of New Parvalbumin Isoforms Using a Novel Combination of Bottom-Up Proteomics, Accurate Molecular Mass Measurement by FTICR−MS, and Selected MS/MS Ion Monitoring','2010-09-03','10.1021/pr100163e','American Chemical Society (ACS)','Parvalbumins (PRVB) (11.20-11.55 kDa) are considered the major fish allergens. In this work, we propose a novel strategy for extensive characterization of this group of proteins based on the integration of a classical Bottom-Up proteomics approach with accurate Mr determination by FTICR-MS of intact proteins and selected MS/MS ion monitoring (SMIM) of peptide mass gaps. For each PRVB, mass spectra obtained by LC-ESI-IT-MS/MS from two digests (trypsin, Glu-C) were de novo sequenced manually with help of two programs (PEAKS, DeNovoX). The deduced peptide sequences were arranged and the theoretical Mr for the resulting sequences was calculated. Experimental Mr for each PRVB was measured with high mass accuracy by FTICR-MS (0.05-4.47 ppm). The masses of several missing peptide gaps were estimated by comparing the theoretical and experimental Mr, and the MS/MS spectra corresponding to these ions were obtained by LC-ESI-IT-MS/MS in the SMIM scanning mode. Finally, all peptide sequences were combined to generate the final protein sequences. This approach allowed the complete de novo MS-sequencing of 25 new PRVB isoforms. These new sequences belong to 11 different species from the Merlucciidae family, organisms for which genomes remain unsequenced. This study constitutes the report accounting for the higher number of new proteins completely sequenced making use of MS-based techniques only.','https://doi.org/10.1021/pr100163e','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(400,'Resurrection of a clinical antibody: Template proteogenomic de novo proteomic sequencing and reverse engineering of an anti‐lymphotoxin‐α antibody','2011-02-01','10.1002/pmic.201000487','Wiley','A mouse hybridoma antibody directed against a member of the tumour necrosis factor (TNF)-superfamily, lymphotoxin-alpha (LT-α), was isolated from stored mouse ascites and purified to homogeneity. After more than a decade of storage the genetic material was not available for cloning; however, biochemical assays with the ascites showed this antibody against LT-α (LT-3F12) to be a preclinical candidate for the treatment of several inflammatory pathologies. We have successfully rescued the LT-3F12 antibody by performing MS analysis, primary amino acid sequence determination by template proteogenomics, and synthesis of the corresponding recombinant DNA by reverse engineering. The resurrected antibody was expressed, purified and shown to demonstrate the desired specificity and binding properties in a panel of immuno-biochemical tests. The work described herein demonstrates the powerful combination of high-throughput informatic proteomic de novo sequencing with reverse engineering to reestablish monoclonal antibody-expressing cells from archived protein sample, exemplifying the development of novel therapeutics from cryptic protein sources.','https://doi.org/10.1002/pmic.201000487','PROTEOMICS','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(401,'De novo sequencing of peptides from the parotid secretion of the cane toad, Bufo marinus (Rhinella marina)','2011-02-01','10.1016/j.toxicon.2010.11.012','Elsevier BV','Amphibian skin secretions are well known as a rich source of bioactive peptides. However, little is known about the presence or role of peptides in the highly toxic, parotid secretion of the cane toad or giant toad, Bufo marinus (Rhinella marina), though small molecule bufadienolides, which act as potent cardiotoxins, have been described. In the current study we used RP-HPLC, MALDI-TOF mass spectrometry and tandem mass spectrometry to analyze and determine the first sequences of peptides from the parotid secretion of B. marinus. We show that peptides in the range of 900-2500 Da are indeed present, however in extremely low abundance. Despite the low abundance, the sequences of 14 peptides were determined, several of which match fragments of larger cellular proteins, yet none share substantial homology with defensive or anti-microbial peptides reported from frog skin secretions. We conclude that peptides are present in the parotid glands of B. marinus only in very low quantities and that they are likely to be breakdown products of proteins involved in cell maintenance. Given these results, we conclude that peptides are unlikely to contribute directly to the high toxicity of the cane toad.','https://doi.org/10.1016/j.toxicon.2010.11.012','Toxicon','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(402,'Development of a host blood meal database: <i>de novo</i> sequencing of hemoglobin from nine small mammals using mass spectrometry','2012-03-01','10.1515/hsz-2011-0196','Walter de Gruyter GmbH','We report the successful de novo sequencing of hemoglobin using a mass spectrometry-based approach combined with automatic data processing and manual validation for nine North American species with currently unsequenced genomes. The complete α and β chain of all nine mammalian hemoglobin samples used in this study were successfully sequenced. These sequences will be appended to the existing database containing all known hemoglobins to be used for identification of the mammalian host species that provided the last blood meal for the tick vector of Lyme disease, Ixodes scapularis.','https://doi.org/10.1515/hsz-2011-0196','bchm','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(403,replace('<i>De novo</i>\n                    sequencing and characterization of a novel Bowman–Birk inhibitor from\n                    <i>Lathyrus sativus</i>\n                    L. seeds by electrospray mass spectrometry','\n',char(10)),'2012-09-19','10.1039/c2mb25241d','Oxford University Press (OUP)','Bowman-Birk serine protease inhibitors (BBIs) from legume seeds are small proteins showing a two-head structure with distinct reactive site loops, which inhibit two molecules of the same enzyme or two different proteases. Purification and characterization of new BBIs is of broad interest for understanding the basic molecular mechanisms underlying natural defence against the action of proteolytic enzymes. In this study, two novel acidic BBIs (LSI-1a and LSI-2a) were isolated from L. sativus seeds using classical biochemical techniques and characterized for their inhibitory activity. In addition, the N-terminal sequencing of LSI-1a was performed by Edman degradation up to residue 10 and the complete primary structure of the most abundant form (LSI-2a) was determined by using a combination of mass spectrometry approaches, including MALDI-TOF MS, tandem MS and Electron Transfer Dissociation coupled with Proton Transfer Reaction (ETD/PTR) top-down sequencing of N- and C-termini. Furthermore, the LSI-2a dimerization surface has also been investigated by a combination of gel filtration, electrophoretic techniques and homology modelling. Knowing the structure of small proteins inhibiting proteolytic enzymes is of general importance for understanding the defence mechanisms against degradation for their use in biological applications as well as for designing artificial inhibitors.','https://doi.org/10.1039/c2mb25241d','Molecular BioSystems','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(404,'Antimicrobial peptides from the skin of the Asian frog, Odorrana jingdongensis: De novo sequencing and analysis of tandem mass spectrometry data','2012-10-01','10.1016/j.jprot.2012.08.004','Elsevier BV','Eight intact antimicrobial peptides were identified from the skin of Odorrana jingdongensis by de novo sequencing following low energy ESI CID Q-TOF MS/MS in positive-mode with the help of Edman degradation and structural similarity analysis. We devised exact mass measurements to discriminate the K/Q amino acid residue in the peptides between 2.0 kDa to 3.8 kDa. Moreover, the cleavage at the CS bond at the side chain of Met was observed in all the spectra of the peptides containing Met residue. And we found unusual cleavages within the intramolecular disulfide loop with high frequency. Our data revealed that the cleavage pathways are significantly different from those reported previously which are similar to the cycle peptide cleavage mode followed by the secondary cleavage at the CS bond on oxidized Cys. Thus, our results highly suggest that ion series generated from the cleavages within the intramolecular disulfide loop should be considered in both the top-down sequencing and the disulfide bridge location with the presence of a relatively high intensity of MH(+)-28 ion marker. Furthermore, our activity data implied that different AMPs may use different strategies to kill microbes.','https://doi.org/10.1016/j.jprot.2012.08.004','Journal of Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(405,'High-definition De Novo Sequencing of Crustacean Hyperglycemic Hormone (CHH)-family Neuropeptides','2012-12-01','10.1074/mcp.m112.020537','Elsevier BV','A complete understanding of the biological functions of large signaling peptides (>4 kDa) requires comprehensive characterization of their amino acid sequences and post-translational modifications, which presents significant analytical challenges. In the past decade, there has been great success with mass spectrometry-based de novo sequencing of small neuropeptides. However, these approaches are less applicable to larger neuropeptides because of the inefficient fragmentation of peptides larger than 4 kDa and their lower endogenous abundance. The conventional proteomics approach focuses on large-scale determination of protein identities via database searching, lacking the ability for in-depth elucidation of individual amino acid residues. Here, we present a multifaceted MS approach for identification and characterization of large crustacean hyperglycemic hormone (CHH)-family neuropeptides, a class of peptide hormones that play central roles in the regulation of many important physiological processes of crustaceans. Six crustacean CHH-family neuropeptides (8-9.5 kDa), including two novel peptides with extensive disulfide linkages and PTMs, were fully sequenced without reference to genomic databases. High-definition de novo sequencing was achieved by a combination of bottom-up, off-line top-down, and on-line top-down tandem MS methods. Statistical evaluation indicated that these methods provided complementary information for sequence interpretation and increased the local identification confidence of each amino acid. Further investigations by MALDI imaging MS mapped the spatial distribution and colocalization patterns of various CHH-family neuropeptides in the neuroendocrine organs, revealing that two CHH-subfamilies are involved in distinct signaling pathways.','https://doi.org/10.1074/mcp.m112.020537','Molecular &amp; Cellular Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(406,replace('High‐resolution mass spectrometry and partial\n                    <i>de novo</i>\n                    sequencing constitute a useful approach for determining the profile of chemokine secretion following the stimulation of human intestinal epithelial cells','\n',char(10)),'2013-10-15','10.1002/rcm.6680','Wiley','Rationale Intestinal epithelial cells (IEC) secrete many chemokines in response to proinflammatory stimuli. We investigated their role in the mucosal inflammatory response in the intestine, by developing a non-targeted approach for analyzing the profile of peptides secreted by stimulated IEC, based on differential mass spectrometry analysis. Methods Lipopolysaccharide (LPS) was incubated with IEC as a proinflammatory stimulus. Differential peptidomic analysis was then carried out, comparing the profiles of IEC with and without LPS stimulation. A mass spectrometry procedure was developed, based on a liquid chromatography/tandem mass spectrometry (LC/MS/MS) approach without enzymatic pretreatment of the peptides. Partial de novo sequencing was carried out by Fourier transform ion cyclotron resonance (FTICR), and the native peptides in the culture media were identified. Results A major ion (m/z 7862.51) detected after stimulation was identified as GRO alpha and a minor ion (m/z 8918.17) was identified as IL-8. ELISA-based comparisons gave results consistent with those obtained by MS. Surprisingly, GRO alpha was secreted in amounts 5 to 15 times higher than those for IL-8 in our cellular model. The truncated form of IL-8, resulting from activation, was detected and distinguished from the native peptide by MS, whereas this was not possible with enzyme-linked immunosorbent assay (ELISA). Conclusions Mass spectrometric analysis of culture media can be used to identify the principal peptides produced in response to the stimulation of IEC, and their metabolites. Mass spectrometry provides a comprehensive view of the chemokines and peptides potentially involved in gut inflammation, making it possible to identify the most appropriate peptides for further quantification.','https://doi.org/10.1002/rcm.6680','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(407,'Mass Spectrometry Analysis Coupled with de novo Sequencing Reveals Amino Acid Substitutions in Nucleocapsid Protein from Influenza A Virus','2014-02-11','10.3390/ijms15022465','MDPI AG','Amino acid substitutions in influenza A virus are the main reasons for both antigenic shift and virulence change, which result from non-synonymous mutations in the viral genome. Nucleocapsid protein (NP), one of the major structural proteins of influenza virus, is responsible for regulation of viral RNA synthesis and replication. In this report we used LC-MS/MS to analyze tryptic digestion of nucleocapsid protein of influenza virus (A/Puerto Rico/8/1934 H1N1), which was isolated and purified by SDS poly-acrylamide gel electrophoresis. Thus, LC-MS/MS analyses, coupled with manual de novo sequencing, allowed the determination of three substituted amino acid residues R452K, T423A and N430T in two tryptic peptides. The obtained results provided experimental evidence that amino acid substitutions resulted from non-synonymous gene mutations could be directly characterized by mass spectrometry in proteins of RNA viruses such as influenza A virus.','https://doi.org/10.3390/ijms15022465','International Journal of Molecular Sciences','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(408,'Novel proline-hydroxyproline glycopeptides from the dandelion (Taraxacum officinale Wigg.) flowers: de novo sequencing and biological activity','2015-09-01','10.1016/j.plantsci.2015.07.002','Elsevier BV','Two novel homologous peptides named ToHyp1 and ToHyp2 that show no similarity to any known proteins were isolated from Taraxacum officinale Wigg. flowers by multidimensional liquid chromatography. Amino acid and mass spectrometry analyses demonstrated that the peptides have unusual structure: they are cysteine-free, proline-hydroxyproline-rich and post-translationally glycosylated by pentoses, with 5 carbohydrates in ToHyp2 and 10 in ToHyp1. The ToHyp2 peptide with a monoisotopic molecular mass of 4350.3Da was completely sequenced by a combination of Edman degradation and de novo sequencing via top down multistage collision induced dissociation (CID) and higher energy dissociation (HCD) tandem mass spectrometry (MS(n)). ToHyp2 consists of 35 amino acids, contains eighteen proline residues, of which 8 prolines are hydroxylated. The peptide displays antifungal activity and inhibits growth of Gram-positive and Gram-negative bacteria. We further showed that carbohydrate moieties have no significant impact on the peptide structure, but are important for antifungal activity although not absolutely necessary. The deglycosylated ToHyp2 peptide was less active against the susceptible fungus Bipolaris sorokiniana than the native peptide. Unique structural features of the ToHyp2 peptide place it into a new family of plant defense peptides. The discovery of ToHyp peptides in T. officinale flowers expands the repertoire of molecules of plant origin with practical applications.','https://doi.org/10.1016/j.plantsci.2015.07.002','Plant Science','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(409,'Mining Novel Allergens from Coconut Pollen Employing Manual <i>De Novo</i> Sequencing and Homology-Driven Proteomics','2015-11-06','10.1021/acs.jproteome.5b00657','American Chemical Society (ACS)','Coconut pollen, one of the major palm pollen grains is an important constituent among vectors of inhalant allergens in India and a major sensitizer for respiratory allergy in susceptible patients. To gain insight into its allergenic components, pollen proteins were analyzed by two-dimensional electrophoresis, immunoblotted with coconut pollen sensitive patient sera, followed by mass spectrometry of IgE reactive proteins. Coconut being largely unsequenced, a proteomic workflow has been devised that combines the conventional database-dependent analysis of tandem mass spectral data and manual de novo sequencing followed by a homology-based search for identifying the allergenic proteins. N-terminal acetylation helped to distinguish "b" ions from others, facilitating reliable sequencing. This led to the identification of 12 allergenic proteins. Cluster analysis with individual patient sera recognized vicilin-like protein as a major allergen, which was purified to assess its in vitro allergenicity and then partially sequenced. Other IgE-sensitive spots showed significant homology with well-known allergenic proteins such as 11S globulin, enolase, and isoflavone reductase along with a few which are reported as novel allergens. The allergens identified can be used as potential candidates to develop hypoallergenic vaccines, to design specific immunotherapy trials, and to enrich the repertoire of existing IgE reactive proteins.','https://doi.org/10.1021/acs.jproteome.5b00657','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(410,'A Proteomic Workflow Using High-Throughput De Novo Sequencing Towards Complementation of Genome Information for Improved Comparative Crop Science','2016-01-01','10.1007/978-1-4939-3341-9_17','Springer New York','The proteomic study of non-model organisms, such as many crop plants, is challenging due to the lack of comprehensive genome information. Changing environmental conditions require the study and selection of adapted cultivars. Mutations, inherent to cultivars, hamper protein identification and thus considerably complicate the qualitative and quantitative comparison in large-scale systems biology approaches. With this workflow, cultivar-specific mutations are detected from high-throughput comparative MS analyses, by extracting sequence polymorphisms with de novo sequencing. Stringent criteria are suggested to filter for confidential mutations. Subsequently, these polymorphisms complement the initially used database, which is ready to use with any preferred database search algorithm. In our example, we thereby identified 26 specific mutations in two cultivars of Pisum sativum and achieved an increased number (17 %) of peptide spectrum matches.','https://doi.org/10.1007/978-1-4939-3341-9_17','Methods in Molecular Biology','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(411,replace('LTQ Orbitrap Velos in routine\n                    <i>de novo</i>\n                    sequencing of non‐tryptic skin peptides from the frog\n                    <i>Rana latastei</i>\n                    with traditional and reliable manual spectra interpretation','\n',char(10)),'2016-01-30','10.1002/rcm.7436','Wiley','Rationale Mass spectrometry has shown itself to be the most efficient tool for the sequencing of peptides. However, de novo sequencing of novel natural peptides is significantly more challenging in comparison with the same procedure applied for the tryptic peptides. To reach the goal in this case it is essential to select the most efficient methods of triggering fragmentation and combine all the possible complementary techniques. Methods Collision-induced dissociation (CID), high-energy collision dissociation (HCD), and electron-transfer dissociation (ETD) tandem mass spectra recorded with a LTQ Orbitrap Velos instrument were used for the elucidation of the sequence of the natural non-tryptic peptides from the skin secretion of Rana latastei. Manual interpretation of the spectra was applied. Results The combined approach using CID, HCD, and ETD tandem mass spectra of the multiprotonated peptides in various charge states, as well as of their proteolytic fragments, allowed the sequences of seven novel peptides from the skin secretion of Rana latastei to be established. Conclusions Manual mass spectrometry sequencing of natural non-tryptic peptides from the skin secretion of Rana latastei provided the opportunity to work successfully with these species and demonstrated once again its advantage over automatic approaches.','https://doi.org/10.1002/rcm.7436','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(412,replace('De Novo Sequencing and Resurrection of a Human Astrovirus-Neutralizing\nAntibody','\n',char(10)),'2016-05-13','10.1021/acsinfecdis.6b00026','American Chemical Society (ACS)','Monoclonal antibody (mAb) therapeutics targeting cancer, autoimmune diseases, inflammatory diseases, and infectious diseases are growing exponentially. Although numerous panels of mAbs targeting infectious disease agents have been developed, their progression into clinically useful mAbs is often hindered by the lack of sequence information and/or loss of hybridoma cells that produce them. Here we combine the power of crystallography and mass spectrometry to determine the amino acid sequence and glycosylation modification of the Fab fragment of a potent human astrovirus-neutralizing mAb. We used this information to engineer a recombinant antibody single-chain variable fragment that has the same specificity as the parent monoclonal antibody to bind to the astrovirus capsid protein. This antibody can now potentially be developed as a therapeutic and diagnostic agent.','https://doi.org/10.1021/acsinfecdis.6b00026','ACS Infectious Diseases','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(413,'De novo protein sequencing, humanization and in vitro effects of an antihuman CD34 mouse monoclonal antibody','2017-03-01','10.1016/j.bbrep.2016.11.006','Elsevier BV','QBEND/10 is a mouse immunoglobulin lambda-chain monoclonal antibody with strict specificity against human hematopoietic progenitor cell antigen CD34. Our in vitro study showed that QBEND/10 impairs the tube formation of human umbilical vein endothelial cells (HUVECs), suggesting that the antibody may be of potential benefit in blocking tumor angiogenesis. We provided a de novo protein sequencing method through tandem mass spectrometry to identify the amino acid sequences in the variable heavy and light chains of QBEND/10. To reduce immunogenicity for clinical applications, QBEND/10 was further humanized using the resurfacing approach. We demonstrate that the de novo sequenced and humanized QBEND/10 retains the biological functions of the parental mouse counterpart, including the binding kinetics to CD34 and blockage of the tube formation of the HUVECs.','https://doi.org/10.1016/j.bbrep.2016.11.006','Biochemistry and Biophysics Reports','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(414,'Complete de novo sequencing of antimicrobial peptides in the venom of the scorpion Isometrus maculatus','2017-12-01','10.1016/j.toxicon.2017.09.010','Elsevier BV','Scorpion venom contains antimicrobial peptides (AMPs) in addition to neurotoxic peptides. Recent extensive transcriptomic analysis of venom glands of various scorpion species dramatically increased the number of identified AMPs. However, identification of peptides from genetic information requires reference sequences of similar peptides, and moreover, it is often difficult to predict post-translational modifications. In this study, we searched for unknown AMPs contained in the Isometrus maculatus scorpion venom based on the structural features, such as the hydrophobic nature and the lack of disulfide bonds, which are commonly observed in the majority of scorpion AMPs. Their primary structures were determined only by a de novo sequencing method using two types of MS instruments, which induce peptide fragmentation in a different fashion. Chemical derivatization techniques were also used to facilitate Leu/Ile discrimination. As a result, total 15 AMP candidates were discovered from the I. maculatus venom. Among them, three peptides were identified as AMPs by evaluating their biological activity. Other 12 candidate peptides were structurally related to the identified AMPs, possibly generated by enzymatic cleavage of the mature peptides in the venom.','https://doi.org/10.1016/j.toxicon.2017.09.010','Toxicon','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(415,'Proteome Based de novo Sequencing of Novel Conotoxins from Marine Molluscivorous Cone Snail Conus amadis and Neurological Activities of Its Natural Venom in Zebrafish Model','2019-10-24','10.2174/0929866526666190614144006','Bentham Science Publishers Ltd.','Background Conus amadis is a carnivorous snail found abundantly in coastal waters of India. Despite its abundance in southern coastal waters of India and the fact that most of the conotoxin act in neuronal system, research work on Conus amadis venom was not much focused. So we have made a brief study on the venom complex of Conus amadis to identify the library of novel conotoxins and to screen the natural venom for neurological function. Objective De novo sequencing of novel conopeptides from the venom cocktail of Conus amadis and to screen its natural venom for the presence of biological activities in zebrafish model. Methods Proteome based MALDI-TOF and LC-MS-MS analysis for identification of novel conotoxins and subsequent sequencing. Due to the complex disulfide rich nature of the venom peptides, the study also involves global chemical modification experiments of the venom extract to unambiguously determine the sequence of novel conotoxins. Biological function analysis of natural venom was tested in zebrafish model to ascertain anti-epileptic properties. Results In this study, we have identified 19 novel conotoxins containing 1, 2 & 3 disulfides, belonging to different classes. Among them, 2 novel contryphans, 3 T-superfamily conotoxins, 2 A-superfamily conotoxins and 2 Mini M-Superfamily conotoxins were sequenced to its amino acid level from the fragmented spectrum of singly and doubly charged parent ions using de novo sequencing strategies. ama1054, a contryphan peptide toxin, possesses post translationally modified bromo tryptophan at its seventh position. Except ama1251, all the sequenced peptide toxins possess modified C-terminal amidation. Crude venom exhibited anticonvulsant properties in pentylenetetrazole-induced seizure in zebrafish larvae, which suggested anti-epileptic property of the venom cocktail. Acetylcholinesterase activity was also identified in the venom complex. Conclusion Based on the preliminary evidence, if this study is extended further through bioassay guided purification, could possibly yield peptide toxins with anticonvulsant and other neurologically active molecules.','https://doi.org/10.2174/0929866526666190614144006','Protein &amp; Peptide Letters','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(416,'Generation of antioxidative peptides from Atlantic sea cucumber using alcalase versus trypsin: In vitro activity, de novo sequencing, and in silico docking for in vivo function prediction','2020-02-01','10.1016/j.foodchem.2019.125581','Elsevier BV','A comprehensive evaluation was conducted to compare the generation of antioxidative peptides produced by alcalase versus trypsin from Atlantic sea cucumber. The in vitro antioxidative peptides were sequenced by de novo sequencing using LC-MS/MS. Key constituent antioxidative amino acids (KCAAA), i.e., Cys, His, Met, Trp and Tyr in the peptides and the molecular interactions between peptides and myeloperoxidase (MPO, a mediator and marker of in vivo oxidative stress), were analyzed by in silico methods. Alcalase-produced protein hydrolysates showed 5-35% higher in vitro antioxidant activity than the trypsin-produced ones. UPLC analysis revealed the total amino acid composition in peptide fractions <2 kDa. Alcalase produced 35.4% of peptides with both KCAAA and potential MPO inhibitory activity, compared with only 30.3% for trypsin. A representative peptide sequence TEFHLL generated by alcalase had intense molecular interactions with MPO active site, predicting a capacity to inhibit in vivo oxidative stress.','https://doi.org/10.1016/j.foodchem.2019.125581','Food Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(417,replace('Complementary\nMethods for de Novo Monoclonal Antibody\nSequencing to Achieve Complete Sequence Coverage','\n',char(10)),'2020-07-02','10.1021/acs.jproteome.0c00223','American Chemical Society (ACS)','Mass spectrometry is a powerful tool for de novo sequencing of novel proteins. Recent efforts in this area have mainly focused on liquid chromatography coupled with tandem mass spectrometry (LC-MS/MS). Here, we present an alternative method, capillary electrophoresis tandem mass spectrometry (CE-MS/MS), for sequencing novel monoclonal antibodies. Using less than 200 ng in total of tryptic digest sample in a triplicated measurement, CE-MS/MS with pH-mediated focusing successfully sequenced mAb infliximab with 100% sequence coverage and 100% accuracy for the light chain and 96% coverage and 93% accuracy for the heavy chain. It was also demonstrated that CE-MS/MS gives comparable results, and in some cases, even better results, as compared to LC-MS/MS when used as a standalone technique. A combined workflow using both CE-MS/MS and LC-MS/MS was also used to sequence a novel antibody, anti-CD-176, resulting in the first proposed sequence for this mAb.','https://doi.org/10.1021/acs.jproteome.0c00223','Journal of Proteome Research','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(418,'Tri‐ and dipeptides identification in whey protein and porcine liver protein hydrolysates by fast LC–MS/MS neutral loss screening and <i>de novo</i> sequencing','2021-02-01','10.1002/jms.4701','Wiley','We describe a fast (5 min) liquid chromatography tandem mass spectrometry method (LC-MS/MS) based on a 46 Da neutral loss of formic acid (H 2 O and CO) to identify tri- and dipeptides (DIPEP) in whey protein and porcine liver protein hydrolysates and confirmed by further de novo sequencing. Sample solutions were acidified to favor [dipep + H] + ions, and a m/z range of 50-300 was used to improve sensitivity. All dipeptide candidates were selected based on all possibilities of the 20 amino acid combinations, and their collision-induced dissociation fragments were screened via de novo sequencing. To determine their biological activities, sequenced dipeptides were compared with the Biopep database and other data from literature. Altogether, 18 dipeptides and 7 tripeptides were identified from the whey protein hydrolysate; they seemed to be broadly active, and peptides were identified as active dipeptidyl peptidase IV inhibitors and active angiotensin-converting enzyme (ACE), according to available information. Porcine liver hydrolysate showed 14 dipeptides which exhibit similar biological activities to whey protein hydrolysate.','https://doi.org/10.1002/jms.4701','Journal of Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(419,replace('Manual mass spectrometry\n                    <i>de novo</i>\n                    sequencing of the anionic host defense peptides of the Cuban Treefrog\n                    <scp>\n                      <i>Osteopilus septentrionalis</i>\n                    </scp>','\n',char(10)),'2021-04-15','10.1002/rcm.9061','Wiley','Rationale Host defense peptides accumulated in the skin glands of the animals constitute the basis of the adaptive and immune system of amphibians. The peptidome of the Cuban frog Osteopilus septentrionalis was established using tandem mass spectrometry as the best analytical tool to elucidate the sequence of these peptides. Methods Manual interpretation of complementary collision-induced dissociation (CID), higher energy collision-induced dissociation (HCD), and electron transfer dissociation (ETD) tandem mass spectra recorded with an Orbitrap Elite mass spectrometer in liquid chromatography/mass spectrometry (LC/MS) mode was used to sequence the peptide components of the frog skin secretion, obtained by mild electrostimulation. Results Although the vast majority of amphibian peptides discovered so far are cationic, surprisingly only anionic peptides were identified in the skin secretion of the Cuban frog Osteopilus septentrionalis. Mass spectrometry allowed the sequences to be established of 16 representatives of new peptide families: septenins 1 and septenins 2. The highest sequence coverage when dealing with these anionic peptides was obtained with CID normalized collision energy 35 and HCD normalized collision energy 28. Conclusions Mirror-symmetrical peptides are sequenced using N-terminal acetylation. Acetylated Ser is reliably distinguished from isomeric Glu by the loss of ketene from b-ions containing the corresponding residue. Calculations of the physicochemical and structural properties of the discovered anionic septenins 1 and 2 allowed the mechanism of their interaction with microbe cells to be postulated.','https://doi.org/10.1002/rcm.9061','Rapid Communications in Mass Spectrometry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(420,replace('De novo sequencing and construction of a unique antibody for the recognition of alternative conformations of cytochrome\n                    <i>c</i>\n                    in cells','\n',char(10)),'2022-11-22','10.1073/pnas.2213432119','National Academy of Sciences','Cytochrome c (cyt c) can undergo reversible conformational changes under biologically relevant conditions. Revealing these alternative cyt c conformers at the cell and tissue level is challenging. A monoclonal antibody (mAb) identifying a key conformational change in cyt c was previously reported, but the hybridoma was rendered nonviable. To resurrect the mAb in a recombinant form, the amino-acid sequences of the heavy and light chains were determined by peptide mapping-mass spectrometry-bioinformatic analysis and used to construct plasmids encoding the full-length chains. The recombinant mAb (R1D3) was shown to perform similarly to the original mAb in antigen-binding assays. The mAb bound to a variety of oxidatively modified cyt c species (e.g., nitrated at Tyr74 or oxidized at Met80), which lose the sixth heme ligation (Fe-Met80); it did not bind to several cyt c phospho- and acetyl-mimetics. Peptide competition assays together with molecular dynamic studies support that R1D3 binds a neoepitope within the loop 40-57. R1D3 was employed to identify alternative conformations of cyt c in cells under oxidant- or senescence-induced challenge as confirmed by immunocytochemistry and immunoaffinity studies. Alternative conformers translocated to the nuclei without causing apoptosis, an observation that was further confirmed after pinocytic loading of oxidatively modified cyt c to B16-F1 cells. Thus, alternative cyt c conformers, known to gain peroxidatic function, may represent redox messengers at the cell nuclei. The availability and properties of R1D3 open avenues of interrogation regarding the presence and biological functions of alternative conformations of cyt c in mammalian cells and tissues.','https://doi.org/10.1073/pnas.2213432119','Proceedings of the National Academy of Sciences','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(421,'Tandem Mass Spectrometry de novo Sequencing of the Skin Defense Peptides of the Central Slovenian Agile Frog Rana dalmatina','2023-10-16','10.3390/molecules28207118','MDPI AG','Peptides released on frogs'' skin in a stress situation represent their only weapon against micro-organisms and predators. Every species and even population of frog possesses its own peptidome being appropriate for their habitat. Skin peptides are considered potential pharmaceuticals, while the whole peptidome may be treated as a taxonomic characteristic of each particular population. Continuing the studies on frog peptides, here we report the peptidome composition of the Central Slovenian agile frog Rana dalmatina population. The detection and top-down de novo sequencing of the corresponding peptides was conducted exclusively by tandem mass spectrometry without using any chemical derivatization procedures. Collision-induced dissociation (CID), higher energy collision-induced dissociation (HCD), electron transfer dissociation (ETD) and combined MS 3 method EThcD with stepwise increase of HCD energy were used for that purpose. MS/MS revealed the whole sequence of the detected peptides including differentiation between isomeric Leu/Ile, and the sequence portion hidden in the disulfide cycle. The array of the discovered peptide families (brevinins 1 and 2, melittin-related peptides (MRPs), temporins and bradykinin-related peptides (BRPs)) is quite similar to that of R . temporaria. Since the genome of this frog remains unknown, the obtained results were compared with the recently published transcriptome of R . dalmatina .','https://doi.org/10.3390/molecules28207118','Molecules','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(422,'Identification and Molecular Mechanism of Novel Two-Way Immunomodulatory Peptides from Ovalbumin: In Vitro Cell Experiments, De Novo Sequencing, and Molecular Docking','2024-05-01','10.1021/acs.jafc.4c00203','American Chemical Society (ACS)','The purpose of this study was to identify ovalbumin-derived immunomodulatory peptides by in vitro cell experiments, de novo sequencing, and molecular docking. Ovalbumin hydrolysates were prepared by two enzymes (alkaline protease and papain) individually, sequentially, or simultaneously, respectively. The simultaneous enzymatic hydrolysate (OVAH) had a high degree of hydrolysis (38.12 ± 0.48%) and exhibited immune-enhancing and anti-inflammatory activities. A total of 160 peptides were identified by LC-MS/MS in OVAH. Three novel peptides NVMEERKIK, ADQARELINS, and WEKAFKDE bound to TLR4-MD2 through hydrogen bonds and hydrophobic interactions with high binding affinity and binding energies of -181.40, -178.03, and -168.12 kcal/mol, respectively. These three peptides were synthesized and validated for two-way immunomodulatory activity. NVMEERKIK exhibiting the strongest immunomodulatory activity, increased NO and TNF-α levels by 128.69 and 38.01%, respectively, in normal RAW264.7 cells and reduced NO and TNF-α levels by 27.31 and 39.13%, respectively, in lipopolysaccharide-induced inflammatory RAW264.7 cells. Overall, this study first revealed that ovalbumin could be used as an immunomodulatory source for controlling inflammatory factor secretion.','https://doi.org/10.1021/acs.jafc.4c00203','Journal of Agricultural and Food Chemistry','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(423,'Reverse-engineering the anti-MUC1 antibody 139H2 by mass spectrometry–based de novo sequencing','2024-06-01','10.26508/lsa.202302366','Life Science Alliance, LLC','Mucin 1 (MUC1) is a transmembrane mucin expressed at the apical surface of epithelial cells at mucosal surfaces. MUC1 has a barrier function against bacterial invasion and is well known for its aberrant expression and glycosylation in adenocarcinomas. The MUC1 extracellular domain contains a variable number of tandem repeats (VNTR) of 20 amino acids, which are heavily O -linked glycosylated. Monoclonal antibodies against the MUC1 VNTR are powerful research tools with applications in the diagnosis and treatment of MUC1-expressing cancers. Here, we report direct mass spectrometry-based sequencing of anti-MUC1 hybridoma-derived 139H2 IgG, enabling reverse-engineering of the functional recombinant monoclonal antibody. The crystal structure of the 139H2 Fab fragment in complex with the MUC1 epitope was solved, revealing the molecular basis of 139H2 binding specificity to MUC1 and its tolerance to O -glycosylation of the VNTR. The available sequence of 139H2 will allow further development of MUC1-related diagnostic, targeting, and treatment strategies.','https://doi.org/10.26508/lsa.202302366','Life Science Alliance','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(424,'Mass spectrometry-based de novo sequencing reveals non-canonical neoantigens with antitumor efficacy in hepatocellular carcinoma','2026-04-01','10.1016/j.jhepr.2026.101775','Elsevier BV','Background & aims Tumor neoantigens, especially cryptic antigens from non-canonical translation, are vital for cancer immunotherapy. Mass spectrometry (MS)-based de novo sequencing identifies candidates, but unverified immunogenicity and antitumor efficacy limit clinical applicability. This study aimed to identify novel non-canonical neoantigens in hepatocellular carcinoma (HCC) using MS-based de novo sequencing and rigorously validate their immunogenicity and antitumor efficacy. Methods Using a C57BL/6 subcutaneous HCC mouse model, immunopeptides were comprehensively profiled via MHC-I immunoprecipitation combined with MS-based de novo sequencing. Identified high-immunogenicity peptides predicted by deep learning were validated using ex vivo ELISpot assays. Endogenous peptide expression was confirmed using parallel reaction monitoring-targeted quantification. The antitumor efficacy of therapeutic peptide vaccines comprising the seven most immunogenic peptides combined with the adjuvant poly(I:C) was evaluated in vivo in the subcutaneous and orthotopic HCC models. Results We identified 5,576 immunopeptides, with sequence motifs consistent with prior reports. Remarkably, 95% of deep learning-predicted high-immunogenicity peptides were successfully validated by ELISpot (p Conclusions MS-based de novo sequencing combined with computational prioritization enables identification of non-canonical, immunogenic neoantigens in HCC. Selected peptides demonstrated endogenous presentation and measurable antitumor activity in preclinical models. Impact and implications This study provides robust experimental validation that mass spectrometry-based de novo sequencing effectively identifies novel, highly immunogenic non-canonical neoantigens in hepatocellular carcinoma, overcoming a key limitation of prior predictive methods and opening avenues for exploring this understudied neoantigen class in other cancers. The findings are critical for cancer immunologists and oncologists developing next-generation immunotherapies, demonstrating a viable discovery-to-validation pipeline for novel therapeutic targets. The validated neoantigens and successful peptide vaccine strategy offer a direct pathway towards developing personalized hepatocellular carcinoma immunotherapies, enabling clinicians to adopt similar integrated approaches for patient-specific neoantigen discovery; however, clinical translation beyond this preclinical murine model requires confirmation in human settings due to potential differences in HLA presentation and the tumor microenvironment.','https://doi.org/10.1016/j.jhepr.2026.101775','JHEP Reports','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(425,'A perspective toward mass spectrometry-based de novo sequencing of endogenous antibodies','2022-12-31','10.1080/19420862.2022.2079449','Informa UK Limited','A key step in therapeutic and endogenous humoral antibody characterization is identifying the amino acid sequence. So far, this task has been mainly tackled through sequencing of B-cell receptor (BCR) repertoires at the nucleotide level. Mass spectrometry (MS) has emerged as an alternative tool for obtaining sequence information directly at the - most relevant - protein level. Although several MS methods are now well established, analysis of recombinant and endogenous antibodies comes with a specific set of challenges, requiring approaches beyond the conventional proteomics workflows. Here, we review the challenges in MS-based sequencing of both recombinant as well as endogenous humoral antibodies and outline state-of-the-art methods attempting to overcome these obstacles. We highlight recent examples and discuss remaining challenges. We foresee a great future for these approaches making de novo antibody sequencing and discovery by MS-based techniques feasible, even for complex clinical samples from endogenous sources such as serum and other liquid biopsies.','https://doi.org/10.1080/19420862.2022.2079449','mAbs','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(426,'Validation of De Novo Peptide Sequences with Bottom-Up Tag Convolution','2021-12-29','10.3390/proteomes10010001','MDPI AG','De novo sequencing is indispensable for the analysis of proteins from organisms with unknown genomes, novel splice variants, and antibodies. However, despite a variety of methods developed to this end, distinguishing between the correct interpretation of a mass spectrum and a number of incorrect alternatives often remains a challenge. Tag convolution is computed for a set of peptide sequence tags of a fixed length k generated from the input tandem mass spectra and can be viewed as a generalization of the well-known spectral convolution. We demonstrate its utility for validating de novo peptide sequences by using a set of those generated by the algorithm PepNovo+ from high-resolution bottom-up data sets for carbonic anhydrase 2 and the Fab region of alemtuzumab and indicate its further potential applications.','https://doi.org/10.3390/proteomes10010001','Proteomes','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(427,'Can we Confidently Sequence the „Peptide Dark Matter“? Reaching a Consensus for De Novo Peptide Sequencing','2026-09-24','10.17952/38eps.2026.p270','The European Peptide Society',NULL,'https://doi.org/10.17952/38eps.2026.p270','Proceedings of the 38th European Peptide Symposium','presentation',NULL,NULL);
INSERT INTO publication VALUES(428,'Mass Spectrometry-Based De Novo Sequencing of N-Glycosylated Light Chains: Linking Urinary Proteoforms to In Situ Renal Amyloid Deposits','2026-09-01','10.1016/j.mcpro.2026.101652','Elsevier BV','Systemic immunoglobulin light-chain (AL) amyloidosis is characterized by clonal immunoglobulin-secreting cells that produce a monoclonal light chain prone to misfolding and amyloid fibril formation in tissues. Understanding its molecular basis requires accurate full-length sequencing of amyloidogenic light chains and linkage of circulating light chains to renal deposits. Achieving this is technically challenging because the low abundance and N-glycosylation of amyloidogenic light chains can complicate protein purification and peptide-level sequence analysis. To address these challenges, we implemented a robust analytical pipeline that integrates intact-mass measurement by Q-TOF MS before and after deglycosylation with multi-protease digestion and de novo peptide sequencing to systematically characterize urinary N-glycosylated light chains. Mass shifts observed before and after deglycosylation supported the presence of N-glycosylation, whereas deglycosylated intact masses were used to constrain full-length sequence assembly. The assembled urinary light-chain sequences were subsequently compared with matched renal amyloid proteomes isolated by laser microdissection and analyzed by bottom-up liquid chromatography-tandem mass spectrometry (LC-MS/MS). Enzymatic deglycosylation reduced glycan-induced spectral interference. Eight monoclonal light-chain sequences were assembled from urinary light chains, including five derived from the immunoglobulin kappa variable 1 (IGKV1), two from the immunoglobulin lambda variable 2 (IGLV2), and one from IGKV4. The close agreement between theoretical and experimental intact masses confirmed the accuracy and completeness of sequence assembly. In each renal amyloid proteome, the corresponding urine-derived sequence had the highest score among light-chain identifications of the patient''s clinically determined isotype (κ or λ) and showed 87.6% to 100% variable-region peptide coverage. Together, these findings support urinary N-glycosylated monoclonal light chains as the precursor proteins of the corresponding renal amyloid fibrils. In conclusion, we have demonstrated a robust workflow that applies established de novo peptide sequencing to characterize urinary N-glycosylated light chains and trace the corresponding sequences in renal amyloid deposits, with potential applications across light chain-related diseases.','https://doi.org/10.1016/j.mcpro.2026.101652','Molecular & Cellular Proteomics','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(429,'From polyclonal to monoclonal: de novo sequencing of goat antibodies for a standardized ApoA-I immunoturbidimetric assay','2026-05-12','10.1186/s13036-026-00697-y','Springer Science and Business Media LLC','Antibodies serve as essential recognition elements in in vitro diagnostics (IVD), yet reliance on polyclonal antibodies (pAbs) introduces significant challenges related to batch-to-batch consistency. To address this, we employed a de novo sequencing platform, which identified 15 candidate monoclonal antibody (mAb) sequences. From these, four distinct mAb mixtures were formulated and evaluated. Using an immunoturbidimetric assay to quantify apolipoprotein A-I (ApoA-I) in 105 human serum samples, the performance of these mixtures was compared to that of a conventional pAb reagent. The four-mAb mixture demonstrated excellent correlation with the pAb assay (Passing-Bablok: y = 1.0536x-0.0748 g/L; r 2 = 0.994). This optimized cocktail successfully replaced the pAb reagent, matching or exceeding its performance in key analytical parameters including linearity, sensitivity, and precision. Our work thus establishes a practical pathway for converting heterogeneous pAbs into defined, recombinant antibody reagents suitable for standardized IVD applications.','https://doi.org/10.1186/s13036-026-00697-y','Journal of Biological Engineering','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(430,'Deep coverage and extended sequence reads obtained with a single archaeal protease expedite de novo protein sequencing by mass spectrometry','2026-03-11','10.1016/j.cels.2026.101536','Elsevier BV','The ability to sequence proteins without reliance on a genomic template defines a critical frontier in proteomics. This approach, known as de novo protein sequencing, is essential for applications in antibody sequencing, microbiome proteomics, and antigen discovery, which require accurate reconstruction of target sequences. To advance this field, we here explore two hyperthermoacidic archaeal (HTA) proteases for de novo antibody sequencing, benchmarking them against trypsin and chymotrypsin. Each HTA-protease generated about five times more unique peptide reads than trypsin or chymotrypsin, providing high redundancy across all complementarity-determining regions. Combined with EAciD fragmentation on a ZenoTOF, this methodology enabled complete, unambiguous antibody sequencing. De novo analysis showed much higher alignment scores and reduced the sequence errors by using the HTA-generated data. With short digestion times, minimal sample cleanup, and analysis in just a single liquid chromatography-mass spectrometry (LC-MS/MS) run, this streamlined single-protease approach delivers a scalable and efficient strategy for de novo protein sequencing across diverse applications. A record of this paper''s transparent peer review process is included in the supplemental information.','https://doi.org/10.1016/j.cels.2026.101536','Cell Systems','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(431,'Mapping protein variants associated with Alzheimer''s disease by mass-spectrometry based de novo sequencing assisted strategy','2026-03-01','10.1177/13872877251414414','SAGE Publications','BackgroundAlzheimer''s disease (AD) is an incurable neurodegenerative disease with poorly understood pathogenesis. Understanding changes in protein sequences due to amino acid substitutions (AASs) may be important for uncovering molecular mechanisms of this disease.ObjectiveThe study aimed at developing a bioinformatic pipeline for searching AASs in proteomic data and revealing the AD-specific ones, highlighting potential biomarkers and/or therapeutic targets.MethodsThe developed pipeline integrates peptide de novo sequencing approach, database searches, and retention time prediction. It was applied to a large collection of AD proteomic data from global consortium studies obtained for post-mortem brain tissue samples.ResultsProteins with identified AASs were clustered by functionality. Proteins heavily enriched with AASs were the ones associated with ion transport activity, ATP binding, and G-protein signaling, aligning with known AD mechanisms. Further we classified the identified AASs by their origin (tRNA misacylation, post-translational modifications, single nucleotide polymorphisms) and by Braak stage and sex. Pathogenicity analysis, cross-referenced with clinical information, identified pathogenic mutations in HBD (W38S), GFAP (N77D), and NEFL (N98D).ConclusionsThe developed pipeline successfully maps disease-relevant protein variants by uncovering novel molecular features of a disease with biomarker and therapeutic potential. AASs identified in the work for AD samples reveal specific pathogenic mutations and implicate important biological processes.','https://doi.org/10.1177/13872877251414414','Journal of Alzheimer''s Disease','peer-reviewed',NULL,'europepmc');
INSERT INTO publication VALUES(432,'LIPNovo+: Self-Reflective Latent Imputation for Robust De Novo Peptide Sequencing','2026-06-06','10.2139/ssrn.6890054','Elsevier BV (SSRN)','De novo peptide sequencing is an important pattern recognition task in computational proteomics, enabling direct identification of peptide sequences from tandem mass spectrometry (MS/MS) data for biomarker discovery, antibody characterization, and analysis of peptides absent from reference databases. State-of-the-art models encode observed spectra into latent representations for peptide prediction. However, the issue of missing fragmentation, attributable to factors such as suboptimal fragmentation efficiency and instrumental constraints, presents a formidable challenge in practical applications. To tackle this obstacle, we propose Latent Imputation before Prediction (LIPNovo), a new computational paradigm that compensates for missing fragmentation information before peptide prediction. Instead of generating raw missing data, LIPNovo performs imputation in the latent space, guided by the theoretical peak profile of the target peptide. The imputation process is formulated as a set-prediction problem, where learnable peak queries reason over observed peaks and generate latent representations of theoretical peaks through optimal bipartite matching. To move beyond static missingness patterns seen during training, we further propose LIPNovo+, a self-reflective extension that identifies fragmentation sites with unreliable latent imputation and refocuses learning on these vulnerable regions through a reflection-guided curriculum. Across four benchmark datasets, LIPNovo and LIPNovo+ consistently outperform state-of-the art methods, with gains of up to +15% in peptide precision. Code is available at https://github.com/usr922/LIPNovo.','https://doi.org/10.2139/ssrn.6890054','SSRN Electronic Journal','preprint',NULL,'crossref');
INSERT INTO publication VALUES(433,'RT-GCTnovo: A Peptide De Novo Sequencing Model Incorporating Gated Multi-scale Features and Dynamic Mass Masks','2025-10-25','10.1109/cisp-bmei68103.2025.11259319','Institute of Electrical and Electronics Engineers (IEEE)','De novo peptide sequencing infers amino acid sequences directly from tandem mass spectra without relying on protein databases. This paper present RT-GCTnovo, a model that integrates multi-scale feature extraction, gated fusion, and dynamic decoding to improve sequencing accuracy. The model employs Transformer encoders and convolutional neural networks to capture global and local spectral features, enhanced by retention time information as a new constraint. A sigmoid gating mechanism adaptively fuses these features, and a semiautoregressive decoder with dynamic mass masking iteratively refines predictions. Experimental results on multispecies datasets show that RT-GCTnovo outperforms DeepNovo, Casanovo, and TSARseqNovo, achieving 57.7 % peptide-level accuracy and 79.8% amino acid-level accuracy.','https://doi.org/10.1109/cisp-bmei68103.2025.11259319','2025 18th International Congress on Image and Signal Processing, BioMedical Engineering and Informatics (CISP-BMEI)','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(434,'Protein Language Model-Aligned Spectra Embeddings for De Novo Peptide Sequencing','2025-10-03','10.1101/2025.10.01.679857','Cold Spring Harbor Laboratory','We consider the problem of de novo peptide sequencing in tandem mass spectrometry, where the goal is to predict the underlying peptide sequence given a spectrum’s fragment peaks and precursor information. We present PLMNovo, a constrained learning framework that leverages pre-trained protein language models (PLMs) to guide the training process. In particular, we cast peptide-spectrum matching as a constrained optimization problem that enforces alignment between spectrum and peptide embeddings produced by a spectrum encoder and a PLM, respectively. We use a Lagrangian primal-dual algorithm to train the spectrum encoder and the peptide decoder by solving the proposed constrained learning problem, while optionally fine-tuning the pre-trained PLM. Through numerical experiments on established benchmarks, we demonstrate that PLMNovo outperforms several state-of-the-art deep learning-based de novo sequencing algorithms.','https://doi.org/10.1101/2025.10.01.679857','bioRxiv','preprint',NULL,'europepmc');
INSERT INTO publication VALUES(435,'A procedure for controlling the false discovery rate of de novo peptide sequencing','2025-09-17','10.1101/2025.09.12.675837','Cold Spring Harbor Laboratory','De novo sequencing is a powerful method for identifying peptides from mass spectrometry proteomics experiments without the use of a protein database. However, applications of de novo sequencing are currently severely limited by the lack of a reliable procedure for controlling the false discovery rate (FDR). Here, we introduce an FDR control procedure for the de novo setting which is at least as powerful as database search, give empirical evidence that it is statistically valid, and demonstrate its utility on a set of common de novo applications.','https://doi.org/10.1101/2025.09.12.675837','bioRxiv','preprint',NULL,'europepmc');
INSERT INTO publication VALUES(436,'Computer program PAAS for the estimation of possible amino acid sequence of peptides','1981-04-01','10.1002/bms.1200080402','Wiley','This paper presents a computer program to determine all the possible combinations of amino acid residues in a peptide with a fixed molecular weight. The program can also give the sequence of a peptide using the results of PTH amino acids released by Edman degradation.','https://onlinelibrary.wiley.com/doi/10.1002/bms.1200080402','Biological Mass Spectrometry','peer-reviewed',NULL,'openalex');
INSERT INTO publication VALUES(437,'Improved PAAS, a computer program to determine possible amino acid sequences of peptides','1983-02-01','10.1002/bms.1200100202','Wiley','The computer program PAAS has been in use for about two years and recently several useful features have been added, which help to predict and interpret mass spectra of peptides and their residues particularly for determining amino acid sequences.','https://onlinelibrary.wiley.com/doi/10.1002/bms.1200100202','Biological Mass Spectrometry','peer-reviewed',NULL,'openalex');
