PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE author (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT
, scholar_id TEXT, disambiguator TEXT, sciprofiles_id TEXT, orcid TEXT, openalex_id TEXT);
CREATE TABLE country (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE
, iso2 TEXT);
CREATE TABLE city (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    country_id INTEGER, lat REAL, lng REAL, lat_source TEXT, lng_source TEXT,
    FOREIGN KEY (country_id) REFERENCES country(id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);
CREATE TABLE affiliation (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    department TEXT,
    country_id INTEGER,
    city_id INTEGER, ror TEXT, canonical_name TEXT, name_source TEXT, department_source TEXT, geo_source TEXT,
    UNIQUE (name, department),
    FOREIGN KEY (country_id) REFERENCES country(id)
        ON DELETE SET NULL
        ON UPDATE CASCADE,
    FOREIGN KEY (city_id) REFERENCES city(id)
        ON DELETE SET NULL
        ON UPDATE CASCADE
);
CREATE TABLE author_affiliation (
    author_id INTEGER, -- NOT NULL,
    affiliation_id INTEGER, -- NOT NULL,
    PRIMARY KEY (author_id, affiliation_id),
    FOREIGN KEY (author_id) REFERENCES author(id)
        ON DELETE CASCADE,
    FOREIGN KEY (affiliation_id) REFERENCES affiliation(id)
        ON DELETE CASCADE
);
CREATE TABLE algorithm (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    documentation TEXT,
    website TEXT
, algorithm_family TEXT, short_description TEXT, kind TEXT, is_deep_learning INTEGER, acquisition_mode TEXT, aliases TEXT, subdomain TEXT);
CREATE TABLE publication (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    publication_date DATE,
    doi TEXT UNIQUE,
    publisher TEXT,
    abstract TEXT,
    url TEXT,
    journal TEXT,
    publication_type TEXT NOT NULL -- 'preprint' or 'peer-reviewed'
, version TEXT, abstract_source TEXT);
CREATE TABLE publication_author (
    publication_id INTEGER NOT NULL,
    author_id INTEGER NOT NULL,
    author_order INTEGER NOT NULL,
    PRIMARY KEY (publication_id, author_id),
    FOREIGN KEY (publication_id) REFERENCES publication(id)
        ON DELETE CASCADE,
    FOREIGN KEY (author_id) REFERENCES author(id)
        ON DELETE CASCADE
);
CREATE TABLE journal_impact (
    journal           TEXT PRIMARY KEY,
    openalex_id       TEXT,
    two_yr_citedness  REAL,
    h_index           INTEGER,
    works_count       INTEGER,
    year_collected    INTEGER NOT NULL
);
CREATE TABLE algorithm_repository (
  algorithm_id INTEGER NOT NULL
      REFERENCES algorithm(id) ON DELETE CASCADE,
  url          TEXT NOT NULL,
  sort_order   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (algorithm_id, url)
);
CREATE TABLE publication_impact (
            publication_id INTEGER PRIMARY KEY,
            openalex_id TEXT,
            cited_by_count INTEGER,
            match_method TEXT NOT NULL,
            match_score REAL,
            year_collected INTEGER NOT NULL,
            fetched_at TEXT NOT NULL,
            FOREIGN KEY (publication_id) REFERENCES publication(id)
                ON DELETE CASCADE
                ON UPDATE CASCADE
        );
CREATE TABLE publication_version (
            preprint_id  INTEGER NOT NULL
                REFERENCES publication(id) ON DELETE CASCADE ON UPDATE CASCADE,
            published_id INTEGER NOT NULL
                REFERENCES publication(id) ON DELETE CASCADE ON UPDATE CASCADE,
            source       TEXT NOT NULL,  -- 'biorxiv' | 'crossref' | 'title' | 'manual'
            PRIMARY KEY (preprint_id, published_id)
        );
CREATE TABLE thesis_supervisor (
    publication_id INTEGER NOT NULL
        REFERENCES publication(id) ON DELETE CASCADE ON UPDATE CASCADE,
    author_id      INTEGER NOT NULL
        REFERENCES author(id) ON DELETE CASCADE ON UPDATE CASCADE,
    PRIMARY KEY (publication_id, author_id)
);
CREATE TABLE publication_author_affiliation (
            publication_id INTEGER NOT NULL REFERENCES publication(id) ON DELETE CASCADE,
            author_id      INTEGER NOT NULL REFERENCES author(id)      ON DELETE CASCADE,
            affiliation_id INTEGER NOT NULL REFERENCES affiliation(id) ON DELETE CASCADE,
            position       INTEGER NOT NULL DEFAULT 0,
            source         TEXT,
            PRIMARY KEY (publication_id, author_id, affiliation_id)
        );
CREATE TABLE publication_algorithm (
    publication_id INTEGER NOT NULL,
    algorithm_id INTEGER NOT NULL,
    -- What the paper does with the method.
    --   'describes': introduces, defines, extends or documents it. Includes a
    --                later version of the same work (preprint and version of
    --                record both describe), and a follow-up method paper by the
    --                same group.
    --   'uses':      applies it, or reports results from it, while the method
    --                itself is described elsewhere. The venomics papers that run
    --                PEAKS are the typical case.
    -- Defaults to 'describes', which is the common case, so an INSERT that
    -- predates this column still means what it meant. A 'uses' link has to
    -- say so. (No count here on purpose: nothing can check a comment inside
    -- the schema, and check_counts.py keeps the split honest in CLAUDE.md.)
    role TEXT NOT NULL DEFAULT 'describes'
        CHECK (role IN ('describes', 'uses')),
    PRIMARY KEY (publication_id, algorithm_id),
    FOREIGN KEY (publication_id) REFERENCES publication(id)
        ON DELETE CASCADE,
    FOREIGN KEY (algorithm_id) REFERENCES algorithm(id)
        ON DELETE CASCADE
);
CREATE TABLE benchmark_tool (
    tool         TEXT PRIMARY KEY,  -- upstream algorithms/<tool> folder
    display_name TEXT NOT NULL,     -- this catalog's name for it, where known
    algorithm_id INTEGER REFERENCES algorithm(id) ON DELETE SET NULL,
    version      TEXT NOT NULL,     -- the version the site's numbers come from
    n_datasets   INTEGER NOT NULL   -- < the total means partial coverage
);
CREATE TABLE benchmark_curve (
    tool      TEXT NOT NULL REFERENCES benchmark_tool(tool) ON DELETE CASCADE,
    level     TEXT NOT NULL,     -- 'peptide' | 'amino acid'
    coverage  REAL NOT NULL,
    precision REAL NOT NULL,     -- dataset-macro-averaged at this coverage
    PRIMARY KEY (tool, level, coverage)
);
CREATE TABLE benchmark_source (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE benchmark_result (
    dataset    TEXT NOT NULL REFERENCES benchmark_dataset(name) ON DELETE CASCADE,
    tool       TEXT NOT NULL REFERENCES benchmark_tool(tool) ON DELETE CASCADE,
    version    TEXT NOT NULL,
    ap_peptide REAL,              -- area under the peptide precision-coverage curve
    ap_aa      REAL,              -- ... and the amino-acid one
    -- 1 on the newest version of this tool that ran on this dataset. The rule
    -- lives in version_key() and is not expressible in SQL, so it is applied
    -- once here and the site filters on the flag.
    is_latest  INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (dataset, tool, version)
);
CREATE TABLE benchmark_dataset (
    name      TEXT PRIMARY KEY,  -- upstream results/<name> folder
    category  TEXT NOT NULL,     -- derived from the name, see categorize()
    cat_group TEXT NOT NULL,     -- the coarser grouping the heatmap labels
    n_tools   INTEGER NOT NULL
);
CREATE TABLE proteobench_submission (
    id           TEXT PRIMARY KEY,  -- ProteoBench's own run id, name + timestamp
    hash         TEXT NOT NULL,     -- intermediate_hash, which names the result file
    software     TEXT NOT NULL,     -- as submitted
    version      TEXT,
    display_name TEXT NOT NULL,     -- this catalog's name for it, where known
    algorithm_id INTEGER REFERENCES algorithm(id) ON DELETE SET NULL,
    decoding     TEXT,              -- decoding_strategy, e.g. 'beam search'
    checkpoint   TEXT,              -- model weights used, where given
    pb_version   TEXT,              -- the ProteoBench version that scored it
    n_spectra    INTEGER,
    submitted    TEXT               -- parsed out of the id, YYYY-MM-DD
);
CREATE TABLE proteobench_metric (
    submission_id TEXT NOT NULL
        REFERENCES proteobench_submission(id) ON DELETE CASCADE,
    level      TEXT NOT NULL,  -- 'peptide' | 'aa'
    match_type TEXT NOT NULL,  -- 'mass' (within 0.1 Da) | 'exact' (sequence)
    precision  REAL,           -- correct / predictions made
    recall     REAL,           -- correct / all spectra = precision at coverage 1
    coverage   REAL,           -- predictions made / all spectra
    auc        REAL,           -- area under the precision-coverage curve
    PRIMARY KEY (submission_id, level, match_type)
);
CREATE TABLE proteobench_curve (
    submission_id TEXT NOT NULL
        REFERENCES proteobench_submission(id) ON DELETE CASCADE,
    level      TEXT NOT NULL,
    match_type TEXT NOT NULL,
    i          INTEGER NOT NULL,   -- position along the stored curve
    coverage   REAL NOT NULL,
    precision  REAL NOT NULL,
    PRIMARY KEY (submission_id, level, match_type, i)
);
CREATE TABLE proteobench_source (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE subdomain (
    id    INTEGER PRIMARY KEY,
    name  TEXT NOT NULL UNIQUE,  -- as stored in algorithm.subdomain, and the page's slug
    label TEXT NOT NULL,         -- display name, shared by the site and the generator
    blurb TEXT                   -- one line: what de novo sequencing is for here
);
CREATE TABLE family_note (
    name  TEXT PRIMARY KEY,  -- as stored in algorithm.algorithm_family
    blurb TEXT NOT NULL      -- one line: what this family's methods share
);
CREATE TABLE dataset (
    id                INTEGER PRIMARY KEY,
    name              TEXT NOT NULL UNIQUE,
    short_description TEXT,
    kind              TEXT NOT NULL,   -- 'benchmark' | 'training' | 'deposit'
    acquisition_mode  TEXT,            -- 'DDA' | 'DIA' | 'both' | NULL
    organisms         TEXT,
    homepage          TEXT
);
CREATE TABLE dataset_version (
    id            INTEGER PRIMARY KEY,
    dataset_id    INTEGER NOT NULL REFERENCES dataset(id),
    version       TEXT NOT NULL,
    description   TEXT,
    n_spectra     INTEGER,
    n_train       INTEGER,
    n_validation  INTEGER,
    n_test        INTEGER,
    released      DATE,
    introduced_by INTEGER REFERENCES publication(id),
    UNIQUE(dataset_id, version)
);
CREATE TABLE dataset_address (
    id                 INTEGER PRIMARY KEY,
    dataset_version_id INTEGER NOT NULL REFERENCES dataset_version(id),
    repository         TEXT NOT NULL,  -- 'MassIVE'|'PRIDE'|'iProX'|'Zenodo'|'figshare'|'Hugging Face'
    accession          TEXT NOT NULL,
    url                TEXT,
    part               TEXT,           -- species, or 'Part II'
    is_provenance      INTEGER NOT NULL DEFAULT 0,
    UNIQUE(repository, accession, dataset_version_id)
);
CREATE TABLE publication_dataset (
    id                 INTEGER PRIMARY KEY,
    publication_id     INTEGER NOT NULL REFERENCES publication(id),
    dataset_id         INTEGER NOT NULL REFERENCES dataset(id),
    dataset_version_id INTEGER REFERENCES dataset_version(id),
    role               TEXT NOT NULL DEFAULT 'uses'  -- 'introduces'|'trains-on'|'evaluates-on'|'uses'
);
CREATE TABLE repository_metrics (
            url            TEXT PRIMARY KEY,
            stars          INTEGER,
            forks          INTEGER,
            open_issues    INTEGER,
            closed_issues  INTEGER,
            open_prs       INTEGER,
            closed_prs     INTEGER,
            last_pushed    TEXT,
            fetched_at     TEXT NOT NULL
        , latest_release TEXT);
CREATE TABLE checkpoint (
    id           INTEGER PRIMARY KEY,
    algorithm_id INTEGER NOT NULL REFERENCES algorithm(id),
    label        TEXT,             -- 'nine-species', 'v4.0.0', 'MassIVE-KB'
    host         TEXT NOT NULL,    -- Zenodo|figshare|Hugging Face|GitHub release|Google Drive|institutional
    url          TEXT NOT NULL,
    accession    TEXT,             -- DOI or repo id, where the host gives one
    licence      TEXT,             -- as the host states it; NULL means unstated, which blocks mirroring
    size_bytes   INTEGER,
    archival     INTEGER NOT NULL DEFAULT 0,   -- 1 = DOI'd and preserved by the host
    -- Filled by build_checkpoints.py, which is this table's only writer.
    status       TEXT NOT NULL DEFAULT 'unchecked',  -- live|moved|dead|unchecked|unverifiable
    http_code    INTEGER,
    last_checked DATE,
    mirror_url   TEXT,             -- our copy, made ONLY for a non-archival host
    notes        TEXT, tool_version TEXT, trained_on TEXT, local_backup TEXT, sha256 TEXT, filename TEXT,
    UNIQUE(algorithm_id, url)
);
CREATE TABLE publication_citation (
    citing_id INTEGER NOT NULL,
    cited_id  INTEGER NOT NULL,
    source    TEXT    NOT NULL,  -- 'crossref', 'semanticscholar', 'both'
    PRIMARY KEY (citing_id, cited_id),
    FOREIGN KEY (citing_id) REFERENCES publication(id) ON DELETE CASCADE,
    FOREIGN KEY (cited_id)  REFERENCES publication(id) ON DELETE CASCADE,
    CHECK (citing_id != cited_id)
);
DELETE FROM sqlite_sequence;
CREATE VIEW author_display AS
SELECT a.*,
       CASE WHEN a.disambiguator IS NOT NULL AND a.disambiguator <> ''
            THEN a.name || ' (' || a.disambiguator || ')'
            ELSE a.name END AS display_name
FROM author a;
CREATE TRIGGER prevent_future_publication_date_outgoing_update
BEFORE UPDATE OF publication_date ON publication
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM publication_citation pc
    JOIN publication cited ON cited.id = pc.cited_id
    WHERE pc.citing_id = NEW.id
      AND date(NEW.publication_date) < date(cited.publication_date)
)
BEGIN
    SELECT RAISE(ABORT, 'publication date would make an outgoing citation point to the future');
END;
CREATE TRIGGER prevent_future_publication_date_incoming_update
BEFORE UPDATE OF publication_date ON publication
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM publication_citation pc
    JOIN publication citing ON citing.id = pc.citing_id
    WHERE pc.cited_id = NEW.id
      AND date(citing.publication_date) < date(NEW.publication_date)
)
BEGIN
    SELECT RAISE(ABORT, 'publication date would make an incoming citation point to the future');
END;
CREATE TRIGGER publication_version_sanity
        BEFORE INSERT ON publication_version
        FOR EACH ROW
        BEGIN
            SELECT CASE
              WHEN (SELECT publication_type FROM publication WHERE id = NEW.preprint_id)
                   <> 'preprint'
                THEN RAISE(ABORT, 'preprint_id must reference a publication_type=preprint row')
              WHEN NEW.preprint_id = NEW.published_id
                THEN RAISE(ABORT, 'a publication cannot be its own other version')
              WHEN date((SELECT publication_date FROM publication WHERE id = NEW.published_id))
                   < date((SELECT publication_date FROM publication WHERE id = NEW.preprint_id))
                THEN RAISE(ABORT, 'published version predates the preprint')
            END;
        END;
CREATE TRIGGER thesis_supervisor_sanity
BEFORE INSERT ON thesis_supervisor
FOR EACH ROW
BEGIN
    SELECT CASE
      WHEN (SELECT publication_type FROM publication WHERE id = NEW.publication_id)
           <> 'thesis'
        THEN RAISE(ABORT, 'thesis_supervisor.publication_id must reference a publication_type=thesis row')
      WHEN EXISTS (SELECT 1 FROM publication_author pa
                   WHERE pa.publication_id = NEW.publication_id
                     AND pa.author_id = NEW.author_id)
        THEN RAISE(ABORT, 'that person is already an author of this thesis; supervisor is a different role')
    END;
END;
CREATE TRIGGER prevent_future_publication_citation_insert
BEFORE INSERT ON publication_citation
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM publication citing
    JOIN publication cited
    WHERE citing.id = NEW.citing_id
      AND cited.id = NEW.cited_id
      AND date(citing.publication_date) < date(cited.publication_date)
)
BEGIN
    SELECT RAISE(ABORT, 'citation cannot point to a future publication');
END;
CREATE TRIGGER prevent_future_publication_citation_update
BEFORE UPDATE OF citing_id, cited_id ON publication_citation
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM publication citing
    JOIN publication cited
    WHERE citing.id = NEW.citing_id
      AND cited.id = NEW.cited_id
      AND date(citing.publication_date) < date(cited.publication_date)
)
BEGIN
    SELECT RAISE(ABORT, 'citation cannot point to a future publication');
END;
CREATE UNIQUE INDEX idx_city_name_country_unique ON city(name, IFNULL(country_id,-1));
CREATE UNIQUE INDEX idx_affiliation_name_dept_unique ON affiliation(name, IFNULL(department,''));
CREATE UNIQUE INDEX idx_author_name_disambig_unique
               ON author(name, IFNULL(disambiguator,''));
CREATE UNIQUE INDEX idx_publication_version_published ON publication_version(published_id);
CREATE UNIQUE INDEX ux_country_iso2 ON country(iso2) WHERE iso2 IS NOT NULL;
CREATE INDEX ix_affiliation_ror ON affiliation(ror) WHERE ror IS NOT NULL;
CREATE UNIQUE INDEX idx_publication_dataset_unique
    ON publication_dataset(publication_id, dataset_id, IFNULL(dataset_version_id, -1), role);
CREATE INDEX idx_dataset_address_accession ON dataset_address(accession);
CREATE INDEX idx_dataset_version_dataset   ON dataset_version(dataset_id);
CREATE INDEX idx_publication_dataset_pub   ON publication_dataset(publication_id);
CREATE INDEX idx_checkpoint_algorithm ON checkpoint(algorithm_id);
CREATE INDEX idx_checkpoint_status    ON checkpoint(status);
CREATE INDEX idx_publication_citation_cited ON publication_citation(cited_id);
COMMIT;
